(window.GIM_TP=window.GIM_TP||{})["Z.Behaalotcha.0"]={"from":0,"a":[[[],[],[]],[["(במדבר ח׳:א׳-ב׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר. דַּבֵּר אֶל אַהֲרֹן וְאָמַרְתָּ אֵלָיו בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת וְגוֹ', רִבִּי יְהוּדָה פָּתַח, (תהילים י״ט:ו׳) וְהוּא כְּחָתָן יוֹצֵא מֵחוּפָּתוֹ וְגוֹ'. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוֹן, וְיָהַב לְהוֹן אוֹרַיְיתָא דִּקְשׁוֹט, אִילָנָא דְּחַיֵּי, דְּבֵיהּ אָחִיד בַּר נָשׁ (ס\"א ירית) חַיִּין לְהַאי עָלְמָא, וְחַיִּין לְעָלְמָא דְּאָתֵי. דְּכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא וְאָחִיד בָּהּ, אִית לֵיהּ חַיִּין (ס\"א אחיד בחיין). וְכָל מַאן דְּשָׁבִיק מִלֵּי דְּאוֹרַיְיתָא, וְאִתְפְּרַשׁ מֵאוֹרַיְיתָא, כְּאִלּוּ מִתְפְּרַשׁ מֵחַיִּין, בְּגִין דְּהִיא חַיִּין, וְכָל מִלּוֹי חַיִּין, הֲדָא הוּא דִכְתִיב, (משלי ד) כִּי חַיִּים הֵם וְגוֹ'. וּכְתִיב (משלי ג׳:ח׳) רִפְאוּת תְּהִי לְשָׁרֶךָ וְגוֹ'.","תָּא חֲזֵי, אִילָנָא דְּחַיֵּי, אָחִיד מֵעֵילָּא לְתַתָּא. וְהַאי שִׁמְשָׁא דְּנָהִיר לְכֹלָּא, נְהוֹרָא דִּילֵיהּ שָׁארֵי מֵרֵישָׁא, וְאִתְפָשַּׁט בְּגוּפָא דְּאִילָנָא בְּאֹרַח מֵישָׁר, ב' סִטְרִין אֲחִידָן בֵּיהּ, חַד לַצָּפוֹן, וְחַד לַדָּרוֹם. חַד יְמִינָא, וְחַד שְׂמָאלָא. (ואינון) בְּשַׁעֲתָא דְּשִׁמְשָׁא נָהִיר כְּמָה דְּאִתְּמַר, מֵהַהוּא גּוּפָא (ס\"א נופא) דְּאִילָנָא, אַתְקִיף לִדְרוֹעָא דִּימִינָא, וְאַנְהִיר בְּתוּקְפֵּיהּ. וּמִתּוּקְפֵּיהּ נָהִיר שְׂמָאלָא, וְאִתְכְּלִיל בִּנְהוֹרֵיהּ.","וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ, מַאן אִיהוּ חֻפָּתוֹ. דָּא אִיהוּ (שיר השירים ג׳:י״א) עֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתּוֹ. יוֹצֵא מֵחֻפָּתוֹ, דָּא אִיהוּ רֵישָׁא דְּכָל נְהוֹרָא כְּמָה דְאַתְּ אָמֵר בַּקְרָא דַּאֲבַּתְרֵיהּ, מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ, דָּא שֵׁירוּתָא דְּכֹלָּא, דְּאִקְרֵי מִקְצֵה הַשָּׁמַיִם. וּכְדֵין, נָפִיק כְּחָתָן מַמָּשׁ, כַּד נָפִיק לְאַעְרְעָא לְכַלָּתֵיהּ, רְחִימָתָא דְּנַפְשׁוֹי, וּפָרִישׂ דְּרוֹעוֹי, וּמְקַבֵּל לָהּ.","כְּהַאי גַּוְונָא וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ, אַזְלָא שִׁמְשָׁא וְאִתְפָשַּׁט לְגַבֵּי מַעֲרָב, כֵּיוָן דְּמַעֲרָב אִתְקְרִיב, סְטָר צָפוֹן אִתְּעַר לְקֳבְלֵיהּ בְּקַדְמִיתָא, וְקָרִיב לְמַעֲרָב, וְזָוִיג לֵיהּ בְּאַתְרֵיהּ, כְּמָה דְּאִתְּמַר דִּכְתִּיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וּלְבָתַר סְטָר דָּרוֹם דְּאִיהוּ יְמִינָא, דִּכְתִּיב וִימִינוֹ תְּחַבְּקֵנִי. כְּדֵין יָשִׂישׂ כְּגִבּוֹר לָרוּץ אֹרַח, לְאַנְהָרָא סִיהֲרָא וְאוֹקְמוּהָ. תָּא חֲזֵי, בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת, אִלֵּין בּוֹצִינִין עִלָּאִין, דְּכֻלְּהוּ נְהִירִין כַּחֲדָא מִן שִׁמְשָׁא. (חסר כאן)","רִבִּי אַבָּא פָּתַח, (תהילים פ״ט:ט״ז) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה יְיָ בְּאוֹר פָּנֶיךָ יְהַלֵּכוּן. הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא, וְאוֹלִיף לוֹן אָרְחוֹי, לְאִתְדַּבְּקָא בֵּיהּ, וּלְמֵיטַר פִּקּוּדֵי דְּאוֹרַיְיתָא, לְמִזְכֵּי בְּהוּ לְעָלְמָא דְּאָתֵי. וְקָרִיב לְהוּ בְּשַׁעֲתָא דְּנָפְקוּ מִמִּצְרָיִם, דְּהָא כְּדֵין אַפִּיק לוֹן מֵרְשׁוּתָא אַחֲרָא, וְסָלִיק לוֹן לְאִתְאַחֲדָא בִּשְׁמֵיהּ, וּכְדֵין אִקְרוּן בְּנֵי יִשְׂרָאֵל, בְּנֵי חוֹרִין מִכֹּלָּא. דְּלָא יָתְבוּ תְּחוֹת רְשׁוּתָא אַחֲרָא, וְסָלִיק לוֹן לְאַחֲדָא בִּשְׁמֵיהּ, דְּסָלִיק עַל כֹּלָּא, דְּשַׁלִּיט עַל עִלָּאִין וְתַתָּאִין."],[[0,"וידבר","וגו' \u0003בהעלותך את הנרות\u0004 וגו': ר' יהודה פתח, והוא כחתן יוצא מחופתו וגו'. אשרי חלקם של ישראל שהקב\"ה רצה בהם, ונתן להם תורת אמת, עץ החיים, שבו יורש האדם חיים לעולם הזה וחיים לעולם הבא. שכל מי שמשתדל בתורה ואוחז בה יש לו חיים. וכל מי שעוזב דברי תורה, ונפרד מן התורה, הוא כאלו נפרד מן החיים, משום שהיא חיים וכל דבריה חיים. ז\"ש כי חיים הם וגו'. וכתוב, רפאות תהי לשריך וגו'."],[1,"ת\"ח אילנא דחיי","וכו': בוא וראה, עץ החיים שהוא ז\"א, אחוז ממעלה למטה. ושמש הזה, שהוא ז\"א, המאיר לכל, האור שלו מתחיל מראש, שהוא חב\"ד, ומתפשט בגוף האילן שהוא ת\"ת, בדרך ישר. ב' צדדים אחוזים בו אחד לצפון, ואחד לדרום, אחד ימין, שהוא חסד, ואחד הוא שמאל, שהוא גבורה. בשעה שהשמש מאיר מהגוף ההוא של האילן, כמו שלמדנו, הוא מתקיף לזרוע ימין תחילה שהוא חסד, ומאיר בתוקפו. ומתוקפו של הימין מאיר השמאל שהיא גבורה, ונכלל באורו."],[2,"והוא כחתן יוצא מחופתו:","שואל, מי היא חופתו. ומשיב, זו היא עטרה שעטרה לו אמו ביום חתונתו. שהם המוחין חב\"ד שמקבל מאמו, שהיא בינה. \u0003יוצא מחופתו,\u0004 זה הוא הראש של כל האור, דהיינו חב\"ד (כנ\"ל תרומה אות קכ\"ו) כמו שאתה אומר בהכתוב שלאחריו מקצה השמים מוצאו. שזה הוא תחילת הכל שנקרא קצה השמים, דהיינו בינה שממנה יוצא ומתחיל ז\"א הנקרא שמים. ואז יוצא כחתן ממש כשיוצא לפגוש כלתו אהבת נפשו, ופורש זרועותיו, שהם חסד וגבורה, ומקבלה."],[3,"כהאי גוונא והוא","וכו': כעין זה, והוא כחתן יוצא מחופתו, השמש שהוא ז\"א, הולך ומתפשט למערב, שהוא המלכות. כיון שהמערב מתקרב, מתעורר כנגדה תחילה צד צפון, שהוא גבורה, וקרב למערב, ומזדווג עמה במקומה, כמו שלמדנו, כי תחילת זווג ז\"א הוא בשמאל שהוא גבורה, (כנ\"ל ב\"ב דף קל\"ו ד\"ה פנימיות) שה\"ס פיוסא ונטילת רשות. שכתוב, שמאלו תחת לראשי. ולאחר כך צד דרום שהוא ימין דהיינו חסד, שכתוב וימינו תחבקני. אז ישיש כגבור לרוץ ארח, להאיר הלבנה מקו האמצעי, שהוא יסוד, והעמידוהו. בוא וראה בהעלותך את הנרות, אלו הם נרות העליונים, שהם ספירות המלכות, שכולם מאירים יחד מן השמש. שהוא ז\"א."],[4,"ר' אבא פתח","וכו': רא\"פ, אשרי העם יודעי תרועה ה' באור פניך יהלכון. מקרא זה העמידוהו. אבל בוא וראה אשרי הם ישראל שהקב\"ה נתן להם התורה הקדושה, ולמד אותם דרכיו להתדבק בו, ולשמור מצות התורה לזכות בהם לעולם הבא. וקרב אותם בשעה שיצאו ממצרים, כי אז הוציאם מרשות אחר, והעלה אותם להתאחד בשמו, ואז נקראו בני ישראל בני חורין מכל, שלא ישבו תחת רשות אחר, והעלה אותם להתאחד בשמו העולה על הכל, השולט על עליונים ותחתונים."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר. דַּבֵּר אֶל אַהֲרֹן וְאָמַרְתָּ אֵלָיו בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים יט) וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בָהֶם, וְנָתַן לָהֶם תּוֹרַת אֱמֶת, עֵץ חַיִּים, שֶׁבּוֹ הָאָדָם אוֹחֵז (יורש) חַיִּים לָעוֹלָם הַזֶּה וְחַיִּים לָעוֹלָם הַבָּא. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְאוֹחֵז בָּהּ, יֵשׁ לוֹ חַיִּים (אוחז בחיים). וְכָל מִי שֶׁעוֹזֵב דִּבְרֵי הַתּוֹרָה וְנִפְרָד מֵהַתּוֹרָה, כְּאִלּוּ נִפְרָד מֵהַחַיִּים, מִשּׁוּם שֶׁהִיא חַיִּים, וְכָל דְּבָרֶיהָ חַיִּים. זֶהוּ שֶׁכָּתוּב (משלי ד) כִּי חַיִּים הֵם וְגוֹ'. וְכָתוּב (שם ג) רִפְאוּת תְּהִי לְשָׁרֶךְ וְגוֹ'."],[1,"","בֹּא רְאֵה, עֵץ הַחַיִּים אָחוּז מִמַּעְלָה לְמַטָּה. וְשֶׁמֶשׁ זוֹ שֶׁמְּאִירָה לַכֹּל, אוֹרָהּ מַתְחִיל מֵהָרֹאשׁ, וּמִתְפַּשֵּׁט בְּגוּף הָאִילָן בְּדֶרֶךְ יָשָׁר. שְׁנֵי צְדָדִים אֲחוּזִים בּוֹ, אֶחָד לַצָּפוֹן וְאֶחָד לַדָּרוֹם, אֶחָד יָמִין וְאֶחָד שְׂמֹאל, (והם) בְּשָׁעָה שֶׁמְּאִירָה הַשֶּׁמֶשׁ כְּמוֹ שֶׁנִּתְבָּאֵר, מֵאוֹתוֹ גּוּף (נוף) הָאִילָן, מְחַזֵּק לִזְרוֹעַ יָמִין וּמֵאִיר בְּתָקְפּוֹ, וּמִתָּקְפּוֹ מֵאִיר הַשְּׂמֹאל וְנִכְלָל בְּאוֹרוֹ."],[2,"","וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ. מַהִי חֻפָּתוֹ? זֶהוּ (שיר השירים א) עֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ. יֹצֵא מֵחֻפָּתוֹ - זֶהוּ רֹאשׁ שֶׁל כָּל אוֹר, כְּמוֹ שֶׁנֶּאֱמַר בַּפָּסוּק שֶׁלְּאַחֲרָיו, מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ. זוֹ רֵאשִׁית הַכֹּל שֶׁנִּקְרֵאת מִקְצֵה הַשָּׁמַיִם. וְאָז יצֵא כְּחָתָן מַמָּשׁ, כְּשֶׁיּוֹצֵא לִפְגֹּשׁ אֶת כַּלָּתוֹ אֲהוּבַת נַפְשׁוֹ, וּפוֹרֵשׂ זְרוֹעוֹתָיו וּמְקַבְּלָהּ."],[3,"","כְּמוֹ זֶה וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ, הוֹלֶכֶת הַשֶּׁמֶשׁ וּמִתְפַּשֶּׁטֶת לַמַּעֲרָב. כֵּיוָן שֶׁמַּעֲרָב מִתְקָרֵב, צַד צָפוֹן מִתְעוֹרֵר מוּלוֹ בַּתְּחִלָּה, וּמִתְקָרֵב לַמַּעֲרָב, וּמְזַוֵּג אוֹתוֹ בִּמְקוֹמוֹ, כְּמוֹ שֶׁנֶּאֱמַר שֶׁכָּתוּב (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְאַחַר כָּךְ צַד דָּרוֹם, שֶׁהוּא יָמִין, שֶׁכָּתוּב וִימִינוֹ תְּחַבְּקֵנִי. אָז יָשִׂישׂ כְּגִבּוֹר לָרוּץ אֹרַח, לְהָאִיר הַלְּבָנָה, וּפֵרְשׁוּהָ. בֹּא רְאֵה, בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת - אֵלּוּ מְנוֹרוֹת עֶלְיוֹנוֹת שֶׁכֻּלָּן מְאִירוֹת כְּאַחַת מֵהַשֶּׁמֶשׁ."],[4,"","רַבִּי אַבָּא פָּתַח, (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה ה' בְּאוֹר פָּנֶיךְ יְהַלֵּכוּן. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, אֲבָל בּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה הַקְּדוֹשָׁה, וְלִמְּדָם דְּרָכָיו לְהִתְדַּבֵּק בּוֹ, וְלִשְׁמֹר מִצְווֹת הַתּוֹרְה לִזְכּוֹת בָּהֶן לָעוֹלָם הַבָּא, וְקֵרְבָם בְּשָׁעָה שֶׁיָּצְאוּ מִמִּצְרַיִם, שֶׁהֲרֵי אָז הוֹצִיאָם מֵרְשׁוּת אַחֶרֶת, וְהֶעֱלָם לְהֵאָחֵז בִּשְׁמוֹ, וְאָז נִקְרְאוּ בְנֵי יִשְׂרָאֵל בְּנֵי חוֹרִין מֵהַכֹּל, שֶׁלֹּא יָשְׁבוּ תַּחַת רָשׁוּת אַחֶרֶת, וְהֶעֱלָם לְהֵאָחֵז בִּשְׁמוֹ, שֶׁעוֹלֶה עַל הַכֹּל, שֶׁשּׁוֹלֵט עַל עֶלְיוֹנִים וְתַחְתּוֹנִים."]]],[["וּמִגּוֹ רְחִימוּתָא דִּלְהוֹן, קָרָא לוֹן (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל, כְּגַוְונָא (דקדושה) עִלָּאָה (ועל דא). קָטַל (ס\"א וקטל) כָּל בְּכוֹר דִּלְעֵילָּא וְתַתָּא, וְשָׁרָא קְטִירִין וְאֲסִּירִין דְּעִלָּאִין וְתַתָּאִין, בְּגִין לְאַפָּקָא לוֹן, וְעָבִיד לוֹן בְּנֵי חוֹרִין מִכֹּלָּא. וְעַל דָּא לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא, לָא מַלְאָךְ, וְלָא שָׂרָף, אֶלָּא אִיהוּ. וְעוֹד, דְּהָא אִיהוּ יָדַע לְאַבְחֲנָא וּלְמִנְדַּע כֹּלָּא, וּלְמִשְׁרֵי אֲסִירִין, וְלָאו אִינּוּן בִּרְשׁוּתָא דִּשְׁלִיחָא אַחֲרָא אֶלָּא בִּידֵיהּ.","תָּא חֲזֵי, בְּהַהוּא לֵילְיָא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְקָטְלָא כָּל אִינּוּן בְּכוֹרֵי כְּמָה דְּאִתְּמַר, בְּשַׁעֲתָא דְּרָמַשׁ לֵילְיָא, אָתוּ מְזַמְּרִין לְזַמְּרָא קַמֵּיהּ, אָמַר לוֹן, לָאו עִידָּן הוּא דְּהָא שִׁירָתָא אַחֲרָא, מְזַמְּרִין בָּנַי בְּאַרְעָא. בְּשַׁעֲתָא דְּאִתְפְּלִיג לֵילְיָא, אִתְּעַר רוּחַ צָפוֹן, וְקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין עֲבַד נוּקְמִין, וְיִשְׂרָאֵל עַבְדִּין שִׁירָתָא בְּקוֹל רָם, (ס\"א וישראל מזמרין ואמרין הלילא בקול רם) וּכְדֵין עֲבַד לוֹן בְּנֵי חוֹרִין מִכֹּלָּא, וּמַלְאָכִין עִלָּאֵי, וְכָל מַשִׁרְיָין כֻּלְּהוּ, הֲווֹ צַיְיתִין לְהוֹן לְקַלֵיהוֹן דְּיִשְׂרָאֵל. בָּתַר דְּאִתְגְּזָרוּ, רְשִׁימוּ לְבָתֵּיהוֹן, מֵהַהוּא דָּמָא, וּמִדָּמָא דְּפִסְחָא, בִּתְלַת רְשִׁימִין. (שמות י״ב:כ״ג) עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזוֹת.","מַאי טַעְמָא. הָא אוּקְמוּהָ בְּגִין דְּאִיהוּ רְשִׁימָא קַדִּישָׁא, וּמְחַבְּלָא כַּד אִיהוּ נָפִיק, וְחָמֵי הַהוּא דָּמָא דְּהֲוָה רָשִׁים עַל הַהוּא פִּתְחָא, חָיִיס עָלַיְיהוּ דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב וּפָסַח יְיָ עַל הַפֶּתַח וְגוֹ'. הָכָא אִית לְאִסְתַּכְּלָא, אִי קוּדְשָׁא בְּרִיךְ הוּא אָתֵי וְקָטִיל בְּאַרְעָא דְּמִצְרַיִם, וְלֹא שְׁלִיחַ אַחֲרָא, רְשִׁימָא דָּא דְּעַל פִּתְחָא לָמָּה, וְהָא כֹּלָּא גַּלֵי קַמֵּיהּ. וְתוּ, מַהוּ וְלֹא יִתֵּן הַמַּשְׁחִית, וְלֹא יַשְׁחִית מִבָּעֵי לֵיהּ.","אֶלָּא וַדַּאי הָכִי הוּא, דִּכְתִּיב, (שמות י״ב:כ״ט) וַיְיָ הִכָּה כָל בְּכוֹר. וַיְיָ: הוּא וּבֵית דִּינוֹ. וְהַהוּא בֵּי דִּינָא הָכָא אִשְׁתְּכַח. (ס\"א מכאן דבכלא) וּבְכֹלָּא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, בְּגִין לְאִשְׁתְּזָבָא. דְּהָא כְּגַוְונָא דָּא עַל גַּבֵּי מַדְבְּחָא, בְּגִין דְּלָא אִשְׁתְּכַח מְחַבְּלָא.","הַאי בְּעוֹבָדָא, וּבְזִמְנָא דְּלָא אִצְטְרִיךְ הַאי, כְּגוֹן רֹאשׁ הַשָּׁנָה, דְּאִיהוּ יוֹמָא דְּדִינָא, וּמָארֵיהוֹן דְּלִישָׁנָא בִּישָׁא קַיְימִין עָלַיְיהוּ דְּיִשְׂרָאֵל, בָּעֵינָן מִלִּין, צְלוֹתִין וּבָעוּתִין, וּבָעֵינָן לְאַחֲזָאָה עוֹבָדָא (ס\"א ברוחא ונפשא) כְּמָה דְּאוֹקִימְנָא. וְהָא אִתְּמַר, וּבְמָה. בַּשּׁוֹפָר. (לאחזאה שופר) לְאַתְּעָרָא שׁוֹפְרָא אַחֲרָא. וַאֲנָן מְפִיקִין בְּהַהוּא קָלָא, רַחֲמֵי וְדִינָא כַּחֲדָא, כֹּלָּא כַּדְקָא יָאוּת. כְּמָה דְּהַהוּא שׁוֹפָר עִלָּאָה, אַפִּיק קָלָא דְּאִיהוּ כְּלָלָא כַּחֲדָא. וּלְאַתְעֲרָא רַחֲמֵי קָאַזְלֵינָן, וּלְתַּבְּרָא מָארֵיהוֹן דְּדִינָא, דְּלָא יִשְׁלְטוּן בְּהַאי יוֹמָא. וְכַד רַחֲמֵי מִתְעָרִין, כֻּלְּהוּ בּוּצִינִין עִלָּאִין נַהֲרִין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא. כְּדֵין (משלי ט״ז:ט״ו) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּכַהֲנָא (רבא) אִתְכְּוָון לְאַדְלְקָא בּוּצִינִין לְתַתָּא, וַהֲוָה קָרִיב קְטוֹרֶת בּוּסְמִין, בְּהַהוּא שַׁעֲתָא כְּדֵין בּוּצִינִין עִלָּאִין נַהֲרִין, וְאִתְקְטַר כֹּלָּא כַּחֲדָא, וְחִדוּ וְחֶדְוָותָא אִשְׁתְּכַח בְּכֻלְּהוּ עָלְמִין, הֲדָא הוּא דִכְתִיב, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטוֹרֶת יְשַׂמַּח לֵב, וְעַל דָּא בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת.","רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי וְרִבִּי יִצְחָק, הֲווֹ אָזְלֵי בְּאוֹרְחָא, פָּגְעוּ בְּאִינּוּן טוּרֵי קַרְדוֹ, עַד דַּהֲווֹ אָזְלֵי, זָקַף עֵינוֹי רִבִּי אֶלְעָזָר, וְחָמֵי אִינּוּן טוּרֵי רָמָאֵי, וַהֲווּ חֲשוֹכָן, וְדַחֲלָן בִּדְחִילוּ. אָמַר רִבִּי אֶלְעָזָר לְאִינּוּן חַבְרַיָּיא, אִלּוּ אַבָּא הָכָא, לָא הֲוָה דָּחִילְנָא, אֲבָל כֵּיוָן דַּאֲנָן תְּלָתָא, וּמִלֵּי דְּאוֹרַיְיתָא בֵּינָנָא, דִּינָא הָכָא לָא אִשְׁתְּכַח.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, כְּתִיב וַתָּנַח הַתֵּיבָה בַחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', עַל הֲרֵי אֲרָרָט וְגוֹ', כְּמָה חֲבִיבִין מִלֵי דְּאוֹרַיְיתָא, דִּבְכָל מִלָה וּמִלָּה, אִית רָזִין עִלָאִין, וְאוֹרַיְיתָא כֹּלָּא, עִלָּאָה אִיקְרֵי. וְתָנֵינָן בִּתְלֵיסָר מְכִילָן דְּאוֹרַיְיתָא, כָל דָּבָר שֶׁהָיָה בִּכְלָל, וְיָצָא מִן הַכְּלָל, לְלַמֵּד, לֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. דְּהָא אוֹרַיְיתָא דְּאִיהִי כְּלָלָא עִלָּאָה, אַף עַל גַּב דְּנָפִק מִנָּהּ, חַד סִפּוּר בְּעָלְמָא. ודַּאי לָא אָתֵי לְאַחֲזָאָה עַל הַהוּא סִפּוּר, אֶלָּא לְאַחֲזָאָה מִלִּין עִלָּאִין, וְרָזִין עִלָּאִין. וְלֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. בְּגִין דְּהַהוּא סִפּוּר דְּאוֹרַיְיתָא, אוֹ הַהוּא עוֹבָדָא, אַף עַל גַּב דְּהוּא נָפְקָא מִכְלָלָא דְּאוֹרַיְיתָא, לָאו לְאַחֲזָאָה עַל גַּרְמֵיהּ נָפַק בִּלְבַד, אֶלָּא לְאַחֲזָאָה עַל הַהוּא כְּלָלָא עִלָּאָה דְּאוֹרַיְיתָא כֹּלָּא נָפַק."],[[0,"ומגו רחימותא דלהון","וכו': ומתוך אהבתם קרא אותם, בני בכורי ישראל, כעין שלמעלה, כמו ז\"א הנקרא בכור. והרג כל בכור שלמעלה ולמטה מסטרא אחרא, והתיר קשרים ואסורים של עליונים ותחתונים, שעשו המצריים שלא יוכלו ישראל לצאת ממצרים, כדי להוציאם, ועשה אותם בני חורין מכל. וע\"כ לא רצה הקב\"ה להוציאם על ידי מלאך ולא שרף אלא הוא עצמו. ועוד כי הוא ידע להבחין בין בכור ושאינו בכור, ולדעת הכל, ולפתוח אסורים, ואינם ברשות שליח אחר אלא בידו."],[1,"תא חזי בההוא","וכו': בוא וראה, בלילה ההוא שרצה הקב\"ה להרוג כל אלו הבכורים, כמו שלמדנו, שבשעה שהחשיך הלילה, באו מזמרים לזמר לפניו. אמר להם הקב\"ה אין הזמן לומר שירה, כי שירה אחרת מזמרים בני בארץ. בשעה שנחלק הלילה, נתעורר רוח צפון, והקב\"ה עשה אז נקמות לישראל וישראל מזמרים שירה בקול רם, ואז עשה אותם בני חורין מכל. ומלאכים עליונים, וכל מחנות העליונים כולם, היו מקשיבים לקולם של ישראל, אחר שנמולו, ורשמו בתיהם מאותו הדם ומדם הפסח בג' רשימות, על המשקוף ועל ב' המזוזות."],[2,"מ\"ט. הא אוקמוה","וכו': מהו הטעם שרשמו הדם על המשקוף וב' המזוזות. הרי העמידוהו. משום שהוא רושם קדוש, והמחבל, כשיצא וראה אותו הדם שהיה רשום על הפתח רחם על ישראל. ז\"ש ופסח ה' על הפתח וגו'. כאן יש להסתכל, אם הקב\"ה בא והרג בארץ מצרים ולא שליח אחד, רושם זה שעל הפתח למה, והרי הכל גלוי לפניו. ועוד מהו, ולא יתן המשחית שמשמע שהוא שליח, ולא ישחית היה צריך לומר."],[3,"אלא ודאי הכי","וכו': אלא ודאי כך הוא. שכתוב, וה' הכה כל בכור. וה' מורה, הוא ז\"א, ובית דינו, מלכות. ובית דינו זה נמצא כאן, וע\"כ כתוב המשחית. ובכל מקום צריכים להראות מעשה למטה כדי לעורר כנגדו למעלה להנצל. ובשביל זה היו צריכים לתת הדם על המשקוף וב' המזוזות כדי לעורר עליהם הרחמים למעלה. כי כעין זה הם הקרבנות על המזבח, כדי שלא יהיה נמצא משחית."],[4,"האי בעובדא ובזמנא","וכו': זה הוא במעשה, דהיינו בקרבנות. ובזמן שלא צריך זה, כגון בראש השנה, שהוא יום הדין, ובעלי לשון הרע עומדים לקטרג על ישראל, שאינו מספיק בקרבנות לבד, צריכים דבורים, דהיינו תפלות ובקשות, וצריכים להראות מעשה, כמו שהעמדנו, ולמדנו, במה. בשופר. כדי לעורר שופר אחר, שהוא בינה, ואנו מוציאים בקול שופר הזה, רחמים ודין יחד הכל כראוי, כמו ששופר עליון ההוא שהוא בינה הוציא קול, שהוא ז\"א, שהוא כלל של חסד דין ורחמים יחד, כי ת\"ת שהוא ז\"א, כלול חסד דין רחמים, ולעורר רחמים אנו הולכים בתקיעת שופר, ולשבר בעלי הדין שלא ישלטו ביום ההוא. (עי' לעיל וירא מאות שפ\"א עד שפ\"ז) וכשהרחמים מתעוררים כל נרות עליונים דהיינו הספירות, מאירים מצד זה ומצד זה, דהיינו מימין ומשמאל, אז באור פני מלך חיים."],[5,"ת\"ח בשעתא דכהנא","וכו': בוא וראה בשעה שהכהן נתכוון להדליק נרות למטה והיה מקריב קטורת הסמים, אז באותה שעה מאירים נרות עליונים, שהם הספירות, ונקשר הכל יחד ושמחה וחדוה נמצאים בכל העולמות, ז\"ש שמן וקטרת ישמח לב. וע\"כ כתוב, בהעלותך את הנרות."],[6,"רבי אלעזר ורבי יוסי","וכו': ר\"א ור\"י ור' יצחק היו הולכים בדרך פגעו באלו הרי חשך, בעוד שהיו הולכים נשא עיניו ר' אלעזר וראה אלו הרים הרמים, והיו חשכים ונוראים באימה. א\"ר אלעזר אל החברים, אלו היה אבי כאן, לא הייתי מתירא, אבל כיון שאנו שלשה, ודברי תורה בינינו, לא יהיה נמצא כאן דין."],[7,"פתח ר' אלעזר","וכו': פר\"א ואמר, כתוב, ותנח התבה בחדש השביעי וגו' על הרי אררט וגו'. כמה חביבים הם דברי תורה, שבכל מלה ומלה יש סודות עליונים, והתורה כולה נקראת עליונה. ולמדנו בברייתא די\"ג מדות שבתורה, כל דבר שהיה בכלל ויצא מן הכלל ללמד, לא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא, כי התורה שהיא כלל עליון, אע\"פ שיוצא ממנה ספור אחד פשוט, ודאי אינו בא להראות על ספור ההוא, אלא להראות דברים עליונים וסודות עליונים, ולא ללמד על עצמו יצא אלא ללמד על הכלל כולו יצא, כי הספור ההוא של התורה או מעשה ההיא, אף על פי שיצא מכלל התורה, לא להראות על עצמו בלבד יצא, אלא להראות על כלל העליון של התורה כולה יצא."]],[[0,"","וּמִתּוֹךָ אַהֲבָתָם קָרָא לָהֶם (שמות ז) בְּנִי בְכֹרִי יִשְׂרָאֵל, כְּדֻגְמָה (של הקדשה) עֶלְיוֹנָה. (ועל זה) הָרַג (והרג) כָּל בְּכוֹר שֶׁלְּמַעְלָה וּמַטָּה, וְהִתִּיר קְשָׁרִים וַאֲסוּרִים שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים כְּדֵי לְהוֹצִיאָם, וַעֲשָׂאָם בְּנֵי חוֹרִין מֵהַכֹּל. וְעַל זֶה לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מַלְאָךְ וְלֹא שָׂרָף, אֶלָּא רַק הוּא. וְעוֹד, שֶׁהֲרֵי הוּא יָדַע לְהַבְחִין וְלָדַעַת הַכֹּל וּלְהַתִּיר אֲסוּרִים, וְאֵינָם בִּרְשׁוּת שָׁלִיחַ אַחֵר, אֶלָּא בְּיָדוֹ."],[1,"","בֹּא רְאֵה, בְּאוֹתוֹ לַיְלָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג כָּל אוֹתָם בְּכוֹרוֹת כְּמוֹ שֶׁנֶּאֱמַר, בְּשָׁעָה שֶׁיָּרַד הַלַּיְלָה, בָּאוּ מְזַמְּרִים לְזַמֵּר לְפָנָיו. אָמַר לָהֶם, לֹא זְמַן הוּא, שֶׁהֲרֵי שִׁירָה אַחֶרֶת מְזַמְּרִים בָּנַי בָּאָ רֶץ. בְּשָׁעָה שֶׁנֶּחֱלַק הַלַּיְלָה הִתְעוֹרְרָה רוּחַ צָפוֹן, וְאָז עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת, וְיִשְׂרָאֵל עוֹשִׂים שִׁירָה בְּקוֹל רָם, (וישראל מזמרים ואומרים הלל בקול רם) וְאָז עֲשָׂאָם בְּנֵי חוֹרִין מֵהַכֹּל, וּמַלְאָכִים עֶלְיוֹנִים וְכָל מַרְכְּבוֹתֵיהֶם הָיוּ מַקְשִׁיבִים לָהֶם לְקוֹלוֹת יִשְׂרָאֵל. אַחַר שֶׁנִּמּוֹלוּ, רָשְׁמוּ אֶת בָּתֵּיהֶם מֵאוֹתוֹ דָּם וּמִדַּם הַפֶּסַח בִּשְׁלֹשָׁה רִשּׁוּמִים: (שם יב) עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזֹּת."],[2,"","מָה הַטַּעַם? הֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁהוּא רֹשֶׁם קָדוֹשׁ, וְהַמַּשְׁחִית כְּשֶׁהוּא יוֹצֵא וְרוֹאֶה אוֹתוֹ דָם שֶׁהָיָה רָשׁוּם עַל אוֹתוֹ פֶּתַח, חָס עַל יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב וּפָסַח ה' עַל הַפֶּתַח וְגוֹ'. כָּאן יֵשׁ לְהִסְתַּכֵּל, אִם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא וְהָרַג בְּאֶרֶץ מִצְרַיִם וְלֹא שָׁלִיחַ אַחֵר, רֹשֶׁם זֶה שֶׁעַל הַפֶּתַח לְשֵׁם מָה, וַהֲרֵי הַכֹּל גָּלוּי לְפָנָיו? וְעוֹד, מַה זֶּה וְלֹא יִתֵּן הַמַּשְׁחִית? וְלֹא יַשְׁחִית צָרִיךְ לוֹ לִהְיוֹת!"],[3,"","אֶלָּא וַדַּאי כָּךְ זֶה, שֶׁכָּתוּב (שם) וַה' הִכָּה כָל בְּכוֹר. וַה' - הוּא וּבֵית דִּינוֹ. וְאוֹתוֹ בֵּית דִּין כָּאן נִמְצָא. (מכאן שבכל) וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה כְּדֵי לְהִנָּצֵל, שֶׁהֲרֵי כְּגוֹן זֶה עַל הַמִּזְבֵּחַ, כְּדֵי שֶׁלֹּא יִמָּצֵא הַמַּשְׁחִית."],[4,"","זֶה בְמַעֲשֶׂה, וּבִזְמַן שֶׁלֹּא צָרִיךְ אֶת זֶה, כְּמוֹ רֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין, וּבַעֲלֵי לָשׁוֹן הָרָע עוֹמְדִים עַל יִשְׂרָאֵל, צְרִיכִים דְּבָרִים, תְּפִלּוֹת וּבַקָּשׁוֹת, וּצְרִיכִים לְהַרְאוֹת מַעֲשֶׂה (ברוח ונפש) כְּמוֹ שֶׁבֵּאַרְנוּ, וַהֲרֵי נִתְבָּאֵר. וּבַמֶּה? בַּשּׁוֹפָר, (להראותשופר) לְעוֹרֵר שׁוֹפָר אַחֵר. וְאָנוּ מוֹצִיאִים בְּאוֹתוֹ קוֹל רַחֲמִים וְדִין כְּאֶחָד, הַכֹּל כָּרָאוּי. כְּמוֹ שֶׁלְּאוֹתוֹ שׁוֹפָר עֶלְיוֹן מוֹצִיא קוֹל שֶׁהוּא כְּלָל שֶׁל אֶחָד. וּלְעוֹרֵר רַחֲמִים אָנוּ הוֹלְכִים, וְלִשְׁבֹּר אֶת בַּעֲלֵי הַדִּין שֶׁלֹּא יִשְׁלְטוּ בַּיּוֹם הַזֶּה. וּכְשֶׁמִּתְעוֹרְרִים הָרַחֲמִים, כָּל הַמְּנוֹרוֹת הָעֶלְיוֹנוֹת מְאִירוֹת מִצַּד זֶה וּמִצַּד זֶה, וְאָז (משלי טז) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים."],[5,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַכֹּהֵן (הגדול) מִתְכַּוֵּן לְהַדְלִיק נֵרוֹת לְמַטָּה וְהָיָה מַקְרִיב קְטֹרֶת בְּשָׂמִים, בְּאוֹתָהּ שָׁעָה אָז מְנוֹרוֹת עֶלְיוֹנוֹת מְאִירוֹת, וְנִקְשָׁר הַכֹּל כְּאֶחָד, וְשִׂמְחָה וְחֶדְוָה נִמְצֵאת בְּכָל הָעוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב (שם כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, וְעַל זֶה בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת."],[6,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. פָּגְעוּ בְּאוֹתָם הָרֵי קַרְדוֹ. עַד שֶׁהָיוּ הוֹלְכִים, הֵרִים רַבִּי אֶלְעָזָר עֵינָיו, וְרָאָה אוֹתָם הָרִים רָמִים, וְהָיוּ חֲשׁוּכִים, וּפָחֲדוּ בְפַחַד. אָמַר רַבִּי אֶלְעָזָר לְאוֹתָם חֲבֵרִים, אִלּוּ אַבָּא כָּאן, לֹא הָיִינוּ פוֹחֲדִים. אֲבָל כֵּיוָן שֶׁאָנוּ שְׁלֹשָׁה וְדִבְרֵי תוֹרָה בֵּינֵינוּ, הַדִּין כָּאן לֹא נִמְצָא."],[7,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, כָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', עַל הָרֵי אֲרָרָט וְגוֹ'. כַּמָּה חֲבִיבִים דִּבְרֵי הַתּוֹרָה, שֶׁבְּכָל דָּבָר וְדָבָר יֵשׁ סוֹדוֹת עֶלְיוֹנִים, וְהַתּוֹרָה כֻּלָּהּ נִקְרֵאת עֶלְיוֹנָה. וְשָׁנִינוּ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל הַתּוֹרָה: כָּל דָּבָר שֶׁהָיָה בִכְלָל וְיָצָא מִן הַכְּלָל לְלַמֵּד, לֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. שֶׁהֲרֵי הַתּוֹרָה, שֶׁהִיא כְּלָל עֶלְיוֹן, אַף עַל גַּב שֶׁיּוֹצֵא מִמֶּנָּה סִפּוּר אֶחָד בָּעוֹלָם, וַדַּאי לֹא בָאָה לְהַרְאוֹת אֶת אוֹתוֹ סִפּוּר, אֶלָּא לְהַרְאוֹת דְּבָרִים עֶלְיוֹנִים וְסוֹדוֹת עֶלְיוֹנִים. וְלֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. מִשּׁוּם שֶׁאוֹתוֹ סִפּוּר שֶׁל הַתּוֹרָה אוֹ אוֹתוֹ מַעֲשֶׂה, אַף עַל גַּב שֶׁהוּא יוֹצֵא מִכְּלַל הַתּוֹרָה, לֹא לְהַרְאוֹת עַל עַצְמוֹ יָצָא בִּלְבַד, אֶלָּא לְהַרְאוֹת עַל אוֹתוֹ כְּלָל עֶלְיוֹן שֶׁל הַתּוֹרָה כֻּלָּהּ יָצָא."]]],[["כְּגוֹן הַאי דִּכְתִּיב, (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט. וַדַּאי הַאי קְרָא מִכְּלָלָא דְּאוֹרַיְיתָא נָפַק, וְאָתֵי בְּסִפּוּר דְּעָלְמָא. מַאי אִכְפַּת לָן, אִי שָׁרֵי בְּהַאי, אוֹ בְּהַאי, דְּהָא בַּאֲתָר חַד לִישְׁרֵי. אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. וְזַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּאִתְיְהִיב לְהוּ אוֹרַיְיתָא עִלָּאָה אוֹרַיְיתָא דִּקְשׁוֹט. וּמַאן דְּאָמַר, דְּהַהוּא סִפּוּרָא דְּאוֹרַיְיתָא, לְאַחֲזָאָה עַל הַהוּא סִפּוּר בִּלְבַד קָאֲתֵי, תִּיפַּח רוּחֵיהּ. דְּאִי הָכִי, לָאו אִיהִי אוֹרַיְיתָא עִלָּאָה, אוֹרַיְיתָא דִּקְשׁוֹט, אֶלָּא וַדַּאי אוֹרַיְיתָא קַדִּישָׁא עִלָּאָה, אִיהִי אוֹרַיְיתָא דִּקְשׁוֹט.","תָּא חֲזֵי, מֶלֶךְ בָּשָׂר וָדָם, לָאו יְקָרָא דִּילֵיהּ הוּא, לְאִשְׁתָּעֵי מִלָּה דְּהֶדְיוֹטָא, כָּל שֶׁכֵּן לְמִכְתַּב לֵיהּ, וְאִי סָלִיק בְּדַעְתָּךְ, דְּמַלְכָּא עִלָּאָה קוּדְשָׁא בְּרִיךְ הוּא, לָא הֲווֹ לֵיהּ מִלִּין קַדִּישִׁין, לְמִכְתַּב וּלְמֶעְבַּד מִנַּיְיהוּ אוֹרַיְיתָא, אֶלָּא דְּאִיהוּ כָּנִישׁ כָּל מִלִּין דְּהֶדְיוֹטִין, כְּגוֹן מִלִּין דְּעֵשָׂו. מִלִּין דְּהָגָר. מִלִּין דְּלָבָן בְּיַעֲקֹב. מִלִּין דְּאָתוֹן. מִלִּין דְּבִלְעָם. מִלִּין דְּבָלָק. מִלִּין דְּזִמְרִי. וְכָנִישׁ לְהוּ, וְכָל שְׁאָר סִפּוּרִין דִּכְתִּיבִין, וְעָבִיד מִנַּיְיהוּ אוֹרַיְיתָא.","אִי הָכִי, אֲמַאי אִקְרֵי (מלאכי ב׳:ו׳) תּוֹרַת אֱמֶת, (תהילים י״ט:ח׳-ט׳) תּוֹרַת יְיָ תְּמִימָה, עֵדוּת יְיָ נֶאֱמָנָה, פִּקּוּדֵי יְיָ יְשָׁרִים, מִצְוַת יְיָ בָּרָה, יִרְאַת יְיָ טְהוֹרָה, מִשְׁפְּטֵי יְיָ אֱמֶת, וּכְתִיב הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב. אִלֵּין אִינּוּן מִלֵּי דְּאוֹרַיְיתָא. אֶלָּא ודַּאי אוֹרַיְיתָא קַדִּישָׁא עִלָּאָה, אִיהוּ אוֹרַיְיתָא דִּקְשׁוֹט, תּוֹרַת יְיָ תְּמִימָה. וְכָל מִלָּה וּמִלָּה, אַתְיָיא לְאַחֲזָאָה מִלִּין (אחרנין) עִלָּאִין, דְּהַהוּא מִלָּה דְּהַהוּא סִפּוּר, לָאו לְאַחֲזָאָה עַל גַּרְמֵיהּ בִּלְבַד קָא אָתְיא, אֶלָּא לְאַחֲזָאָה עַל הַהוּא כְּלָלָא קָאֲתֵי, כְּמָה דְּאוֹקִימְנָא.","תָּא חֲזֵי וַתָּנַח הַתֵּיבָה וְגוֹ'. הַאי קְרָא כַּךְ, כָּל שֶׁכֵּן אַחֲרָנִין, (ס\"א האי קרא כך איהו והא אתמר) בְּשַׁעֲתָא דְּדִינָא תָּלֵי עַל עָלְמָא, וְדִינִין שַׁרְיָין, וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כּוּרְסְיָיא דְּדִינָא לְמֵידָן עָלְמָא בְּהַהוּא כּוּרְסְיָיא, כַּמָה רְשִׁימִין אִתְרְשִׁימוּ בֵּיהּ, כַּמָה פִּיתְקִין גְּנִיזִין בְּגַוִיהּ, בְּגוֹ אַחְמְתָא דְּמַלְכָּא, כֻּלְּהוּ סְפָרִים דִּפְתִּיחוּ תַּמָּן אִתְגְּנִיזוּ, וּבְגִין כַּךְ לָא אִתְנְשֵׁי מִלָּה מִן מַלְכָּא, וְהַאי כּוּרְסְיָיא לָא אַתְקָן, וְלָא שַׁרְיָא. אֶלָּא בַּחֹדֶשׁ הַשְּׁבִיעִי, דְּאִיהוּ יוֹמָא דְּדִינָא, יוֹמָא דְּכָל בְּנֵי עָלְמָא אִתְפַּקְּדוּן בֵּיהּ, כֻּלְּהוּ עַבְרִין קַמֵּי הַהוּא כֻּרְסְיָיא. וְעַל דָּא, וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, בַּחֹדֶשׁ הַשְּׁבִיעִי ודַּאי, דְּאִיהוּ דִּינָא דְּעָלְמָא.","עַל הָרֵי אֲרָרָט, אִלֵּין (סמכי כורסייא) מָארֵיהוֹן דְּדִינִין, מָארֵיהוֹן דִּיבָבָא וִילָלָא, וְכֻלְּהוּ שְׁלִיחִין (ס\"א דכלהו שכיכין) בְּהַהוּא יוֹמָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְכַמָּה מָארֵי תְּרִיסִין אִתְּעֲרוּ בְּהַאי יוֹמָא, וְכֻלְּהוּ קַיְימֵי תְּחוֹת הַהוּא כֻּרְסְיָיא, בְּדִינָא דְּעָלְמָא.","וְיִשְׂרָאֵל מְצַלָאן צְלוֹתָא בְּהַהוּא יוֹמָא, וּבָעָאן וּמִתְחַנְּנָן קַמֵּיהּ, וְתַקְעִין בַּשּׁוֹפָר, וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עָלַיְיהוּ, וּמְהַפֵּךְ דִּינָא לְרַחֲמֵי. וְכָל עִלָּאֵי וְתַתָּאֵי, פָּתְחֵי וְאָמְרֵי, (תהילים פ״ט:ט״ז) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. וְעַל דָּא בָּעֵינָא בְּהַהוּא יוֹמָא, דְּהַהוּא דְּתָקַע, דְּיָדַע עִקָּרָא דְּמִלָּה, וִיכַוִּון בֵּיהּ בִּתְרוּעָה, וְיַעְבִּיד מִלָּה בְּחָכְמְתָא, וְעַל דָּא כְּתִיב, אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, וְלָא כְּתִיב תּוֹקְעֵי תְּרוּעָה, וְהָא אִתְּמַר.","אָזְלוּ כָּל הַהוּא יוֹמָא, כַּד רָמַשׁ לֵילְיָא, סְלִיקוּ לְחַד אֲתָר, וְאַשְׁכָּחוּ חַד מְעַרְתָּא. אָמַר רִבִּי אֶלְעָזָר, לִיעוּל חַד גּוֹ מְעַרְתָּא, אִי אִשְׁתְּכַח אֲתָר דְּאִיהוּ יַתִּיר מְתַּתְקָּן. עָאל רִבִּי יוֹסֵי, וְחָמָא מְעַרְתָּא אַחֲרָא בְּגַוִּיהּ, נְהוֹרָא דִּשְׁרָגָא בֵּיהּ, שָׁמַע חַד קָלָא דְּהֲוָה אָמַר, בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת אֶל מוּל פְּנֵי הַמְּנוֹרָה יָאִירוּ שִׁבְעַת הַנֵּרוֹת. הָכָא נָטְלָא כְּנֶסֶת יִשְׂרָאֵל נְהוֹרָא, וְאִמָא עִלָּאָה מִתְעַטְּרָא, וְכֻלְּהוּ בּוּצִינִין מִינָהּ נַהֲרִין. בָּהּ תְּרֵין טוּפְסִירִין דְּקִיקִין פַּרְחִין, שׁוּשְׁבִינִין (ס\"א שבשבין) כֻּלְּהוּ קֹטְרִין לְגַבֵּי עִלָּאָה, וּמִתַּמָּן לְתַתָּא."],[[0,"כגון האי דכתיב","וכו': כמו זה שכתוב, ותנח התבה בחדש השביעי בשבעה עשר יום לחדש על הרי אררט. ודאי מקרא זה יצא מכלל התורה, ובא לספור פשוט. שואל, מה אכפת לנו אם נחה בהר זה או בזה, שהרי הוכרחה לנוח באיזה מקום שהוא. ומשיב, אלא ללמד על הכלל כולו יצא. כי הוא, רומז על זמן הדין כמ\"ש לפנינו. ואשרי הם ישראל שניתנה להם תורה עליונה תורת אמת. ומי שאומר, שספור ההוא של התורה הוא להראות על אותו ספור בלבד בא, תיפח רוחו. כי א\"כ אין התורה העליונה תורת אמת. אלא ודאי, התורה הקדושה העליונה, תורת אמת היא."],[1,"ת\"ח מלך בשר ודם","וכו': בוא וראה מלך בשר ודם, אין לפי כבודו לדבר דבורי הדיוט, כל שכן לכתוב אותם. וכי יעלה על דעתך, שמלך עליון הקב\"ה לא היה לו דברים קדושים לכתוב ולעשות מהם תורה, אלא שהוא אסף כל דברי הדיוטות כמו דברי עשו, דברי הגר, דברי לבן ביעקב, דברי האתון, דברי בלעם, דברי בלק, דברי זמרי, וקבץ אותם וכל שאר הספורים הכתובים, ועשה מהם התורה."],[2,"אי הכי אמאי","וכו': אם כן, למה נקרא תורת אמת, תורת ה' תמימה, עדות ה' נאמנה, פקודי ה' ישרים, מצות ה' ברה, יראת ה' טהורה, משפטי ה' אמת, וכתוב הנחמדים מזהב ומפז רב, שאלו הם דברי תורה. אלא ודאי התורה הקדושה העליונה, היא תורת אמת, תורת ה' תמימה, וכל מלה ומלה באה להראות דברים עליונים, כי דבר ההוא שבספור, אינו בא להראות על עצמו בלבד, אלא להראות על הכלל בא, כמו שהעמדנו."],[3,"תא חזי ותנח","וגו': בוא וראה, ותנח התיבה. מקרא זה הוא כך, כמו שיתבאר, כל שכן אחרים. בשעה שהדין תולה על העולם, והדינים שורים, והקב\"ה יושב על כסא הדין, לדון העולם בכסא ההוא, כמה רשומות נרשמו בו, כמה פסקי דינים גנוזים בתוכו, בתוך התיק של המלך, כל ספרים הפתוחים, נגנזו שמה, ומשום זה לא נשכח דבר מן המלך. וכסא ההוא אינו מתוקן ואינו שורה אלא בחדש השביעי, שהוא יום הדין, יום שכל בני העולם נפקדים בו, כולם עוברים לפני כסא ההוא. ועל זה, ותנח התיבה שהיא מלכות הנקראת תיבה, בחדש השביעי. בחדש השביעי ודאי, שהוא דין העולם."],[4,"על הרי אררט:","אררט, הוא לשון ארור, רומז על אלו בעלי הדין, בעלי יבבה ויללה, וכל השליחים הנמצאים ביום ההוא לפני הקב\"ה. וכמה בעלי מגינים מתעוררים ביום ההוא וכולם עומדים תחת כסא ההוא בדין העולם."],[5,"וישראל מצלאן צלותא","וכו': וישראל מתפללים תפלה ביום ההוא, ומבקשים ומתחננים לפניו, ותוקעים בשופר, והקב\"ה מרחם עליהם, ומהפך הדין לרחמים. וכל העליונים והתחתונים פותחים ואומרים, אשרי העם יודעי תרועה. וע\"כ צריכים ביום ההוא, שמי שתוקע, ידע עיקר סוד הדברים, ויכוין בהם בתרועה, ויעשה הדבר בחכמה עליונה, וע\"כ כתוב, אשרי העם יודעי תרועה, ולא כתוב תוקעי תרועה. וכבר למדנו. פירוש כי תקיעה יורה על חסד, ותרועה על דין, ועיקר הכונה צריך להיות על התרועה שהוא דין כדי להפך הדין לרחמים."],[6,"אזלו כל ההוא","וכו': הלכו כל אותו היום. כשהחשיך הלילה, עלו למקום אחד, ומצאו מערה אחת. א\"ר אלעזר יכנס אחד תוך המערה, אם ימצא שם מקום שהוא מתוקן יותר. נכנס ר' יוסי, וראה מערה אחרת בתוכה ואור נר מאיר בה. שמע קול אחד שהיה אומר, בהעלותך את הנרות אל מול פני המנורה יאירו שבעת הנרות. כאן לקחה כנסת ישראל, שהיא המלכות, אור, שאמא עלאה. שהיא בינה, מתעטרת, וכל הנרות, שהם ספירות המלכות, מאירים בה, ממנה. ואמרו על עצמם, ב' נשמות דקות פורחות דהיינו שמעלים מ\"ן בתורתם, וכל השושבינים, דהיינו כל המעלים מ\"ן ע\"י תורתם. שנקראים שושבינים, קושרים המלכות אל העליונה שהיא בינה, ומשם ממשיכים הארתה למטה. \u0003טופסירין,\u0004 פירושו נשמות לפי הענין. או מלשון טפסר, שפירושו שר, כי הנשמה היא מושלת על הגוף."]],[[0,"","כְּגוֹן זֶה, שֶׁכָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט. וַדַּאי פָּסוּק זֶה יָצָא מִכְּלַל הַתּוֹרָה, וּבָא בְּסִפּוּר הָעוֹלָם. מָה אִכְפַּת לָנוּ אִם שׁוֹרֶה בָזֶה אוֹ בָזֶה, שֶׁהֲרֵי בְּמָקוֹם אֶחָד שֶׁיִּשְׁרֶה? אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. וְאַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁנִּתְּנָה לָהֶם תּוֹרָה עֶלְיוֹנָה תּוֹרַת אֱמֶת. וּמִי שֶׁאוֹמֵר שֶׁאוֹתוֹ סִפּוּר שֶׁל הַתּוֹרָה, לְהַרְאוֹת עַל אוֹתוֹ סִפּוּר בִּלְבַד הוּא בָּא - תִּפַּח רוּחוֹ. שֶׁאִם כָּךְ, הִיא אֵינָהּ תּוֹרָה עֶלְיוֹנָה, תּוֹרַת אֱמֶת, אֶלָּא וַדַּאי תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה הִיא תּוֹרַת אֱמֶת."],[1,"","בֹּא רְאֵה, מֶלֶךְ בָּשָׂר וָדָם לֹא מִכְּבוֹדוֹ לְדַבֵּר דִּבְרֵי הֶדְיוֹט, כָּל שֶׁכֵּן לְכָתְבָם. וְאִם עוֹלֶה בְדַעְתְּךְ שֶׁמֶּלֶךְ עֶלְיוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הָיוּ לוֹ דְּבָרִים קְדוֹשִׁים לִכְתֹּב וְלַעֲשׂוֹת מֵהֶם תּוֹרָה, אֶלָּא שֶׁהוּא כִּנֵּס דִּבְרֵי הֶדְיוֹטוֹת, כְּמוֹ דִּבְרֵי עֵשָׂו, דִּבְרֵי הָגָר, דִּבְרֵי לָבָן בְּיַעֲקֹב, דִּבְרֵי הָאָתוֹן, דִּבְרֵי בִלְעָם, דִּבְרֵי בָלָק, דִּבְרֵי זִמְרִי, וְכִנְּסָם, וְכָל שְׁאָר הַסִּפּוּרִים שֶׁכְּתוּבִים, וְעָשָׂה מֵהֶם תּוֹרָה."],[2,"","אִם כָּךְ, לָמָּה נִקְרֵאת תּוֹרַת אֱמֶת, (תהלים יט) תּוֹרַת ה' תְּמִימָה, עֵדוּת ה' נֶאֱמָנָה, פִּקּוּדֵי ה' יְשָׁרִים, מִצְוַת ה' בָּרָה, יִרְאַת ה' טְהוֹרָה, מִשְׁפְּטֵי ה' אֱמֶת, וְכָתוּב הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב, אֵלֶּה אוֹתָם דִּבְרֵי תוֹרָה? אֶלָּא וַדַּאי תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה הִיא תּוֹרַת אֱמֶת, תּוֹרַת ה' תְּמִימָה, וְכָל דָּבָר וְדָבָר בָּא לְהַרְאוֹת דְּבָרִים (אחרים) עֶלְיוֹנִים. שֶׁאוֹתוֹ דָּבָר שֶׁל אוֹתוֹ סִפּוּר לֹא לְהַרְאוֹת עַל עַצְמוֹ יָצָא בִּלְבַד בָּא, אֶלָּא לְהַרְאוֹת עַל אוֹתוֹ כְּלָל הוּא בָּא, כְּמוֹ שֶׁבֵּאַרְנוּ."],[3,"","בֹּא רְאֵה, וַתָּנַח הַתֵּבָה וְגוֹ'. פָּסוּק זֶה כָּךְ, כָּל שֶׁכֵּן אֲחֵרִים, (הפסוק הזה כך הוא, והרי נתבאר) בְּשָׁעָה שֶׁדִּין תָּלוּי עַל הָעוֹלָם וְהַדִּינִים שְׁרוּיִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא דִין לָדוּן הָעוֹלָם בְּאוֹתוֹ כִּסֵּא, כַּמָּה רִשּׁוּמִים נִרְשְׁמוּ בוֹ, כַּמָּה פְתָקִים גְּנוּזִים בְּתוֹכוֹ בְּתוֹךְ תִּיק הַמֶּלֶךְ. כָּל הַסְּפָרִים שֶׁפְּתוּחִים שָׁם נִגְנְזוּ, וּמִשּׁוּם כָּךְ לֹא נִשְׁכַּח דָּבָר מֵהַמֶּלֶךְ, וְכִסֵּא זֶה לֹא נִתְקָן וְלֹא שׁוֹרֶה אֶלָּא בַּחֹדֶשׁ הַשְּׁבִיעִי, שֶׁהוּא יוֹם הַדִּין, יוֹם שֶׁבּוֹ כָּל בְּנֵי הָעוֹלָם נִפְקָדִים בּוֹ, כֻּלָּם עוֹבְרִים לִפְנֵי אוֹתוֹ כִּסֵּא. וְעַל זֶה וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, בַּחֹדֶשׁ הַשְּׁבִיעִי וַדַּאי, שֶׁהוּא דִּין הָעוֹלָם."],[4,"","עֵל הָרֵי אֲרָרָט - אֵלּוּ (עמודי הכסא) בַּעֲלֵי הַדִּין, בַּעֲלֵי יְבָבָה וִילָלָה, וְכֻלָּם שְׁלוּחִים (שכלם שקטים) בְּאוֹתוֹ יוֹם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכַמָּה בַּעֲלֵי מָגִנִּים מִתְעוֹרְרִים בְּיוֹם זֶה, וְכֻלָּם עוֹמְדִים תַּחַת אוֹתוֹ כִּסֵּא בְּדִין הָעוֹלָם."],[5,"","וְיִשְׂרָאֵל מִתְפַּלְלִים תְּפִלָּה בְּאוֹתוֹ יוֹם, וּמְבַקְשִׁים וּמִתְחַנְּנִים לְפָנָיו, וְתוֹקְעִים בַּשּׁוֹפָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וְהוֹפֵךְ דִּין לְרַחֲמִים, וְכָל עֶלְיוֹנִים וְתַחְתּוֹנִים פּוֹתְחִים וְאוֹמְרִים: (שם פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. וְעַל זֶה צָרִיךְ בְּאוֹתוֹ הַיּוֹם, שֶׁאוֹתוֹ שֶׁתּוֹקֵעַ שֶׁיֵּדַע עִקַּר הַדָּבָר, וִיכַוֵּן בָּהּ בִּתְרוּעָה, וְיַעֲשֶׂה הַדָּבָר בְּחָכְמָה, וְעַל זֶה כָּתוּב אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, וְלֹא כָתוּב תּוֹקְעֵי תְרוּעָה, וַהֲרֵי נִתְבָּאֵר."],[6,"","הָלְכוּ כָּל אוֹתוֹ יוֹם. כְּשֶׁיָּרַד הַלַּיְלָה עָלוּ לְמָקוֹם אֶחָד, וּמָצְאוּ מְעָרָה אַחַת. אָמַר רַבִּי אֶלְעָזָר, יִכָּנֵס אֶחָד לְתוֹךְ הַמְּעָרָה, אִם נִמְצָא מָקוֹם שֶׁהוּא יוֹתֵר מְתֻקָּן. נִכְנַס רַבִּי יוֹסֵי, וְרָאָה מְעָרָה אַחֶרֶת בְּתוֹכָהּ, אוֹר הַנֵּר בָּהּ. שָׁמַע קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת אֶל מוּל פְּנֵי הַמְּנוֹרָה יָאִירוּ שִׁבְעַת הַנֵּרוֹת. כָּאן לָקְחָה כְּנֶסֶת יִשְׂרָאֵל אוֹר, וְהָאֵם הָעֶלְיוֹנָה מִתְעַטֶּרֶת, וְכָל הַנֵּרוֹת מִמֶּנָּה מְאִירִים. בָּהּ שְׁתֵּי שַׁלְהָבוֹת דַּקִּיקוֹת פּוֹרְחוֹת, כֻּלָּם שׁוֹשְׁבִינִים (מסרגים) קְשׁוּרִים לָעֶלְיוֹנָה, וּמִשָּׁם לְמַטָּה."]]],[["שָׁמַע רִבִּי יוֹסֵי וְחַדֵּי, אָתָא לְגַבֵּי רִבִּי אֶלְעָזָר, אָמַר לֵיהּ רִבִּי אֶלְעָזָר, נֵיעוּל, דְקוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים לָן הַאי יוֹמָא, לְאִתְרַחֲשָׁא לָן בְּנִסִּין. עָאלוּ, כֵּיוָן דְּעָאלוּ, חָמוּ תְּרֵין בְּנֵי נָשָׁא, דַּהֲווֹ לָעָאן בְּאוֹרַיְיתָא. אָמַר רִבִּי אֶלְעָזָר, (תהילים ל״ו:ח׳) מַה יָקָר חַסְדֶּךָ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךָ יֶחֱסָיוּן. קָמוּ אִלֵּין, וְיַתְבֵי כֻּלְּהוּ, וְחַדּוּ כֻּלְּהוּ, אָמַר רִבִי אֶלְעָזָר, מָה יָקָר חַסְדְּךָ אֱלֹהִים, דְּאַשְׁכַּחְנָא לְכוּ. חֶסֶד עָבַד לָן קוּדְשָׁא בְּרִיךְ הוּא בַּאֲתָר דָּא, הַשְׁתָּא אַדְלִיקוּ בּוּצִינִין.","פָּתַח רִבִּי יוֹסֵי וְאָמַר. (במדבר ח׳:ב׳) בְּהַעֲלוֹתְךָ אֶת הַנֵּרוֹת, בְּהַעֲלוֹתְךָ מַמָּשׁ, בְּאַדְלָקוּתָךְ. דְּהָא כַּחֲדָא אִתְעָבִיד עַל יְדָא דְּכַהֲנָא תְּרֵין פּוּלְחָנִין. דְּאִינּוּן קִשּׁוּרָא חֲדָא. וּמַאן אִינּוּן. שֶׁמֶן וּקְטֹרֶת. כְּדִכְתִּיב, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. דִּכְתִּיב, (שמות ל׳:ח׳) וְהִקְטִיר עָלָיו אַהֲרֹן וְגוֹ'. וּכְתִיב וּבְהַעֲלוֹת אַהֲרֹן אֶת הַנֵּרוֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. מַאי שְׁנָא הָכָא בְּהֵטִיבוֹ, וּמַאי שְׁנָא הָתָם וּבְהַעֲלוֹת. אָמַר רִבִּי יְהוּדָה, כֹּלָּא חַד מִלָּה.","רִבִּי יוֹסֵי אָמַר, בְּהֵטִיבוֹ: כְּמָה דְאַתְּ אָמֵר (שיר השירים א׳:ב׳) כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן. טוֹבִים: רָוִוי חַמְרָא. כְּמָה דְאַתְּ אָמֵר, (ירמיהו מ״ד:י״ז) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים. רִבִּי יְהוּדָה אָמַר, הֲטָבָה מַמָּשׁ. כְּמָה דְאַתְּ אָמֵר (משלי ט״ו:ט״ו) וְטוֹב לֵב מִשְׁתֶּה תָמִיד. וּבְהַעֲלוֹת, דְּהָא בְּזִמְנָא דְּאִתְּשַׁקְיָין וְאִתְרַוְיָין מִשַּׁקְיוּ דְּנַחֲלָא, כְּדֵין עִלָּאִין עִלּוּיָא, וּבִרְכָאן (ס\"א עלאין מתתאין) אִשְׁתַּכְּחוּ בְּכֻלְּהוּ, וְחַדּוּ בְּכֹלָּא. וְעַל דָּא וּבְהַעֲלוֹת.","רִבִּי אֲחָא אָמַר, בְּשַׁעֲתָא דַּעֲמִיקָא דְּכֹלָּא נָהִיר, (ס\"א דסתימא דכלא נהיר) נָהִיר בְּנַחֲלָא. וְנַחֲלָא, נָגִיד (ס\"א נהיר) בְּאֹרַח מֵישָׁר לְאַשְׁקָאָה כֹּלָּא. כְּדֵין כְּתִיב, בְּהַעֲלוֹת (נ\"א בהטיבו) בְּגִין דְּהָא מֵעוּמְקָא דְּכֹלָּא נָפְקֵי, בְּהַעֲלוֹת דְּאָתֵי מִסִּטְרָא עִלָּאָה, (בראשית כ\"א א') דְּעֲמִיקָא (ס\"א דסתימא) דְּכֹלָּא, דְּאִקְרֵי מַחֲשָׁבָה. וְכֹלָּא חַד מִלָּה, וּכְדֵין כְנֶסֶת יִשְׂרָאֵל אִתְבָּרְכָא, וּבִרְכָּאן אִשְׁתַּכְּחֵי בְּכֻלְּהוּ עָלְמִין.","רִבִּי יִצְחָק פָּתַח, כְּתִיב (מלכים א ח׳:י״ג) בָּנֹה בָּנִיתִי בֵּית זְבוּל לָךְ מָכוֹן לְשִׁבְתְּךָ עוֹלָמִים. בֵּית זְבוּל, בֵּית זְבוּל וַדַּאי, כַּד אִתְפְּקָדוּ בִּידָהָא, כָּל גִּנְזֵי מַלְכָּא, וְשַׁלְטָא בְּהוּ. כְּדֵין אִקְרֵי בֵּית זְבוּל. וְרָקִיעַ חַד אִית דְּאִקְרֵי זְבוּל, דְּהָא דָּא אַשְׁכַּח לְקַבְּלָא בִּרְכָאָן, וּלְסַדְּרָא כֹּלָּא, וְהַאי אִקְרֵי בֵּית זְבוּל.","תָּא חֲזֵי, כְּתִיב (דברים ל״ג:י״ח) וְלִזְבוּלֻן אָמַר שְׂמַח זְבוּלֻן בְּצֵאתֶךָ וְיִשָּׂשׂכָר בְּאָהֳלֶךָ, מְלַמֵּד דְּאִשְׁתָּתָפוּ כַּחֲדָא. דָּא נָפִיק וְאָגַח קְרָבָא, וְדָא יָתִיב וְלָעֵי בְּאוֹרַיְיתָא. וְדָא יָהִיב חוּלָקָא לְדָא, וְדָא יָהִיב חוּלָקָא לְדָא. בְּחוּלָקֵיהּ דִּזְבוּלוּן יַמָּא, וּכְּנֶסֶת יִשְׂרָאֵל אִקְרֵי יָם כִּנֶּרֶת. וְהָכִי אִתְחֲזֵי, בְּגִין דְּהָא תְּכֵלֶת נָפִיק מִתַּמָּן, וְאוֹקְמוּהָ, דְּהָא לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא, יָם כִּנֶּרֶת לְעֵילָּא, יָם כִּנֶּרֶת לְתַתָּא. תְּכֵלֶת לְעֵילָּא, תְּכֵלֶת לְתַתָּא, וְכֹלָּא בַּאֲתָר חַד.","וְעַל דָּא יָרִית זְבוּלוּן, לְמֵיפַּק לְאַגָּחָא קְרָבָא, וּמְנָלָן דְּהָכִי הוּא. דִּכְתִּיב, (דברים ל״ג:י״ט) עַמִּים הַר יִקְרָאוּ שָׁם יִזְבְּחוּ זִבְחֵי צֶדֶק. זִבְחֵי צֶדֶק וַדַּאי. מַאי טַעְמָא. כִּי שֶׁפַע יַמִּים יִינָקוּ. וְיִשָּׂשׂכָר חוּלָקֵיהּ בְּאוֹרַיְיתָא, וְיָהִיב לִזְבוּלוּן חוּלָקָא דְּאוֹרַיְתָא וַדַּאי, וְעַל דָּא אִשְׁתָּתָּפוּ כַּחֲדָא, לְאִתְבָּרְכָא זְבוּלוּן מִיִשְּׂשׂכָר, דְּבִרְכָתָא דְּאוֹרַיְיתָא, הִיא בִּרְכָתָא דְּכֹלָּא.","רִבִּי אַבָּא אָמַר, אַחֲסַנְתָּא דְּאוֹרַיְיתָא ודַּאי הָכִי הוּא, וְדַרְגָּא דָּא שְׁתִיתָאָה יָהִיב אֲגָר (ס\"א חד שתיתאה יהיב אגר) אוֹרַיְיתָא, וְאַחֲסִין לָהּ לִכְּנֶסֶת יִשְׂרָאֵל, אַחֲסִין חִוָּורָא לִתְכֶלְתָּא. וְעַל דָּא תָּנֵינָן, מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן, דְּיִשְׁתְּמוֹדָען גְּוָונֵי, דְּהָא כְּדֵין אִקְרֵי בֹּקֶ\"ר, וְחִוָּורָא אָתֵי לְעָלְמָא, וּתְכֶלְתָּא אִתְעַבָר. וְעַל דָּא כָּל קְרָבִין דְּמַלְכָּא, וְכָל זַיְינֵי מַלְכָּא בִּידָהָא אִתְמָנָן, וְהָא אוֹקִימְנָא. (חסר תחילת המאמר ועיין פרשת וילך רפ\"ו ע\"א)","(במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם, בְּאֵר, דָּא כְּנֶסֶת יִשְׂרָאֵל. חֲפָרוּהָ שָׂרִים, דָּא אַבָּא וְאִמָא, דְּאוֹלִידוּ לָהּ. כָּרוּהָ נְדִיבֵי הָעָם, אִלֵּין אֲבָהָן. דִּכְתִּיב, (תהילים מ״ז:י׳) נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם וְגוֹ'. בְּגִין לְאִתְבָּרְכָא מִנְּהוֹן, עַל יְדֵי דְּדַרְגָא חַד, וּמַנּוֹ. צַדִּיק דְּקָאִים עָלָה. וְעַל דָּא אַמְרֵינָן, כַּד הַאי בְּאֵר נַטְלָא, בְּסִיוּעָא דַּאֲבָהָן נַטְלָא."],[[0,"שמע ר' יוסי","וכו': שמע ר\"י ושמח. בא אל ר' אלעזר, א\"ל רבי אלעזר. נכנס, כי הקב\"ה הקדים אותנו ביום הזה לעשות לנו נסים. נכנסו. כיון שנכנסו ראו שני בני אדם שהיו עוסקים בתורה. א\"ר אלעזר מה יקר חסדך אלקים ובני אדם בצל כנפיך יחסיון. קמו אלו. וישבו כולם ושמחו כולם. א\"ר אלעזר, מה יקר חסדך אלקים שמצאתי אתכם. חסד עשה לנו הקב\"ה במקום הזה. עתה הדליקו הנרות. כלומר שיאמרו דברי תורה להעלות מ\"ן להדליק ספירות המלכות מאמא. כמו שאמרו לעיל."],[1,"פתח ר' יוסי","וכו': פתח ר' יוסי ואמר, בהעלותך את הנרות, פירושו בהעלותך ממש, דהיינו בהדלקתך, כי נעשה ע\"י הכהן ב' עבודות שהם קשר אחד, ומי הם שמן וקטרת, שה\"ס חו\"ב, כמ\"ש, שמן וקטרת ישמח לב. שכתוב והקטיר עליו אהרן וגו' בהטיבו את הנרות יקטירנה. וכתוב ובהעלות אהרן את הנרות בין הערבים יקטירנה. שואל, מה השינוי שכתוב כאן בהטיבו, ומה השינוי שכתוב שם ובהעלות. אמר רבי יהודה הטבה והעלאה, הכל הוא דבר אחד. כי הטבה היא כמו הדלקה."],[2,"ר' יוסי אמר","וכו': רי\"א בהטיבו, הוא כמו שאתה אומר, כי טובים דודיך מיין, כי הרויים. דהיינו השבעים, מיין הם טובים. כש\"א ונשבע לחם ונהיה טובים. כלומר כל מי ששבע מיין או מלחם, שה\"ס אורות דג\"ר, נקראים טובים. ונמצא, בהטיבו את הנרות, היינו שימשיך בשפע את האורות המכונים יין ולחם, שה\"ס הארת חכמה וחסדים, ר' יהודה אומר הטבה ממש. שחולק על ר' יוסי שאומר, שהטבה היא תוצאה משפע האורות, אלא האורות דמשתה, שה\"ס הארת חכמה, הן עצמם נקראים הטבה, כש\"א, וטוב לב משתה תמיד. \u0003ובהעלות\u0004 פירושו, שבזמן שהספירות נשקים ונרוים משקוי של הנחל, שהנחל הוא בינה והשקוי שלו הוא מחכמה, אז מתעלים העליונים וברכות נמצאות בכולם וכולם שמחים. ונמצא שהטבת הנרות היא הארת החכמה הנמשכת מבינה שה\"ס יין. והעלאת הנרות, ה\"ס המשכת שפע החסדים דלא פסיק, מן החכמה. וע\"כ כתוב, ובהעלות."],[3,"רבי אחא אמר","וכו': רא\"א, בשעה שהעמוק מכל, שהוא אבא עלאה, מאיר, מאיר בנחל, שהוא אמא עלאה, והנחל נמשך, בדרך ישר, דהיינו ע\"י קו האמצעי, שהוא ז\"א, להשקות הכל, דהיינו כל המדרגות שבמלכות, אז כתוב, \u0003בהעלות,\u0004 משום שהכל יוצא מן העמוק מכל, \u0003בהעלות,\u0004 פירושו, שבא מצד העליון העמוק מכל שנקרא מחשבה, שהוא אבא, והכל הוא דבר אחד. דהיינו שהוא דבר אחד עם שאמרו ר\"י ור\"י, ואז כנסת ישראל מתברכת והברכות נמצאות בכל העולמות."],[4,"ר' יצחק פתח","וכו': רי\"פ, כתוב, בנה בניתי בית זבול לך מכון לשבתך עולמים. \u0003בית זבול,\u0004 בית זבול ודאי כי כשנפקדו בידי המלכות כל גנזי המלך שהוא ז\"א, והיא שולטת בהם אז נקראת בית זבול. ורקיע אחד יש שנקרא זבול. משום שהוא עומד לקבל ברכות ולסדר הכל. וזו, המלכות כששולטת על הכל נקראת ג\"כ בית זבול."],[5,"ת\"ח כתיב ולזבולן","וגו': בוא וראה, כתוב ולזבולן אמר שמח זבולן בצאתך ויששכר באהלך, מלמד שנשתתפו יחד, זה יצא ועשה מלחמה, וזה יושב ועוסק בתורה, וזה נותן חלק לזה, משללו. וזה נותן חלק לזה, מתורתו. כי יששכר ה\"ס ת\"ת, וזבולן ה\"ס מלכות. בחלקו של זבולן הוא הים. וכנסת ישראל, שהיא המלכות, נקראת ים כנרת. וכך ראוי להקרא, משום שהתכלת יוצא משם, שתכלת ה\"ס מלכות וכנרת היא מלכות. והעמידוהו, כי למטה הוא כעין של מעלה, ים כנרת למעלה שהוא מלכות, ים כנרת למטה. תכלת למעלה, שהיא מלכות, תכלת למטה. והכל הוא במקום אחד, שהוא מלכות."],[6,"וע\"ד ירית זבולן","וכו': וע\"כ ירש זבולן לצאת לערוך מלחמה. משום שהוא בחינת מלכות. ומאין לנו שכך הוא. שכתוב, עמים הר יקראו שם יזבחו זבחי צדק. זבחי צדק ודאי, דהיינו של מלכות הנקראת צדק. מהו הטעם. הוא כי שפע ימים יינקו, דהיינו השפע ע\"י מלחמות, ויששכר חלקו בתורה. ונותן לזבולן חלקו בתורה, ודאי, וע\"כ נשתתפו יחדיו, שיתברך זבולן מיששכר. כי הברכה שבתורה היא ברכת כל."],[7,"ר' אבא אמר","וכו': רא\"א, הנחלה של התורה ודאי כך הוא, ומדרגה זו היא הששית, דהיינו יסוד, שנותן שכר התורה ומנחילה לכנסת ישראל, ומנחיל לבן שהוא חסד, לתכלת שהוא דין. וע\"כ למדנו משיכיר בין תכלת ללבן, לקריאת שמע (ברכות ט') דהיינו שהגוונים יהיו ניכרים, אז נקרא בקר, והלבן בא לעולם, והתכלת, שהוא דין, נעבר מן העולם. וע\"כ כל המלחמות של המלך וכל כלי זיין של המלך נתמנו בידי המלכות שאז נקרא בית זבול. וכן זבולן, כנ\"ל. וכבר העמדנו."],[8,"באר חפרוה שרים","וגו': באר חפרוה שרים כרוה נדיבי העם. \u0003באר,\u0004 זו כנסת ישראל, שהיא המלכות. \u0003חפרוה שרים,\u0004 זה הוא אבא ואמא שהולידו המלכות, \u0003כרוה נדיבי עם,\u0004 אלו הם האבות, שהם חג\"ת דז\"א, שכתוב, נדיבי עמים נאספו עם אלקי אברהם. ואלקי אברהם הוא חסד דז\"א שגבורה ות\"ת נמשכים ממנו. וכרוה נדיבי עם, פירושו שתקנו אותה כדי להתברך מהם ע\"י מדרגה אחת שהיא צדיק, דהיינו יסוד דז\"א, העומד עליה ומשפיע לה כל מה שבחג\"ת, וע\"כ אנו אומרים, כשבאר הזו נוסעת, בעזרת האבות היא נוסעת."]],[[0,"","שָׁמַע רַבִּי יוֹסֵי וְשָׂמַח. בָּא אֶל רַבִּי אֶלְעָזָר. אָמַר לוֹ רַבִּי אֶלְעָזָר, נִכָּנֵס, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּימָנוּ הַיּוֹם הַזֶּה לְהַרְחִישׁ לָנוּ בְנִסִּים. נִכְנְסוּ. כֵּיוָן שֶׁנִּכְנְסוּ, רָאוּ שְׁנֵי בְּנֵי אָדָם שֶׁהָיוּ עוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר, (תהלים לו) מַה יָּקָר חַסְדְּךְ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךְ יֶחֱסָיוּן. קָמוּ אֵלֶּה, וְיָשְׁבוּ כֻלָּם, וְשָׂמְחוּ כֻלָּם. אָמַר רַבִּי אֶלְעָזָר, מַה יָּקָר חַסְדְּךְ אֱלֹהִים, שֶׁמָּצָאנוּ אֶתְכֶם. חֶסֶד עָשָׂה לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמָקוֹם זֶה. עַכְשָׁו הַדְלִיקוּ נֵרוֹת."],[1,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת, בְּהַעֲלֹתְךְ מַמָּשׁ, בְּהַדְלָקָתְךְ. שֶׁהֲרֵי כְּאַחַת נַעֲשׂוֹת עַל יְדֵי הַכֹּהֵן שְׁתֵּי עֲבוֹדוֹת, שֶׁהֵן קֶשֶׁר אֶחָד, וּמָהֵן? שֶׁמֶן וּקְטֹרֶת, כְּמוֹ שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, שֶׁכָּתוּב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן וְגוֹ'. וְכָתוּב וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. מַה שּׁוֹנֶה כָּאן בְּהֵיטִיבוֹ, וּמַה שּׁוֹנֶה שָׁם וּבְהַעֲלֹת? אָמַר רַבִּי יְהוּדָה, הַכֹּל דָּבָר אֶחָד."],[2,"","רַבִּי יוֹסֵי אָמַר, בְּהֵיטִיבוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים א) כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן. טוֹבִים - רְווּיֵי יַיִן, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה מד) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים. רַבִּי יְהוּדָה אָמַר, הֲטָבָה מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָמִיד. וּבְהַעֲלֹת, שֶׁהֲרֵי בִּזְמַן שֶׁמֻּשְׁקִים וּמֻרְוִים מֵהַשְׁקָאַת הַנַּחַל, אָז עֶלְיוֹנִים מִתְעַלִּים, וּבְרָכוֹת (עליונות ותחתונות) נִמְצָאוֹת בְּכֻלָּם, וּשְׂמֵחִים בַּכֹּל. וְעַל זֶה וּבְהַעֲלֹת."],[3,"","רַבִּי אָחָא אָמַר, בְּשָׁעָה שֶׁעֹמֶק הַכֹּל מֵאִיר, (שסתום הכל מאיר) מֵאִיר בַּנַּחַל, וְהַנַּחַל שׁוֹפֵעַ (מאיר) בְּדֶרֶךְ יָשָׁר לְהַשְׁקוֹת הַכֹּל, וְאָז כָּתוּב בְּהַעֲלֹת (בהיטיבו), מִשּׁוּם שֶׁזֶּה יוֹצֵא מֵעֹמֶק הַכֹּל. בְּהַעֲלֹת, שֶׁבָּא מִצַּד עֶלְיוֹן שֶׁל עֹמֶק (של סתום) הַכֹּל שֶׁנִּקְרָא מַחֲשָׁבָה. וְהַכֹּל דָּבָר אֶחָד. וְאָז כְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת, וּבְרָכוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת."],[4,"","רַבִּי יִצְחָק פָּתַח, כָּתוּב (מלכים א ח) בָּנֹה בָּנִיתִי בֵּית זְבֻל לָךְ מָכוֹן לְשִׁבְתְּךְ עוֹלָמִים. בֵּית זְבֻל, בֵּית זְבוּל וַדַּאי. כְּשֶׁנִּפְקְדוּ בְיָדֶיהָ כָּל גִּנְזֵי הַמֶּלֶךְ וְשׁוֹלֶטֶת בָּהֶם, אָז נִקְרָא בֵית זְבוּל. וְרָקִיעַ אֶחָד יֵשׁ שֶׁנִּקְרָא זְבוּל, שֶׁהֲרֵי זֶה נִמְצָא לְקַבֵּל בְּרָכוֹת וּלְסַדֵּר הַכֹּל, וְזֶה נִקְרָא בֵּית זְבוּל."],[5,"","בֹּא רְאֵה, כָּתוּב (דברים לג) וְלִזְבוּלֻן אָמַר שְׂמַח זְבוּלֻן בְּצֵאתֶךְ וְיִשָּׂשכָר בְּאָהֳלֶךְ. מְלַמֵּד שֶׁהִשְׁתַּתְּפוּ כְאֶחָד. זֶה יוֹצֵא וְעוֹרֵךְ קְרָב, וְזֶה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, וְזֶה נוֹתֵן חֵלֶק לָזֶה, וְזֶה נוֹתֵן חֵלֶק לָזֶה. בְּחֵלֶק זְבוּלוּן הַיָּם, וּכְנֶסֶת יִשְׂרָאֵל נִקְרֵאת יָם כִּנֶּרֶת. וְכָךְ רָאוּי, מִשּׁוּם שֶׁתְּכֵלֶת זוֹ יוֹצֵאת מִשָּׁם, וּפֵרְשׁוּהָ, שֶׁהֲרֵי לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. יָם כִּנֶּרֶת לְמַעְלָה - יָם כִּנֶּרֶת לְמַטָּה, תְּכֵלֶת לְמַעְלָה - תְּכֵלֶת לְמַטָּה, וְהַכֹּל בְּמָקוֹם אֶחָד."],[6,"","וְעַל זֶה יָרַשׁ זְבוּלוּן, לָצֵאת לַעֲרֹךְ קְרָב. וּמִנַּיִן לָנוּ שֶׁכָּךְ זֶה? שֶׁכָּתוּב (שם) עַמִּים הַר יִקְרָאוּ שָׁם יִזְבְּחוּ זִבְחֵי צֶדֶק. זִבְחֵי צֶדֶק בְּוַדַּאי. מָה הַטַּעַם? כִּי שֶׁפַע יַמִּים יִינָקוּ. וְיִשָּׂשכָר חֶלְקוֹ בַתּוֹרָה, וְנוֹתֵן לִזְבוּלוּן חֵלֶק שֶׁל הַתּוֹרָה בְּוַדַּאי. וְעַל זֶה הִשְׁתַּתְּפוּ כְאֶחָד, לְהִתְבָּרֵךְ זְבוּלוּן מִיִּשָּׂשכָר, שֶׁבִּרְכַּת הַתּוֹרָה הִיא בִּרְכַּת הַכֹּל."],[7,"","רַבִּי אַבָּא אָמַר, יְרֻשַּׁת הַתּוֹרָה בְּוַדַּאי כָּךְ הִיא, וְדַרְגָּה שִׁשִּׁית זוֹ נוֹתֶנֶת שְׂכַר (ששית אחת נותנת שכר) תּוֹרָה, וּמוֹרִישָׁה לָהּ לִכְנֶסֶת יִשְׂרָאֵל, מוֹרִישׁ הַלָּבָן לַתְּכֵלֶת. וְעַל זֶה שָׁנִינוּ, (ברכות א) מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן, שֶׁיִּוָּדְעוּ הַגְּוָנִים, שֶׁהֲרֵי אָז נִקְרָא בֹּקֶ\"ר, וְהַלֹּבֶן בָּא לָעוֹלָם, וְהַתְּכֵלֶת נֶעֱבַר. וְעַל זֶה כָּל קְרָבוֹת הַמֶּלֶךְ וְכָל כְּלֵי זֵין הַמֶּלֶךְ נִמְנוּ בְיָדֶיהָ, וַהֲרֵי בֵּאַרְנוּ."],[8,"","בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. בְּאֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. חֲפָרוּהָ שָׂרִים - זֶה אַבָּא וְאִמָּא שֶׁהוֹלִידוּ אוֹתָהּ. כָּרוּהָ נְדִיבֵי הָעָם - אֵלּוּ הָאָבוֹת, שֶׁכָּתוּב (תהלים מז) נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם וְגוֹ'. בִּשְׁבִיל לְהִתְבָּרֵךְ מֵהֶם עַל יְדֵי דַרְגָּה אַחֶרֶת. וּמִי הַדַּרְגָּה? צַדִּיק שֶׁעוֹמֵד עָלֶיהָ. וְעַל זֶה אָמַרְנוּ, כְּשֶׁבְּאֵר זוֹ נוֹטֶלֶת - בְּסִיּוּעַ הָאָבוֹת נוֹטֶלֶת."]]],[["וְאִקְרֵי בְּאֵר, וְאִקְּרֵי יָם. אִקְרֵי בְּאֵר, בְּשַׁעֲתָא דְּיִצְחָק נָפִק מִזַּיְינָא מִסִּטְרָא דְּאִימָא, וְאָתֵי לְאַמְשָׁכָא אֲבַּתְרָא דְּדָא, וּמַלֵּי לָהּ, כְּדֵין אִקְרֵי בְּאֵר דְּיִצְחָק. בְּאֵר דְּמִרְיָם. וְהָא אוּקְמוּהָ. יָם כַּד אִתְנַהֲרָא מִנָּהֲרָא עִלָּאָה דְּאַבָּא, כְּדֵין אִקְרֵי יָם, דְּנַחֲלִין אַזְלִין לְגַוָּוהּ, כְּמָה דְאַתְּ אָמֵר (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא.","וּמִיּוֹמָא דְּגָלְתָה כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא, כְּתִיב (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם, דָּא כְנֶסֶת יִשְׂרָאֵל. וְנָהָר יֶחֱרָב וְיָבֵשׁ, דָּא צַדִּיק. וְעַל דָּא כְּתִיב, (ישעיהו נ״ז:א׳) הַצַּדִיק אָבָד וְגוֹ'. דְּהוּא הֲוָה נָהָר עִלָּאָה וְיַקִירָא, דְּעָיִיל בְּגַוָוהּ, וְהוּא כָּנִישׁ כָּל אִינּוּן נַהֲרִין וּנַחֲלִין, דְּנַגְדִּין מִנְּגִידוּ דְּהַהוּא נָהָר קַדִּישָׁא, דְּלָא פַּסְקִין מֵימוֹי לְעָלְמִין, דְּנָגִיד וְנָפִיק מֵעֵדֶן עִלָּאָה, וְהוּא עָיֵיל בְּגַוָּוהּ וּמַלֵּי אַגְמָהָא, וּמִתַּמָּן יָרְתִין עָלְמִין כֻּלְּהוּ (אתזנו וירתין) בִּרְכָּן בְּכֹלָּא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְבָּרְכָא כְּנֶסֶת יִשְׂרָאֵל, עָלְמִין כֻּלְּהוּ אִתְבָּרְכָן, וְיִשְׂרָאֵל לְתַתָּא, יַנְקִין וּמִתְבָּרְכָן בְּגִינָהּ. וְהָא אוֹקִימְנָא דְּהִיא אַגָנָא עָלַיְיהוּ, דְּיִשְׂרָאֵל, כְּמָה דְּאִתְּמַר.","כְּתִיב (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ וְגוֹ'. מַלְאַךְ הָאֱלֹהִים דָּא כְּנֶסֶת יִשְׂרָאֵל. וְהָא אוֹקִימְנָא, דְּהַהִיא שַׁעֲתָא, בְּסִיוּעַ דַּאֲבָהָן נַטְלָא. וְכַד אִינּוּן מִשְׁתַּכְּחִין לְגַבָּהּ, כֹּלָּא מִשְׁתַּכְּחֵי. וּבְגִין כָּךְ אִתְמְסַר בְּאִלֵּין קְרָאֵי שְׁמָא קַדִּישָׁא, דְּכָלִיל בְּהוֹן אֲבָהָתָא, כְּמָה דְּאוֹקִימְנָא. חַד קְרָא כְּסִדְרָא, וְחַד לְמַפְרֵעַ, וְחַד כְּסִדְרָא.","וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ וְגוֹ', דָּא כְּסִדְרָא בְּגִין דְּאַבְרָהָם אִשְׁתְּכַח הָכָא, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרֵיהּ, וְעַל דָּא אִיהוּ כְּסִדְרָא כְּגַוְונָא דָּא. (אמר המגי\"ה כאן מצאתי כתוב פסוק ויסע כסדר כל אות ואות בבית אחד במרובע עם זה הלשון ותמצאם כולם בסוף ח\"ב בסוף שמות)","הָכָא אִתְעֲטָּר אַבְרָהָם בְּעִטְרוֹי, וְאַעְטַּר לָהּ לִכְנֶסֶת יִשְׂרָאֵל, וְאִלֵּין אַתְוָון כֻּלְּהוּ בְּאֹרַח מֵישָׁר, לְמֵיהַךְ בִּימָמָא. דִּכְתִיב (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְעַל דָּא כְּתִיב וַיִּסַּע, אֵימָתַי נַטְלִין בְּמַטְלָנַיְיהוּ, הֲוִי אֵימָא בִּימָמָא, כַּד נָהִיר שִׁמְשָׁא. וְדָא חַד קְרָא דְּאִיהוּ בְּשִׁבְעִין וּתְרֵין אַתְוָון.","תִּנְיָינָא דְּיִצְחָק, הָכִי נָמֵי דְּאִשְׁתְּכַח בְּע\"ב אַתְוָון, לְאִשְׁתַּכְחָא בְּדִינָא לְגַבֵּי מִצְרָאֵי וּלְגַבֵּי יִשְׂרָאֵל בְּרַחֲמֵי. וְעַל דָּא כְּתִיב, וַיָּבֹא בֵּין מַחֲנֵה מִצְרַיִם וּבֵין מַחֲנֵה יִשְׂרָאֵל, לָקֳבֵיל אִלֵּין וְלָקֳבֵיל אִלֵּין. וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, דְּהָכִי הוּא יוֹמָא דְּיִצְחָק, דְּעִיבָא הֲוִי, עֲנָנָא וַחֲשׁוֹכָא מִנֵּיהּ הוּא. וּבְגִין כַּךְ סִדוּרָא דְּאַתְוָון לְמַפְרֵעַ, (באורחא עקימא) וְלָא בְּאֹרַח מֵישָׁר, כְּגַוְונָא דָּא. (כאן מצאתי כתוב פסוק ויבא למפרע כל אות ואות בבית אחד במרובע עם זה הלשון)","וְעַל דָּא אַתְוָון כֻּלְּהוּ לְמַפְרֵעַ, דִּכְתִּיב וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, דְּכֵיוָן דְּעָאל יִצְחָק בְּדִינוֹי, לֹא קָרַב זֶה אֶל זֶה. כְּתִיב זֶה אֶל זֶה, אִינּוּן דְּאָתוּ מִסִּטְרָא דְּאַבְרָהָם, לָא קְרִיבוּ דָּא בְּדָא. דְּהָא לָא יַכְלִין, בְּגִין דְּהַאי בְּאֵר אִתְדַּבְּקָא בְּיִצְחָק. כְּמָה דְאַתְּ אָמֵר, וַיָּאֶר אֶת הַלָּיְלָה. דְּכַד אִתְמַלְּיָיא לְאִתְחַבְּרָא (ס\"א לאתקפא) בְּיִצְחָק, לֹא קָרַב זֶה אֶל זֶה, וְלָא יָכִיל לְקָרְבָא. עַד דְּאָתָא יַעֲקֹב, וְאִתְחַבָּר בְּאַבְרָהָם, וְנָטַל לְיִצְחָק, וְשָׁארִי לֵיהּ בְּאֶמְצָעִיתָא, כְּדֵין אִתְקְשַׁר מְהֵימְנוּתָא דָּא בְּדָא וְדָא בְּדָא, וְאִשְׁתְּזִיבוּ יִשְׂרָאֵל.","וְתָנֵינָן, בַּאֲתָר דַּאֲבָהָתָא אִשְׁתַּכְחֵי, שְׁאָר צַדִיקַיָּיא מִשְׁתַּכְחֵי גַּבַּיְיהוּ, וְעַל דָּא שְׁמָא דָּא, סָלִיק לְסִטְרִין אַחֲרָנִין מִתְפָּרְשָׁן, אַף עַל גַּב דְּכֻלְּהוּ נָפְקִין לְאָרְחָא חַד."],[[0,"ואקרי באר ואקרי ים","וכו': ופעם, המלכות נקראת באר, ופעם נקראת ים. נקראת \u0003באר,\u0004 בשעה שיצחק, שהוא גבורה דז\"א, יוצא מזויין, מקו שמאל מצד אמא, ובא להמשיך הארת חכמה מאמא אחר זו המלכות, וממלא אותה, בסו\"ה שמאלו תחת לראשי, אז נקראת בארו של יצחק, או בארה של מרים. וכבר העמידוהו. \u0003ים\u0004 היא נקראת, כשמאירה מנהר העליון דאבא, שמקבלת אז חכמה וחסדים, אז נקראת ים, שנחלים הולכים אליה. כמש\"א, כל הנחלים הולכים אל הים והים איננו מלא."],[1,"ומיומא דגלתה כנסת","וכו': ומיום שגלתה כנסת ישראל, שהיא המלכות, בגלות, כתוב, אזלו מים מני ים, זו כנסת ישראל הנקראת ים, יחרב ויבש, זה צדיק, שהוא יסוד. וע\"כ כתוב, הצדיק אבד וגו', שהוא היה נהר העליון והיקר שנכנס בתוכה, והוא קבץ כל אלו נהרות ונחלים, הנמשכים מן ההמשכה של נהר הקדוש ההוא שאין מימיו פוסקים לעולם, דהיינו הבינה, הנמשך ויוצא מעדן העליון, שהוא חכמה סתימאה, שה\"ס הבינה שיצאה מראש א\"א, בסו\"ה ונהר יוצא מעדן, שהיא המקור לכל המוחין דזו\"ן ותחתונים. והוא נכנס בתוכה וממלא האגמים שלה דהיינו ספירות המלכות, ומשם יורשים העולמות כל הברכות בכל השלמות."],[2,"ת\"ח בשעתא דאתברכא","וכו': בוא וראה בשעה שנתברכת כנסת ישראל, מתברכים כל העולמות, וישראל למטה יונקים ומתברכים בשבילה. והעמדנו, שהמלכות מגינה על ישראל, כמו שלמדנו."],[3,"כתיב ויסע","וגו': כתוב ויסע מלאך האלקים ההולך וגו', מלאך האלקים זה כנסת ישראל, והעמדנו שבשעה ההיא, שנאמר ויסע מלאך וגו', נסעה בעזרת האבות, כלומר שקבלה אז מג' קוין חג\"ת הנקראים אבות. וכשאלו נמצאים אצלה. הכל נמצא, הן חכמה והן חסדים. ומשום זה נמסר באלו הפסוקים השם הקדוש ע\"ב, שהאבות כלולים בו, כמו שהעמדנו, פסוק אחד כסדר, שיורה על קו ימין, ופסוק אחד למפרע המורה על קו שמאל, ופסוק אחד כסדר המורה על קו האמצעי. (כמ\"ש לעיל בזהר בשלח דף נ' ע\"ש)."],[4,"ויסע מלאך האלקים","וגו': ויסע מלאך האלקים ההולך וגו'. מקרא זה הוא כסדר, משום שאברהם נמצא כאן, שהוא חסד, קו ימין, וכל אלו הבאים מצדו, וע\"כ האותיות הן כסדר כעין זה."],[5,"הכא אתעטר אברהם","וכו': כאן נתעטר אברהם שהוא חסד, בעטרותיו, והעטיר לכנסת ישראל, שהיא המלכות, בדרך יושר, ללכת ביום, דהיינו בחסד, שכתוב, יומם יצוה ה' חסדו ובלילה שירה עמי. וע\"כ כתוב, \u0003ויסע,\u0004 מתי נוסעים במסעיהם הוי אומר, ביום, כשמאיר השמש. שהוא ז\"א, שאז שליטת החסד. וזה הוא מקרא אחד, שבו ע\"ב אותיות."],[6,"תניינא, דיצחק, הכי","וכו': מקרא השני הוא של יצחק, דהיינו גבורה דז\"א, ונמצא גם כן בע\"ב אותיות, להמצא בדין אל המצרים, ואל ישראל ברחמים. וע\"כ כתוב כאן, ויבא בין מחנה מצרים ובין מחנה ישראל, דהיינו כנגד אלו וכנגד אלו. כי יצחק ה\"ס הארת החכמה, ואין הארת החכמה נמשכת אלא עם דינים קשים לרשעים (כנ\"ל אד\"ר אות רי\"ט) ושכר טוב לצדיקים. שז\"ס, ויבא בין מחנה מצרים ובין מחנה ישראל. \u0003ויהי הענן והחשך,\u0004 כי כך הוא יום של יצחק, יום המעונן הוא. שהענן והחשך ממנו הוא. ומשום זה סדור האותיות הוא למפרע ולא בדרך ישר. כעין זה."],[7,"ועל דא אתוון","וכו': וע\"כ האותיות כולן הם למפרע, שכתוב, ויהי הענן והחשך שהוא דין, ולמפרע רומז על דין. כי כיון שנכנס יצחק בדינים שלו, לא קרב זה אל זה. כתוב, \u0003זה אל זה,\u0004 שהם אלו הבאים מצד אברהם, דהיינו מן אור החסד, לא קרבו זה אל זה. כלומר שהקו ימין שהוא חסד לא קרב להשפיע לקו שמאל שהוא גבורה, וע\"כ היה השמאל בחכמה בלא חסדים שהוא דין קשה והוא חשך (כנ\"ל ב\"א דף מ\"ז ד\"ה נפק) וז\"א שהוא חסד לא קרב אל הנוקבא להשפיע בה חסדים, והיתה הנוקבא מקבלת מקו שמאל חכמה בלי חסדים שהוא חשך. כי לא יכלו לקרב זה אל זה, משום שבאר הזו, שהיא מלכות, נתדבקה ביצחק, שהוא קו שמאל. כש\"א ויאר את הלילה. שהקו שמאל האיר את הלילה שהוא המלכות. וכשנתמלאה להתחבר ביצחק לא קרב זה אל זה, ולא יכול לקרב שלא היה זווג ז\"א ומלכות מצד החסד. עד שבא יעקב, שהוא קו האמצעי ונתחבר באברהם שהוא חסד, ולקח את יצחק והשרה אותו באמצע, בין הרחמים שהוא קו האמצעי, ובין החסד שהוא קו ימין, אז נקשר האמונה זה בזה וזה בזה, דהיינו שב' הקוין ימין ושמאל נקשרו יחדיו, וכן ז\"א ומלכות נזדווגו יחד מצד החסד. ונצלו ישראל."],[8,"ותנינן באתר דאבהתא","וכו': ולמדנו, במקום שהאבות נמצאים, שאר הצדיקים נמצאים אצלם כלומר, שבמקום שיש חג\"ת שהם האבות נכללים שם ג\"כ נהי\"מ, הנקראים משה אהרן יוסף. וע\"כ שם זה של ע\"ב, עולה ומתפרש באפנים אחרים. דהיינו שהשם ע\"ב מתבאר באפן זה, שי\"ב גבולים, שה\"ס חו\"ב תו\"מ שבכל אחד מג' קוין, שהם י\"ב, מאירים בכל קצה מו\"ק דז\"א. וששה פעמים י\"ב הם ע\"ב. וכן לעוד אפנים בדרך הזה. ואע\"פ שכל הפירושים יוצאים לדרך אחד."]],[[0,"","וְנִקְרֵאת בְּאֵר, וְנִקְרֵאת יָם. נִקְרֵאת בְּאֵר בְּשָׁעָה שֶׁיִּצְחָק יוֹצֵא מְזֻיָּן מִצַּד אִמָּא וּבָא לְהַמְשִׁיךְ אַחֲרֵי זֶה וּמְמַלֵּא אוֹתָהּ, אָז נִקְרֵאת בְּאֵר יִצְחָק, בְּאֵר מִרְיָם, וַהֲרֵי בֵּאַרְנוּ. יָם, כְּשֶׁמְּאִירָה מֵאוֹר עֶלְיוֹן שֶׁל אַבָּא, אָז נִקְרֵאת יָם, שֶׁנְּחָלִים הוֹלְכִים לְתוֹכָהּ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא."],[1,"","וּמִיּוֹם שֶׁגָּלְתָה כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, כָּתוּב (איוב יד) אָזְלוּ מַיִם מִנִּי יָם - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְנָהָר יֶחֱרַב וְיָבֵשׁ - זֶה צַדִּיק. וְעַל זֶה כָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד וְגוֹ'. שֶׁהוּא הָיָה נָהָר עֶלְיוֹן וּמְכֻבָּד שֶׁנִּכְנָס לְתוֹכָהּ, וְהוּא כּוֹנֵס כָּל אוֹתָם נְהָרוֹת וּנְחָלִים שֶׁשּׁוֹפְעִים מִשֶּׁפַע אוֹתוֹ נָהָר קָדוֹשׁ שֶׁלֹּא פוֹסְקִים מֵימָיו לְעוֹלָמִים, שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן הָעֶלְיוֹן, וְהוּא נִכְנָס לְתוֹכָהּ וּמְמַלֵּא אֲגַמֶּיהָ, וּמִשָּׁם יוֹרְשִׁים כָּל הָעוֹלָמוֹת (נזונו ויורשים) בְּרָכוֹת בַּכֹּל."],[2,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל, כָּל הָעוֹלָמוֹת מִתְבָּרְכִים, וְיִשְׂרָאֵל לְמַטָּה יוֹנְקִים וּמִתְבָּרְכִים בִּגְלָלָהּ. וַהֲרֵי בֵּאַרְנוּ שֶׁהִיא מְגִנָּה עַל יִשְׂרָאֵל, כְּמוֹ שֶׁנִּתְבָּאֵ ר."],[3,"","כָּתוּב (שמות יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ וְגוֹ'. מַלְאַךְ הָאֱלֹהִים - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וַהֲרֵי בֵּאַרְנוּ שֶׁאוֹתָהּ שָׁעָה בְּסִיּוּעַ הָאָבוֹת לוֹקַחַת. וּכְשֶׁהֵם נִמְצָאִים אֶצְלָהּ, הַכֹּל נִמְצָאִים. וּמִשּׁוּם כָּךְ נִמְסָר בִּפְסוּקִים אֵלּוּ שֵׁם הַקָּדוֹשׁ, שֶׁכּוֹלֵל בָּהֶם הָאָבוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ. פָּסוּק אֶחָד כַּסֵּדֶר, וְאֶחָד לְמַפְרֵעַ, וְאֶחָד כַּסֵּדֶר."],[4,"","וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ וְגוֹ' - זֶה כַּסֵּדֶר, מִשּׁוּם שֶׁאַבְרָהָם נִמְצָא כָּאן וְכָל אוֹתָם שֶׁבָּאִים מִצִּדּוֹ, וְעַל כָּךְ הוּא כַּסֵּדֶר כְּמוֹ זֶה."],[5,"","כָּאן הִתְעַטֵּר אַבְרָהָם בְּעַטְרוֹתָיו וְעִטֵּר אֶת כְּנֶסֶת יִשְׂרָאֵל, וְאוֹתִיּוֹת אֵלּוּ כֻּלָּן בְּדֶרֶךְ יָשָׁר לָלֶכֶת בַּיּוֹם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְעַל זֶה כָּתוּב וַיִּסַּע. אֵימָתַי לוֹקְחִים בְּמַשְׂאוֹתֵיהֶם? הֱוֵה אוֹמֵר בַּיּוֹם, כְּשֶׁמֵּאִיר הַשֶּׁמֶשׁ, וְזֶהוּ פָּסוּק אֶחָד שֶׁהוּא בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת."],[6,"","שֵׁנִי שֶׁל יִצְחָק, כָּךְ גַּם שֶׁנִּמְצָא בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת, לְהִמָּצֵא בְדִין לְגַבֵּי הַמִּצְרִים וּלְגַבֵּי יִשְׂרָאֵל בְּרַחֲמִים. וְעַל זֶה כָּתוּב וַיָּבא בֵּין מַחֲנֵה מִצְרַיִם וּבֵין מַחֲנֵה יִשְׂרָאֵל, לְמוּל אֵלֶּה וּלְמוּל אֵלֶּה. וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, שֶׁכָּךְ הוּא יוֹם שֶׁל יִצְחָק, שֶׁמְּעֻנָּן הָיָה, עָנָן וְחֹשֶׁךְ מִמֶּנּוּ הוּא. וּמִשּׁוּם כָּךְ סִדּוּר הָאוֹתִיּוֹת לְמַפְרֵעַ, (בדרך עקם) וְלֹא בְדֶרֶךְ יָשָׁר כְּמוֹ זֶה."],[7,"","וְעַל זֶה כָּל הָאוֹתִיּוֹת לְמַפְרֵעַ, שֶׁכָּתוּב וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ. שֶׁכֵּיוָן שֶׁנִּכְנַס יִצְחָק בְּדִינָיו, לֹא קָרַב זֶה אֶל זֶה. כָּתוּב זֶה אֶל זֶה. אוֹתָם שֶׁבָּאוּ מִצַּד אַבְרָהָם לֹא קָרְבוּ זֶה לָזֶה, שֶׁהֲרֵי לֹא יָכְלוּ, מִשּׁוּם שֶׁבְּאֵר זוֹ נִדְבְּקָה בְיִצְחָק, כְּמוֹ שֶׁנֶּאֱמַר וַיָּאֶר אֶת הַלָּיְלָה. שֶׁכְּשֶׁהִתְמַלְּאָה לְהִתְחַבֵּר (להתחזק) בְּיִצְחָק, לֹא קָרַב זֶה אֶל זֶה וְלֹא יָכֹל לְהִתְקָרֵב, עַד שֶׁבָּא יַעֲקֹב וְהִתְחַבֵּר בְּאַבְרָהָם, וְלָקַח אֶת יִצְחָק וְשָׂם אוֹתוֹ בָּאֶמְצַע, וְאָז הִתְקַשְּׁרָה הָאֱמוּנָה זֶה בָּזֶה וְזֶה בָּזֶה, וְנִצְּלוּ יִשְׂרָאֵל."],[8,"","וְשָׁנִינוּ, בְּמָקוֹם שֶׁנִּמְצָאִים הָאָבוֹת, שְׁאָר הַצַּדִּיקִים נִמְצָאִים אִתָּם, וְעַל זֶה שֵׁם זֶה עוֹלֶה לִצְדָדִים אֲחֵרִים מֻפְרָדִים, אַף עַל גַּב שֶׁכֻּלָּם יוֹצְאִים לְדֶרֶךְ אֶחָד."]]],[["כַּד נַהֲרָא הַאי בְּאֵ\"ר מִסִּטְרָא דְּיִצְחָק, וְאִתְקָשַׁר בֵּיהּ, אִתְעָבִיד יַמָּא רַבָּא תַּקִּיפָא, וְגַלְגְּלִין תַּקִּיפִין, סַלְּיקִין וְנַחְתִּין בְּזַעַף וְרוּגְזָא בִּתְקִיפוּ, נָטִיל לְעֵילָּא, סָלִיק, וְנָחִית לְתַתָּא, אַבְרָהָם אָתֵי לְקֳבְּלָא (ס\"א לקבליה), וּמִגּוֹ רוּגְזָא וְזַעְפָּא וְחֵימָתָא וּתְקִיפוּ, זֶה אֶל זֶה לָא הֲווֹ מִתְקָרְבִין, עַד דְּאָתָא יַעֲקֹב, וְשָׁכִיךְ רוּגְזָא, וּמָאִיךְ וְתָבַר גַּלְגַלֵּי יַמָּא, הֲדָא הוּא דִכְתִיב, (שמות י״ד:כ״א) וַיֵּט מֹשֶׁה אֶת יָדוֹ עַל הַיָּם וַיּוֹלֶךְ יְיָ אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה וְגוֹ'. מַאי בְּרוּחַ קָדִים עַזָּה. דָּא רוּחַ יַעֲקֹב, עַזָּה תַּקִּיף לָקֳבְלֵיהּ, לְתַבְרָא רוּגְזָא דְּהַאי יַמָּא. וַיָּשֶׂם אֶת הַיָּם לֶחָרָבָה וַיִבָּקְעוּ הַמָּיִם (נ\"א הוא) אָרִיק יַמָּא מֵימֵי רוּגְזִין, וְאִתְפְלִיגוּ מַיָּא לְסִטְרָא דְּאַבְרָהָם וּלְסִטְרָא דְּיַעֲקֹב, הֲדָא הוּא דִכְתִיב וַיִבָּקְעוּ הַמָּיִם לְסִטְרָא דָּא וּלְסִטְרָא דָּא. וְעַל דָּא אַתְוָון כֻּלְּהוּ בְּאֹרַח מֵישָׁר כַּדְּקָא יֵאוּת. (כאן היה כתוב פסוק ויט כסדר כל אות ואות בבית אחד במרובע עם זה הלשון)","אִלֵּין אַתְוָון בְּאֹרַח מֵישָׁר, בִּסְטַר דְּיַעֲקֹב, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרֵיהּ, וְכַד אָתָא יַעֲקֹב, אִתְחַבָּר בְּאַבְרָהָם, וְנָטַל לְיִצְחָק, וְשָׁארִי לֵיהּ בְּאֶמְצָעִיתָא. כְּדֵין אִתְקְשַׁר מְהֵימְנוּתָא דָּא בְּדָא וְדָא בְּדָא. וְעַל דָּא, עוֹבָדָא בְּתִקּוּנָא בִּשְׁמָא קַדִישָׁא בְּזִוּוּגָא דַּאֲבָהָן אִשְׁתְּמוֹדַע, דְּאִיהוּ קִשּׁוּרָא חַד, קִשּׁוּרָא מְהֵימָנָא, לְמֶהֱוִי רְתִיכָא שְׁלֵימָתָא. וּבְזִוּוּגָא דַּאֲבָהָן כַּחֲדָא, אִתְעָבִיד כֹּלָּא.","וְיַדְעִין חַבְרַיָּיא לְמֵיהַךְ בְּאֹרַח מֵישָׁר, לְאַתְקְּנָא עוֹבָדִין כַּדְּקָא יֵאוּת, וּבִשְׁמָא דָּא קִשּׁוּרָא דַּאֲבָהָן, אִשְׁתְּכָחוּ אוֹרְחִין לְדִינָא, וּלְרַחֲמֵי, לְסִיּיוּעַ, לְחֶסֶד, לִדְחִילוּ, לְאוֹרַיְיתָא, לְחַיֵּי, לְמוֹתָא, לְטָב, לְבִישׁ. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּיַדְעִין אוֹרְחוֹי דְּאוֹרַיְיתָא, וְיַדְעִין לְמֵיהַךְ בְּאוֹרְחוֹי דְּמַלְכָּא קַדִּישָׁא, זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. (וכאן מצאתי הע\"ב שמות היוצאים מג' פסוקים אלו במרובע כל שם ושם מג' אותיות בבית אחד ישר הפוך ישר, וסימניך יהי אור ולא הדפסתי אותו מפני יקר תפארת קדושתו)","הָא אֲבָהָן בְּמַטְלָנִין, בְּעוֹבָדִין, בְּקִשּׁוּרִין דְּמִתְקַשְּׁרֵי דָּא בְּדָא. וְכַד מִתְחַבְּרָן כַּחֲדָא, לֵית מַאן דִּיְקוּם קַמַּיְיהוּ. וְתָנֵינָן, בַּאֲתָר דַּאֲבָהָתָא אִשְׁתְּכָּחוּ, שְׁאַר צַדִיקַיָּיא מִשְׁתַּכְּחֵי גַּבַּיְיהוּ. וְעַל דָּא שְׁמָא דָּא סָלִיק לְסִטְרִין אַחֲרָנִין מִתְפָּרְשָׁן, אַף עַל גַּב דְּכֻלְּהוּ נָפְקִין לְאָרְחָא חַד.","שִׁבְעָה קִשּׁוּרִין אִינּוּן, דְּמִתְקַשְּׁרֵי בְּהוּ ג' אֲבָהָן, וְד' אַחֲרָנִין. רֵישָׁא וְאֶמְצָעִיתָא בְּקִשּׁוּרָא חֲדָא. וְאִלֵּין אִינּוּן דְּחַפְרוּ בֵּירָא דְּמַיָא. תִּנְיָינָא זֶה אֶל זֶה, וְאִינּוּן קִשּׁוּרָא חֲדָא, בִּתְלַת יוֹדִין.","תְּלִיתָאָה, שְׁלִימוּ דְּכָל מְהֵימְנוּתָא. רְבִיעָאָה, תְּרֵין קַיָּימִין, דְּגוּפָא קַיָּימָא עָלַיְיהוּ. חֲמִישָׁאָה, טַב וּבִישׁ, נַהֲרָא דְּנָפִיק אִילָנָא דְּחַיֵּי וּמוֹתָא, (בראשית רכ\"א ע\"א) עֲמִיקְתָא דְּכֹלָּא. שְׁתִיתָאָה, דִּינָא בְּרַחֲמֵי. שְׁבִיעָאָה, בְּקַדְמִיתָא אִתְּמַר, בְּהַהוּא רֵישָׁא דְּאַמָרָן, בְּגִין דְּאִיהוּ אֶמְצָעִיתָא דְּכֹלָּא. וּבְגִין דְּאִיהוּ אֶמְצָעִיתָא דְּכֹלָּא, אִקְרֵי (שמות נ\"ה ע\"א) אֲנִי, קִיּוּמָא דְּכָל עַנְפִין דְּמִתְאַחֲדָן מִסַּחֲרָנֵיהּ.","שִׁבְעָה דַּרְגִּין אִלֵּין, מִדַרְגָּא חֲדָא לְדַרְגָּא חֲדָא (ס\"א אחרא), אִשְׁתְּמוֹדְעָא רְתִיכָא חֲדָא, בְּכָל אִינּוּן דְּמִתְאַחֲדָאן בֵּיהּ. וְכֵן מִדַרְגָּא לְדַרְגָּא, וְכֻלְּהוּ אִתְנָהֲגָן אֲבַּתְרֵיהּ דְּהַהוּא דַּרְגָּא דְּאִתְפָּקְּדָא עָלַיְיהוּ, וְהָא אוֹקִימְנָא מִלֵּי.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִלֵּין דַּרְגִּין מִשְׁתַּכְחֵי, כָּל מְהֵימְנוּתָא אִשְׁתְּכַח, וְאִלֵּין שִׁבְעָה עֲנָנִין דְּאַסְחֲרוּ לְהוּ לְיִשְׂרָאֵל. בְּגִין כָּךְ כַּד נַטְלָא שְׁכִינְתָּא, בַּאֲבָהָתָא נַטְלָא. וְכַד אִלֵּין נַטְלִין, כֻּלְּהוּ דַּרְגִין אַחֲרָנִין נַטְלִין בְּהוּ, וּכְדֵין אִתְעַטְּרָת כְּנֶסֶת יִשְׂרָאֵל כַּדְּקָא יָאוּת.","תָּא חֲזֵי, זְבוּלֻן דְּקָאַמְרָן יָרִית יָם כִּנֶּרֶת. יָם כִּנֶּרֶת סְתָם, וְהָכִי אִתְחֲזֵי. אִי הָכִי יְהוּדָה מַה חוּלָקָא אִית בֵּיהּ, אֶלָּא יְהוּדָה נָטַל מַלְכוּתָא כֹּלָּא, וְאִתְאֲחִיד בֵּיהּ בְּכָל סִטְרִין.","רִבִּי אֶלְעָזָר אָמַר, הַאי פַּרְשְׁתָא, הָא אִתְּמַר עוֹבָדָא דִּמְנַרְתָּא וְתִקוּנָהָא וְכָל מַה דְּבָהּ, אֲמַאי הָכִי זִמְנָא אַחֲרָא. אֶלָּא כֵּיוָן דִּנְשִׂיאִים קְרִיבוּ (לעילא) קוּרְבְּנָא דְּמַדְבְּחָא, וְכָל תִּקּוּנָא דְּאִתְחֲזֵי לֵיהּ, אָתָא קְרָא וְאִשְׁתָּעֵי עוֹבָדָא דִּמְנַרְתָּא, דְּהִיא תִּקּוּנָא עַל יְדָא דְּאַהֲרֹן, דְּהָא לְעֵילָּא מְנַרְתָּא, וְכָל בּוּצִינִין (ס\"א תקונין) דִּילָהּ, עַל יְדָא דְּאַהֲרֹן נַהֲרִין כֹּלָּא.","תָּא חֲזֵי, מַדְבְּחָא, תְּרֵיסָר נְשִׂיאִין הֲווֹ לְחַנְּכָא לֵיהּ, וּלְאַתְקְּנָא לֵיהּ, וְהָא אוּקְמוּהָ תְּרֵיסָר אִינּוּן שְׁבָטִין, לְד' סִטְרִין, ד' דְּגָלִים, וְכֻלְּהוּ תְּרֵיסָר. וְכֹלָּא כְּגַוְונָא דִּלְעֵילָּא. מְנַרְתָּא אִתְמְנֵי בְּשִׁבְעָה בּוּצִינִין, לְאַדְלְקָא עַל יְדָא דְּכַהֲנָא, וְכֹלָּא כְּגַוְונָא דִּלְעֵילָּא. וּמְנַרְתָּא, עַל אָת קַיָּימָא, וּבְנִיסָא אִתְעָבִידַת, וְהָא אוּקְמוּהָ בְּעוֹבָדָא דִּמְנַרְתָּא."],[[0,"כד נהרא האי","וכו': כשמאירה באר הזו שהיא מלכות שמצד יצחק, שהוא קו שמאל, ונתקשר בו, נעשה ים הגדול, חזק וזועף, וגלגלים חזקים עולים ויורדים בזעף ורוגז בתקיפות, נוסע למעלה, עולה, ויורד למטה. בסו\"ה יעלו שמים ירדו תהומות. (כמ\"ש לעיל באדרא רבא אות רי\"ד ע\"ש) אברהם בא כנגדו שהוא קו ימין, כלומר, משום שקו ימין בא כנגדו ע\"כ נעשה המחלוקת והרעש הזה, שבהתגבר השמאל אז גלי הים עולים עד השמים שיאם, ובהתגבר הימין, שהוא אברהם, אז הגלים ירדו תהומות (כמ\"ש שם). ומתוך הרוגז והזעף והחימה והתקיפות, לא היו מתקרבים זה אל זה, ב' הקוין, אלא שנלחמו. עד שבא יעקב, שהוא קו האמצעי והשקיט הכעס, והשפיל, דהיינו שמיעט את ג\"ר דשמאל, (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת ולך דף י\"ג ד\"ה ונתבאר) ושיבר גלי הים, ז\"ש, ויט משה את ידו על הים ויולך ה' את הים ברוח קדים עזה, מהו ברוח קדים עזה, זה הוא רוח יעקב, שהוא קו האמצעי שהוא עזה ותקיף כנגד הקו שמאל, לשבר הרוגז של ים הזה, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר) אז, וישם את הים לחרבה ויבקעו המים, כי הריק הים ממימי הרוגז, ונתחלקו המים לצד אברהם, שהוא ימין שהוא חסד, ולצד יעקב, שהוא קו האמצעי שהוא רחמים. ז\"ש ויבקעו המים, לצד זה ולצד זה. וע\"כ האותיות כולם שבמקרא הזה דקו האמצעי הן בדרך יושר, כראוי."],[1,"אלין אתוון בארח","וכו': אלו האותיות הם בדרך יושר. בצד יעקב, שהוא קו האמצעי, וכל הבאים מצדו. וכשבא יעקב, נתחבר באברהם, שהוא קו ימין, ולקח את יצחק, שהוא קו שמאל, והשרה אותו באמצע, בינו ובין קו ימין, אז נקשר האמונה זה בזה וזה בזה, דהיינו שנקשרו ב' קוין, קו ימין וקו שמאל, זה בזה וזה בזה. ושלשתם במלכות, שנק' אמונה. וע\"כ העבודה בתקון השם הקדוש נודעת, בזווג האבות, דהיינו ימין בשמאל ושמאל בימין, ושניהם באמצעי, שהוא קשר אחד, שכל ג' קוין נעשו אחד, קשר האמונה, וכל ג' הקוין מתקשרים במלכות, הנקראת אמונה, להיות מרכבה שלמה. שהם ג' קוין ומלכות ד' רגלי הכסא. שהם כסא ומרכבה אל הבינה. ובזווג האבות יחד כנ\"ל, נעשה הכל."],[2,"וידעין חברייא למיהך","וכו': ויודעים החברים ללכת בדרך יושר, דהיינו בקו האמצעי, לתקן המעשים כראוי. ובשם זה, ע\"ב, שהוא קשר האבות, נמצאים דרכים לדין, לרחמים, לעזרה, לחסד, ליראה, לתורה, לחיים, למות, לטוב ולרע. אשרי הם הצדיקים שיודעים דרכי התורה, ויודעים ללכת בדרכי המלך הקדוש. אשרי הם בעולם הזה ובעולם הבא."],[3,"הא אבהן במטלנין","וכו': הנה האבות, בנסיעות שה\"ס נסיעתם בג' דוכתי (בשלח דף ל\"ט ד\"ה וג') במעשים להעלות מ\"ן, בקשרים היינו ביחודים, שמתקשרים זה בזה. כי בכל שם מע\"ב שמות אלו, נקשרים כל האבות יחד, שהם ג' הקוין. וכשמתחברים יחד אין מי שיקום לפניהם. ולמדנו, במקום שהאבות נמצאים, נמצאים עמהם שאר הצדיקים, משה אהרן יוסף, וע\"כ עולה שם ע\"ב זה ומתפרשים באפנים אחדים, אע\"פ שכל הפירושים יוצאים לדרך אחד. (כנ\"ל אות ל\"ח ע\"ש)."],[4,"שבעה קשורין אינון","וכו': שבעה קשרים הם בע\"ב שמות, שמתקשרים בהם, בכל קשר וקשר, ג' אבות, שהם חג\"ת, וארבעה אחרים, שהם נהי\"מ. ומפרש. הראש של ע\"ב שמות, שהם ג' ספירות חב\"ד, המכונים ראש, והאמצע שבהם, שהוא המלכות, הם בקשר אחד. משום שאלו חכמה ובינה, הם שחפרו באר המים, שהיא המלכות, כמ\"ש באר חפרוה שרים, שהם חכמה ובינה (כנ\"ל אות כ\"ט) וע\"כ החו\"ב דעת עם המלכות הם בקשר אחד. קשר השני, הוא זה אל זה, כלומר ב' הקוין חסד וגבורה, שעליהם נאמר ולא קרב זה אל זה (כנ\"ל אות ל\"ז) והם קשר אחד, המתחיל בג' יודין."],[4,"","פירוש. כי השם ע\"ב מתחלק על עשר חלוקות, שבכל אחת. ז' שמות כנגד חג\"ת נהי\"מ כנ\"ל, וג' חלוקות הראשונות המתחילות בהשם \u0003וה\"ו\u0004 עד השם \u0003נל\"ך\u0004 הוא רישא, דהיינו חב\"ד. ועמהם נקשרת חלוקה הו' שהיא האמצעית, המתחלת מן השם \u0003מנ\"ד\u0004 עד השם \u0003מי\"כ,\u0004 שבתוכם השם \u0003אנ\"י.\u0004 וחלוקה זו היא כנגד מלכות, ונקשרת עם הראש בקשר אחד, ונמצא שקשר הב', שהוא חסד וגבורה מתחיל מן השם \u0003י' י' י'\u0004 עד השם \u0003כו\"ק.\u0004 דהיינו ב' חלוקות, שבכל אחת ז' שמות. והם נחשבים לקשר אחד. והם קשר הב'. וז\"ש, \u0003תניינא, זה אל זה,\u0004 דהיינו חסד וגבורה, \u0003ואינון קשורא חדא בתלת יודין,\u0004 שהם שניהם קשר אחד, ומתחילים בג' יודין, \u0003יי\"י.\u0004"],[5,"תליתאה שלימו דכל","וכו': הקשר השלישי, הוא תפארת, שהוא קו האמצעי והוא שלמות של כל האמונה. שהוא משפיע למלכות הנקראת אמונה ומשלימה. קשר הרביעי, הוא ב' עמודים שהגוף עומד עליהם שהם נצח והוד, ונחשבים לנצח. קשר החמישי הוא הוד, שבו טוב ורע, והוא נהר היוצא לאילן של חיים ומות, שהוא המלכות. כי הוד משפיע למלכות. והוא העמוק מכל. כלומר שיש בו דינין יותר מבכל הספירות. קשר \u0003הששי,\u0004 הוא יסוד, שבו הדין ברחמים. קשר השביעי, שהוא המלכות, כבר נאמר בתחילה שנכלל בראש ההוא שאמרנו, משום שהוא אמצע הכל, כנ\"ל בדבור הסמוך, ומשום שהוא אמצע הכל נקרא \u0003אנ\"י,\u0004 כלומר שבחלוקה שלה יש השם \u0003אנ\"י,\u0004 שהוא קיום של כל הענפים המתאחדים מסביב לה."],[5,"","פירוש. הקשר השלישי מתחיל מן השם \u0003וו\"ל\u0004 עד השם \u0003וה\"ו,\u0004 כי ג' חלוקות הראשונות הן בחב\"ד, וב' חלוקות שלאחריהן, הן בחסד וגבורה. וחלוקה הששית המתחלקת מן מנ\"ד עד מי\"כ, היא חלוקה האמצעית שהיא בחינת המלכות, והיא נקשרת לקשר אחד עם קשר הא' שהוא הראש, כנ\"ל בדבור הסמוך. וע\"כ מתחיל קשר השלישי בחלוקה השביעית מן \u0003וו\"ל\u0004 עד \u0003וה\"ו.\u0004 הקשר הרביעי מתחיל בחלוקה הח' מן השם \u0003דנ\"י\u0004 עד השם \u0003פו\"י.\u0004 הקשר החמישי מתחיל בחלוקה הט' מן השם \u0003נמ\"ם\u0004 עד השם \u0003ענ\"ו.\u0004 הקשר הששי מתחיל בחלוקה העשירית מן השם \u0003מח\"י\u0004 עד השם \u0003יב\"מ.\u0004 וב' שמות האחרונים נכללים בהם. בסוד ע' סנהדרין וב' סהדי (כנ\"ל בשלח אות קס\"ג)."],[6,"שבעה דרגין אלין","וכו': שבע מדרגות אלו, דהיינו שבעה הקשרים הנ\"ל, ממדרגה אחת עד למדרגה אחת, כלומר ממדרגה הראשונה עד האחרונה, מרכבה אחת נודעת בהם בכל אלו השמות המתאחדים בה. וכן ממדרגה למדרגה. כלומר, וכן כל מדרגה פרטית היא מרכבה שלמה בפני עצמה. ואע\"פ שבכל מדרגה הם אותם ז\"ס חג\"ת נהי\"מ, ההפרש ביניהם היא. שבכל מדרגה, כולם נוהגים אחר מדרגה ההיא הנפקדת עליהם. וכבר העמדנו הדברים. כי למשל, במדרגת החסד יש ז\"ס חג\"ת נהי\"מ, אבל כולם נוהגים אחר ספירת החסד. וכן בגבורה שיש בה ז\"ס חג\"ת נהי\"מ, מתנהגים כולם לפי שליטת הגבורה. וכן בכל מדרגה ומדרגה."],[7,"ת\"ח בשעתא דאלין","וכו': בוא וראה, בשעה שאלו המדרגות של שם ע\"ב נמצאות, נמצא כל האמונה, דהיינו כל שלמות המלכות, ואלו שבע קשרים הם שבעה עננים שהקיפו להם לישראל. והם היו עשרה, כי החסד כלול ג\"ר, כנודע. משום זה כשהשכינה נוסעת היא נוסעת באבות, שהם חג\"ת, שה\"ס השם ע\"ב, כי כשאלו נוסעים, כל מדרגות אחרות נוסעות בתוכם, כנ\"ל, ואז מתעמרת כנסת ישראל, שהיא המלכות, כראוי. וכל הארתם היא בעיקר בעת הנסיעה (כנ\"ל בשלח דף ל\"ט ד\"ה וג' ע\"ש)."],[8,"ת\"ח זבולן דקאמרן","וכו': בוא וראה, זבולן שאמרנו שהוא ירש ים כנרת, ים כנרת סתם, שהיא המלכות. וכך ראוי להיות. שואל, א\"כ יהודה, שאמרנו בכל מקום שהוא מלכות, איזה חלק יש בו מן המלכות אחר שכבר נטלה זבולן. ומשיב, אלא יהודה לקח כל המלכות ונתאחד בה בכל המדרגות שלה, הן בקטנות הן בגדלות בסוד ד' ה' דיהודה. שד' היא הקטנות מטרם שקבלה עליה דכר. ו \u0003ה'\u0004 היא הגדלות. משא\"כ זבולן, לקח רק בחינת מלכות בעת שנקראת ים כנרת. בסוד המלחמות שבה (כנ\" ל אות כ\"ו כ\"ז)."],[9,"ר' אלעזר אמר","וכו': רא\"א פרשה זו, כבר נאמר מעשה המנורה וכל תקוניה וכל מה שבה, למה נאמר כאן פעם שניה. ומשיב, אלא כיון שהנשיאים הקריבו קרבנות המזבח, וכל התקונים הראוי לו, בא הכתוב וסיפר מעשה המנורה שהוא תקון על ידי אהרן, כי למעלה, המנורה, שהיא המלכות, וכל הנרות שלה שהם הספירות, הכל מאיר על ידי אהרן."],[10,"ת\"ח מדבחא תריסר","וכו': בוא וראה, המזבח, י\"ב נשיאים היו, לחנכו ולתקנו, והרי העמידוהו, שי\"ב הם השבטים לד' רוחות ד' דגלים, שבכל דגל ג' שבטים, וכולם יחד היו י\"ב. והכל כעין שלמעלה. כי המזבח שלמעלה שהוא המלכות מקבלת מי\"ב צירופי הויה שבז\"א שה\"ס חו\"ב תו\"מ שבכל אחד ג' קוין, והם י\"ב. המנורה, בשבעה נרות, נתמנתה להדליקם על ידי הכהן. והכל כעין של מעלה, כנגד ז\"א המאיר לחג\"ת נהי\"מ דמלכות. והמנורה על אות עומדת ובנס נעשית (כנ\"ל תרומה אות תקפ\"א) שהיתה נעשית מאליה. וכבר העמידוהו במעשה המנורה."]],[[0,"","כְּשֶׁמְּאִירָה בְּאֵ\"ר זוֹ מִצַּד יִצְחָק וְנִקְשֶׁרֶת בּוֹ, נַעֲשֶׂה יָם הַגָּדוֹל תַּקִּיף, וְגַלִּים חֲזָקִים עוֹלִים וְיוֹרְדִים בְּזַעַף וְרֹגֶז בְּתַקִּיפוּת, נוֹטֵל לְמַעְלָה, עוֹלֶה, וְיוֹרֵד לְמַטָּה. אַבְרָהָם בָּא מוּלוֹ (כנגדו), וּמִתּוֹךְ רֹגֶז וְזַעַף וְחֵמָה וְתַקִּיפוּת זֶה אֶל זֶה לֹא הָיוּ מִתְקָרְבִים, עַד שֶׁבָּא יַעֲקֹב וְשׁוֹכֵךְ הָרֹגֶז, וּמֵמִיךְ וְשׁוֹבֵר גַּלֵּי הַיָּם. זֶהוּ שֶׁכָּתוּב (שמות יד) וַיֵּט מֹשֶׁה אֶת יָדוֹ עַל הַיָּם וַיּוֹלֶךְ ה' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה וְגוֹ'. מַה זֶּה בְּרוּחַ קָדִים עַזָּה? זוֹ רוּחַ יַעֲקֹב, עַזָּה, תַּקִּיפָה לְמוּלוֹ לִשְׁבֹּר רֹגֶז יָם זֶה. וַיָּשֶׂם אֶת הַיָּם לֶחָרָבָה וַיִּבָּקְעוּ הַמָּיִם, (הוא) רוֹקֵן הַיָּם מִמֵּי רֹגֶז, וְנֶחְלְקוּ הַמַּיִם לְצַד אַבְרָהָם וּלְצַד יַעֲקֹב. זֶהוּ שֶׁכָּתוּב וַיִּבָּקְעוּ הַמָּיִם, לְצַד זֶה וּלְצַד זֶה, וְעַל כָּךְ כָּל הָאוֹתִיּוֹת בְּדֶרֶךְ יָשָׁר כָּרָאוּי."],[1,"","אֵלֶּה אוֹתִיּוֹת בְּדֶרֶךְ יָשָׁר בְּצַד יַעֲקֹב, וְכָל אוֹתָם שֶׁבָּאוּ מִצִּדּוֹ. וּכְשֶׁבָּא יַעֲקֹב, הִתְחַבֵּר בְּאַבְרָהָם וְלָקַח אֶת יִצְחָק, וְהִשְׁרָהוּ בָאֶמְצַע. אָז הִתְקַשְּׁרָה הָאֱמוּנָה זֶה בָּזֶה וְזֶה בָּזֶה. וְעַל זֶה מַעֲשֶׂה בְּתִקּוּן בַּשֵּׁם הַקָּדוֹשׁ בְּזִוּוּג הָאָבוֹת נוֹדָע, שֶׁהוּא קֶשֶׁר אֶחָד, קֶשֶׁר נֶאֱמָן, לִהְיוֹת מֶרְכָּבָה שְׁלֵמָה, וּבְזִוּוּג הָאָבוֹת כְּאֶחָד נַעֲשֶׂה הַכֹּל."],[2,"","וְיוֹדְעִים הַחֲבֵרִים לָלֶכֶת בְּדֶרֶךְ יָשָׁר, לְהַתְקִין מַעֲשֶׂה כָּרָאוּי, וּבְשֵׁם זֶה קֶשֶׁר הָאָבוֹת, נִמְצְאוּ דְרָכִים לְדִין וּלְרַחֲמִים, לְסִיּוּעַ, לְחֶסֶד, לְיִרְאָה, לְתוֹרָה, לְחַיִּים, לְמָוֶת, לְטוֹב, לְרַע. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה וְיוֹדְעִים לָלֶכֶת בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","הֲרֵי הָאָבוֹת בְּמַסָּעוֹת, בְּמַעֲשִׂים, בִּקְשָׁרִים שֶׁמִּתְקַשְּׁרִים זֶה בָּזֶה. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, אֵין מִי שֶׁיָּקוּם לִפְנֵיהֶם. וְשָׁנִינוּ, בְּמָקוֹם שֶׁהָאָבוֹת נִמְצָאִים, שְׁאָר הַצַּדִּיקִים נִמְצָאִים עֲלֵיהֶם. וְעַל זֶה שֵׁם זֶה עוֹלֶה לִצְדָדִים אֲחֵרִים נִפְרָדִים, אַף עַל גַּב שֶׁכֻּלָּם יוֹצְאִים לְדֶרֶךְ זֶה."],[4,"","שִׁבְעָה קִשּׁוּרִים הֵם שֶׁמִּתְקַשְּׁרִים בָּהֶם שְׁלֹשֶׁת הָאָבוֹת וְאַרְבָּעָה אֲחֵרִים. רֹאשׁ וָאֶמְצַע בְּקֶשֶׁר אֶחָד. וְאֵלֶּה אוֹתָם שֶׁחָפְרוּ בְּאֵר מַיִם. שֵׁנִי זֶה אֶל זֶה, וְהֵם קֶשֶׁר אֶחָד בְּשָׁלֹשׁ יוֹדִי\"ן."],[5,"","שְׁלִישִׁי שְׁלֵמוּת כָּל הָאֱמוּנָה. רְבִיעִי שְׁנֵי עַמּוּדִים שֶׁהַגּוּף עוֹמֵד עֲלֵיהֶם. הַחֲמִישִׁי טוֹב וָרָע, נָהָר שֶׁמּוֹצִיא עֵץ הַחַיִּים וְהַמָּוֶת, הָעֹמֶק שֶׁל הַכֹּל. שִׁשִּׁי דִּין בְּרַחֲמִים. שְׁבִיעִי בַּתְּחִלָּה נֶאֱמַר בְּאוֹתוֹ רֹאשׁ שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁהוּא אֶמְצַע הַכֹּל. וּמִשּׁוּם שֶׁהוּא אֶמְצַע הַכֹּל, נִקְרָא אֲנִי, עַמּוּד שֶׁכָּל הָעֲנָפִים נֶאֱחָזִים מִסְּבִיבוֹ."],[6,"","שֶׁבַע דְּרָגוֹת אֵלּוּ, מִדַּרְגָּה אַחַת לְדַרְגָּה אַחַת (אחרת), נוֹדַעַת מֶרְכָּבָה אַחַת בְּכָל אֵלּוּ שֶׁנֶּאֱחָזִים בָּהּ. וְכֵן מִדַּרְגָּה לְדַרְגָּה, וְכֻלָּם מִתְנַהֲגִים אַחֲרֶיהָ שֶׁל אוֹתָהּ דַּרְגָּה שֶׁנִּפְקְדָה עֲלֵיהֶם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים."],[7,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁדְּרָגוֹת אֵלּוּ נִמְצָאוֹת, כָּל הָאֱמוּנָה נִמְצֵאת. וְאֵלּוּ שִׁבְעַת הָעֲנָנִים שֶׁסָּבְבוּ אֶת יִשְׂרָאֵל. בִּגְלַל זֶה כְּשֶׁנּוֹטֶלֶת הַשְּׁכִינָה - בָּאָבוֹת הִיא נוֹטֶלֶת. וּכְשֶׁאֵלֶּה נוֹטְלִים, כָּל הַדְּרָגוֹת הָאֲחֵרוֹת נוֹטְלוֹת בָּהֶם, וְאָז מִתְעַטֶּרֶת כְּנֶסֶת יִשְׂרָאֵל כָּרָאוּי."],[8,"","בֹּא רְאֵה, זְבוּלוּן שֶׁאָמַרְנוּ יוֹרֵשׁ יָם כִּנֶּרֶת. יָם כִּנֶּרֶת סְתָם, וְכָךְ רָאוּי. אִם כָּךְ, יְהוּדָה מַה חֵלֶק יֵשׁ בּוֹ? אֶלָּא יְהוּדָה נָטַל מַלְכוּת הַכֹּל וְנֶאֱחַז בָּהּ בְּכָל הַצְּדָדִים."],[9,"","רַבִּי אֶלְעָזָר אָמַר, בְּפָרָשָׁה זוֹ הֲרֵי נֶאֱמַר הַמַּעֲשֶׂה שֶׁל הַמְּנוֹרָה וְתִקּוּנֶיהָ וְכָל מַה שֶּׁבָּהּ, מַדּוּעַ כָּךְ בְּפַעַם אַחֶרֶת? אֶלָּא כֵּיוָן שֶׁהַנְּשִׂיאִים הִקְרִיבוּ (למעלה) קָרְבַּן הַמִּזְבֵּחַ וְכָל תִּקּוּן שֶׁרָאוּי לוֹ, בָּא הַכָּתוּב וְדִבֵּר שׁוּב עַל מַעֲשֵׂה הַמְּנוֹרָה שֶׁהוּא תִקּוּן עַל יָדוֹ שֶׁל אַהֲרֹן, שֶׁהֲרֵי לְמַעְלָה מְנוֹרָה, וְכָל הַנֵּרוֹת (התקונים) שֶׁלָּהּ, עַל יְדֵי אַהֲרֹן הַכֹּל מְאִירִים."],[10,"","בֹּא רְאֵה, הַמִּזְבֵּח, שְׁנֵים עָשָׂר נְשִׂיאִים הָיוּ לְחַנְּכוֹ וּלְהַתְקִינוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שְׁנֵים עָשָׂר הֵם הַשְּׁבָטִים לְאַרְבָּעָה צְדָדִים, אַרְבָּעָה דְגָלִים, וְכֻלָּם שְׁנֵים עָשָׂר, וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה. הַמְּנוֹרָה נִמְנֵית בְּשִׁבְעָה נֵרוֹת לְהִדָּלֵק עַל יְדֵי הַכֹּהֵן, וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה. וְהַמְּנוֹרָה עַל אוֹת עוֹמֶדֶת וּבְנֵס נֶעֶשְׂתָה, וַהֲרֵי פֵּרְשׁוּהָ בְּמַעֲשֵׂה הַמְּנוֹרָה."]]],[["וּמַדְבַּח פְּנִימָאָה, וּמְנַרְתָּא, קַיְימֵי כַּחֲדָא, לְחֶדְוָותָא דְּכֹלָּא. דִּכְתִּיב, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וְאוֹקִימְנָא דִּתְרֵי מַדְבְּחָן הֲווֹ, חַד פְּנִימָאָה דְּכֹלָּא, וְהַאי קַיְּימָא לְחֶדְוָותָא. וְחַד לְבַר, לְקָרְבָא קָרְבְּנִין. וּמֵהַאי פְּנִימָאָה נָפִיק לְהַאי דִּלְבַר, וּמַאן דְּחָמֵי וְיִסְתָּכַּל, יִנְדַּע חָכְמְתָא עִלָּאָה, רָזָא דְּמִלָּה אֲדֹנָי יְדוָֹד. וְעַל דָּא לָא אִתְקְרַב קְטָרְתָּא, אֶלָּא בְּשַׁעֲתָא דְּשֶמֶן אִשְׁתְּכַח.","אַשְׁכַּחְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, קְטֹרֶת הוּא לְחֶדְוָה, וּלְסַלְּקָא מוֹתָנָא. מַאי טַעֲמָא. בְּגִין דְּדִינָא מֵהַאי דִּלְבַּר אִשְׁתְּכַח, וְחֶדְוָותָא וְחַדוּ וְקִשּׁוּרָא דִּנְהִירוּ, מֵהַהוּא פְּנִימָאָה, דְּכָל חֵידוּ בֵּיהּ קַיְּימָא. וְכַד הַאי אַתְעַר, כָּל דִּינָא אִסְתַּלָּק מֵהַאי, וְלָא יָכִיל לְמֶעְבַּד דִּינָא. וּבְגִין כָּךְ קְטֹרֶת קַיְּימָא לְבַטְּלָא מוֹתָנָא, וְעַל דָּא, קְטֹרֶת קְשִׁירוּ הוּא דְּכֹלָּא, וְדָא אִתְקְרִיב בְּהַהוּא פְּנִימָאָה. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'.","(במדבר ח׳:ו׳) קַח אֶת הַלְוִיִּם וְגוֹ', הָא אוּקְמוּהָ דְּבָעֵי לְדַכְּאָה (ס\"א לדברא) לוֹן, וּלְאַמְשָׁכָא לוֹן, לְאִתְקַשְּׁרָא בְּאַתְרַיְיהוּ, בְּגִין דְּאִינּוּן דְּרוֹעָא שְׂמָאלָא, וְסִטְרָא דְּדִינָא, וְכָל מַאן דְּאָתֵי מִסִּטְרָא דְּדִינָא, בָּעֵי דְּלָא יַרְבֵּי שַׂעֲרָא, בְּגִין דְּאַסְגֵּי דִּינָא בְּעָלְמָא. וְעַל דָּא אִתְּתָא כְּהַאי גַּוְונָא, דְּלָא יִתְחֲזֵי שַׂעֲרָא לְבַר, וּבַעְיָיא לְאִתְחַפְּיָיא רֵישֵׁהּ, וּלְכַסֵּי שַׂעְרָהָא, וְאוֹקִימְנָא, וְהָא אִתְּמַר. וּכְדֵין אִתְבָּרְכָן כָּל אִינּוּן דְּאַתְיָין מִסִּטְרָא דְּדִינָא. וְעַל דָּא בְּלֵיוָאֵי כְּתִיב, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם וְגוֹ', וְהֶעֱבִירוּ תַעַר וְגוֹ'. וְאִתְּמַר לֵיוָאֵי לָא סַלְּקִין לְאַתְרַיְיהוּ, עַד דְּיָרִים לוֹן כַּהֲנָא, בְּגִין דִּימִינָא מַדְבַּר תָּדִיר לִשְׂמָאלָא.","רַבִּי שִׁמְעוֹן אָמַר, בְּיוֹמָא דְּסַלְּקִין לֵּיוָאֵי בְּדוּכְתַיְיהוּ, בִּתְרֵין פָּרִים. מַאי טַעְמָא פָּרִים. אֶלָּא אִינְהוּ כְּפָרִים, לְקַבְּלָא בִּשְׂמָאלָא לְהַאי פָּרָה דְּאִקְרֵי פָּרָה אֲדוּמָה. כַּהֲנָא כָּל חֵילָא וְכָל תִּקּוּנָא בֵּיהּ תַּלְיָיא, בְּגִין דְּכָל חֵילָא דְּגוּפָא בִּדְרוֹעָא יְמִינָא קַיְּימָא. וְעַל דָּא כַּהֲנָא דְּרוֹעָא דְּיִשְׂרָאֵל כֻּלְּהוּ הֲוִי. וּבֵיהּ קַיְּימָא לְאַתְקְנָא כֹּלָּא וּלְאַתְקְנָא עָלְמָא (ס\"א מאי טעמא פרים אלא אינהו שמאלא כפרים לקבלא בשמאלא. תא חזי כהנא דרועא ימינא דישראל כלהו הוה וביה קיימא לאתתקנא עלמא ולאתתקנא כלא בגין דכל חילא דגופא בדרועא ימינא קיימא וכל תקונא ביה תלייא) וְעִם כָּל דָּא, לָא אִשְׁתְּכַח בִּלְחוֹדוֹי, אֶלָּא בְּגוּפָא וּשְׂמָאלָא, וְגוּפָא עִקָּרָא הוּא דְּכֹלָּא.","(במדבר ח׳:כ״ד) זֹאת אֲשֶׁר לַלְוִיִּם וְגוֹ'. תָּא חֲזֵי, לֵיוָאָה בַּר חָמֵשׁ וְעֶשְׂרִין שְׁנִין יִפְלַח בַּר חַמְשִׁין שְׁנִין סְלִיק לְדוּכְתֵּיהּ וְאִתְעַטָּר. וְחָמֵשׁ וְעֶשְׂרִין יִפְלַח דְּהָא בַּר נָשׁ (ס\"א תא חזי ליואה בר חמש ועשרין שנין לדוכתיה ואתעטר. וחמש ועשרין יפלח עד דסליק לדרגא דחמשין). כַּד סָלִיק לְהַאי דַּרְגָּא דְּחַמְשִׁין שְׁנִין וּלְהָלְאָה, נָחִית מִן תּוּקְפָּא דְּאֶשָּׁא דְּבֵיהּ, וְכֵיוָן דְּאֶשָּׁא וַחֲמִימוּתָא אִתְקָרִר, הָא פָּגִים לְהַהוּא אֲתָר דְּאִתְקְשַׁר בֵּיהּ.","וְעוֹד, דְּקָלָא דְּזִמְרָא לָא אִתְקְשַׁר בַּהֲדֵיהּ כָּל כַּךְ. וְקָלָא בָּעֵי דְּלָא יִתְפְּגָם, אֶלָּא בָּעֵי לְאִתָּקְפָא, דְּהָא בַּאֲתָר דְּדִינָא תַּקִּיף קַיְּימָא, וְלָא בְּחַלְשָׁא. וּבְגִין כָּךְ בָּעֵי דְּלָא יַפְגִּים הַהוּא אֲתָר דְּאִתְקְשַׁר בֵּיהּ, דְּאִיהוּ דִּינָא תַּקִּיפָא, וְלָא חַלְשָׁא, וְעַל דָּא לָא בָּעֵי לְאַחֲזָאָה חוּלְשָׁתָא כְּלָל בְּכָל סִטְרִין. זַכָּאָה הוּא בַּר נָשׁ דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, וְיִנְדַּע אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא סָטֵי לִימִינָא וְלִשְׂמָאלָא, דִּכְתִיב (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ.","(במדבר ט׳:א׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה בְּמִדְבַּר סִינַי וְגוֹ'. אָמַר רִבִּי אַבָּא, מַאי טַעְמָא אַזְהַר לְהוֹן הָכָא עַל פִּסְחָא, וְהָא אִתְּמַר לְהוּ בְּמִצְרַיִם. אֶלָּא בַּשָּׁנָה הַשֵּׁנִית הֲוָה, דְּיִשְׂרָאֵל חָשִׁיבוּ דְּהָא פֶּסַח לָאו אִיהוּ אֶלָּא בְּמִצְרַיִם, וְכֵיוָן דְּעָבְדוּ לֵיהּ זִמְנָא חֲדָא בְּמִצְרַיִם, חֲשִׁיבוּ דְּלָא אִצְטְרִיךְ יַתִיר. אָתָא קוּדְשָׁא בְּרִיךְ הוּא וְאַזְהַר לוֹן עָלֵיהּ, דְּלָא יַחְשְׁבוּן דְּהָא קָא עָבַר זִמְנֵיהּ בְּמִצְרַיִם, וְלֹא יִצְטְרִיךְ. בְּגִין כַּךְ בְּמִדְבַּר סִינַי בַּשָּׁנָה הַשֵּׁנִית, לְאַתְקְנָא לְהוּ לְדָרֵי דָּרִין."],[[0,"ומדבח פנימאה ומנרתא","וכו': ומזבח הפנימי והמנורה, עומדים יחד לשמחת הכל, שכתוב שמן וקטרת ישמח לב. ששמן הוא המנורה, דהיינו המלכות המקבלת מחכמה. וקטרת הוא המזבח הפנימי, והעמדנו כי ב' מזבחות היו. אחד פנימי של הכל, שהוא מזבח הקטרת, וזה עומד לשמחה. והוא כנגד בינה. ואחד לחוץ דהיינו מזבח החיצון, העומד להקריב קרבנות, שהוא כנגד מלכות. וממזבח הפנימי, שהיא כנגד הבינה, יוצא שפע לזה שמבחוץ, שהוא מלכות. ומי שרואה ומסתכל יודע חכמה העליונה שסוד הדבר אדנ\"י הוי\"ה. כי מזבח הפנימי היא הוי\"ה, בינה. והחיצון אדנ\"י, מלכות. וע\"כ לא נקרב קטרת אלא בשעה שנמצא שמן (כנ\"ל אות כ\"ב). שה\"ס יחוד אחד חו\"ב."],[1,"אשכחנא בספרא דשלמה","וכו': מצאתי בספרו של שלמה המלך, שהקטרת היא, לשמחה ולהעביר המות. מהו הטעם. הוא, משום שהדין נמצא ממזבח החיצון, שהוא מלכות. והשמחה והחדוה וקשר האור הם ממזבח הפנימי, שכל שמחה עומדת בו. שהוא בינה. וכשזה נתעורר, דהיינו הפנימי, כל דין מסתלק מזה, מן החיצון, ואינו יכול לעשות דין. ומשום זה קטרת שה\"ס הפנימי, עומדת לבטל המות. כי כשהפנימי שה\"ס בינה, מתעוררת ע\"י הקטרת, אין החיצון, שהוא המלכות, יכולה לעשות דין. וע\"כ קטרת הוא קשר הכל, והוא נקרב במזבח הפנימי, שכל שמחה נמצאת בו. אשרי הם ישראל בעולם הזה ובעולם הבא. עליהם כתוב, ויאמר לי עבדי אתה ישראל אשר בך אתפאר."],[2,"קח את הלוים","וגו': הרי העמידוהו, שצריכים לטהר אותם ולהמשיכם להתקשר במקומם, בקו שמאל. משום שהם מזרוע שמאל, מגבורה דז\"א, וצד הדין, וכל מי שבא מצד הדין, צריך שלא יגדל שער, משום שמרבה דין בעולם. ולפיכך, אשה, כעין זה, צריכה שלא יתראו שערותיה לחוץ, וצריכה לכסות ראשה ולכסות שערותיה, והעמידוה, וכבר למדנו. ואז, מתברכים כל אלו הבאים מצד הדין. וע\"כ כתוב בלוים וכה תעשה להם לטהרם וגו' והעבירו תער וגו'. ולמדנו שהלוים אינם עולים למקומם עד שיניפו אותם הכהן, משום שהימין מנהיג תמיד את השמאל."],[2,"","פירוש. שורש השערות הוא, מכניסת ה \u0003י'\u0004 באור, שמסלקת הג\"ר והאור נעשה לאויר. ומבחי' חסרון ג\"ר שנעשה יוצאים השערות, שהם מלשון סערות דהיינו דינים. כי הס\"א נאחזת במקום שיש חסרון. וז\"ש, \u0003וכל מאן דאתי מסטרא דדינא בעי דלא ירבי שערא בגין דאסגי דינא בעלמא.\u0004 אמנם וכל זה באותם הנמשכים מצד השמאל כגון אשה, וכן הלוים. אבל הנמשכים מצד הימין מסוד הקדושה, הוא להיפך, שהשערות בהם הוא קדש, כגון נזיר שנאמר בו קדוש יהיה גדל פרע שער ראשו (כמ\"ש כל זה לעיל פרשת תזריע אות קכ\"א בהסולם ע\"ש) שזה כל ההפרש בין קדוש ובין טהור."],[3,"ר\"ש אמר ביומא","וכו': רש\"א, ביום שעלו הלוים למקומם הקריבו ב' פרים. מהו הטעם פרים. ומשיב, אלא הם כפרים דהיינו בקו שמאל, בסוד ופני שור מהשמאל, שיקבלו בשמאל אותה הפרה שנקראת פרה אדומה, דהיינו מלכות שמצד השמאל. והכהן, שהוא קו ימין כל כח וכל תקון תלוי בו, משום שכל כח הגוף עומד בזרוע ימין. וע\"כ הכהן, היה זרוע ימין של כל ישראל שבו עומד לתקן הכל ולתקן העולם. ועם כל זה לא נמצא קו הימין בלבדו, אלא במחובר עם הגוף ועם השמאל, דהיינו עם ב' הקוין אמצע ושמאל. והגוף, שהוא קו אמצעי הוא עיקר הכל. כי הוא מיחד ב' הקוין, ומשלימם, וגם כולל אותם."],[4,"זאת אשר ללוים","וגו': בוא וראה, הלוי, בן חמש ועשרים שנה, עולה למקומו ומתעטר. וחמש ועשרים שנה יעבוד עד שעולה למדרגת חמשים. כשעולה למדרגת חמשים שנה ולהלאה, הוא יורד מתוקף האש שבו, וכיון שהאש והחום מתקרר, הוא פוגם לאותו מקום שקשור בו, שהוא שמאל. פירוש. כי אין הארת החכמה שבשמאל מאירה אלא בתוקף כח הדין המטיל אימה ופחד על הרשעים (כנ\"ל אדרא רבא אות רי\"ט) וכיון שפסק ממנו כח האש, שהוא דינים, ע\"כ אינו ראוי לעבוד, והוא פוגם את השמאל, שבשבילו אינו ראוי להמשכת החכמה."],[5,"ועוד, דקלא דזמרא","וכו': ועוד, שלאחר חמשים שנה, הקול של הזמרה אינו מקושר בו כל כך, דהיינו שנחלש מעט, והקול צריך שלא יופגם אלא צריך להתחזק כי במקום דין חזק עומד ולא בחלש, ומשום זה צריך שלא יפגום אותו מקום, שהוא השמאל, שנקשר בו, שהוא דין תקיף ולא חלש, ולא צריך משום זה להראות איזה חולשה מכל הצדדים. (ועי' לעיל ויחי אות תתכ\"ה) אשרי הוא האדם העוסק בתורה, ויודע דרכיו של הקב\"ה, ואינו סר לימין ולשמאל. שכתוב כי ישרים דרכי ה'. דהיינו שהולך תמיד בקו האמצעי."],[6,"וידבר","וגו' \u0003במדבר סיני\u0004 וגו': א\"ר אבא, מהו הטעם שהזהיר אותם כאן על הפסח. והרי כבר נאמר להם במצרים. ומשיב, אלא בשנה השנית היה, וישראל חשבו שהפסח אינו נוהג אלא במצרים, וכיון שעשו אותו פעם אחת במצרים, חשבו, שלא צריך יותר. בא הקב\"ה והזהירם עליו, שלא יחשבו שעבר זמנו במצרים ואין צריך יותר. ומשום זה הזהיר במדבר סיני בשנה השנית, לתקן להם הפסח לדורי דורות."]],[[0,"","וּמִזְבֵּחַ פְּנִימִי וּמְנוֹרָה עוֹמְדִים כְּאֶחָד לְשִׂמְחַת הַכֹּל, שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וּבֵאַרְנוּ שֶׁשְּׁנֵי מִזְבְּחוֹת הָיוּ: אֶחָד פְּנִימִי שֶׁל הַכֹּל, וְזֶה עוֹמֵד לְחֶדְוָה, וְאֶחָד בַּחוּץ לְהַקְרִיב קָרְבָּנוֹת. וּמֵהַפְּנִימִי הַזֶּה יוֹצֵא לָזֶה שֶׁבַּחוּץ. וּמִי שֶׁרוֹאֶה וְיִסְתַּכֵּל, יֵדַע חָכְמָה עֶלְיוֹנָה, סוֹד הַדָּבָר אֲדנָי יְהֹוָה, וְעַל כָּךְ לֹא נִקְרְבָה הַקְּטֹרֶת אֶלָּא בְּשָׁעָה שֶׁשֶּׁמֶן נִמְצָא."],[1,"","מָצָאנוּ בְסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהַקְּטֹרֶת הִיא לְחֶדְוָה וּלְסַלֵּק הַמָּוֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁהַדִּין נִמְצָא מִזֶּה שֶׁבַּחוּץ, וְשִׂמְחָה וְחֶדְוָה וְקֶשֶׁר שֶׁמֵּאִיר מֵאוֹתוֹ פְּנִימִי שֶׁכָּל שִׂמְחָה בּוֹ קַיֶּמֶת. וּכְשֶׁזֶּה מִתְעוֹרֵר, כָּל הַדִּין מִסְתַּלֵּק מִזֶּה וְלֹא יָכוֹל לַעֲשׂוֹת דִּין, וּמִשּׁוּם זֶה קְטֹרֶת עוֹמֶדֶת לְבַטֵּל הַמָּוֶת, וְעַל זֶה קְטֹרֶת הִיא קֶשֶׁר הַכֹּל, וְזוֹ נִקְרֶבֶת בַּפְּנִימִי. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'."],[2,"","קַח אֶת הַלְוִיִּם וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ שֶׁצָּרִיךְ לְטַהֲרָם (להנהיגם) וּלְהַמְשִׁיכָם לְהִתְקַשֵּׁר בִּמְקוֹמָם, מִשּׁוּם שֶׁהֵם זְרוֹעַ שְׂמֹאל וְצַד הַדִּין. וְכָל מִי שֶׁבָּא מִצַּד הַדִּין, צָרִיךְ שֶׁלֹּא יַרְבֶּה שֵׂעָר, מִשּׁוּם שֶׁמַּרְבֶּה דִין בָּעוֹלָם. וְעַל כָּךְ אִשָּׁה כְּמוֹ זֶה, שֶׁלֹּא תִתְרָאֶה שַׂעֲרָה הַחוּצָה, וּצְרִיכָה לְכַסּוֹת רֹאשָׁהּ וּלְכַסּוֹת שְׂעָרָהּ, וּבֵאַרְנוּ וַהֲרֵי נִתְבָּאֵר. וְאָז מִתְבָּרְכִים כָּל אֵלּוּ שֶׁבָּאִים מִצַּד הַדִּין. וְעַל כָּךְ כָּתוּב בַּלְוִיִּם, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם וְגוֹ', וְהֶעֱבִירוּ תַעַר וְגוֹ'. וְנֶאֱמַר כִּי הַלְוִיִּם לֹא עוֹלִים לִמְקוֹמָם עַד שֶׁיָּרִים אוֹתָם הַכֹּהֵן, מִשּׁוּם שֶׁהַיָּמִין מַנְהִיג תָּמִיד לַשְּׂמֹאל."],[3,"","רַבִּי שִׁמְעוֹן אָמַר, בַּיּוֹם שֶׁעוֹלִים הַלְוִיִּם לִמְקוֹמָם, בִּשְׁנֵי פָרִים. מָה הַטַּעַם פָּרִים? אֶלָּא הֵם כְּפָרִים לְקַבֵּל בִּשְׂמֹאל אֶת הַפָּרָה הַזּוֹ שֶׁנִּקְרֵאת פָּרָה אֲדֻמָּה. הַכֹּהֵן, כָּל הַכֹּחַ וְכָל תִּקּוּן תָּלוּי בּוֹ, מִשּׁוּם שֶׁכָּל כֹּחַ הַגּוּף עוֹמֵד בִּזְרוֹעַ יָמִין, וְעַל כָּךְ הַכֹּהֵן הוּא זְרוֹעַ שֶׁל כָּל יִשְׂרָאֵל, וּבוֹ עוֹמֵד לְהַתְקִין הַכֹּל וּלְהַתְקִין עוֹלָם, (מה הטעם פרים, ' אלא הם שמאל כמו הפרים לקבל בשמאל. בא ראה, הכהן זרוע ימין של כל ישראל היה, ובו עומד להתקין העולם ולהתקין הכל, משום שכל כח הגוף בזרוע הימין עומד, וכל התקון בו תלוי) וְעִם כָּל זֶה לֹא נִמְצָא לְבַדּוֹ, אֶלָּא בְּגוּף וּשְׂמֹאל, וְהַגּוּף הוּא עִקַּר הַכֹּל."],[4,"","זֹאת אֲשֶׁר לַלְוִיִּם וְגוֹ'. בֹּא רְאֵה, לֵוִי בֶּן עֶשְׂרִים וְחָמֵשׁ שָׁנִים יַעֲבֹד, בֶּן חֲמִשִּׁים שָׁנִים עוֹלֶה לִמְקוֹמוֹ וּמִתְעַטֵּר, וְעֶשְׂרִים וְחָמֵשׁ יַעֲבֹד, שֶׁהֲרֵי אָדָם (בא ראה, לוי בן עשרים וחמש שנים עולה למקומו ומתעטר, ועשרים וחמש שנים יעבד, עד שעולה לדרגת חמשים), כְּשֶׁעוֹלֶה לְדַרְגָּה זוֹ שֶׁל חֲמִשִּׁים שָׁנִים וָהָלְאָה, יוֹרֵד מִתֹּקֶף הָאֵשׁ שֶׁבּוֹ. וְכֵיוָן שֶׁהָאֵשׁ וְהַחֲמִימוּת מִתְקָרֶרֶת, הֲרֵי הוּא פּוֹגֵם לְאוֹתוֹ מָקוֹם שֶׁנִּקְשָׁר בּוֹ."],[5,"","וְעוֹד, שֶׁקּוֹל זִמְרָה לֹא כָּל כָּךְ נִקְשָׁר בּוֹ, וְקוֹל צָרִיךְ שֶׁלֹּא יִפָּגֵם, אֶלָּא צָרִיךְ לְהִתְחַזֵּק, שֶׁהֲרֵי בִּמְקוֹם הַדִּין הַקָּשֶׁה עוֹמֵד, וְלֹא בְחֻלְשָׁה. וּמִשּׁוּם זֶה צָרִיךְ שֶׁלֹּא יִפְגֹּם אוֹתוֹ מָקוֹם שֶׁהוּא קָשׁוּר בּוֹ, שֶׁהוּא דִּין הַקָּשֶׁה, וְלֹא הַחַלָּשׁ, וְעַל זֶה לֹא צָרִיךְ לְהַרְאוֹת חֻלְשָׁה כְּלָל בְּכָל הַצְּדָדִים. אַשְׁרֵי הָאִישׁ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְיֵדַע דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא סוֹטֶה לְיָמִין וְלִשְׂמֹאל, שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה'."],[6,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי וְגוֹ'. אָמַר רַבִּי אַבָּא, מָה הַטַּעַם הִזְהִירָם כָּאן עַל פֶּסַח, וַהֲרֵי נִתְבָּאֵר לָהֶם בְּמִצְרַיִם? אֶלָּא בַּשָּׁנָה הַשֵּׁנִית זֶה הָיָה, שֶׁחָשְׁבוּ יִשְׂרָאֵל שֶׁפֶּסַח זֶה הוּא רַק בְּמִצְרַיִם, וְכֵיוָן שֶׁעָשׂוּ אוֹתוֹ פַּעַם אַחַת בְּמִצְרַיִם, חָשְׁבוּ שֶׁלֹּא צָרִיךְ יוֹתֵר. בָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִזְהִירָם עָלָיו, שֶׁלֹּא יַחְשְׁבוּ שֶׁעָבַר זְמַנּוֹ בְּמִצְרַיִם וְלֹא יִצְטָרֵךְ. בִּגְלַל זֶה בְּמִדְבַּר סִינַי בַּשָּׁנָה הַשֵּׁנִית, לְהַתְקִין לָהֶם לְדוֹרֵי דוֹרוֹת."]]],[["וְאַף עַל גַּב דְּהָא אַזְהַר לְהוּ בְּמִצְרַיִם, הַשְׁתָּא פָּקִיד לוֹן זִמְנָא אַחֲרָא, בְּהַהוּא אֲתָר דְּכָל פִּקוּדִין דְּאוֹרַיְיתָא בֵּיהּ אִתְיְהִיבוּ. וְעַל דָּא בַּשָּׁנָה הַשֵּׁנִית. מַאי בַּשָּׁנָה הַשֵּׁנִית בַּחֹדֶשׁ הָרִאשׁוֹן. אֶלָּא רָזָא עִלָּאָה הִיא, חַד שָׁנָה. וְחַד חֹדֶשׁ. מַה בֵּין הַאי לְהַאי. חֹדֶשׁ: דָּא סִיהֲרָא. שָׁנָה: דָּא שִׁמְשָׁא, דְּנָהִיר לְסִיהֲרָא. וּכְדֵין הֲוָה בְּזִמְנָא דְּכָל פִּקוּדִין דְּאוֹרַיְיתָא אִתְמְסָרוּ בֵּיהּ.","רַבִּי שִׁמְעוֹן אָמַר, וַוי לְהַהוּא בַּר נָשׁ דְּאָמַר, דְּהָא אוֹרַיְיתָא אָתָא לְאַחֲזָאָה סִפּוּרִין בְּעָלְמָא, וּמִלִּין דְּהֶדְיוֹטֵי. דְּאִי הָכִי, אֲפִילּוּ בְּזִמְנָא דָּא, אֲנָן יַכְלִין לְמֶעְבַּד אוֹרַיְיתָא, בְּמִלִּין דְּהֶדְיוֹטֵי, וּבִשְׁבָחָא יַתִיר מִכֻּלְּהוּ. אִי לְאַחֲזָאָה מִלָּה דְּעָלְמָא, אֲפִילּוּ אִינּוּן קַפְסִירֵי דְּעָלְמָא, אִית בֵּינַיְיהוּ מִלִּין עִלָּאִין יַתִיר. אִי הָכִי נֵזִיל אֲבַּתְרַיְיהוּ, וְנַעְבֵּיד מִנַּיְיהוּ אוֹרַיְיתָא, כְּהַאי גַּוְונָא. אֶלָּא כָּל מִלִּין דְּאוֹרַיְיתָא, מִלִּין עִלָּאִין אִינּוּן, וְרָזִין עִלָּאִין.","תָּא חֲזֵי, עָלְמָא עִלָּאָה וְעָלְמָא תַּתָּאָה בְּחַד מַתְקְלָא אִתְקָלוּ. יִשְׂרָאֵל לְתַתָּא, מַלְאֲכֵי עִלָּאֵי לְעֵילָּא. מַלְאֲכֵי עִלָּאֵי כְּתִיב בְּהוּ, (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹת. (האי באתר עלאה) בְּשַׁעֲתָא דְּנַחְתִּין לְתַתָּא (אף על גב דנחתין), מִתְלַבְּשֵׁי בִּלְבוּשָׁא דְּהַאי עָלְמָא. וְאִי לָאו מִתְלַבְּשֵׁי בִּלְבוּשָׁא כְּגַוְונָא דְּהַאי עָלְמָא, לָא יַכְלִין לְמֵיקָם בְּהַאי עָלְמָא, וְלָא סָבִיל לוֹן עָלְמָא. וְאִי בְּמַלְאָכֵי כַּךְ, אוֹרַיְיתָא דְּבָרָא לְהוּ, וּבָרָא עָלְמִין כֻּלְּהוּ, וְקַיְימִין בְּגִינָהּ, עַל אַחַת כַּמָּה וְכַמָּה כֵּיוָן דְּנַחְתַּת לְהַאי עָלְמָא, אִי לָאו דְּמִתְלַבְּשָׁא בְּהָנֵי לְבוּשִׁין דְּהַאי עָלְמָא, לָא יָכִיל עָלְמָא לְמִסְבַּל.","וְעַל דָּא הַאי סִפּוּר דְּאוֹרַיְיתָא, לְבוּשָׁא דְּאוֹרַיְיתָא. אִיהוּ. מַאן דְּחָשִׁיב דְּהַהוּא לְבוּשָׁא אִיהוּ אוֹרַיְיתָא מַמָּשׁ, וְלָא מִלָּה אַחֲרָא, תִּיפַּח רוּחֵיהּ, וְלָא יְהֵא לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי. בְּגִין כַּךְ אָמַר דָּוִד, (תהילים קי״ט:י״ח) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ. מַה דִּתְחוֹת לְבוּשָׁא דְּאוֹרַיְיתָא.","תָּא חֲזֵי, אִית לְבוּשָׁא דְּאִתְחֲזֵי לְכֹלָּא, וְאִינּוּן טִפְּשִׁין כַּד חָמָאן לְבַר נָשׁ בִּלְבוּשָׁא דְּאִתְחֲזֵי לוֹן שַׁפִּירָא, לָא מִסְתַּכְּלִין יַתִּיר. חֲשִׁיבוּ דְּהַהוּא לְבוּשָׁא, גּוּפָא, וַחֲשִׁבוּ דְּגוּפָא, נִשְׁמְתָא.","כְּהַאי גַּוְונָא אוֹרַיְיתָא, אִית לָהּ גּוּפָא, וְאִינּוּן פִּקּוּדֵי אוֹרַיְיתָא, דְּאִקְרוּן גּוּפֵי תּוֹרָה. הַאי גּוּפָא מִתְלַבְּשָׁא בִּלְבוּשִׁין, דְּאִינּוּן סִפּוּרִין דְּהַאי עָלְמָא. טִפְּשִׁין דְּעָלְמָא, לָא מִסְתַּכְּלֵי אֶלָּא בְּהַהוּא לְבוּשָׁא, דְּאִיהוּ סִפּוּר דְּאוֹרַיְיתָא, וְלָא יַדְעֵי יַתִּיר, וְלָא מִסְתַּכְּלֵי בְּמָה דְּאִיהוּ תְּחוֹת הַהוּא לְבוּשָׁא. אִינּוּן דְּיַדְעִין יַתִּיר, לָא מִסְתַּכְּלָן בִּלְבוּשָׁא, אֶלָּא בְּגוּפָא, דְּאִיהוּ תְּחוֹת הַהוּא לְבוּשָׁא. חַכִּימִין עַבְדֵי דְּמַלְכָּא עִלָּאָה, אִינּוּן דְּקַיְימוּ בְּטוּרָא דְּסִינַי, לָא מִסְתַּכְּלֵי אֶלָּא בְּנִשְׁמְתָא, דְּאִיהִי עִקָּרָא דְּכֹלָּא אוֹרַיְיתָא מַמָּשׁ. (ולעלמא) וּלְזִמְנָא דְּאָתֵי, זְמִינִין לְאִסְתַּכְּלָא בְּנִשְׁמְתָא דְּנִשְׁמְתָא דְּאוֹרַיְיתָא.","תָּא חֲזֵי, הָכִי נָמֵי לְעֵילָּא, אִית לְבוּשָׁא, וְגוּפָא, וְנִשְׁמְתָא, וְנִשְׁמְתָא לְנִשְׁמְתָא. שְׁמַיָּא וְחֵילֵיהוֹן. אִלֵּין אִינּוּן לְבוּשָׁא. וּכְנֶסֶת יִשְׂרָאֵל, דָּא גּוּפָא, דִּמְקַבְּלָא לְנִשְׁמְתָא, דְּאִיהִי תִּפְאֶרֶת יִשְׂרָאֵל. וְעַל דָּא אִיהוּ גּוּפָא לְנִשְׁמְתָא. נִשְׁמְתָא דְּאַמָרָן דָּא תִּפְאֶרֶת יִשְׂרָאֵל, דְּאִיהִי אוֹרַיְיתָא מַמָּשׁ. וְנִשְׁמְתָא לְנִשְׁמְתָא, דָּא אִיהוּ עֲתִּיקָא קַדִּישָׁא. וְכֹלָּא אָחִיד דָּא בְּדָא.","וַוי לְאִינּוּן חַיָּיבַיָּא, דְּאָמְרֵי דְּאוֹרַיְיתָא לָאו אִיהִי אֶלָּא סִפּוּרָא בְּעָלְמָא, וְאִינּוּן מִסְתַּכְּלֵי בִּלְבוּשָׁא דָּא וְלָא יַתִּיר. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּמִסְתַּכְּלֵי בְּאוֹרַיְיתָא כַּדְּקָא יֵאוּת. חַמְרָא לָא יָתִיב אֶלָּא בְּקַנְקָן. כַּךְ אוֹרַיְיתָא לָא יְתִיב אֶלָּא בִּלְבוּשָׁא דָּא. וְעַל דָּא לָא בָּעֵי לְאִסְתַּכְּלָא, אֶלָּא בְּמָה דְּאִית תְּחוֹת לְבוּשָׁא. וְעַל דָּא כָּל אִינּוּן מִלִּין, וְכָל אִינּוּן סִפּוּרִין, לְבוּשִׁין אִינּוּן.","(במדבר ט׳:ב׳-ג׳) וְיַעֲשׂוּ בְנֵי יִשְׂרָאֵל אֶת הַפָּסַח בְּמוֹעֲדוֹ מַאי וְיַעֲשׂוּ. אָמַר רִבִּי יוֹסֵי, הָא אִתְּמַר, כָּל מַאן דְּאַחְזֵי עוֹבָדָא לְתַתָּא כַּדְקָא יֵאוּת, כְּאִילּוּ עָבִיד לֵיהּ לְעֵילָּא. דְּהָא בְּגִינֵיהּ אִתְּעַר הַהוּא מִלָּה, כִּבְיָכוֹל, כְּאִילּוּ הוּא עָבִיד לֵיהּ, וְהָא אִתְּמַר."],[[0,"ואע\"ג דהא אזהר","וכו': פירוש אחר. אע\"פ שהזהירם במצרים, צוה אותם עתה פעם שנית באותו המקום שכל מצות התורה ניתנו בו. וע\"כ בשנה השנית וגו'. שואל, מהו בשנה השנית בחדש הראשון. דהיינו למה זה רומו. ומשיב, אלא סוד עליון הוא. יש אחד שנקרא שנה, ויש אחד שנקרא חדש, מה בין זה לזה. \u0003חדש\u0004 הוא הלבנה. דהיינו המלכות, \u0003שנה\u0004 זה השמש, שהוא ז\"א, המאיר ללבנה. ובשנה השנית בחדש הראשון יורה על זווג ז\"א ומלכות הנקראים שנה וחדש, במקום מדבר סיני, שהוא זווג שני לאחר יציאת מצרים. שזה היה בזמן שכל מצות התורה נמסרו בו. כי ע\"י זווג זו\"ן שבמדבר סיני ניתנו כל מצות התורה."],[1,"ר\"ש אמר ווי","וכו': רש\"א, אוי לאותו אדם שאומר, כי התורה באה לספר ספורים בפשטות, ודברי הדיוט של עשו ולבן וכדומה, כי אם כן, אפילו בזמן הזה אנו יכולים לעשות תורה מדברי הדיוט, ועוד יותר יפים מהם, ואם התורה באה להראות דברי העולם, אפילו שליטי העולם יש ביניהם דברים מעולים יותר. אם כן נלך אחריהם ונעשה מהם תורה, כאותו האופן. אלא שכל דברי התורה, הם דברים עליונים, וסודות עליונים."],[2,"ת\"ח עלמא עלאה","וכו': בוא וראה, עולם העליון ועולם התחתון, במשקל אחד נשקלו. ישראל למטה כנגד מלאכים עליונים למעלה. מלאכים עליונים כתוב בהם עושה מלאכיו רוחות. ובשעה שיורדים למטה מתלבשים בלבוש של עולם הזה, ואם לא היו מתלבשים בלבוש כעין עולם הזה לא היו יכלו לעמוד בעולם הזה, והעולם לא סבל אותם. ואם במלאכים כך, התורה שבראה את המלאכים ואת כל העולמות, והם מתקיימים בשבילה, על אחת כמה וכמה, כיון שירדה לעולם הזה, אם לא היתה מתלבשת באלו הלבושים שבעולם הזה, שהם הספורים ודברי הדיוט, לא היה יכול העולם לסבול."],[3,"וע\"ד האי ספור","וכו': וע\"כ ספור הזה שבתורה היא לבושה של התורה, מי שחושב שאותו הלבוש הוא תורה ממש ואין בו דבר אחר, תיפח רוחו, ולא יהיה לו חלק לעולם הבא. משום זה, אמר דוד, גל עיני ואביטה נפלאות מתורתך, דהיינו להביט מה שמתחת לבושה של התורה."],[4,"ת\"ח אית לבושא","וכו': בוא וראה, יש לבוש הנראה לכל, ואלו הטפשים כשרואים אדם לבוש יפה, שנראה להם הדור בלבושו, אין מסתכלים יותר, ודנים אותו ע\"פ לבושו ההדור. וחושבים את הלבוש כגוף האדם, וחושבים גוף האדם כמו נשמתו."],[5,"כהאי גוונא אורייתא","וכו': כעין זה היא התורה, יש לה גוף, והוא מצות התורה הנקראות גופי תורה. גוף הזה מתלבש בלבושים שהם ספורים של עולם הזה, הטפשים שבעולם אינם מסתכלים אלא בלבוש ההוא, שהוא ספור התורה ואינם יודעים יותר, ואינם מסתכלים במה שיש תחת לבוש ההוא. אלו שיודעים יותר, אינם מסתכלים בלבוש, אלא בגוף שהוא תחת הלבוש ההוא. החכמים, עבדי המלך העליון, אותם שעמדו בהר סיני, אינם מסתכלים אלא בנשמה שבתורה, שהוא עיקר הכל, תורה ממש. ולעתיד לבא, עתידים להסתכל בנשמה של נשמה שבתורה."],[6,"ת\"ח הכי נמי","וכו': בוא וראה, אף כך הוא למעלה, שיש לבוש, גוף, נשמה, ונשמה לנשמה. השמים וצבאם, אלו הם \u0003לבוש.\u0004 וכנסת ישראל שהיא המלכות, היא \u0003גוף,\u0004 המקבל \u0003הנשמה,\u0004 שהיא תפארת ישראל. דהיינו ז\"א, וע\"כ המלכות היא גוף לנשמה. כי ז\"א מתלבש בה כמו נשמה בגוף. הנשמה שאמרנו שזו תפארת ישראל, הוא התורה ממש, דהיינו נשמת התורה הנ\"ל בדבור הסמוך, שבה מסתכלים החכמים. \u0003ונשמה לנשמה,\u0004 זה הוא עתיקא קדישא. שבו יסתכלו לעתיד לבא כנ\"ל בסמוך. והכל אחוז זה בזה, שעתיקא קדישא מתלבש בז\"א, וז\"א מתלבש במלכות, ומלכות בעולמות בי\"ע וכל צבאם."],[7,"ווי לאינון חייביא","וכו': אוי לאלו הרשעים האומרים שהתורה אינה יותר מספור בלבד, והם מסתכלים בלבוש ולא יותר, אשרי הם הצדיקים המסתכלים בתורה כראוי, יין אינו יושב אלא בכד, כך התורה אינה יושבת אלא בלבוש זה. וע\"כ לא צריכים להסתכל אלא במה שיש תחת הלבוש. וע\"כ כל אלו הדברים וכל אלו הספורים הם לבושים."],[8,"ויעשו","וגו' \u0003את הפסח במועדו\u0004 וכו': שואל, מהו ויעשו. שהיה לו לומר ויאכלו. אמר ר' יוסי, הרי למדנו, כל מי שמראה מעשה למטה כראוי, הוא כאלו עושה אותה למעלה, כיון שבשבילו נתעורר הדבר למעלה הוא, כביכול, כאלו עושה אותו. וכבר למדנו."]],[[0,"","וְאַף עַל גַּב שֶׁהִזְהִירָם בְּמִצְרַיִם, עַכְשָׁו צִוָּה לָהֶם פַּעַם אַחֶרֶת בְּאוֹתוֹ מָקוֹם שֶׁבּוֹ נִתְּנוּ כָּל מִצְווֹת הַתּוֹרָה. וְעַל כָּךְ בַּשָּׁנָה הַשֵּׁנִית. מַה זֶּה בַּשָּׁנָה הַשֵּׁנִית בַּחֹדֶשׁ הָרִאשׁוֹן? אֶלָּא סוֹד עֶלְיוֹן הוּא שָׁנָה אַחַת וְחֹדֶשׁ אֶחָד. מַה בֵּין זֶה לָזֶה? חֹדֶשׁ זוֹ הַלְּבָנָה. שָׁנָה זֶה הַשֶּׁמֶשׁ, שֶׁמֵּאִיר לַלְּבָנָה. וְאָז הָיָה בִּזְמַן שֶׁכָּל הַמִּצְווֹת נִמְסְרוּ בוֹ."],[1,"","רַבִּי שִׁמְעוֹן אָמַר, אוֹי לְאוֹתוֹ אִישׁ שֶׁאָמַר שֶׁתּוֹרָה זוֹ בָּאָה לְהַרְאוֹת סִפּוּרִים בְּעָלְמָא וְדִבְרֵי הֶדְיוֹטוֹת. שֶׁאִם כָּךְ, אֲפִלּוּ בִּזְמַן זֶה אָנוּ יְכוֹלִים לַעֲשׂוֹת תּוֹרָה בְּדִבְרֵי הֶדְיוֹטוֹת, וּבְשֶׁבַח יוֹתֵר מִכֻּלָּם. אִם לְהַרְאוֹת דְּבַר הָעוֹלָם, אֲפִלּוּ אוֹתָם סוֹפְרִים בָּעוֹלָם יֵשׁ בֵּינֵיהֶם דְּבָרִים יוֹתֵר עֶלְיוֹנִים. אִם כָּךְ, נֵלֵךְ אַחֲרֵיהֶם וְנַעֲשֶׂה מֵהֶם תּוֹרָה כְּמוֹ זֶה. אֶלָּא כָּל דִּבְרֵי הַתּוֹרָה דְּבָרִים עֶלְיוֹנִים הֵם וְסוֹדוֹת עֶלְיוֹנִים."],[2,"","בֹּא רְאֵה, עוֹלָם עֶלְיוֹן וְעוֹלָם תַּחְתּוֹן בְּמִשְׁקָל אֶחָד נִשְׁקְלוּ. יִשְׂרָאֵל לְמַטָּה - מַלְאָכִים עֶלְיוֹנִים לְמַעְלָה. בַּמַּלְאָכִים הָעֶלְיוֹנִים כָּתוּב, (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת. (זה במקום עליון) בְּשָׁעָה שֶׁיּוֹרְדִים לְמַטָּה (אף על גב שיורדים), מִתְלַבְּשִׁים בִּלְבוּשׁ הָעוֹלָם הַזֶּה. וְאִם לֹא יִתְלַבְּשׁוּ בִּלְבוּשׁ כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, לֹא יוּכְלוּ לַעֲמֹד בָּעוֹלָם הַזֶּה, וְהָעוֹלָם לֹא יִסְבֹּל אוֹתָם. וְאִם בְּמַלְאָכִים כָּךְ, הַתּוֹרָה שֶׁבָּרְאָה אוֹתָם וּבָרְאָה אֶת כָּל הָעוֹלָמוֹת וְעוֹמְדִים בִּגְלָלָהּ עַל אַחַת כַּמָּה וְכַמָּה, כֵּיוָן שֶׁיָּרְדָה לָעוֹלָם הַזֶּה, אִם לֹא תִתְלַבֵּשׁ בִּלְבוּשֵׁי הָעוֹלָם הַזֶּה, לֹא יוּכַל הָעוֹלָם לִסְבֹּל."],[3,"","וְעַל זֶה סִפּוּר זֶה שֶׁל הַתּוֹרָה, לְבוּשׁ הַתּוֹרָה הוּא. מִי שֶׁחוֹשֵׁב שֶׁאוֹתוֹ לְבוּשׁ הִיא הַתּוֹרָה מַמָּשׁ וְלֹא דָּבָר אַחֵר - תִּפַּח רוּחוֹ, וְלֹא יִהְיֶה לוֹ חֵלֶק לָעוֹלָם הַבָּא. בִּגְלַל זֶה אָמַר דָּוִד, (שם קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ. מַה שֶּׁתַּחַת לְבוּשׁ הַתּוֹרָה."],[4,"","בֹּא רְאֵה, יֵשׁ לְבוּשׁ שֶׁנִּרְאֶה לַכֹּל, וְאוֹתָם הַטִּפְּשִׁים כְּשֶׁרוֹאִים לְבוּשׁ עַל בֶּן אָדָם שֶׁנִּרְאֶה יָפֶה, לֹא מִסְתַּכְּלִים יוֹתֵר. חוֹשְׁבִים שֶׁאוֹתוֹ לְבוּשׁ הוּא הַגּוּף, וְחוֹשְׁבִים שֶׁהַגּוּף הִיא הַנְּשָׁמָה."],[5,"","כְּמוֹ זֶה הַתּוֹרָה יֵשׁ לָהּ גּוּף, וְהֵם מִצְווֹת הַתּוֹרָה שֶׁנִּקְרָאִים גּוּפֵי תוֹרָה. גּוּף זֶה מִתְלַבֵּשׁ בִּלְבוּשִׁים, שֶׁהֵם סִפּוּרֵי הָעוֹלָם הַזֶּה. טִפְּשֵׁי הָעוֹלָם לֹא מִסְתַּכְּלִים, רַק בְּאוֹתוֹ לְבוּשׁ, שֶׁהוּא סִפּוּר הַתּוֹרָה, וְלֹא יוֹדְעִים יוֹתֵר, וְלֹא מִסְתַּכְּלִים בְּמַה שֶּׁתַּחַת אוֹתוֹ לְבוּשׁ. אוֹתָם שֶׁיּוֹדְעִים יוֹתֵר לֹא מִסְתַּכְּלִים בַּלְּבוּשׁ, אֶלָּא בַּגּוּף שֶׁהוּא תַחַת אוֹתוֹ לְבוּשׁ. הַחֲכָמִים עַבְדֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהֵם עָמְדוּ בְּהַר סִינַי, לֹא מִסְתַּכְּלִים אֶלָּא רַק בַּנְּשָׁמָה, שֶׁהִיא עִקַּר הַכֹּל, תּוֹרָה מַמָּשׁ. (ולעולם) וְלֶעָתִיד לָבֹא עֲתִידִים לְהִסְתַּכֵּל בַּנְּשָׁמָה שֶׁל נִשְׁמַת הַתּוֹרָה."],[6,"","בֹּא רְאֵה, כָּךְ גַּם לְמַעְלָה יֵשׁ לְבוּשׁ, וְגוּף, וּנְשָׁמָה, וּנְשָׁמָה לִנְשָׁמָה. הַשָּׁמַיִם וְחֵילוֹתֵיהֶם אֵלֶּה אוֹתָם לְבוּשִׁים, וּכְנֶסֶת יִשְׂרָאֵל זֶה הַגּוּף שֶׁמְּקַבֵּל אֶת הַנְּשָׁמָה שֶׁהִיא תִפְאֶרֶת יִשְׂרָאֵל, וְעַל כָּךְ הִיא גּוּף לַנְּשָׁמָה. נְשָׁמָה שֶׁאָמַרְנוּ זוֹ תִפְאֶרֶת יִשְׂרָאֵל, שֶׁהִיא תּוֹרָה מַמָּשׁ. וּנְשָׁמָה לִנְשָׁמָה זֶהוּ הָעַתִּיק הַקָּדוֹשׁ, וְהַכֹּל אָחוּז זֶה בָּזֶה."],[7,"","אוֹי לְאוֹתָם רְשָׁעִים שֶׁאוֹמְרִים שֶׁהַתּוֹרָה הִיא רַק סִפּוּר בְּעָלְמָא, וְהֵם מִסְתַּכְּלִים בִּלְבוּשׁ זֶה וְלֹא יוֹתֵר. אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּסְתַּכְּלִים בַּתּוֹרָה כָּרָאוּי. יַיִן אֵינוֹ יוֹשֵׁב, רַק בְּקַנְקַן. כָּךְ הַתּוֹרָה אֵינָהּ יוֹשֶׁבֶת אֶלָּא בִּלְבוּשׁ זֶה, וְעַל כָּךְ לֹא צָרִיךְ לְהִסְתַּכֵּל אֶלָּא בְּמַה שֶּׁיֵּשׁ תַּחַת הַלְּבוּשׁ. וְעַל כָּךְ כָּל הַדְּבָרִים הַלָּלוּ וְכָל הַסִּפּוּרִים הַלָּלוּ הֵם לְבוּשִׁים."],[8,"","וְיַעָשׂוּ בְנֵי יִשְׂרָאֵל אֶת הַפָּסַח בְּמוֹעֲדוֹ. מַה זֶּה וְיַעֲשׂוּ? אָמַר רַבִּי יוֹסֵי, הֲרֵי נִתְבָּאֵר, כָּל מִי שֶׁמַּרְאֶה מַעֲשֶׂה לְמַטָּה כָּרָאוּי, כְּאִלּוּ עֲשָׂאוֹ לְמַעְלָה, שֶׁהֲרֵי בִּגְלָלוֹ הִתְעוֹרֵר דָּבָר זֶה, כִּבְיָכוֹל, כְּאִלּוּ הוּא עֲשָׂאוֹ, וַהֲרֵי נִתְבָּאֵר."]]],[["(במדבר ט׳:י׳) אִישׁ אִישׁ כִּי יִהְיֶה טָמֵא וְגוֹ'. אִישׁ אִישׁ תְּרֵי זִמְנֵי, אֲמַאי, אֶלָּא אִישׁ דְּהוּא אִישׁ, וְיִתְחֲזֵי לְקַבְּלָא נִשְׁמְתָא עִלָּאָה, וְהוּא פָּגִים גַּרְמֵיהּ. דְּלָא שַׁרְיָיא עֲלוֹי שְׁכִינְתָּא (ס\"א שירותא) (ס\"א נשמתא) עִלָּאָה. מַאי טַעְמָא. בְּגִין דְּאִיהוּ גָּרִים, וְהוּא מְסָאֵב לֵיהּ לְגַרְמֵיהּ. וְעַל דָּא אִישׁ אִישׁ. אִישׁ דְּיִתְחֲזֵי לְמֶהֱוִי אִישׁ, וְהוּא מְסָאֵב גַּרְמֵיהּ, דְּלָא יִשְׁרֵי עֲלוֹי קְדוּשָּׁה דִּלְעֵילָּא.","(במדבר ט׳:י׳) אוֹ בְדֶרֶךְ רְחוֹקָה, דָּא אִיהוּ חַד מֵעַשְׂרָה דְּאִינּוּן נְקוּדִים בְּאוֹרַיְיתָא, וְכֻלְּהוּ אַתְיָין לְאַחֲזָאָה מִלָּה. מַאי בְדֶרֶךְ רְחוֹקָה. בְּגִין דְּבַּר נָשׁ דְּאִיהוּ מַסְאִיב גַּרְמֵיהּ, מְסָאֲבִין לֵיהּ לְעֵילָּא. כֵּיוָן דִּמְסָאַבִין לֵיהּ לְעֵילָּא, הָא אִיהוּ בְּדֶרֶךְ רְחוֹקָה. מֵהַהוּא אֲתָר וְאָרְחָא דְּזַרְעָא דְּיִשְׂרָאֵל אֲחִידָן בֵּיהּ, הָא בְּדֶרֶךְ רְחוֹקָה אָחִיד, דְּאִתְרְחַק (נ\"א מלמקרב) לְמִקְרַב לְכוֹן, וּלְאִתְקַשְּׁרָא בְּכוֹן, כְּמָה דְּאַתּוּן מִתְקַשְּׁרִין.","אָמַר רִבִּי יִצְחָק, וְהָא כְּתִיב כִּי יִהְיֶה טָמֵא לָנֶפֶשׁ אוֹ בְדֶרֶךְ רְחוֹקָה, דְּאִתְחֲזֵי תְּרֵין מִלִּין. מַשְׁמַע דִּכְתִּיב אוֹ. אָמַר רִבִּי יוֹסֵי, כָּאן, עַד לָא מְסָאֲבִין לֵיהּ. כָּאן, בָּתַר דִּמְסָאַבִין לֵיהּ. וּמַשְׁמַע אֲפִילּוּ הַאי, אוֹ הַאי, לָא יִשְׁרֵי עֲלוֹי קְדוּשָּׁה דִּלְעֵילָּא, וְלָא יַעַבְדוּן פִּסְחָא בְּזִמְנָא דְּיִשְׂרָאֵל עָבְדִין לֵיהּ.","וְאִי תֵּימָא, הָא בְּיַרְחָא תִּנְיָינָא עָבִיד אִי לָא מְתַקֵּן גַּרְמֵיהּ. לָא, אֶלָּא כֵּיוָן דְּמִתַדְּכֵי וּמְתַקֵּן גַּרְמֵיהּ, הָא יַרְחָא תִּנְיָינָא לְמֶעְבַּד פִּסְחָא. מִכָאן, כָּל בַּר נָשׁ דִּמְדָּכֵי גַּרְמֵיהּ, מְדָכָּאן לֵיהּ.","דְּאִי תֵּימָא דִּבְדַּרְגָּא עִלָּאָה יַתִיר קָאִים בְּיַרְחָא תִּנְיָינָא. לָאו הָכִי, דְּהָא יִשְׂרָאֵל זַרְעָא קַדִּישָׁא דְּעָבְדוּ פִּסְחָא בְּזִמְנֵיהּ, נַטְלוּ לֵיהּ לְסִיהֲרָא וּלְשִׁמְשָׁא כְּחָד. וּמַאן דְּנָטִיל יְסוֹדָא בְּקַדְמִיתָא, נָטִיל בִּנְיָינָא. מַאי יְסוֹדָא. לָא תֵּימָא יְסוֹדָא עִלָּאָה דְּצַדִּיקָא דְּעָלְמָא, אֶלָּא יְסוֹדָא דְּאֶבֶן טָבָא, כְּמָה דְאַתְּ אָמֵר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָה. וְהַאי הוּא אֶבֶן דְּשָׁארִי עָלֵיהּ מַאן דְּשָׁארֵי.","אָמַר רִבִּי יְהוּדָה, וַדַּאי כֹּלָּא נָטִיל אֲפִילּוּ בְּיַרְחָא תִּנְיָינָא. אֲבָל לָאו אִיהוּ כְּמַאן דְּנָטִיל לֵיהּ בְּזִמְנֵיהּ. מַאי טַעֲמָא. דָּא דְּנָטִיל פִּסְחָא בְּזִמְנֵיהּ, נָטִיל מִתַּתָּא לְעֵילָּא, וְלָא נָחִית. בְּגִין דְּמַעֲלִין בַּקֹּדֶשׁ, וְלָא מוֹרִידִין. וְדָא דְּנָטִיל בָּתַר זִמְנֵיהּ, נָחִית מֵעֵילָּא לְתַתָּא. בְּגִין כָּךְ שַׁוְיָן בְּכֹלָּא, וְלָא שַׁוְיָן. דְּדָא סָלִיק וְלָא נָחִית, וְדָא נָחִית וְלָא סָלִיק. בְּגִין כַּךְ מַאן דִּמְקָרֵב פִּסְחָא בְּזִמְנֵיהּ, שְׁבָחָא יַתִיר אִית לֵיהּ. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּזַכָּאן בְּכֹלָּא, דְּזַכָּאן בְּאוֹרַיְיתָא, וְכָל מַאן דְּזָכֵי בְּאוֹרַיְיתָא, זָכֵי לֵיהּ בִּשְׁמָא קַדִּישָׁא. זַכָּאִין אִינּוּן יִשְׂרָאֵל, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי."],[[0,"איש איש כי יהיה טמא","וגו': שואל, איש איש ב' פעמים, למה. ומשיב אלא הפירוש הוא איש שהוא איש, דהיינו שהוא ראוי לקבל נשמה עליונה, והוא פגם עצמו שאין השכינה העליונה שורה עליו. מהו הטעם. משום שהוא גרם, שהוא טימא את עצמו. וע\"כ כתוב איש איש, שפירושו, שראוי להיות איש, והוא טימא את עצמו, שלא ישרה עליו קדושה שלמעלה."],[1,"או בדרך רחוקה:","זה הוא אחד מעשרה מקומות שהם מנוקדים בתורה. וכולם באות להראות איזה דבר. מהו בדרך רחוקה. כי יש נקודה על הה של רחוקה, הוא משום, שאדם שמטמא את עצמו, מטמאים אותו למעלה. כיון שמטמאים אותו למעלה, הרי הוא בדרך רחוקה מאותו המקום והדרך שזרע ישראל אחוזים בו, כי הוא אחוז בדרך רחוקה, שנתרחק מלקרב לכם לישראל, ולהתקשר בכם כמו שאתם מתקשרים. וע\"כ כתוב בדרך רחוקה לכם, בנקודה על \u0003ה'\u0004 דרחוקה. להורות שהכונה הוא על סטרא אחרא הרחוקה מקדושה."],[2,"א\"ר יצחק והא","וכו': אר\"י, והרי כתוב, כי יהיה טמא לנפש או בדרך רחוקה, שמשמע שהם ב' דברים, שזה משמע משכתוב או. ואיך תאמר שהם דבר אחד, אשר הטומאה גרמה לו לדרך רחוקה. אמר ר' יוסי כאן, כשאומר טמא לנפש, הפירוש הוא מטרם שטמאו אותו מלמעלה. וכאן, כשאומר בדרך רחוקה, הפירוש הוא, אחר שטמאו אותו למעלה ונפל לדרך רחוקה שהוא הס\"א. ומשמע שהן זה והן זה, לא ישרה עליו הקדושה שלמעלה, ולא יעשו הפסח בזמן שישראל עושים אותו."],[3,"ואי תימא הא","וכו': ואם תאמר הרי בחדש השני הוא עושה הפסח, אע\"פ שאינו מתקן עצמו. אינו כן, אלא אחר שנטהר ותקן את עצמו, יש לו חדש שני לעשות הפסח. מכאן, כל אדם שמטהר עצמו, מטהרין אותו מלמעלה."],[4,"דאי תימא דבדרגא","וכו': ואם תאמר, שבמדרגה עליונה יותר הוא נמצא בחדש השני. אינו כן, כי ישראל זרע קדוש העושים הפסח בזמנו, לוקחים הלבנה והשמש, שהם מלכות וז\"א, כאחד, ומי שלוקח היסוד בתחלה הוא לוקח הבנין. מהו יסוד. אל תאמר שהוא יסוד העליון של צדיק העולם, שהוא יסוד דז\"א, אלא היסוד של אבן טוב, שהוא המלכות, כש\"א אבן מאסו הבונים היתה לראש פנה, כי זו היא אבן ששורה עליו מי ששורה, דהיינו ז\"א. וז\"ש, \u0003מי שלוקח היסוד בתחלה,\u0004 דהיינו שלוקח תחלה את המלכות, שהיא יסוד, שעליה נבנים כל הספירות דז\"א \u0003נטיל בנינא,\u0004 הוא לוקח גם הבנין. שהם כל הספירות שעליה מז\"א. כי המלכות הוא פתח לז\"א."],[5,"א\"ר יהודה ודאי","וכו': אר\"י, ודאי הכל לוקח אפילו בחדש השני, דהיינו שגם בחדש השני לוקח המלכות וז\"א כאחד כמו בפסח ראשון. אבל הוא אינו שוה כמי שלוקח הפסח בזמנו. מהו הטעם. הוא משום שזה הלוקח הפסח בזמנו מקבל ממטה למעלה, ואינו יורד. משום שמעלים בקדש ואין מורידים. וזה שלוקח הפסח אחר זמנו, יורד ממעלה למטה, משום זה הם שוים בכל ואינם שוים, כי זה עולה ואינו יורד, וזה יורד ואינו עולה, משום זה מי שמקריב הפסח במועדו הוא יותר משובח. אשרי הם ישראל שזוכים בכל, כי זוכים בתורה, וכל מי שזוכה בתורה זוכה בשם הקדוש. אשרי הם ישראל בעולם הזה ובעולם הבא."],[5,"","פירוש. חדש הראשון ה\"ס ימין, וחדש השני ה\"ס השמאל. ופסח ה\"ס המוחין דהארת חכמה ששורשם בקו שמאל דבינה. וצריכים לקחת אותם מקו ימין, שה\"ס חדש הראשון, שאז הזמן להקריב הפסח. ואז מעלים בקדש, והאורות מתרבים והולכים כדרך הקדושה. אבל המקריב בחדש השני, שלוקח המוחין דפסח מקו השמאל, אז האורות מתמעטים ויורדים כדרך פרי החג. וז\"ש, \u0003דא דנטיל פסחא בזמניה נטיל מתתא לעילא\u0004 כלומר שאורותיו הולכים ומתרבים כדרך האורות המתוקנים בקדושה. \u0003בגין דמעלין בקדש ואין מורידים\u0004 שכן דרך הימין, \u0003ולא נחית,\u0004 שאין האורות מתמעטים. \u0003ודא דנטיל בתר זמניה נחית מעילא לתתא,\u0004 שמוריד חשיבות האורות ממעלה למטה, כלומר שהולכים ומתמעטים כמו פרי החג, שהוא משום שלוקחם מקו שמאל, שהוא חדש השני."]],[[0,"","אִישׁ אִישׁ כִּי יִהְיֶה טָמֵא וְגוֹ'. אִישׁ אִישׁ - שְׁתֵּי פְעָמִים, לָמָּה? אֶלָּא אִישׁ שֶׁהוּא אִישׁ וְרָאוּי לְקַבֵּל נְשָׁמָה עֶלְיוֹנָה, וְהוּא פָּגַם עַצְמוֹ שֶׁלֹּא שׁוֹרָה עָלָיו שְׁכִינָה (תחלה) (נשמה) עֶלְיוֹנָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא גָּרַם וְהוּא טִמֵּא אֶת עַצְמוֹ. וְעַל זֶה אִישׁ אִישׁ. אִישׁ שֶׁרָאוּי לִהְיוֹת אִישׁ, וְהוּא מְטַמֵּא אֶת עַצְמוֹ שֶׁלֹּא תִשְׁרֶה עָלָיו קְדֻשָּׁה שֶׁל מַעְלָה."],[1,"","אוֹ בְדֶרֶךְ רְחוֹקָה - זֶהוּ אֶחָד מֵעֲשָׂרָה שֶׁהֵם נְקוּדִים בַּתּוֹרָה, וְכֻלָּם בָּאִים לְהַרְאוֹת דָּבָר. מַה זֶּה בְּדֶרֶךְ רְחוֹקָה? מִשּׁוּם שֶׁאָדָם שֶׁהוּא מְטַמֵּא אֶת עַצְמוֹ, מְטַמְּאִים אוֹתוֹ מִלְמַעְלָה. כֵּיוָן שֶׁמְּטַמְּאִים אוֹתוֹ מִלְמַעְלָה, הֲרֵיהוּ בְדֶרֶךְ רְחוֹקָה. מֵאוֹתוֹ מָקוֹם וְדֶרֶךְ שֶׁזֶּרַע יִשְׂרָאֵל אֲחוּזִים בּוֹ, הֲרֵי בְּדֶרֶךְ רְחוֹקָה אָחוּז, שֶׁהִתְרַחֵק (מלהתקרב) לִקְרַב אֲלֵיכֶם וּלְהִתְקַשֵּׁר בּכֶם כְּמוֹ שֶׁאַתֶּם מִתְקַשְּׁרִים."],[2,"","אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב כִּי יִהְיֶה טָמֵא לָנֶפֶשׁ אוֹ בְדֶרֶךְ רְחוֹקָה, שֶׁנִּרְאֶה שְׁנֵי דְבָרִים מִמַּשְׁמָע שֶׁכָּתוּב אוֹ. אָמַר רַבִּי יוֹסֵי, כָּאן עַד שֶׁלֹּא מְטַמְּאִים אוֹתוֹ, כָּאן אַחַר שֶׁטִּמְּאוּ אוֹתוֹ. וּמַשְׁמָע אֲפִלּוּ זֶה אוֹ זֶה לֹא תִשְׁרֶה עָלָיו קְדֻשָּׁה שֶׁלְּמַעְלָה, וְלֹא יַעֲשׂוּ פֶסַח בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹשִׂים אוֹתוֹ."],[3,"","וְאִם תֹּאמַר, הֲרֵי בַּחֹדֶשׁ הַשֵּׁנִי עוֹשֶׂה אִם לֹא תִקֵּן עַצְמוֹ - לֹא! אֶלָּא כֵּיוָן שֶׁנִּטְהַר וְתִקֵּן עַצְמוֹ, הֲרֵי הַחֹדֶשׁ הַשֵּׁנִי לַעֲשׂוֹת פֶּסַח. מִכָּאן, כָּל אִישׁ שֶׁמְּטַהֵר עַצְמוֹ, מְטַהֲרִים אוֹתוֹ."],[4,"","שֶׁאִם תֹּאמַר שֶׁבְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר עוֹמֵד בַּחֹדֶשׁ הַשֵּׁנִי - לֹא כָּךְ! שֶׁהֲרֵי יִשְׂרָאֵל זֶרַע קֹדֶשׁ שֶׁעָשׂוּ פֶסַח בִּזְמַנּוֹ, לָקְחוּ אֶת הַלְּבָנָה וְאֶת הַשֶּׁמֶשׁ כְּאֶחָד, וּמִי שֶׁלּוֹקֵחַ יְסוֹד בַּתְּחִלָּה - לוֹקֵחַ הַבִּנְיָן. מָה הַיְסוֹד? אַל תֹּאמַר יְסוֹד עֶלְיוֹן שֶׁל צַדִּיק הָעוֹלָם, אֶלָּא יְסוֹד שֶׁל אֶבֶן טוֹבָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְזוֹהִי הָאֶבֶן שֶׁשּׁוֹרֶה עָלֶיהָ מִי שֶׁשּׁוֹרֶה."],[5,"","אָמַר רַבִּי יְהוּדָה, וַדַּאי הַכֹּל אֲפִלּוּ בַּחֹדֶשׁ הַשֵּׁנִי, אֲבָל אֵינוֹ כְּמִי שֶׁנּוֹטֵל בִּזְמַנּוֹ. מָה הַטַּעַם? זֶה שֶׁנּוֹטֵל פֶּסַח בִּזְמַנּוֹ, נוֹטֵל מִמַּטָּה לְמַעְלָה וְלֹא יוֹרֵד, מִשּׁוּם שֶׁמַּעֲלִים בַּקֹּדֶשׁ וְלֹא מוֹרִידִים. וְזֶה שֶׁנּוֹטֵל אַחַר זְמַנּוֹ, יוֹרֵד מִמַּעְלָה לְמַטָּה. בִּגְלַל זֶה שָׁוִים בַּכֹּל, וְלֹא שָׁוִים. שֶׁזֶּה עוֹלֶה וְלֹא יוֹרֵד, וְזֶה יוֹרֵד וְלֹא עוֹלֶה. בִּגְלַל כָּךְ מִי שֶׁמַּקְרִיב פֶּסַח בִּזְמַנּוֹ, יֵשׁ לוֹ שֶׁבַח יוֹתֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁזַּכָּאִים בַּכֹּל, שֶׁזַּכָּאִים בַּתּוֹרָה, וְכָל מִי שֶׁזּוֹכֶה בַתּוֹרָה, זוֹכֶה לוֹ בַּשֵּׁם הַקָּדוֹשׁ. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."]]],[["\u0003רעיא מהימנא\u0004 פִּקּוּדָא לְמֶעְבַּד פֶּסַח שֵׁנִי, עַל אִינּוּן דְּלָא יָכִילוּ, אוֹ דְּאִסְתְּאָבוּ בִּמְסָאֲבוּ אַחֲרָא. אִי רָזָא דְּפֶסַח, רָזָא דִּמְהֵימְנוּתָא דְּיִשְׂרָאֵל עָאלִין בָּהּ, שַׁלְטָא בְּנִיסָן, וּכְדֵין אִיהוּ זִמְנָא לְחֶדְוָה, אֵיךְ יַכְלִין אִלֵּין דְּלָא יָכִילוּ, אוֹ דְּאִסְתְּאָבוּ, לְמֶעְבַּד בְּיַרְחָא תִּנְיָינָא, דְּהָא אַעְבָּר זִמְנָא.","אֶלָּא כֵּיוָן דְּכְּנֶסֶת יִשְׂרָאֵל מִתְעַטְרָא בְּעִטְרָהָא בְּנִיסָן, לָא אִתְעֲדִיאַת כִּתְרָהָא וְעִטְרָהָא מִנָּהּ תְּלָתִין יוֹמִין. וְכָל אִינּוּן ל' יוֹמִין מִן יוֹמָא דְּנַפְקוּ יִשְׂרָאֵל מִפֶּסַח יָתְבָא מַטְרוֹנִיתָא בְּעִטְרָהָא, וְכָל חֵילָאָה בְּחֶדְוָה. מַאן דְּבָעֵי לְמֵחֱמֵי לְמַטְרוֹנִיתָא, יָכִיל לְמֵחֱמֵי. כָּרוֹזָא כָּרִיז, כָּל מַאן דְּלָא יָכִיל לְמֵחֱמֵי מַטְרוֹנִיתָא, יֵיתֵי וְיֶחְמֵי עַד לָא יִנְעֲלוּן תַּרְעֵיה. אֵימָתַי כָּרוֹזָא כָּרִיז. בְּאַרְבָּעָה עָשָׂר לְיַרְחָא תִּנְיָינָא, דְּהָא מִתַּמָּן עַד שִׁבְעָה יוֹמִין, תַּרְעִין פְּתִיחָן. מִכָּאן וּלְהָלְאָה יִנְעֲלוּן תַּרְעֵי. וְעַל דָּא פֶּסַח שֵׁנִי. (ע\"כ) (פקודא דא לספור ספירת העומר צ\"ז ע\"א)","פִּקּוּדָא דָא, שְׁחִיטַת הַפֶּסַח בִּזְמַנּוֹ. וַאֲבַּתְרֵיהּ פֶּסַח רִאשׁוֹן וּפֶסַח שֵׁנִי לֶאֱכוֹל אוֹתָן כְּמִשְׁפָּטָן. וּטְמֵאִים לִהְיוֹת נִדְחִים לְפֶסַח שֵׁנִי, דְּאִיהוּ פִּקּוּדָא תְּלִיתָאָה. תָּנָאִין וַאֲמוֹרָאִין, אִית בְּנֵי נָשָׁא כְּחוּלִין דְּטָהֲרָה, מִסִּטְרָא דְּמִיכָאֵל. וּכְחוּלִין דְּהֶקְדֵשׁ, כְּגוֹן בְּשַׂר קֹדֶשׁ, וְאִינּוּן מִסִּטְרָא דְּגַבְרִיאֵל. כֹּהֵן וְלֵוִי. וְאִית בְּנֵי נָשָׁא דְּאִינּוּן כְּיוֹמִין טָבִין, וְאִינּוּן קֹדֶשׁ קֳדָשִׁים.","שְׁכִינְתָּא אִיהִי פֶּסַח רִאשׁוֹן, מִימִינָא. וּפֶסַח שֵׁנִי, מִשְּׂמָאלָא. פֶּסַח רִאשׁוֹן מִימִינָא, דְּתַמָּן חָכְמָ\"ה. פֶּסַח שֵׁנִי מִשְּׂמָאלָא, דְּתַמָּן בִּינָה. וּבְגִין דְּבִגְבוּרָה מִתְעַבְּרִין כָּל אֶשִּׁין נוּכְרָאִין, דְּאִינּוּן כְּקַּשׁ וְתֶבֶן לְגַבֵּי אֵשׁ דִּגְבוּרָה, טְמֵאִים נִדְחִים לְפֶסַח שֵׁנִי.","וְכָל טוּמְאָה נִדָּה, וּמְצּוֹרָע, וְזָב וְזָבָה וְיוֹלֶדֶת, בְּאֶשָּׁא דִּגְבוּרָה אִיהוּ שׂוֹרֵף. דְּנִשְׁמְתָא אִיהוּ מָאנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִיהוּ לָא שָׁרֵי בָּהּ, עַד דְּאִתְלַבְּנַת בְּאֶשָּׁא דִּגְבוּרָה, דִּכְתִּיב, (ירמיהו כ״ג:כ״ט) הֲלֹא כֹה דְּבָרִי כָּאֵשׁ נְאֻם יְיָ. וּבְהַאי אֶשָּׁא, אִם בַּרְזְל הוּא מִתְפּוֹצֵּץ, וְאִם אֶבֶן הוּא נִמוֹחַ.","וּבִימִינָא (נ\"א ובמיא) דְּתַמָּן תּוֹרָה שֶׁבִּכְתָב, דְּאִיהִי מַיִם, (ויקרא י״ב:ז׳) וְטָהֲרָה מִמְּקוֹר דָּמֶיהָ, וְאִתְדַּכֵּי בָּהּ מְצּוֹרָע, וְטָמֵא מֵת, וְזָב וְטָמֵא בְּכָל מִינֵי שֶׁרֶץ. הֲדָא הוּא דִכְתִיב, (יחזקאל לג) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם וְגוֹ'.","בְּעַמּוּדָא דְּאֶמְצָּעִיתָא מָאנָא אִתְיַחֲדַת בְּבַעְלָהּ, דְּאִיהִי אִתְּתָא, בָּתַר דְּאִתְקַדְּשַׁת בִּשְׂמָאלָא, וְאִתְדַכְּאַת בְּמֵי מִקְוֵה בִּימִינָא, וְאוֹמְרִים עַל מָאנֵי דְּפִסְחָא, כֵּלִים שֶׁנִּשְׁתַּמְּשׁוּ בָּהֶן בְּצּוֹנֵן, מַטְבִּילָן בְּצּוֹנֵן, וְהֵן טְהוֹרִים. אִינּוּן נִשְׁמָתִין דְּאִינּוּן מִסִּטְרָא דְּרַחֲמֵי, וְאִינּוּן רַחֲמָנִים, מָארֵי חִנָּא וְחִסְדָּא, לָא צְּרִיכִין לְאַדְכְּאָה בְּמַיִם פּוֹשְׁרִים כַּבֵּינוֹנִיִּים. כָּל שֶׁכֵּן בְּחַמֵּי חַמִּין, דִּבְהוֹן מִתְדָּכִין רְשָׁעִים גְּמוּרִים, דִּמְחַמְּמִין גַּרְמַיְיהוּ בְּאֶשָּׁא דְיִצֶּר הָרָע. וְעָלַיְיהוּ אִתְּמַר, כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ. בְּגִין דְּזוּהֲמָא דִּלְהוֹן נְפִישָׁא. אֲבָל צַּדִיקִים גְּמוּרִים בְּצּוֹנֵן. דְּעָלַיְיהוּ אִתְּמַר, כָּל הַמֵּשִׂים רֶיוַח בֵּין הַדְּבֵקִים, מְצַּנְּנִים לֵיהּ גֵּיהִנָּם.","וְאִי נִשְׁמָתִין חָמְרִיִּים, דְּאִינּוּן כְּמָאנֵי חֶרֶס, שְׁבִירָתָן זוֹ הִיא טַהֲרָתָן. כְּמָה דְאַתְּ אָמֵר נִשְׁבָּרוּ, נִטְהָרוּ. וְרָזָא דְּמִלָּה, (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. אֲבָל אִינּוּן דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא דְּבִכְתָב וּבְאוֹרַיְיתָא דְבְּעַל פֶּה, דְּאִינּוּן אֵשׁ וּמַיִם, וְאִינּוּן דְּמִשְׁתַּדְּלִין בְּרָזֵי דְּאוֹרַיְיתָא, דְּאִיהוּ אוֹר, דִּכְתִּיב בָּהּ, (משלי ו׳:כ״ג) וְתוֹרָה אוֹר, בְּאוֹרַיְיתָא אִינּוּן מִתְדַּכִין בָּה.","וְעוֹד בְּפֶרֶק הָרוֹאֶה, הָרוֹאֶה תְּמָרִים בַּחֲלוֹם, תַּמּוּ עֲוֹנוֹתָיו. הֲדָא הוּא דִכְתִיב, (איכה ד׳:כ״ב) תַּם עֲוֹנֵךְ בַּת צִּיּוֹן. בְּגִין דִּתְמָרִים, בֵּיהּ תַּם, דַּרְגָא דְּיַעֲקֹב, דְּאִתְּמַר בֵּיהּ, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. חוֹבִין מָרִים, וְעַל דָּא תְּמָרִים: תַּמָּן תָּ\"ם, וְתַמָּן מָ\"ר.","הָכָא רָמִיז, וַיִמְתְּקוּ הַמָּיִם. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:כ״ה) וַיּוֹרֵהוּ יְיָ עֵץ וַיִמְתְּקוּ הַמָּיִם. מֵהָכָא, מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא, דְּאִיהוּ עֵץ. חוֹבִין דִּילֵיהּ, דְּאִתְּמַר בְּהוֹן (שמות א׳:י״ד) וַיְמָרַרוּ אֶת חַיִּיהֶם בַּעֲבוֹדָה קָשָׁה, קוּדְשָׁא בְּרִיךְ הוּא מָחִיל לֵיהּ, וְיִתְחַזְרוּן מְתִיקִין.","דְּיוֹמִין יֵיתוּן, דְּיִתְקַיָּים בְּהוּ כְּמַפְקָנוּ דְּמִצְּרַיִם, דְּאִתְּמַר בֵּיהּ (שמות א׳:ו׳) וַיָּמָת יוֹסֵף וְכָל אֶחָיו וְכֹל הַדּוֹר הַהוּא. וּבְגָלוּתָא בַּתְרָאָה, לֵית מִיתָה אֶלָּא עוֹנִי דְּעָנִי חָשׁוּב כַּמֵּת. לְקַיֵּים בְּהוֹן (צפניה ג׳:י״ב) וְהִשְׁאַרְתִּי בָּךְ עַם עָנִי וָדָל וְחָסוּ בְּשֵׁם יְיָ. לְאִתְקַיְּימָא בְּהוֹן (שמואל ב כ״ב:כ״ח) וְאֶת עַם עָנִי תּוֹשִׁיעַ. וְאִלֵּין עֲתִירִים דְּיִשְׁתַּאֲרוּן בְּהוֹן יִתְקַיֵּים בְּהוֹן, (שמות ה׳:י״ז) נִרְפִּים אַתֶּם נִרְפִּים. נִרְפִּים הֵם בְּאוֹרַיְיתָא. נִרְפִּים הֵם, לְמֶעְבַּד טִיבוּ עִם מָארֵי תּוֹרָה. וְאַנְשֵׁי חַיִל הַמְסוֹבְבִים מֵעִיר לָעִיר וְלָא יְחוּנָּנוּ.","וְנִרְפִּים הֵם בְּכוֹבֶד הַמַּס, דְּאִי תֵּימָא כְּבֵדִין אִינּוּן בְּכוֹבֶד הַמַּס, וְלָא עַבְדִין טִיבוּ, בְּגִין דָּא תִּכְבַּד הָעֲבוֹדָה עַל הָאֲנָשִׁים וְיַּעֲשׂוּ בָּה, דְּכוֹבֶד הַמַּס עָלַיְיהוּ, וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר, דְּאִינּוּן מְשַׁקְּרִין וְאַמְרִין דְּכוֹבֶד הַמַּס עָלַיְיהוּ, וּבְגִין דָּא לָא יַעַבְדּוּן טִיבוּ. אִינּוּן מְשַׁקְרָן בְּמִלּוּלַיְיהוּ, וְאַמְרִין דְּמֵהַכּוֹבֶד דְּתִכְבַּד עָלַיְיהוּ, תֶּבֶן אֵין נִתָּן, מָמוֹנָא דְּשִׁקְרָא, דְּבֵיהּ טוֹעִין (ס\"א שועין) לְּקוּדְשָׁא בְּרִיךְ הוּא וּבְגִין דְּלָא יִשְׁעוּן בֵּיהּ, וְלָא חָסוּ בְּשֵׁם יְיָ, אֵין נִתָּן לַעֲבָדֶיךָ.","וְאִלֵּין דְּאִית לוֹן, טָמִיר וְגָנִיז מָמוֹנָא מִלְּגוֹ, דְּאִיהוּ תּוֹכֶן, כְּגוֹן תּוֹךְ הָאוֹצָּר וְתֵיבָה, אִתְקַיָּים בְּהוּ וְתוֹכֶן לְבֵנִים תִּתֵּנוּ. וְדָא כְּסָפִים לְבָנִים, דִּיהוֹן בְּהַהוּא דָּרָא.","בְּהַהוּא זִמְנָא (שמות ט״ו:כ״ג) שָׁם שָׂם לוֹ חוֹק וּמִשְׁפָּט, וְאִינּוּן מָארֵי מִשְׁנָה. אוּף הָכָא וַיָבֹאוּ מָרָתָה, אִתְהַדָר לוֹן אוֹרַיְיתָא דִּבְעַל פֶּה, מָרָה בְּדַחֲקִין סַגִיאִין, בַּעַנִיוּתָא, דְּיִתְקַיָּים בְּהוּ, (שם א) וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה: זוֹ קוּשְׁיָא. בְּחֹמֶר: דָּא קַל וָחוֹמֶר. וּבִלְבֵנִים: דָּא לִבּוּן הֲלָכָה. וּבְכָל עֲבוֹדָה בַּשָּׂדֶה: דָּא בָּרַיְיתָא. אֵת כָּל עֲבוֹדָתָם אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ: דָּא תֵּיק\"וּ.","וְרַעְיָא מְהֵימָנָא, תַּמָּן אִתְקַיָּים בָּךְ, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. וּבְהַאי עֵץ הַדַּעַת טוֹב וָרָע, דְּאִיהוּ אִיסוּר וְהֵיתֶּר. וּבְאִינּוּן רָזִין דְּאִתְגַּלְּיָין עַל יְדָךְ, וַיִּמְתְּקוּ הַמַּיִם. כַּמֶּלַח דְּמַמְתְּקָת בִּשְׂרָא, הָכִי יִתְמַתְּקוּן בְּרַזְיָיא דְּאִתְגַּלְּיָין עַל יְדָךְ, כָּל אִינּוּן קוּשְׁיָין וּמַחְלוֹקוֹת, דְּמַיִין מְרִירָן דְּאוֹרַיְיתָא דִּבְעַל פֶּה, אִתְהֲדָרוּ מְתִיקָן מֵי אוֹרַיְיתָא, וְיִסוּרִין דִּילָךְ, בְּרָזִין אִלֵּין דְּאִתְגַּלְּיָין עַל יְדָךְ, יֵהוֹן לָךְ מְתִיקִן, וִיהַדְרוּן לָךְ כָּל דַּחֲקִין דִּילָךְ, כְּחֶלְמִין דְּעַבְרִין. וַחֲלֹ\"ם, בְּהִיפוּךְ אַתְוָון מֶלַ\"ח. דְּמַמְתְּקַת יַת בִּשְׂרָא. אוּף יִסּוּרִין מְמַתְקִים. כְּמָה דְּאוּקְמוּהָ.","וְלָרְשָׁעִים מִתְהַדְרָן יִסוּרִין מֶלַח סְדוֹמִית, דְּאִיהִי מְסַמֵּא אֶת הָעֵינַיִם, לְקַיְּימָא בְּהוּ (איוב י״א:כ׳) וְעֵינֵי רְשָׁעִים תִּכְלֶינָה. וְאִינּוּן עֵרֶב רַב רַשִּׁיעַיָּיא, דְּיִתְקַיָּים בְּהוּ בְּהַהוּא זִמְנָא, (דניאל י״ב:י׳) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים וְהִרְשִׁיעוּ רְשָׁעִים. יִתְלַבְּנוּ: אִינּוּן מָארֵי מִשְׁנָה. וְיִצָּרְפוּ: אִינּוּן זַרְעָא קַדִישָׁא דִּשְׁאַר עַמָּא. הֲדָא הוּא דִכְתִיב, (זכריה י״ג:ט׳) וּצְּרַפְתִּים כִּצְּרוֹף אֶת הַכֶּסֶף. וְהִרְשִׁיעוּ רְשָׁעִים, אִינּוּן עֵרֶב רַב."],[[0,"פקודא למעבד פסח שני","וכו': מצוה שיעשו פסח שני על אלו שלא יכלו לעשות הפסח במועדו, שהיו בדרך רחוקה. או שנטמאו בטומאה אחרת. שואל, אם סוד הפסח שהוא סוד האמונה שישראל נכנסו בה, שולטת בחדש ניסן, ואז הוא הזמן לשמחה, איך אלו שלא יכלו לעשותו במועדו, או שנטמאו, יכלו לעשות הפסח בחדש השני, הרי עבר זמנו."],[1,"אלא כיון דכ\"י","וכו': ומשיב, אלא כיון שכנסת ישראל, שהיא המלכות, מתעטרת בעטרות שלה, דהיינו במוחין דג\"ר, בחדש ניסן, אינה מסירה הכתרים והעטרות ממנה, כל שלשים יום. וכל אלו שלשים יום מיום שיצאו ישראל מפסח, יושבת המטרוניתא בעטרותיה, וכל צבאיה בשמחה. ומי שרוצה לראות המטרוניתא יכול לראות. והכרוז קורא, כל מי שלא יכול לראות המטרוניתא יבא ויראה מטרם שננעלו השערים. מתי מכריז הכרוז, הוא בי\"ד לחדש השני. כי משם עד שבעה ימים השערים פתוחים. מכאן ולהלאה סוגרים השערים. וע\"ז מביאים פסח שני."],[2,"פקודא דא שחיטת","וכו': מצוה זו היא שחיטת ה פסח בזמנו. ואחריה פסח ראשון ופסח שני לאכול אותם כמשפטם. והטמאים יהיו נדחים לפסח שני, שהיא מצוה שלישית. תנאים ואמוראים. יש בני אדם שהם כמו חולין דטהרה, מצד מיכאל. וכמו חולין מהקדוש, כגון בשר קדש והם מצד גבריאל, שמיכאל וגבריאל הם כהן ולוי, דהיינו חסד וגבורה. ויש בני אדם שהם כימים טובים, והם קדש קדשים."],[3,"שכינתא איהי פסח","וכו': השכינה היא פסח ראשון מצד הימין. כי חדש הראשון הוא קו ימין. ופסח שני משמאל. כי חדש השני הוא קו שמאל. כי ניסן אייר הם חסד וגבורה, פסח ראשון מימין, ששם החכמה. כי החכמה הוא בקו ימין. פסח שני הוא בשמאל, ששם בינה, כי הבינה היא בקו שמאל. ומשום שבגבורה, דהיינו בקו שמאל, נעברים כל אש זרה, שהם כקש וכתבן כלפי אש הגבורה, ע\"כ נדחים הטמאים לפסח שני."],[4,"וכל טומאה נדה","וכו': וכל טומאה נדה ומצורע וזב וזבה ויולדת, אש הגבורה שורפת אותם. כי הנשמה היא כלי של הקב\"ה, והקב\"ה אינו שורה בה עד שמתלבנת באש הגבורה. שכתוב, הלא כה דברי כאש נאם ה'. ובאש זה אם יצר הרע הוא ברזל, הוא מתפוצץ. ואם אבן הוא, נמוח."],[5,"ובימינא דתמן תורה","וכו': ובימין, ששם התורה שבכתב, שהיא נקראת מים, נאמר, וטהרה ממקור דמיה. ונטהר בה מצורע וטמא מת וזב וטמא בכל מיני שרץ. ז\"ש, וזרקתי עליכם מים טהורים וטהרתם וגו'."],[6,"בעמודא דאמצעיתא","וכו': בקו האמצעי הכלי, מתיחדת בבעלה, הכלי, היא אשה, מלכות אחר שמתקדשת בקו שמאל, ונטהרת במי מקוה בקו ימין, היא מתיחדת בקו האמצעי. ואומרים על כלים דפסח, כלים שנשתמשו בהם בצונן מטבילן בצונן והן טהורים, שהם הנשמות הבאות מצד הרחמים, והם רחמנים בעלי חן וחסד, אינם צריכים להטהר במים פושרים כבינונים, כ\"ש בחמי חמים, שבהם נטהרים רשעים גמורים המחממים עצמם באש היצר הרע. ועליהם נאמר, כל דבר אשר יבא באש וגו'. משום שהזוהמא שלהם רבה. אבל צדיקים גמורים בצונן, שעליהם אמרו, כל המשים ריוח בין הדבקים דהיינו שאינו מדבק אותיות שבקריאת שמע זו אל זו, מצננים לו הגיהנם."],[7,"ואי נשמתין חמריים","וכו': ואם הנשמות הן מגושמות, שהן ככלי חרס, שבירתם זו טהרתם, כמו שאתה אומר, נשברו נטהרו. וסוד הדבר זבחי אלקים רוח נשברה וגו'. אבל אלו העוסקים בתורה שבכתב ובתורה שבעל פה, שהן אש ומים, ואלו שמשתדלים בסודות התורה, שהוא אור, שכתוב בו, ותורה אור, הם נטהרים ע\"י התורה. ואינם צריכים גיהנם."],[8,"ועוד בפרק הרואה","וכו': ועוד, בפרק הרואה יש, הרואה תמרים בחלום, תמו עונותיו. ז\"ש תם עונך בת ציון משום שבתמרים יש אותיות תם, שהוא מדרגת יעקב, שכתוב בו, ויעקב איש תם. העונות הם מרים, וע\"כ תמרים, \u0003שם\u0004 אותיות \u0003תם\u0004 ושם אותיות \u0003מר,\u0004 וע\"כ רומזים שתמו עונותיו."],[9,"הכא רמיז וימתקו","וגו': כאן רמוז וימתקו המים. ז\"ש ויורהו ה' \u0003עץ\u0004 וימתקו המים. מכאן מי שמשתדל בתורה שהוא \u0003עץ\u0004 החיים, העונות שלו, שנאמר בהם, וימררו את חייהם בעבודה קשה, הקב\"ה מוחל אותם וחוזרים להיות מתוקים, דהיינו שהעונות יעשו כזכיות."],[10,"דיומין ייתון דיתקיים","וכו': כי ימים יבואו, ויתקיים בהם כביציאת מצרים, שנאמר שם, וימת יוסף וכל אחיו וכל הדור ההוא. ובגלות האחרון אין מיתה אלא עוני, כי עני חשוב כמת, לקיים בהם, והשארתי בכם עם עני ודל וחסו בשם ה'. ולהתקיים בהם, ואת עם עני תושיע. ואלו העשירים שישארו בהם, יתקיים בהם, נרפים אתם נרפים, נרפים, הם בתורה, נרפים, הם לעשות חסד עם בעלי תורה, ואנשי חיל המסובבים מעיר לעיר לא יחוננו."],[11,"ונרפים הם בכובד","וכו': ונרפים הם בכובד המס. כי אם תאמר שבשביל שהם כבדים בכובד המס אינם עושים חסד. משום זה, \u0003תכבד העבודה על האנשים\u0004 ויעשו בה, שכובד המס עליהם באמת. \u0003ואל ישעו בדברי שקר,\u0004 שהיו משקרים ואומרים שכובד המס עליהם, ומשום זה אינם עושים חסד. גם הם משקרים בדבריהם, שאומרים שמכובד המס המכביד עליהם, \u0003תבן אין נתן,\u0004 דהיינו ממון השקר, שטעו בו להקב\"ה, שמשום שלא שעו אליו ולא חסו בשם ה', תבן, שהוא ממון, אין נתן לעבדיך. ולא מטעם כובד המס."],[12,"ואלין דאית לון","וכו': ואלו שיש להם, הכסף נסתר וגנוז בפנים, שהוא \u0003תוכן,\u0004 כגון תוך האוצר, ותוך התיבה. ומתקיים בהם \u0003ותוכן\u0004 לבנים תתנו. וזה הוא כספים שהם לבנים, שיהיו בדור ההוא."],[13,"בההוא זמנא שם","וגו': בזמן ההוא, שם שם לו חק ומשפט. שהם בעלי המשנה, אף הם כך, ויבואו מרתה, שתורה שבעל פה תחזור להיות להם מרה, בדוחק רב ובעניות, שיתקיים בהם, וימררו את חייהם \u0003בעבודה קשה,\u0004 זו קושיא. \u0003בחמר,\u0004 זה הוא קל וחומר. \u0003ובלבנים,\u0004 זה הוא לבון הלכה. \u0003ובכל עבודה בשדה,\u0004 זה הוא ברייתא. כי ברייתא פירושו שדה. \u0003את כל עבודתם אשר עבדו בהם בפרך\u0004 זהו תיק\"ו."],[14,"ורעיא מהימנא תמן","וכו': ורועה הנאמן, שם יתקיים בך, שם שם לו חק ומשפט ושם נסהו. כי בעץ הדעת טוב ורע הזה, שהוא איסור והיתר, ובאלו הסודות שיתגלו על ידך, \u0003וימתקו המים,\u0004 כמו מלח הממתק את הבשר, כך יתמתקו בהסודות שיתגלו על ידך. כל אלו הקושיות והמחלוקת של מים המרים שבתורה שבעל פה, יחזרו להיות מי התורה, מתוקים. והיסורין שלך, ע\"י סודות אלו שיתגלו על ידך, יהיו לך מתוקים, וכל הצרות שלך יחזרו עליך כמו חלומות העוברים ואינם. \u0003וחלם\u0004 בהיפוך האותיות הוא \u0003מלח,\u0004 שכמו מלח הממתק את הבשר, כך היסורים ממתקים. כמו שהעמידוהו."],[15,"ולרשעים מתהדרן יסורין","וכו': ולרשעים יחזרו היסורים להיות כמלח סדומית המעוור את העינים. לקיים בהם, ועיני רשעים תכלינה. ואלו ערב רב הרשעים, יתקיים בהם בזמן ההוא, יתבררו ויתלבנו ויצרפו רבים והרשיעו רשעים. \u0003יתלבנו,\u0004 אלו הם בעלי משנה. \u0003ויצרפו,\u0004 אלו הם זרע קדוש שאר העם. ז\"ש וצרפתים כצרוף את הכסף. \u0003והרשיעו רשעים,\u0004 הם ערב רב."]],[[0,"","מִצְוָה לַעֲשׂוֹת פֶּסַח שֵׁנִי עַל אֵלּוּ שֶׁלֹּא יָכְלוּ אוֹ שֶׁנִּטְמְאוּ בְטֻמְאָה אַחֶרֶת. אִם סוֹד הַפֶּסַח סוֹד הָאֱמוּנָה שֶׁיִּשְׂרָאֵל נִכְנָסִים בָּהּ, שׁוֹלֵט בְּנִיסָן, וְאָז הוּא זְמַן לְשִׂמְחָה, אֵיךְ יָכְלוּ אֵלֶּה שֶׁלֹּא יָכְלוּ אוֹ שֶׁנִּטְמְאוּ לַעֲשׂוֹת בַּחֹדֶשׁ הַשֵּׁנִי, שֶׁהֲרֵי עָבַר הַזְּמַן?"],[1,"","אֶלָּא כֵּיוָן שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְעַטֶּרֶת בְּעַטְרוֹתֶיהָ בְּנִיסָן, לֹא מַעֲבִירָה כְתָרֶיהָ וְעַטְרוֹתֶיהָ מִמֶּנָּה שְׁלֹשִׁים יוֹם. וְכָל אוֹתָם שְׁלֹשִׁים יוֹם מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִפֶּסַח, יוֹשֶׁבֶת הַמַּלְכָּה בְּעַטְרוֹתֶיהָ, וְכָל חֵילוֹתֶיהָ בְּחֶדְוָה. מִי שֶׁרוֹצֶה לִרְאוֹת אֶת הַמַּלְכָּה יוּכַל לִרְאוֹת. הַכָּרוֹז מַכְרִיז: כָּל מִי שֶׁלֹּא יָכוֹל לִרְאוֹת אֶת הַמַּלְכָּה, יָבֹא וְיִרְאֶה עַד שֶׁלֹּא יִנָּעֲלוּ הַשְּׁעָרִים. אֵימָתַי הַכָּרוּז מַכְרִיז? בְּאַרְבָּעָה עָשָׂר לַחֹדֶשׁ הַשֵּׁנִי, שֶׁהֲרֵי מִשָּׁם וְעַד שִׁבְעָה יָמִים הַשְּׁעָרִים פְּתוּחִים. מִכָּאן וָהָלְאָה יִנָּעֲלוּ הַשְּׁעָרִים. וְעַל זֶה פֶּסַח שֵׁנִי."],[2,"","מִצְוָה זוֹ - שְׁחִיטַת הַפֶּסַח בִּזְמַנּוֹ. וְאַחֲרָיו פֶּסַח רִאשׁוֹן וּפֶסַח שֵׁנִי לֶאֱכֹל אוֹתָם כְּמִשְׁפָּטָן. וּטְמֵאִים לִהְיוֹת נִדְחִים לְפֶסַח שֵׁנִי, שֶׁהִיא מִצְוָה שְׁלִישִׁית. תַּנָּאִים וְאָמוֹרָאִים, יֵשׁ בְּנֵי אָדָם כְּמוֹ חֻלִּין שֶׁל טָהֳרָה מִצַּד מִיכָאֵל, וּכְמוֹ חֻלִּין שֶׁל הֶקְדֵּשׁ, כְּגוֹן בְּשַׂר קֹדֶשׁ, וְהֵם מִצַּד גַּבְרִיאֵל. כֹּהֵן וְלֵוִי. וְיֵשׁ בְּנֵי אָדָם שֶׁהֵם כְּמוֹ יָמִים טוֹבִים, וְהֵם קֹדֶשׁ קָדָשִׁים."],[3,"","שְׁכִינָה הִיא פֶּסַח רִאשׁוֹן מִיָּמִין, וּפֶסַח שֵׁנִי מִשְּׂמֹאל. פֶּסַח רִאשׁוֹן מִיָּמִין, שֶׁשָּׁם חָכְמָ\"ה. פֶּסַח שֵׁנִי מִשְּׂמֹאל, שֶׁשָּׁם בִּינָה. וּמִשּׁוּם שֶׁבִּגְבוּרָה עוֹבְרִים כָּל הָאִשִּׁים הַנָּכְרִיִּים, שֶׁהֵם כְּקַשׁ וְתֶבֶן לְגַבֵּי אֵשׁ שֶׁל גְּבוּרָה, הַטְּמֵאִים נִדְחִים לְפֶסַח שֵׁנִי."],[4,"","וְכָל טֻמְאָה נִדָּה, וּמְצֹרָע, וְזָב וְזָבָה וְיוֹלֶדֶת, בְּאֵשׁ הַגְּבוּרָה הוּא שׂוֹרֵף. שֶׁהַנְּשָׁמָה הִיא כְּלִי שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא לֹא שׁוֹרֶה בָּהּ עַד שֶׁמִּתְלַבֶּנֶת בְּאֵשׁ הַגְּבוּרָה, שֶׁכָּתוּב (ירמיהכג) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. וּבְאֵשׁ זוֹ, אִם בַּרְזֶל הוּא - מִתְפּוֹצֵץ, וְאִם אֶבֶן הוּא - נִמּוֹחַ."],[5,"","וּבְיָמִין, שֶׁשָּׁם תּוֹרָה שֶׁבִּכְתָב, שֶׁהִיא מַיִם - (ויקרא יב) וְטָהֳרָה מִמְּקוֹר דָּמֶיהָ, וְנִטְהָר בָּהּ מְצֹרָע, וּטְמֵא מֵת, וְזָב, וְטָמֵא בְּכָל מִינֵי שֶׁרֶץ. זֶהוּ שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם וְגוֹ'."],[6,"","בָּעַמּוּד הָאֶמְצָעִי כְּלִי מִתְיַחֶדֶת בְּבַעְלָהּ, שֶׁהִיא אִשָּׁה, אַחַר שֶׁמִּתְקַדֶּשֶׁת בִּשְׂמֹאל וְנִטְהֶרֶת בְּמֵי מִקְוֶה בְּיָמִין, וְאוֹמְרִים עַל כְּלֵי פֶסַח: כֵּלִים שֶׁנִּשְׁתַּמְּשׁוּ בָהֶם בְּצוֹנֵן, מַטְבִּילָם בְּצוֹנֵן וְהֵם טְהוֹרִים. אוֹתָן נְשָׁמוֹת שֶׁהֵן מִצַּד הָרַחֲמִים, וְהֵן רַחֲמָנִים, בַּעֲלֵי חֵן וָחֶסֶד, לֹא צְרִיכִים לְהִטָּהֵר בְּמַיִם פּוֹשְׁרִים כְּבֵינוֹנִיִּים. כָּל שֶׁכֵּן בְּחַמֵּי חַמִּים, שֶׁבָּהֶם נִטְהָרִים רְשָׁעִים גְּמוּרִים שֶׁמְּחַמְּמִים עַצְמָם בְּאֵשׁ יֵצֶר הָרָע, וַעֲלֵיהֶם נֶאֱמַר (במדבר לא) כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ, בִּגְלַל שֶׁזֻּהַמְתָּם רַבָּה. אֲבָל צַדִּיקִים גְּמוּרִים בְּצוֹנֵן, שֶׁעֲלֵיהֶם נֶאֱמַר, כָּל הַמֵּשִׂים רֶוַח בֵּין הַדְּבֵקִים מְצַנְּנִין לוֹ גֵּיהִנֹּם."],[7,"","וְאִם נְשָׁמוֹת חָמְרִיּוֹת, שֶׁהֵם כִּכְלֵי חֶרֶס - שְׁבִירָתָן זוֹהִי טָהֳרָתָן, כְּמוֹ שֶׁנֶּאֱמַר נִשְׁבָּרוּ, נִטְהָרוּ. וְסוֹד הַדָּבָר - (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. אֲבָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה שֶׁבִּכְתָב וּבַתּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהֵם אֵשׁ וּמַיִם, וְאוֹתָם שֶׁמִּשְׁתַּדְּלִים בְּסוֹדוֹת הַתּוֹרָה, שֶׁהִיא אוֹר, שֶׁכָּתוּב בָּהּ (משלי ו) וְתוֹרָה אוֹר, הֵם נִטְהָרִים בָּהּ."],[8,"","וְעוֹד בְּפֶרֶק הָרוֹאֶה: הָרוֹאֶה תְמָרִים בַּחֲלוֹם, תַּמּוּ עֲווֹנוֹתָיו. זֶהוּ שֶׁכָּתוּב (איכה ד) תַּם עֲוֹנֵךְ בַּת צִיּוֹן. מִשּׁוּם שֶׁתְּמָרִים, בּוֹ תָּם, דַּרְגַּת יַעֲקֹב, שֶׁנֶּאֱמַר בּוֹ (בראשית כה) וְיַעֲקֹב אִישׁ תָּם. עֲבֵרוֹת מָרוֹת, וְעַל כָּךְ תְּמָרִים - שָׁם תָּ\"ם, וְשָׁם מָ\"ר."],[9,"","כָּאן רָמוּז, וַיִּמְתְּקוּ הַמָּיִם. זֶהוּ שֶׁכָּתוּב (שמות טו) וַיּוֹרֵהוּ ה' עֵץ, וַיִּמְתְּקוּ הַמָּיִם. מִכָּאן, מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה שֶׁהִיא עֵץ, עֲווֹנוֹתָיו, שֶׁנֶּאֱמַר בָּהֶן (שם א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל לוֹ, וְיַחְזְרוּ מְתוּקִים."],[10,"","שֶׁיָּבֹאוּ יָמִים שֶׁיִּתְקַיֵּם בָּהֶם כִּיצִיאַת מִצְרַיִם, שֶׁנֶּאֱמַר בָּהּ (שם) וַיָּמָת יוֹסֵף וְכָל אֶחָיו וְכֹל הַדּוֹר הַהוּא. וּבַגָּלוּת הָאַחֲרוֹנָה אֵין מִיתָה, אֶלָּא עֹנִי, שֶׁעָנִי חָשׁוּב כְּמֵת, לְקַיֵּם בָּהֶם (צפניה ג) וְהִשְׁאַרְתִּי בְקִרְבֵּךְ (בך) עַם עָנִי וָדָל וְחָסוּ בְּשֵׁם ה'. לְהִתְקַיֵּם בָּהֶם (שמואל ב כב) וְאֶת עַם עָנִי תּוֹשִׁיעַ. וַעֲשִׁירִים אֵלּוּ שֶׁיִּשָּׁאֲרוּ בָהֶם, יִתְקַיֵּם בָּהֶם (שמות ה) נִרְפִּים אַתֶּם נִרְפִּים. נִרְפִּים הֵם בַּתּוֹרָה, נִרְפִּים הֵם לַעֲשׂוֹת טוֹבוֹת עִם בַּעֲלֵי תוֹרָה וְאַנְשֵׁי חַיִל הַמְּסוֹבְבִים מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ."],[11,"","וְנִרְפִּים הֵם בְּכֹבֶד הַמַּס. שֶׁאִם תֹּאמַר, כְּבֵדִים הֵם בְּכֹבֶד הַמַּס וְלֹא עוֹשִׂים טוֹבוֹת - בִּגְלַל זֶה (שם) תִּכְבַּד הָעֲבֹדָה עַל הָאֲנָשִׁים וְיַעֲשׂוּ בָהּ, שֶׁכֹּבֶד הַמַּס עֲלֵיהֶם, וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר, שֶׁהֵם מְשַׁקְּרִים וְאוֹמְרִים שֶׁכֹּבֶד הַמַּס עֲלֵיהֶם, וּמִשּׁוּם זֶה לֹא יַעֲשׂוּ טוֹבוֹת. הֵם מְשַׁקְּרִים בְּדִבְרֵיהֶם, וְאוֹמְרִים שֶׁמֵּהַכֹּבֶד שֶׁתִּכְבַּד עֲלֵיהֶם, תֶּבֶן אֵין נִתָּן, מָמוֹן הַשֶּׁקֶר שֶׁבּוֹ טוֹעִים (מדברים) לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וּמִשּׁוּם שֶׁלֹּא מְדַבְּרִים בּוֹ וְלֹא חָסוּ בְּשֵׁם ה', אֵין נִתָּן לַעֲבָדֶיךְ."],[12,"","וְאֵלֶּה שֶׁיֵּשׁ לָהֶם נִסְתָּר וְגָנוּז הַמָּמוֹן מִבִּפְנִים, שֶׁהוּא תֹּכֶן, כְּמוֹ תּוֹךְ הָאוֹצָר וְתֵבָה, מִתְקַיֵּם בָּהֶם וְתֹכֶן לְבֵנִים תִּתֵּנוּ. וְזֶה כְּסָפִים לְבָנִים שֶׁיִּהְיוּ בְּאוֹתוֹ דוֹר."],[13,"","בְּאוֹתוֹ זְמַן, (שמות טו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, וְהֵם בַּעֲלֵי מִשְׁנָה. גַּם כָּאן וַיָּבאוּ מָרָתָה, חוֹזֶרֶת לָהֶם תוֹרָה שֶׁבְּעַל פֶּה מָרָה בִּדְחָקִים רַבִּים, בַּעֲנִיּוּת, שֶׁיִּתְקַיֵּם בָּהֶם (שם א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבדָה קָשָׁה - זוֹ קֻשְׁיָא. בְּחֹמֶר - זֶה קַל וָחֹמֶר. וּבִלְבֵנִים - זֶה לִבּוּן הֲלָכָה. וּבְכָל עֲבֹדָה בַּשָּׂדֶה - זוֹ בָּרַיְתָא. אֵת כָּל עֲבֹדָתָם אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ - זֶה תֵּיק\"וּ."],[14,"","וְרוֹעָה הַנֶּאֱמָן, שָׁם הִתְקַיֵּם בְּךְ, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. וּבְעֵץ הַדַּעַת הַזֶּה טוֹב וָרָע, שֶׁהוּא אִסּוּר וְהֶתֵּר, וּבְאוֹתָם סוֹדוֹת שֶׁהִתְגַּלּוּ עַל יָדְךְ, וַיִּמְתְּקוּ הַמָּיִם. כְּמוֹ מֶלַח שֶׁמַּמְתִּיק אֶת הַבָּשָׂר, כָּךְ יִתְמַתְּקוּ בְסוֹדוֹת שֶׁמִּתְגַּלִּים עַל יָדְךְ כָּל אוֹתָן קֻשְׁיוֹת וּמַחֲלוֹקוֹת שֶׁל מַיִם מְרִירִים שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה, יַחְזְרוּ מְתוּקִים מֵי הַתּוֹרָה. וְיִסּוּרֶיךְ, בְּסוֹדוֹת אֵלּוּ שֶׁהִתְגַּלּוּ עַל יָדְךְ, יִהְיוּ לְךְ מְתוּקִים, וְיַחְזְרוּ לְךְ כָּל הַדְּחָקִים שֶׁלְּךְ כַּחֲלוֹמוֹת שֶׁעָבְרוּ. וַחֲלֹ\"ם בְּהִפּוּךְ אוֹתִיּוֹת - מֶלַ\"ח, שֶׁמַּמְתִּיק אֶת הַבָּשָׂר. גַּם יִסּוּרִים מְמַתְּקִים, כְּמוֹ שֶׁפֵּרְשׁוּהָ."],[15,"","וְלָרְשָׁעִים חוֹזְרִים הַיִּסּוּרִים מֶלַח סְדוֹמִית, שֶׁמְּעַוֵּר אֶת הָעֵינַיִם, לְקַיֵּם בָּהֶם (איוב יא) וְעֵינֵי רְשָׁעִים תִּכְלֶינָה. וְהֵם עֵרֶב רַב רְשָׁעִים, שֶׁיִּתְקַיֵּם בָּהֶם בְּאוֹתוֹ זְמַן, (דניאל יב) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים וְהִרְשִׁיעוּ רְשָׁעִים. יִתְלַבְּנוּ - אֵלֶּה בַּעֲלֵי מִשְׁנָה. וְיִצָּרְפוּ - הֵם זֶרַע קֹדֶשׁ שֶׁל שְׁאָר הָעָם. זֶהוּ שֶׁכָּתוּב (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף. וְהִרְשִׁיעוּ רְשָׁעִים - אֵלֶּה עֵרֶב רַב."]]],[["(דניאל י״ב:י׳) וְהַמַשְׂכִּילִים יָבִינוּ, אִינּוּן מָארֵי קַבָּלָה, דְּאִתְּמַר בְּהוֹן (דניאל י״ב:ג׳) וְהַמַשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ. אִלֵּין אִינּוּן דְּקָא מִשְׁתַּדְּלִין בְּזֹהַר דָּא, דְּאִקְרֵי סֵפֶר הַזֹּהַר, דְּאִיהוּ כְּתֵיבַת נֹחַ, דְּמִתְכַּנְּשִׁין בָּהּ שְׁנַיִם מֵעִיר, וְשֶׁבַע מִמַּלְכוּתָא. וּלְזִמְנִין אֶחָד מֵעִיר, וּשְׁנַיִם מִמִּשְׁפָּחָה. דִּבְהוֹן יִתְקָיֵּים (שמות א׳:כ״ב) כָּל הַבֵּן הַיִּלּוֹד הַיְּאוֹרָה תַּשְׁלִיכוּהוּ. וְדָא אוֹרָה דְּסִפְרָא דָּא, וְכֹלָּא עַל סִיבָּה דִּילָךְ.","וּמַאן גָּרִים דָּא. עוֹרֵב דְּאַנְתְּ תְּהֵא בְּהַהוּא זִמְנָא, כַּיּוֹנָה. דְּשָׁלִיחַ אַחֲרָא דְּאִקְרֵי בִּשְׁמָךְ, כָּעוֹרֵב דְּאִשְׁתְּלַח בְּקַדְמִיתָא, וְלָא אִתְהַדָר בִּשְׁלִיחוּתָא, דְּאִשְׁתְּדַּל בַּשְּׁקָצִּים, דְּאִתְּמַר בְּהוֹן, עַמֵּי הָאָרֶץ שֶׁקֶץ. בְּגִין מָמוֹנָא דִּלְהוֹן, וְלָא אִשְׁתָּדַּל בִּשְׁלִיחוּתֵיהּ לְאָהַדְרָא לְצַּדִיקַיָּיא בְּתִיוּבְתָא. כְּאִילּוּ לָא עָבִיד שְׁלִיחוּתָא דְּמָארֵיהּ.","וּבָךְ יִתְקַיֵּים רָזָא דְּיוֹנָה, דְּעָאל בְּעִמְקִין דִּתְהוֹמֵי יַמָּא, הָכִי תֵּיעוּל אַנְתְּ בַּעֲמִיקוּ דִּתְהוֹמֵי אוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב, (יונה ב׳:ד׳) וַתַּשְׁלִיכֵנִי מְצּוּלָה בִּלְבַב יַמִּים. וְיִהוֹן חָכְמָה חֶסֶד נֶצַּח לִיְמִין. דִּבְגִּינַיְיהוּ אָמַר דָּוִד, (תהילים קי״ח:ט״ו-ט״ז) יְמִין יְיָ עוֹשָׂה חָיִל יְמִין יְיָ רוֹמֵמָה יְמִין יְיָ עוֹשָׂה חָיִל. וּתְלַת מִשְּׂמָאלָא יִתְקַשְּׁרוּן כַּחֲדָא, דְּאִינּוּן בִּינָה גְּבוּרָה הוֹד. וְג' דַּרְגִּין דְּאֶמְצָּעִיתָא, כֶּתֶר תִּפְאֶרֶת יְסוֹד, דַּאֲחִידָן בִּימִינָא וּשְׂמָאלָא.","וּבְגִין דְּחָזָא לָךְ נָבִיא מִתְקַשָּׁר בִּתְלַת דַּרְגִּין דְּאֶמְצָּעִיתָא, פָּתַח עֲלָךְ הַאי קְרָא, (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. וּבְגִין דְּאַנְתְּ תְּהֵא אָחִיד בִּתְרֵין מְשִׁיחִין, אָמַר דָּוִד עַל ג' יְמִינִין דְּמָשִׁיחַ בֶּן דָּוִד, יְמִין יְיָ תְּלַת זִמְנִין. לָקֳבֵיל ג' שְׂמָאלִין, דְּאָחִיד בְּהֹן מָשִׁיחַ בֶּן אֶפְרַיִם, אָמַר מִסִּטְרָא דְּחַד שְׂמָאלָא, גְּבוּרָה, לֹא אָמוּת. כִּי אֶחְיְה, מִסִּטְרָא דִּשְׂמָאלָא דְּהוֹ\"ד דִּילָךְ, דְּאִתְּמַר בֵּיהּ וְנִתַן הַהוֹד לְמֹשֶׁה. אִתְיְיהִיב בָּךְ, מִסִּטְרָא דְּבִינָה.","בְּגִין דְּבֵיהּ הֲוִית אַנְתְּ חָרֶב וְיָבֵשׁ בְּכֹלָּא, בְּגִין מָשִׁיחַ בֶּן אֶפְרַיִם, בְּאוֹרַיְיתָךְ, בִּנְבִיאוּתָךְ עָלֵיהּ, בְּגוּפָךְ דִּסְבִילַת כַּמָה מִינֵי יִסּוּרִין, בְּגִין דְּלָא יְמוּת הוּא. וּבָעִית רַחֲמֵי עָלֵיהּ. אִתְּמַר בֵּיהּ כִּי אֶחְיֶה, מִסִּטְרָא דְּבִינָה. וּבְגִין דָּא לָא אָמוּת, מִסִּטְרָא דִּגְבוּרָה. כִּי אֶחְיֶה מִסִּטְרָא דְּבִינָה, אִילָנָא דְּחַיִּי, דְּאִתְגַבָּר עָלֵיהּ קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית, וְקָשִׁיר לֵיהּ בְּקִשּׁוּרָא דִּתְפִילִּין, בִּימִינָא דְּאַבְרָהָם, דְּאִיהוּ שַׁחֲרִית.","וַאֲסַפֵּר מַעֲשֵׂי יָהּ, מִסִּטְרָא דְּהוֹד. יַסּוֹר יִסְּרַנִּי יָהּ, חָכְמָה וּבִינָה, מִימִינָא וּמִשְּׂמָאלָא, בִּתְלַת יְמִינִין, וּתְלַת שְׂמָאלִין. וְלַמָּוְת לֹא נְתָנָנִי, עַמּוּדָא דְּאֶמְצָּעִיתָא, בְּג' דְּכָלִיל כֶּתֶר, וְצַּדִיק, וְאִיהוּ בֶּן יָ\"הּ. וּמִיַּד יָקוּם ו' לְה' בְּיָ\"הּ, בִּימִינָא וּשְׂמָאלָא, בְּרַחֲמֵי וְתַחֲנוּנֵי, בְּכַמָּה פִּיּוּסִים לָהּ וְלִבְנָהָא, הֲדָא הוּא דִכְתִיב, (עמוס ט׳:י״א) בַּיוֹם הַהוּא אָקִים אֶת סוּכַּת דָּוִד הַנּוֹפֶלֶת. וּבְגִין דָּא אָמַר נָבִיא, (ירמיהו ל״א:ט׳) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם.","קָם רַעְיָא מְהֵימְנָא, וְנָשִׁיק לֵיהּ, וּבָרִיךְ לֵיהּ, וְאָמַר וַדַּאי שְׁלִיחָא דְּמָארָךְ אַנְתְּ לְגַבָּן. פָּתְחוּ תָּנָאִין וַאֲמוֹרָאִין וְאָמְרוּ, רַעְיָא מְהֵימָנָא, אַנְתְּ הֲוִית יְדַע כָּל דָּא, וְעַל יְדָךְ הִיא אִתְגַּלְיָיא, אֲבָל בַּעֲנָוָה דִּילָךְ, דְּאִתְּמַר בָּךְ (במדבר י״ב:ג׳) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד, בְּאִלֵּין אַתְרִין דְּאַנְתְּ מִתְבַּיִּישׁ לְאַחְזְקָא טִיבוּ לְגַבָּךְ, מַנִּי קוּדְשָׁא בְּרִיךְ הוּא לָן, וּלְבוּצִּינָא קַדִּישָׁא, לְמֶהֱוִי בִּידָךְ וּבְפוּמָךְ בְּאִלֵּין אַתְרִין. (ע\"כ רעיא מהימנא) (ע\"ח ע\"א פקודא בתר דא וכו')","(במדבר ט׳:ט״ו) וּבְיוֹם הָקִים אֶת הַמִּשְׁכָּן. רִבִּי חִיָּיא פָּתַח, (תהילים קי״ב:ט׳) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עוֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְכָבוֹד. פִּזַּר לָאֶבְיוֹנִים, מַאי פִּזַּר. כְּמָה דְאַתְּ אָמֵר (משלי י״א:כ״ד) יֵשׁ מְפַזֵּר וְנוֹסָף עוֹד. יָכוֹל פִּזּוּר בְּעָלְמָא, קָא מַשְׁמַע לָן פִּזַּר נָתַן לָאֶבְיוֹנִים, כֵּיוָן דְּיָהִיב לְמִסְכְּנֵי, הַאי פִּזּוּרָא יָאוּת. מַאי וְנוֹסָף עוֹד. בְּכֹלָּא. וְנוֹסָף עוֹד בְּעוּתְרָא. וְנוֹסָף עוֹד בְּחַיֵּי.","הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, יֵשׁ מְפַזֵּר וְיוֹסֵף עוֹד, מַאי וְנוֹסַף. אֶלָּא הַהוּא אֲתָר דְּשָׁרֵי בֵּיהּ מִיתָה, הוּא גָּרִים לֵיהּ דְּיִתוֹסַף מֵחַיִים דִּלְעֵילָּא לְאוֹסְפָא לֵיהּ. אָמַר רִבִּי יְהוּדָה אָמַר רִבִּי חִיָּיא, קְרָא אַסְהִיד, דְּכָל מַאן דְּיָהִיב לְמִסְכְּנֵי, אִתְעַר אִילָנָא דְּחַיֵּי, לְאוֹסְפָא לְהַהִיא אִילָנָא דְּמוֹתָא, וּכְדֵין אִשְׁתְּכַח חַיִּים וְחֵדוּ לְעֵילָּא. וּבַר נָשׁ דְּגָרִים דָּא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ, הַהוּא אִילָנָא דְּחַיֵּי קָאִים עָלֵיהּ, וְהַהוּא אִילָנָא דְּמוֹתָא אַגִּין עֲלוֹי. וּבְגִין כַּךְ וְנוֹסַף עוֹד. (כמה דאת אמר)"],[[0,"והמשכילים יבינו:","אלו הם בעלי קבלה, ונאמר בהם, והמשכילים יזהירו כזהר הרקיע. אלו הם המשתדלים בזהר הזה הנקרא \u0003ספר הזהר.\u0004 שהוא כתיבת נח, שמתקבצים בה, שנים מעיר, ושבע ממלכות, ולפעמים אחד מעיר ושנים ממשפחה, שבהם מתקיים כל הבן הילוד היאורה תשליכוהו. שסוד התורה נקרא בן, \u0003הילוד\u0004 היינו המושג. \u0003היאורה\u0004 היינו אור התורה, \u0003תשליכוהו,\u0004 כמו תשכילוהו, שכל סוד וסוד הנולד לך תשכיל אותו לאור התורה ולנשמתה. וזה הוא האור של ספר הזהר הזה. והכל הוא בסבתך."],[1,"ומאן גרים דא","וכו': ומי גרם לזה עורב. כי אתה תהיה בזמן ההוא כיונה. שזה רומז לעורב והיונה ששלח נח מן התיבה, אחר שהמשיל את הזהר לתיבת נח. כי שליח אחר, שנקרא בשמך, כמו העורב שנשלח תחילה מן התיבה ולא חזר בשליחותו, שהשתדל בשקצים, שנאמר בהם, עמי הארץ שקץ (פסחים מט:) והשתדל בהם, משום הכסף שלהם, ולא השתדל בשליחותו להחזיר הצדיקים בתשובה. והוא כאלו לא עשה שליחות אדונו. הרמ\"ק ז\"ל כתב, שסובב על ירבעם בן נבט, שהיה ראוי לגאול את ישראל, ונכשל בעגלי זהב, וחטא והחטיא את הרבים. ונמשל לעורב שמעל בשליחותו. עי' באוה\"ח בהעלותך."],[2,"ובך יתקיים רזא","וכו': ובך יתקיים הסוד של היונה, שנכנסה בעמקי תהום הים, כך תכנס אתה בעמקי תהומות התורה. ז\"ש ביונה הנביא, ותשליכני מצולה בלבב ימים. דהיינו בים התורה. ואז, יהיה חכמה חסד נצח לימין, ובשבילם אמר דוד, ימין ה' עושה חיל ימין ה' רוממה ימין ה' עושה חיל. וג' מדרגות משמאל יתקשרו יחד, שהם, בינה גבורה הוד. וג' מדרגות שבאמצע, שהם כתר תפארת יסוד, הנאחזים בימין ושמאל. כי קו האמצעי נאחז בימין ושמאל. ויושלמו כן כל עשר ספירות, לרבות גם הג\"ר."],[3,"ובגין דחזא לך","וכו': ומשום שהנביא ראה אותך מתקשר בג' מדרגות כתר ת\"ת יסוד שבאמצע, פתח עליך מקרא הזה, הנה ישכיל עבדי ה\"ס יסוד, ירום ונשא ה\"ס ת\"ת, וגבה מאד, ה\"ס כתר. ומשום שאתה תהיה אחוז בב' משיחין, אמר דוד על ג' ימינים, חכמה חסד נצח, דמשיח בן דוד, ימין ה' ג' פעמים, כנ\"ל בדבור הסמוך. וכנגד ג' שמאלים, גבורה בינה הוד, שאחוז בהם משיח בן אפרים, אמר מצד שמאל אחד, שהוא \u0003גבורה,\u0004 לא אמות. ואמר כי אחיה, מצד שמאל הב', שהוא \u0003הוד\u0004 שלך, שנאמר בו, ונתן ההוד למשה. דהיינו כמ\"ש ונתת מהודך עליו, משמע שהקב\"ה נתן לו הוד שיהיה שלו. וניתן בך מצד \u0003הבינה.\u0004 כי הארת החכמה דשמאל דבינה, נגלית בהוד."],[4,"בגין דביה הוית","וכו': משום שבו בגבורה, היית חרב ויבש בכל, משום משיח בן אפרים, יבש בתורה שלך ובנבואה שלך, ובגופך, שסבלת כמה מיני יסורים כדי שלא ימות הוא, משיח בן אפרים, ובקשת רחמים עליו, ע\"כ נאמר בו, כי אחיה מצד הבינה. ומשום זה, לא אמות מצד הגבורה, שנמשכה ממנה דין קשה, כנ\"ל. כי אחיה מצד הבינה, דהיינו אחר שנגלה ממנה המוחין שה\"ס עץ החיים שהוא קו האמצעי, שנתגבר עליו, על קו השמאל, גבורה, ע\"י קריאת שמע של שחרית, שה\"ס חסד, וקשר אותו בקשר התפילין, בימין דאברהם, שהוא שחרית. דהיינו חסד."],[5,"ואספר מעשי יה:","הוא מצד ההוד. כי הארת חכמה הנגלית מבינה, אינה נגלה אלא מחזה ולמטה, שהוא בהוד. \u0003יסור יסרני יה,\u0004 היינו בחכמה ובינה, שהם מימין ומשמאל, שהחכמה כלולה ג' ימינים חכמה חסד נצח, והבינה כוללת ג' שמאלים בינה גבורה הוד, שמטרם ביאת קו האמצעי, הימין והשמאל הם במחלוקת זה עם זה, ונמשך מהם דינים, ע\"כ נאמר יסור יסרני יה. \u0003ולמות לא נתנני,\u0004 הוא קו האמצעי הכולל ג' אמצעים, כתר, וצדיק דהיינו יסוד, והוא עצמו דהיינו תפארת, שהוא בן י\"ה. ומיד יקום \u0003ו'\u0004 ל \u0003ה'\u0004 ב \u0003י\"ה\u0004 ויושלם שם הוי\"ה, בימין ובשמאל ברחמים ובתחנונים בכמה פיוסים לה, למלכות, ולבניה. ז\"ש ביום ההוא אקים סוכת דוד הנופלת, שהיא מלכות. ומשום זה אמר הנביא בבכי יבואו ובתחנונים אובילם."],[5,"","ביאור המאמר. כי ע\"י חטא דור המבול, נתפרק החבור של מלכות בבינה, ונגלה המלכות דמדת הדין, שממנה נמשך המבול. חוץ מתיבת נח שנשארה במתוק המלכות בבינה, שבה נקבצו כל החיים, אמנם בזמן המבול היו בקטנות בחסד ג\"ר. וז\"ש (באות פ\"ח) \u0003דאקרי ספר הזהר דאיהו כתיבת נח,\u0004 שספר הזהר, הוא סוד הביאור של המיתוק דמלכות בבינה, שהיתה בתיבת נח, שהוא יסוד כל נשמת חיים. אמנם או כבשעת המבול, \u0003דמתכנשין בה שנים מעיר ושבע ממלכותא,\u0004 שנים מעיר ה\"ס ז\"א בבחי' ו\"ק בלי ראש, והמלכות בבחינת נקודה. \u0003ושבע ממלכותא,\u0004 היינו ז\"ס תחתונות חסר ג\"ר. שזה רומז על דרושי הקטנות שבספר הזהר. \u0003ולזמנין א' מעיר וב' ממשפחה,\u0004 רומז על ג' קוין שקו אחד מיחד שנים. וזהו רומז על דרושי הגדלות שבזהר. \u0003דבהון יתקיים כל הבן הילוד היאורה תשליכוהו,\u0004 שה\"ס מיעוט הג\"ר דשמאל, ע\"י קו האמצעי שאין שם אור זכר, המאיר ממעלה למטה (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) שז\"ס היאורה תשליכוהו, כדי שיוכל להאיר, כי היאורה, פירושו כמו למאור, שע\"י מיעוט הזה מתיחד השמאל עם הימין ויוכל להאיר (כמ\"ש שם) \u0003וכל הבת תחיון,\u0004 היינו רק אור הנקבה, הנמשכת ממטה למעלה, שה\"ס המלכות הנקראת \u0003בת,\u0004 זהו בלבד שקו האמצעי מחיה, ולא יותר. וז\"ש \u0003ודא אורה דספרא דא,\u0004 שסדר הזה של כל הבן וגו' וכל הבת תחיון, שאור הזה מבואר בספר הזהר באר היטב, מכל הבחינות שבו. \u0003וכלא על סבה דילך,\u0004 היינו על סבת רעיא מהימנא, שהוא קו האמצעי, שהוא מסבב כל זה הנ\"ל."],[5,"","ונודע סדר יציאת המוחין שאחר המיעוט הנעשה ע\"י נקודת החולם, המכניס \u0003י'\u0004 באור וממעטו לאויר ו\"ק, יוצא תקון ראשון ע\"י נקודת השורק, שה\"ס קו השמאל, המוציא ה \u0003י'\u0004 מאויר ומחזירו לאור. אמנם נמשכו ממנו דינים ואינו יכול להאיר, (כנ\"ל ב\"א דף מ\"ז אות ל\"ד ד\"ה נפק. וב\"א דף ט\"ו ד\"ה ההיא) ונדמה שלא עשה שליחותו ולא תקן דבר. עד שבא קו האמצעי, בסוד נקודת החירק. שהוא ממעט הג\"ר דשמאל ומיחד אותו עם הימין ומשלים שלמות המוחין. ונמצא שכל השליחות והתקון נעשה ע\"י קו אמצעי, וקו השמאל לא עשה שליחותו. ולפיכך מיחס הזהר את ב' השליחים ששלח נח מן התיבה, שהם העורב והיונה, לב' קוין שמאל והאמצעי, שהעורב שלא קיים שליחותו היה נמשך מקו השמאל. והיונה שעשתה שליחותו נמשכה מקו האמצעי. וכן ביונה הנביא שבפעם הראשונה לא עשה שליחותו אלא ברח בספינה מפני ה'. ופעם ב' עשה שליחותו, שהיא ג\"כ מטעם הנ\"ל, שבפעם הראשונה היה דבוק בקו שמאל בבחינת עורב, וע\"כ לא עשה שליחותו. ובפעם ב' נתדבק בקו אמצעי, ועשה שליחותו."],[5,"","וז\"ש (באות פ\"ט) \u0003ומאן גרים דא עורב,\u0004 כלומר, אע\"פ שהעורב, שה\"ס קו שמאל, לא עשה שליחותו, אמנם הוא גרם לביאת קו האמצעי, שיוכל להשלים התקון, כי לולא העורב שהוא קו שמאל, לא היה לו לקו האמצעי מה לעשות. וז\"ש, \u0003דאנת תהא בההוא זמנא כיונה,\u0004 שרעיא מהימנא יהיה כיונה, שהוא קו האמצעי. \u0003דשליח אחרא דאקרי בשמך\u0004 שנקרא בשם יונה, דהיינו יונה הנביא בפעם הראשונה, שנקרא \u0003בשם יונה,\u0004 אבל היה, \u0003כעורב דאשתלח בקדמיתא, ולא אתהדר בשליחותא,\u0004 שהיה אז דומה כמו עורב ששלח נח מן התיבה ולא חזר אליו בשליחותו, כנ\"ל משום שהיה דבוק בקו השמאל. \u0003דאשתדל בשקצים, דאתמר בהון עמי הארץ שקץ, בגין ממונא דלהון,\u0004 כי ההארת חכמה שבשמאל נבחן לעשירות, כמ\"ש חז\"ל הרוצה להעשיר יצפין, אבל הדבוק בשמאל נסתם ממנו אור תורה והוא כעם הארץ. וז\"ש \u0003דאשתדל בשקצים,\u0004 שהם בחינת עמי הארץ. ועשה זה כדי לינק מן החכמה שבשמאל שנקרא עשירות, וז\"ש \u0003בגין ממונא דלהון. ולא אשתדל בשליחותיה לאהדרא צדיקייא בתיובתא,\u0004 דהיינו להחזיר בני ננוה בתשובה, מבחינת קו האמצעי, וע\"כ אע\"פ שקו השמאל הוא הגורם לקו האמצעי שיעשה ויגמר השליחות כנ\"ל, עכ\"ז נחשב, \u0003כאלו לא עביד שליחותא דמאריה,\u0004 משום שהוא לא נתכוון לזה."],[5,"","ונודע שאין קו שמאל נכנע להתחבר עם הימין, אלא ע\"י התעוררות המסך דחירק שבקו אמצעי, הממעטו מג\"ר, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר). וז\"ס שיונה שהיה דבוק בשמאל נשלך לעמקי תהומות הים, אשר תהומות הים ה\"ס שליטת המסך דחירק (כנ\"ל באדרא רבא אות רי\"ד) שעי\"ז נתמעטו ג\"ר דשמאל של יונה הנביא וחזר להתדבק בקו האמצעי. וז\"ש (באות צ'), \u0003ובך יתקיים רזא דיונה דעאל בעקמין דתהומי ימא,\u0004 שבא בתהומות הים כדי שיתמעטו הג\"ר דשמאל בסוד המסך דחירק, \u0003הכי תיעול אנת בעמיקו דתהומי אורייתא,\u0004 התורה ה\"ס ז\"א, קו האמצעי, ותהומי אורייתא, ה\"ס המסך דחירק שבקו האמצעי, ואמר לרעיא מהימנא, שגם הוא יתדבק בתהומי אורייתא שהוא מסך דחירק דז\"א, כדי ליחד קו ימין וקו שמאל זה בזה. וז\"ש, \u0003ויהון חכמה חסד ונצח לימין,\u0004 וכו' כי כשייחד ימין ושמאל זה בזה, יהיה כל קו כולל ג' ספירות, בסוד ראש תוך סוף, ויהיה קו ימין, חכמה בראש, חסד בתוך, נצח בסוף. ועד\"ז קו שמאל, יהיה בינה בראש, גבורה בתוך, הוד בסוף. ועד\"ז קו האמצעי המיחד אותם, יהיה כתר בראש או דעת, תפארת בתוך, יסוד בסוף. ולעתיד, בשעת הגאולה, כשיתגלה משה רבינו עם ב' משיחין, יהיה רעיא מהימנא בבחינת קו אמצעי, ומשיח בן דוד בבחינת קו ימין, ומשיח בן אפרים בבחינת קו שמאל."],[5,"","וז\"ש (באות צ\"א) \u0003ובגין דאנת תהא אחיד בתרין משיחין\u0004 וכו', דהיינו בשעת הגאולה, כנ\"ל, יהיו חח\"נ כלול במשיח בן דוד, ובג\"ה במשיח בן אפרים. ונודע שמטרם שהשמאל מתיחד עם הימין אע\"פ שיש לו אז ג\"ר, אינם אלא ג\"ר דו\"ק, ולא ג\"ר אמיתים, וע\"כ אין אז ספירת בינה בקו שמאל, אלא גבורה הוד בלבד שהם ו\"ק. וז\"ש, \u0003אמר, מסטרא דחד שמאלא גבורה, לא אמות,\u0004 שמטרם שהיה לו בינה, דהיינו מטרם שנתיחד עם קו הימין, שהתחיל בספירת הגבורה, היה נמשך ממנו דינים קשים, ואז אמר \u0003לא אמות,\u0004 דהיינו שהתפלל שלא ימות מחמת דינים הקשים, וז\"ש, \u0003בגין דביה הוית אנת חרב ויבש בכלא בגין משיח בן אפרים,\u0004 כלומר, משום שליטת משיח בן אפרים שהוא קו שמאל, בעת שלא היה לו בינה, דהיינו מטרם שנתיחד עם משיח בן דוד שהוא קו ימין, היה נמשך ממנו חורבן ויבשות בכל. \u0003דסבילת כמה מיני יסורין בגין דלא ימות,\u0004 שסבל כל אלו היסורין הנמשכים ממנו, כדי שלא ימות ויתבטל הארת השמאל, אלא ליחדו עם הימין בשעת הכושר, בעת שיתעורר המסך דחירק, ובינתים סבל ממנו כדי שלא יתבטל הארתו, ונמשך זה עד שנתעורר המסך דחירק ואז נכנע השמאל ויחד אותו עם הימין ואז יצאו הג\"ר המכונים ראש, ואז השיג קו השמאל שהוא משיח בן אפרים בחינת הראש שלו שהוא בינה. וז\"ש, (באות צ\"ב) \u0003לא אמות מסטרא דגבורה,\u0004 בעת שהיה חסר בינה והתחיל מגבורה, כי לא נתיחד עם הימין, ואז התפלל שלא ימות. \u0003כי אחיה מסטרא דבינה,\u0004 דהיינו בעת שיתיחד עם קו הימין ויצאו הג\"ר דראש, ויהיה בקו שמאל ספירת הבינה. ומ\"ש לעיל (באות צ\"א), \u0003כי אחיה מסטרא דשמאלא דהוד,\u0004 היינו משום שמדבר ממקום הארת החכמה, שאינה מאירה לא בראש ולא בתוך אלא בסוף דהיינו רק מטבור ולמטה. וכאן מדבר ממקום מוצאה דהארת החכמה, שהוא בראש, ע\"כ אומר, \u0003כי אחיה מסטרא דבינה.\u0004"],[6,"קם רעיא מהימנא","וכו': קם רעיא מהימנא ונשק אותו וברך אותו, ואמר ודאי שליח של אדונך אתה לנו. פתחו תנאים ואמוראים ואמרו, רעיא מהימנא, אתה היית יודע כל זה, ועל ידך נתגלה, אבל בענוה שלך, שנאמד בך, והאיש משה ענו מאד, באלו המקומות שאתה מתבייש להחזיק לך טובה, הקב\"ה מינה אותנו ולמאור הקדוש, דהיינו רשב\"י, להיות בידך ובפיך באלו המקומות."],[7,"וביום הקים את המשכן","וכו': ר' חייא פתח, פזר נתן לאביונים צדקתו עומדת לעד קרנו תרום בכבוד. \u0003פזר נתן לאביונים,\u0004 שואל, מהו \u0003פזר.\u0004 ומשיב, הוא כמו שאתה אומר, יש מפזר ונוסף עוד. ואפשר לומר שלכל מפזר הוא כך. לכן משמיענו, פזר נתן לאביונים. כיון שנותן פיזור הזה לאביונים, ראוי הוא להתברך. מהו \u0003ונוסף עוד.\u0004 היינו בכל, ונוסף עוד בעושר, ונוסף עוד בחיים."],[8,"האי קרא הכי","וכו': שואל, מקרא זה, כך היה צריך לומר, יש מפזר ויוסיף עוד, מהו ונוסף. ומשיב, אלא מקום הזה ששורה בה מיתה, דהיינו המלכות, הוא גורם לו שיתוסף בחיים של מעלה, ולהמשיך משם, ולהוסיף לו חיים. אמר ר' יהודה אמר ר' חייא, המקרא מעיד, שכל מי שנותן צדקה לאביונים, מתעורר עץ החיים, שהוא ז\"א, להוסיף חיים לאילן המות, שהוא המלכות, ואז נמצא חיים ושמחה למעלה, במלכות, והאדם שגרם זה, ע\"י שנתן צדקה, הנה בשעה שצריך, אותו עץ החיים עומד עליו, ואותו אילן המות מגין עליו. ומשום זה, \u0003ונוסף עוד.\u0004"]],[[0,"","וְהַמַּשְׂכִּלִים יָבִינוּ (דניאל שם) - אֵלּוּ בַּעֲלֵי קַבָּלָה, שֶׁנֶּאֱמַר בָּהֶם (שם) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. אֵלּוּ אוֹתָם שֶׁמִּשְׁתַּדְּלִים בְּזֹהַר זֶה שֶׁנִּקְרָא סֵפֶר הַזֹּהַר, שֶׁהוּא כְּמוֹ תֵּבַת נֹחַ שֶׁמִּתְכַּנְּסִים בָּהּ שְׁנַיִם מֵעִיר וְשֶׁבַע מִמַּלְכוּת, וְלִפְעָמִים אֶחָד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה, שֶׁבָּהֶם יִתְקַיֵּם (שמות א) כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ. וְזֶה אוֹרָה שֶׁל סֵפֶר זֶה, וְהַכֹּל עַל הַסִּבָּה שֶׁלְּךְ."],[1,"","וּמִי גָרַם זֶה? עוֹרֵב, שֶׁאַתָּה תִהְיֶה בְּאוֹתוֹ זְמַן כְּיוֹנָה, שֶׁשָּׁלִיחַ אַחֵר שֶׁנִּקְרָא בְשִׁמְךְ, כָּעוֹרֵב שֶׁנִּשְׁלַח בַּתְּחִלָּה וְלֹא חָזַר בַּשְּׁלִיחוּת, שֶׁהִשְׁתַּדֵּל בַּשְּׁקָצִים, שֶׁנֶּאֱמַר בָּהֶם עַמֵּי הָאָרֶץ שֶׁקֶץ, בִּגְלַל מָמוֹנָם, וְלֹא הִשְׁתַּדֵּל בִּשְׁלִיחוּתוֹ לְהַחֲזִיר צַדִּיקִים בִּתְשׁוּבָה, כְּאִלּוּ לֹא עָשָׂה שְׁלִיחוּת רִבּוֹנוֹ."],[2,"","וּבְךָ יִתְקַיֵּם סוֹד הַיּוֹנָה שֶׁנִּכְנַס בְּעִמְקֵי תְהוֹם רַבָּה, כָּךְ תִּכָּנֵס אַתָּה בְּעָמְקֵי תְּהוֹמֵי הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (יונה ב) וַתַּשְׁלִיכֵנִי מְצוּלָה בִּלְבַב יַמִּים. וְיִהְיוּ חָכְמָה חֶסֶד נֵצַח לְיָמִין, שֶׁבִּגְלָלָם אָמַר דָּוִד (תהלים קיח) יְמִין ה' רוֹמֵמָה יְמִין ה' עֹשָׂה חָיִל. וְשָׁלֹשׁ מִשְּׂמֹאל יִתְקַשְּׁרוּ כְאֶחָד, שֶׁהֵם בִּינָה גְּבוּרָה הוֹד, וְשָׁלֹשׁ דְּרָגוֹת שֶׁבָּאֶמְצַע - כֶּתֶר תִּפְאֶרֶת יְסוֹד - שֶׁאֲחוּזוֹת בְּיָמִין וּשְׂמֹאל."],[3,"","וּמִשּׁוּם שֶׁרָאָה אוֹתְךְ נָבִיא מִתְקַשֵּׁר בִּשְׁלֹשׁ דַּרְגוֹת הָאֶמְצַע, פָּתַח עָלֶיךְ פָּסוּק זֶה, (ישעיהנב) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. וּמִשּׁוּם שֶׁאַתָּה תִהְיֶה אָחוּז בִּשְׁנֵי מְשִׁיחִים, אָמַר דָּוִד עַל שְׁלֹשָׁה יְמִינִים שֶׁל מָשִׁיחַ בֶּן דָּוִד, יְמִין ה' שָׁלֹשׁ פְּעָמִים. כְּנֶגֶד שְׁלֹשָׁה שְׂמָאלִים שֶׁאָחוּז בָּהֶם מָשִׁיחַ בֶּן אֶפְרַיִם, אָמַר מִצַּד אֶחָד שְׂמֹאל, גְּבוּרָה, לֹא אָמוּת. כִּי אֶחְיֶה - מִצַּד שְׂמֹאל שֶׁל הוֹ\"ד שֶׁלְּךְ, שֶׁנֶּאֱמַר בּוֹ וְנִתַּן הַהוֹד לְמֹשֶׁה, נִתַּן בְּךְ מִצַּד בִּינָה."],[4,"","מִשּׁוּם שֶׁבּוֹ הָיִיתָ חָרֵב וְיָבֵשׁ בַּכֹּל, בִּגְלַל מָשִׁיחַ בֶּן אֶפְרַיִם, בְּתוֹרָתְךְ, בִּנְבִיאוּתְךְ עָלָיו, בְּגוּפְךְ שֶׁסָּבַלְתָּ כַּמָּה מִינֵי יִסּוּרִים כְּדֵי שֶׁהוּא לֹא יָמוּת, וּבִקַּשְׁתָּ עָלָיו רַחֲמִים, נֶאֱמַר בּוֹ כִּי אֶחְיֶה, מִצַּד הַבִּינָה. וּמִשּׁוּם זֶה לֹא אָמוּת - מִצַּד הַגְּבוּרָה. כִּי אֶחְיֶה - מִצַּד הַבִּינָה, עֵץ הַחַיִּים, שֶׁהִתְגַּבְּרָה עָלָיו קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית, וְקוֹשֵׁר אוֹתוֹ בְּקֶשֶׁר שֶׁל תְּפִלִּין בִּימִין אַבְרָהָם, שֶׁהוּא שַׁחֲרִית."],[5,"","וַאֲסַפֵּר מַעֲשֵׂי יָהּ - מִצַּד הַהוֹד. יַסֹּר יִסְּרַנִּי יָּהּ - חָכְמָה וּבִינָה, מִיָּמִין וּמִשְּׂמֹאל, בִּשְׁלֹשָׁה יְמָנִים וּבִשְׁלֹשָׁה שְׂמָאלִים. וְלַמָּוֶת לֹא נְתָנָנִי - הָעַמּוּד הָאֶמְצָעִי בְּג' שֶׁכּוֹלֵל כֶּתֶר וְצַדִּיק, וְהוּא בֶּן יָ\"הּ. וּמִיָּד יָקוּם ו' לְה' בְּיָ\"הּ, בְּיָמִין וּשְׂמֹאל, בְּרַחֲמִים וְתַחֲנוּנִים, בְּכַמָּה פִיּוּסִים לָהּ וּלְבָנֶיהָ. זֶהוּ שֶׁכָּתוּב (עמוס ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. וּמִשּׁוּם זֶה אָמַר הַנָּבִיא (ירמיה לא) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם."],[6,"","קָם רוֹעֶה הַנֶּאֱמָן וְנָשַׁק לוֹ וּבֵרַךְ אוֹתוֹ, וְאָמַר, וַדַּאי שְׁלִיחַ רִבּוֹנְךְ אַתָּה אֵלֵינוּ. פָּתְחוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, אַתָּה הָיִיתָ יוֹדֵעַ כָּל זֶה, וְעַל יָדְךְ הִתְגַּלְּתָה, אֲבָל בָּעֲנָוָה שֶׁלְּךְ, שֶׁנֶּאֱמַר בְּךְ (במדבר יב) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד, בִּמְקוֹמוֹת אֵלּוּ שֶׁאַתָּה מִתְבַּיֵּשׁ לְהַחֲזִיק טוֹבָה אֵלֶיךְ, מִנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָנוּ וְלַמְּנוֹרָה הַקְּדוֹשָׁה לִהְיוֹת בְּיָדְךְ וּבְפִיךְ בִּמְקוֹמוֹת אֵלּוּ."],[7,"","וּבְיוֹם הָקִים אֶת הַמִּשְׁכָּן. רַבִּי חִיָּיא פָּתַח, (תהלים קיב) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. פִּזַּר לָאֶבְיוֹנִים, מַה זֶּה פִּזַּר? כְּמוֹ שֶׁנֶּאֱמַר (משלי יא) יֵשׁ מְפַזֵּר וְנוֹסָף עוֹד. יָכוֹל פִּזּוּר בְּעָלְמָא? בָּא לְהַשְׁמִיעֵנוּ פִּזַּר נָתַן לָאֶבְיוֹנִים. כֵּיוָן שֶׁנָּתַן לַעֲנִיִּים, פִּזּוּר זֶה נָאֶה. מַה זֶה וְנוֹסָף עוֹד? בַּכֹּל. וְנוֹסָף עוֹד - בְּעֹשֶׁר. וְנוֹסָף עוֹד - בְּחַיִּים."],[8,"","פָּסוּק זֶה כָּךְ צָרִיךְ לוֹ לִהְיוֹת: יֵשׁ מְפַזֵּר וְיוֹסֵף עוֹד. מַה זֶּה וְנוֹסָף? אֶלָּא אוֹתוֹ מָקוֹם שֶׁשּׁוֹרָה בּוֹ מִיתָה, הוּא גּוֹרֵם לוֹ שֶׁיִּתּוֹסֵף מֵחַיִּים שֶׁלְּמַעְלָה לְהוֹסִיף לוֹ. אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא, הַפָּסוּק מֵעִיד שֶׁכָּל מִי שֶׁנּוֹתֵן לַעֲנִיִּים, מְעוֹרֵר עֵץ הַחַיִּים לְהוֹסִיף לְאוֹתוֹ עֵץ הַמָּוֶת, וְאָז נִמְצָא חַיִּים וְשִׂמְחָה לְמַעְלָה. וְהָאָדָם שֶׁגּוֹרֵם אֶת זֶה, בְּשָׁעָה שֶׁצָּרִיךְ לוֹ, אוֹתוֹ עֵץ הַחַיִּים עוֹמֵד עָלָיו, וְאוֹתוֹ עֵץ הַמָּוֶת מֵגֵן עָלָיו, וּמִשּׁוּם כָּךְ וְנוֹסָף עוֹד (כמו שנאמר)."]]],[["(תהילים קי״ב:ט׳) צִדְקָתוֹ עוֹמֶדֶת לָעַד. מַאי עוֹמֶדֶת לָעַד. עוֹמֶדֶת עָלֵיהּ דְּבַר נָשׁ, לְזַמְּנָא לֵיהּ קִיוּמָא וְחַיִּים, כְּמָה דְּאִיהוּ יָהִיב לֵיהּ חַיִּים, וְאַתְעַר לְגַבֵּי חַיִּין, הָכִי נָמֵי יַהֲבִין לֵיהּ. וְאִינּוּן תְּרֵי אִילָנִין (יהבין ליה) קַיְימִין עָלֵיהּ לְשֵׁיזָבָא לֵיהּ, וּלְאוֹסְפָא לֵיהּ חַיִּין.","קַרְנוֹ תָּרוּם בְכָבוֹד, תָּא חֲזֵי עָלְמָא דְּאַמָרָן, הַהוּא (ק\"כ ע\"א) קֶרֶן תָּרוּם. וּבְמָה. בְכָבוֹד דִּלְעֵילָּא, דְּהַאי בַּר נָשׁ גָּרִים לְחַבְּרָא לוֹן כַּחֲדָא, וּלְאַרְקָא בִּרְכָאן לְעֵילָּא וְתַתָא.","רִבִּי אַבָּא אָמַר, בְּכָל זִמְנָא דְּמַשְׁכְּנָא אִתְּקַם בְּעוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, כְּדֵין הַהוּא יוֹמָא, יוֹמָא דְּחֶדְוָוה דְּכֹלָּא, וּמָשַׁח רְבוּת קַדִישָׁא אִתְרַק בְּהַנְהוּ בּוֹצִינִין, וְנַהֲרִין כֻּלְּהוּ. מַאן דְּגָרִים דָּא, גָּרִים לֵיהּ (בההוא עלמא דאתי) דְּיִשְׁתְּזִיב בְּהַאי עָלְמָא, וִיהֵא לֵיהּ חַיִּים בְּעָלְמָא דְּאָתֵי, הֲדָא הוּא דִכְתִיב, (משלי י״א:ד׳) וּצְדָקָה תַּצִּיל מִמָּוְת, וּכְתִיב (משלי ד׳:י״ח) וְאֹרַח צַדִיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.","(במדבר י׳:ב׳) עֲשֵׂה לְךָ שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף וְגוֹ'. רִבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א׳:י״ט) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים. וּבְלֶכֶת הַחַיּוֹת, בְּקוּזְפִירָא דִּלְעֵילָּא הֲווֹ אָזְלֵי. דְּאִי תֵּימָא דְּהַאי לְעֵילָּא לְעֵילָּא. לָאו, לְתַתָּא. אֶלָּא כְּגַוְונָא הַאי מִקַּמֵּי אַנְפִּין, וְהַאי לְבָתַר אַנְפִּין.","זִיקָא מֵאַרְבַּע זִיקִין, בְּד' מָדוֹרִין, וּבְד' סִטְרִין, בְּזִיוָון דְּאִתְבְּרוּן בְּקוֹלְמִיטִין דְּאַנְפִּין נְהִירִין. בְּגִין כַּךְ כְּעֵין (נאש\"ר) כְּמַרְאֵה הַחַיּוֹת, דְּאִינּוּן אַרְבַע זִוְיָין, דְּגָלִין פְּרִישָׂן, אַרְיֵ\"ה. נֶשֶׁ\"ר. שׁוֹ\"ר. אָדָ\"ם. דְּכָלִיל כֻּלְּהוּ ד' מַלְאֲכִין דְּשַׁלְטִין וּכְלִילָן כֹּלָּא.","דִּגְלָא קַדְמָאָה, מַשִׁרְיָא מִזַּיְינָא, אַרְיֵ\"ה. מִיכָאֵ\"ל, רָשִׁים בִּפְרִישׁוּ דִּגְלָא פְּרִישָׁא לִימִינָא. מִזְרָח שֵׁירוּתָא דְּשִׁמְשָׁא, אָזִיל בְּמַטְלָנוֹי, בִּנְהִירוּ. תְּרֵין מְמָנָן תְּחוֹת יְדֵיהּ, יוֹפִי\"אֵל, צַדְקִי\"אֵל. חַד לְאוּרְתָא (נ\"א לאורייתא). וְחַד, לְמֵיהַךְ בְּשׁוּקָא דְּאָזִיל","כַּד אִלֵּין נַטְלִין, נַטְלִין כַּמָה מַשִּׁרְיָין מְזַיְּינִין, מִסִּטְרָא דִּימִינָא, וְכֹלָּא חַד. לְסִטְרָא שְׂמָאלָא, שִׁמְשָׁא אָזִיל (ס\"א נטל כד חד לסטר שמשא, שמשא אזיל) וְנָהִיר, וּמְעַטֵּר לְהוּ. אֶלֶף וְרִבְוָון מְמָנָן תְּחוֹתוֹי. וְכֻלְּהוּ בִּדְחִילוּ בְּאֵימָתָא בְּזִיעַ בְּרֶתֶת.","אַרְיֵה אוֹשִׁיט יְדֵיהּ יְמִינָא, כָּנִישׁ לְכָל חֵילוֹי לְגַבֵּיהּ, תְּלַת מְאָה וְשִׁבְעִין אֶלֶף אַרְיְוָותָא, סוֹחֲרָנֵיהּ דְּהַהוּא אַרְיֵ\"ה, וְאִיהוּ בֵּינַיְיהוּ בְּאֶמְצָעִיתָא.","כַּד גָּעֵי הַאי אַרְיֵה, מִזְדַעְזְעָן רְקִיעִין, וְכָל חַיָּלִין וּמַשִׁרְיָין מִזְדַעְזְעִין, מִדְּחִילוּ דִּילֵיהּ. מֵהַהוּא קָלָא, נְהַר דִּי נוּר מִתְלַהֲטָא, וְנָחִית בְּאֶלֶף וַחֲמֵשׁ מְאָה דַּרְגִּין דְּגֵיהִנָּם לְתַתָּא, כְּדֵין כֻּלְּהוּ חַיָּיבִין דְּגֵיהִנָּם מִזְדַעְזְעָן, וּמְלַהֲטָן אֶשָּׁא, וְעַל דָּא כְּתִיב, (עמוס ג׳:ח׳) אַרְיֵה שָׁאָג מִי לֹא יִירָא.","גָּעֵי תִּנְיָינוּת, תְּלַת מְאָה וְשִׁבְעִין אֶלֶף אַרְיְוָותָא, כֻּלְּהוּ גָּעָאן. אוֹשִׁיט יְדֵיהּ שְׂמָאלָא, כָּל מָארֵיהוֹן דְּדִינָא לְתַתָּא דַּחֲלִין, וְאִתְכַּפְיָין תְּחוֹת הַהוּא יְדָא. וְהַהוּא יְדָא פָּשִׁיט עָלַיְיהוּ, וְכֻלְּהוּ תְּחוֹתֵיהּ. כְּמָה דְאַתְּ אָמֵר, (בראשית מ״ט:ח׳) יָדְךָ בְּעוֹרֶף אוֹיְבֶיךָ.","אַרְבַּע גַּדְפִּין לְכָל חַד וְחַד, מֵאֶשָּׁא חִוָּורָא. כֻּלְּהוּ מְלַהֲטִין. כָּל אַפִּין דְּחִזּוּר וְשׁוּשָן בְּחִוַורְתָּא דְּהַהוּא אֶשָּׁא שְּׁקִיעָן.","אַרְבַּע אַנְפִּין לְכָל חַד וְחַד לְאַרְבַּע סִטְרִין, כֻּלְּהוּ נְהִירִין בְּחִוָּורָא דְּשִׁמְשָׁא. חַד לִסְטַר מִזְרָח, נָהִיר בְּחֵדוּ. וְחַד לִסְטַר מַעֲרָב, (ס\"א דא כניש) דְּאִתְכְּנִישׁ נְהוֹרֵיהּ. וְחַד לִסְטַר צָפוֹן, חָשׁוּךְ בְּלָא נְהִירוּ, כְּצִלָא דְּשִׁמְשָׁא לְגַבֵּי שִׁמְשָׁא. צִלָּא חָשׁוּךְ, שִׁמְשָׁא נָהִיר. בְּגִין דְּשִׁמְשָׁא וְצִלָא, יְמִינָא וּשְׂמָאלָא, וְאַזְלָא כַּחֲדָא. חַשוֹכָן (ס\"א חושבן) דְּאַזְלִין עִמֵּיהּ, כָּל אִינּוּן דְּנַטְלִין זַיְינָא.","וְכֻלְּהוּ מִימִינָא וּמִשְּׂמָאלָא בִּתְלַת רֵישִׁין. רֵישָׁא חֲדָא דִּילֵיהּ, שִׁבְעִין וְאַרְבַּע אֶלֶף, וְשִׁית מְאָה. אִלֵּין אִינּוּן רֵישָׁא חַד. נָפְקֵי חֵילָא בִּימִינָא, דְּאִיהוּ אָרִים עָלַיְיהוּ. בַּר כָּל אִינּוּן מְמָנָן דִּלְתַּתָּא, תְּחוֹת אִלֵּין. שִׁלְטוֹנִין אִלֵּין עַל אִלֵּין, דַּרְגִּין תַּתָּאִין עִם עִלָּאִין, דְּלֵית לוֹן חוּשְׁבָּנָא.","רֵישָׁא תִּנְיָינָא, דְּאָזִיל בְּרֵישָׁא קַדְמָאָה, חוּשְׁבָּן דִּילֵיהּ חַמְשִׁין וְאַרְבַּע אֶלֶף, וְאַרְבַּע מְאָה. בַּר כָּל אִלֵּין מְמָנָן דִּתְחוֹת לְד' סִטְרִין, דְּלֵית לוֹן חוּשְׁבָּנָא. רֵישָׁא תְּלִיתָאָה, דְּאָזִיל בַּתְרַיְיהוּ, חַמְשִׁין וְשִׁבְעָה אֶלֶף, וְאַרְבַּע מְאָה. כְּגַוְונָא דְּנָטִיל יְמִינָא, הָכִי נָמֵי נָטִיל שְׂמָאלָא, הָכִי נָמֵי מִקַּמַּיְיהוּ, הָכִי נָמֵי מִבַּתְרַיְיהוּ."],[[0,"צדקתו עומדת לעד:","שואל, מהו עומדת לעד. ומשיב, שהצדקה עומדת על האדם לתת לו קיום וחיים, כמו שהוא נותן לו חיים אל העני, ומתעורר אצלו חיים העליונים, דהיינו בסבתו, כנ\"ל בדבור הסמוך, כך נותנים לו חיים, ואלו ב' אילנות, ז\"א ומלכות, עומדים עליו להצילו, ולהוסיף לו חיים."],[1,"קרנו תרום בכבוד:","בוא וראה, העולם שאמרנו, שהוא ז\"א, נאמר לו, ההוא קרן, שהוא המלכות, תרום. ובמה. בכבוד של מעלה, שהוא הבינה. שע\"י הארת הבינה מתרוממת המלכות. משום שאותו האדם, ע\"י הצדקה שנתן, גרם לחבר אותם דהיינו ז\"א ומלכות, יחד, ולהוריק ברכות למעלה ולמטה."],[2,"רבי אבא אמר","וכו': רא\"א, בכל זמן, שהמשכן הוקם, דהיינו שהמלכות מזדווגת עם ז\"א. במעשה בני אדם, אז יום ההוא יום שמחת כל, ושמן משחת קדש הורק בנרות האלו, בספירות המלכות, וכולם מאירים. מי שגרם זה, גרם לעצמו שינצל בעולם הזה, ויהיה לו חיים בעולם הבא. ז\"ש וצדקה תציל ממות. וכתוב ואור צדיקים כאור נגה הולך ואור עד נכון היום."],[3,"עשה לך שתי חצוצרות","וגו': ר' שמעון פתח, \u0003ובלכת החיות\u0004 ילכו האופנים אצלם ובהנשא החיות מעל הארץ ינשאו האופנים. ובלכת החיות, בהשפעה של מעלה היו הולכים. ואם תאמר שזה למעלה למעלה. ומשיב לא, למטה. אלא כעין זה הוא לפני ד' פנים, וזה לאחר ד' פנים."],[3,"","פירוש. חגת\"ם דז\"א נקראים ד' חיות בד' פנים אריה שור נשר אדם. והם מקבלים מישסו\"ת, בסוד תלת נפקי מחד חד בתלת קיימא (כמ\"ש לעיל ב\"א דף רפ\"ז ד\"ה תלת) וז\"ש, ובלכת החיות \u0003בקוזפירא דלעילא הוו אזלי,\u0004 דהיינו בהשפעת חו\"ב תו\"מ דישסו\"ת. \u0003דאי תימא האי לעילא לעילא,\u0004 דהיינו למעלה מישסו\"ת, אלא מחו\"ב תו\"מ דאו\"א עלאין \u0003לאו,\u0004 אינו כן, \u0003לתתא,\u0004 שמקבלים מלמטה מישסו\"ת, \u0003כגוונא האי\u0004 כי כעין זה דאו\"א, \u0003מקמי אנפין,\u0004 הם מטרם שנעשה בהם ד' פנים אריה שור נשר אדם, כי באו\"א אין שם אלא חסד, כי בהם ה \u0003י'\u0004 אינו יוצא מאויר. \u0003והאי,\u0004 וזה דישסו\"ת, \u0003לבתר אנפין,\u0004 שכבר נתחלקו בהם לד' פנים, שבהם כבר שורש לאריה שור נשר אדם. כי בהם מתגלה החכמה, ויהיה פני אריה חסדים ופני שור חכמה, ופני נשר כלול מחכמה וחסדים, ופני אדם כלול מכל הג'. וע\"כ הכרח הוא שהחיות דז\"א מקבלים מישסו\"ת, שהם למעלה ממנו. \u0003בקוזפירא,\u0004 פירושו בהשפעה לפי הענין."],[4,"זיקא מארבע זיקין","וכו': רוח מד' רוחות מתלבש בארבע מדורים ובד' צדדים, בזיוים שנבראו בסומכים של הפנים המאירים. ומשום זה הם כמראה החיות שהם ד' זוית שהרגלים פרושים בהם. הנקראים \u0003אריה נשר שור אדם,\u0004 שכולל כל ד' מלאכים השולטים שהם מיכאל גבריאל אוריאל רפאל. וכולל הכל, שד' מלאכים אלו כוללים כל צבאות השמים. \u0003קולמיטין\u0004 פירושו סומכים. מלשון שומט קלמנטרין שלה (ירושלמי מ\"ק ג')."],[4,"","פירוש. אחר שביאר שהחיות נמשכים מישסו\"ת, מבאר עתה איך נמשכו. ונודע שתחילה עלה ז\"א והכריע בין ב' קוין דישסו\"ת, והוציא שם ג' קוין ומלכות המקבלתם, ומתוך זה, שגרם יציאת ג' קוין ומלכות בישסו\"ת, זכה גם הוא באותם ג' קוין ומלכות. כי כל שיעור האור שהתחתון גרם לעליון, זוכה בו גם התחתון (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת) וז\"ש, \u0003זיקא מארבע זיקין,\u0004 רוח אחד מארבע רוחות שיצאו בישסו\"ת, דהיינו קו האמצעי, שהוא ז\"א, שהוציא ד' רוחות בישסו\"ת שהם ג' קוין ומלכות, רוח הזה התפשט \u0003בד' מדורין,\u0004 שהם ג\"כ ג' קוין ומלכות, כאותו השיעור שז\"א הוציא בישסו\"ת. ונקראים מדורין, משום שבכל אחד מד' אלו, שורים בו ג' קוין. שה\"ס י\"ב כנודע. \u0003בד' סטרין,\u0004 שכל מדור בג' קוין שבו, מאיר לצד אחד מד' צדדים דרום צפון מזרח מערב. ונודע שג' קוין אלו שבכל מדור ממשיכים הארת הג\"ר הנקראים פנים מאירים. שמקודם שבא קו אמצעי ויחד ימין ושמאל, היו הפנים דשמאל חשכים. ואחר שבא קו האמצעי והוציא ג' קוין והמלכות, אז הם סומכים את הפנים שיהיו פנים מאירים. וז\"ש \u0003בזיוון דאתברון בקולמיטין דאנפין נהירין,\u0004 שד' מדורין וד' הסטרין הם הזיוים הסומכים את הפנים המאירים, כי כל סטר יש לו תכונה מיוחדה, שבצירוף כל תכונות ההם יחד נמצאים הפנים מאירים. \u0003בגין כך כמראה החיות דאינון ד' זויין דגלין פרישן אריה נשר שור אדם,\u0004 שמשום זה, יש לכל חיה מראה מיוחדה לפי תכונתה, שה\"ס ד' הפאות שהרגלים פרושים, בסוד מראה החיות פני אריה פני שור וכו', שבהצטרפם יחד הם ממשיכים פנים המאירים. וד' חיות אלו, \u0003דכליל כלהו ד' מלאכין דשלטין,\u0004 שהם מיכאל גבריאל אוריאל רפאל. שהם שולטים על ד' מחנות שכינה. באפן, שבכל דגל, נבחנת החיה, שהיא המקור שבז\"א, ונבחן המלאך הנמשך ממנו, העומד בסוד המרכבה שבמלכות. וגם נבחן הצד המולך שם, אם ימין אם שמאל, וכן אם מזרח או מערב, כמו שיתבאר לפנינו. \u0003וכלילן כלא,\u0004 שאלו ד' המלאכים כוללים כל צבאות השמים. שהם תחת שליטתם."],[5,"דגלא קדמאה","וכו': דגל ראשון, מחנה מזוינת, שה\"ס יוצאי צבא מבן עשרים ומעלה, החיה שלה היא \u0003אריה.\u0004 המלאך, הוא \u0003מיכאל\u0004 רשום בפרישת הדגל הפרוש לצד \u0003ימין,\u0004 והרוח שלה הוא \u0003מזרח,\u0004 שהוא תחילת השמש ההולך בנסיעותיו בהארתו. שני ממונים תחת ידו, של מיכאל, \u0003יופיאל וצדקיאל.\u0004 אחד לתורה. ואחד ללכת בשוק."],[6,"כד אלין נטלין","וכו': כשאלו נוסעים, נוסעים כמה מחנות מזוינים מצד ימין, וכולם אחד, שהם תחת הנהגתם של ג' מלאכים הנ\"ל. לצד שמאל הולך השמש ומאיר ומעטר אותם, את המחנות. אלף ורבבות ממונים תחתיו, וכולם ביראה באימה בזיע וברתת."],[7,"אריה אושיט ידיה","וכו': האריה הושיט יד ימינו, מקבץ כל צבאיו אצלו, ש\"ע אריות מסביב אריה ההוא, והוא ביניהם באמצע."],[8,"כד געי האי","וכו': כשאריה ההוא שואג, מזדעזעים הרקיעים, וכל הצבאות והמחנות מזדעזעים מפחדו. מקול ההוא נהר דינור מתלהט ויורד באלף ות\"ק מדרגות הגיהנם למטה. אז כל הרשעים שבגיהנם מזדעזעים ולוהטים באש. ועל זה כתוב, אריה שאג מי לא יירא."],[9,"געי תנינות תלת","וכו': שואג פעם שנית, ש\"ע אלף אריות כולם שואגים. האריה מושיט יד שמאלו, כל בעלי הדין למטה יראים ונכנעים תחת יד ההוא, ופושט יד ההוא עליהם, וכולם תחתיו. כמש\"א, ידך בעורף אויביך."],[10,"ארבע גדפין לכל","וכו': ארבע כנפים לכל אחד ואחד, מאש לבנה, וכולם לוהטים. כל הפנים של כפתור ופרח שקועים בלבן של אש ההוא."],[11,"ארבע אנפין לכל","וכו': ארבעה פנים לכל אחד ואחד לד' צדדים, כולם מאירים בלבן של השמש. אחד לצד מזרח, מאיר בשמחה. ואחד לצד מערב זה מקבץ אורו. ואחד לצד צפון, שהוא חושך בלי אור, כצל השמש כלפי השמש. הצל חושך, השמש מאיר, משום שהשמש והצל הם ימין ושמאל, והולכים יחד. החשכים ההולכים עמו כל אלו נושאים כלי קרב."],[12,"וכלהו מימינא ומשמאלא","וכו': וכולם מימין ומשמאל הם בג' ראשים, ראש אחד שלו, ע\"ד אלף ושש מאות, אלו הם ראש אחד. יוצאים צבאות ביד ימין שהרים עליהם. חוץ מכל אלו הממונים שלמטה, שהם תחת אלו השליטים, אלו על אלו, מדרגות תחתונות עם עליונות שאין להם חשבון."],[13,"רישא תנינא","וכו': ראש הב' ההולך עם ראש הא' החשבון שלו נ\"ד אלף ות'. חוץ מכל אלו הממונים שלמטה, לד' צדדים שאין להם חשבון. ראש השלישי, ההולך אחריהם, נ\"ז אלף וארבע מאות. כעין שנוסע הימין כן נוסע השמאל וכן מלפנים, וכן מלאחור."]],[[0,"","צִדְקָתוֹ עֹמֶדֶת לָעַד (תהלים קיא). מַה זֶּה עֹמֶדֶת לָעַד? עוֹמֶדֶת עַל הָאָדָם לְזַמֵּן לוֹ קִיּוּם וְחַיִּים. כְּמוֹ שֶׁהוּא נָתַן לוֹ חַיִּים וְעוֹרֵר לְגַבֵּי הַחַיִּים, כָּךְ גַּם נוֹתְנִים לוֹ, וְאֵלּוּ שְׁנֵי אִילָנוֹת (נותנים לו) עוֹמְדִים עָלָיו לְהַצִּילוֹ וּלְהוֹסִיף לוֹ חַיִּים."],[1,"","קַרְנוֹ תָרוּם בְּכָבוֹד. בֹּא רְאֵה, הָעוֹלָם שֶׁאָמַרְנוּ, אוֹתָהּ קֶרֶן תָּרוּם, וּבַמֶּה? בַּכָּבוֹד שֶׁלְּמַעְלָה, שֶׁאִישׁ זֶה גָּרַם לְחַבְּרָם כְּאֶחָד, וּלְרוֹקֵן בְּרָכוֹת לְמַעְלָה וּמַטָּה."],[2,"","רַבִּי אַבָּא אָמַר, בְּכָל זְמַן שֶׁהַמִּשְׁכָּן מוּקָם בְּמַעֲשֵׂי בְּנֵי אָדָם, אָז אוֹתוֹ יוֹם, יוֹם שֶׁל שִׂמְחַת הַכֹּל, וְשֶׁמֶן מִשְׁחַת קֹדֶשׁ מִתְרוֹקֵן בְּאוֹתָם נֵרוֹת, וּמְאִירִים כֻּלָּם. מִי שֶׁגּוֹרֵם אֶת זֶה, גּוֹרֵם לוֹ (באותו עולם הבא) שֶׁיִּנָּצֵל בָּעוֹלָם הַזֶּה, וְיִהְיוּ לוֹ חַיִּים בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (משלי יא) וּצְדָקָה תַּצִּיל מִמָּוֶת, וְכָתוּב (שם ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם."],[3,"","עָשֵׂה לְךְ שְׁתֵּי חֲצוֹצְרֹת כֶּסֶף וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים. וּבְלֶכֶת הַחַיּוֹת, בָּרְשׁוּת שֶׁלְּמַעְלָה הָיוּ הוֹלְכִים. שֶׁאִם תֹּאמַר שֶׁזֶּה לְמַעְלָה לְמַעְלָה - לֹא. לְמַטָּה. אֶלָּא כְּמוֹ זֶה מִלִּפְנֵי הַפָּנִים, וְזֶה לְאַחַר הַפָּנִים."],[4,"","רוּחַ מֵאַרְבַּע רוּחוֹת בְּאַרְבָּעָה מָדוֹרִים וּבְאַרְבָּעָה צְדָדִים, בְּזִיוָם שֶׁנִּבְרְאוּ בְּהִדּוּר הַפָּנִים הַמְּאִירוֹת. בִּגְלַל זֶה כְּעֵין (נאש\"ר) כְּמַרְאֵה הַחַיּוֹת, שֶׁהֵם אַרְבַּע זָוִיּוֹת, דְּגָלִים פְּרוּשִׂים, אַרְיֵ\"ה נֶשֶׁ\"ר שׁוֹ\"ר אָדָ\"ם, שֶׁכּוֹלֵל כֻּלָּם אַרְבָּעָה מַלְאָכִים שֶׁשּׁוֹלְטִים וְכוֹלְלִים הַכֹּל."],[5,"","דֶּגֶל רִאשׁוֹן, מֶרְכָּבָה מְזֻיֶּנֶת, אַרְיֵ\"ה, מִיכָאֵ\"ל, רָשׁוּם בִּפְרִישַׂת הַדֶּגֶל הַפָּרוּשׂ לְיָמִין. מִזְרָח רֵאשִׁית הַשֶּׁמֶשׁ הוֹלֵךְ בְּמַשָּׂאוֹ בְּאוֹר. שְׁנֵי מְמֻנִּים תַּחַת יָדָיו, יוֹפִיאֵ\"ל צַדְקִיאֵ\"ל. אֶחָד לְלַמֵּד (לתורה), וְאֶחָד לָלֶכֶת בַּשּׁוּק שֶׁהוֹלֵךְ."],[6,"","כְּשֶׁאֵלֶּה לוֹקְחִים, לוֹקְחִים כַּמָּה מֶרְכָּבוֹת מְזֻיָּנוֹת מִצַּד יָמִין, וְהַכֹּל אֶחָד. לְצַד שְׂמֹאל הַשֶּׁמֶשׁ הוֹלֵךְ (לוקח כאחד לצד השמאל, השמש הולך) וּמֵאִיר וּמְעַטֵּר אוֹתָם. אֶלֶף וּרְבָבוֹת מְמֻנִּים תַּחְתָּיו, וְכֻלָּם בְּיִרְאָה וּבְאֵימָה, בְּזִיעַ וּבְרֶתֶת."],[7,"","אַרְיֵה מוֹשִׁיט יַד יְמִינוֹ, כּוֹנֵס לְכָל חֵילוֹתָיו אֵלָיו. שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אֶלֶף אֲרָיוֹת סְבִיב אוֹתוֹ אַרְיֵ\"ה, וְהוּא בֵינֵיהֶם בָּאֶמְצַע."],[8,"","כְּשֶׁגּוֹעָה הָאַרְיֵה הַזֶּה, הָרְקִיעִים מִזְדַּעְזְעִים, וְכָל הַחֲיָלוֹת וְהַמֶּרְכָּבוֹת מִזְדַּעְזְעִים מִיִּרְאָתוֹ. מֵאוֹתוֹ קוֹל מִתְלַהֵט נְהַר דִּי נוּר, וְיוֹרֵד בְּאֶלֶף וַחֲמֵשׁ מֵאוֹת דַּרְגוֹת הַגֵּיהִנֹּם שֶׁל מַטָּה. אָז מִזְדַּעְזְעִים כָּל רִשְׁעֵי הַגֵּיהִנֹּם, וְהָאֵשׁ לוֹהֶטֶת, וְעַל זֶה כָּתוּב (עמוס ג) אַרְיֵה שָׁאָג מִי לֹא יִירָא."],[9,"","גּוֹעָה פַּעַם שְׁנִיָּה - שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אֶלֶף אֲרָיוֹת, כֻּלָּם גּוֹעִים. מוֹשִׁיט יַד שְׂמֹאלוֹ - כָּל בַּעֲלֵי הַדִּין לְמַטָּה פּוֹחֲדִים וְנִכְפִּים תַּחַת אוֹתָהּ יָד, וְאוֹתָהּ יָד פּוֹשֶׁטֶת עֲלֵיהֶם, וְכֻלָּם תַּחְתֶּיהָ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) יָדְךְ בְּעֹרֶף אֹיְבֶיךְ."],[10,"","אַרְבַּע כְּנָפַיִם לְכָל אֶחָד וְאֶחָד מֵאֵשׁ לְבָנָה. כֻּלָּם לוֹהֲטִים. כָּל פָּנִים שֶׁל כַּפְתּוֹר וָפֶרַח בְּלֹבֶן שֶׁל אוֹתָהּ אֵשׁ שְׁקוּעִים."],[11,"","אַרְבַּע פָּנִים לְכָל אֶחָד וְאֶחָד לְאַרְבָּעָה צְדָדִים, כֻּלָּם מְאִירִים בְּלֹבֶן הַשֶּׁמֶשׁ. אֶחָד לְצַד מִזְרָח מֵאִיר בְּשִׂמְחָה, וְאֶחָד לְצַד מַעֲרָב, (זה כונס) שֶׁהִכְנִיס מְאוֹרוֹ. וְאֶחָד לְצַד צָפוֹן, חָשׁוּךְ בְּלִי אוֹר, כְּצֵל הַשֶּׁמֶשׁ לְגַבֵּי הַשֶּׁמֶשׁ. הַצֵּל חָשׁוּךְ, הַשֶּׁמֶשׁ מֵאִיר. מִשּׁוּם שֶׁהַשֶּׁמֶשׁ וְהַצֵּל - יָמִין וּשְׂמֹאל, וְהוֹלְכִים כְּאֶחָד. חֲשׁוּכִים (חשבון) שֶׁהוֹלְכִים עִמּוֹ, כָּל אֵלּוּ שֶׁלּוֹקְחִים כְּלֵי זַיִן."],[12,"","וְכֻלָּם מִיָּמִין וּמִשְּׂמֹאל בִּשְׁלֹשָׁה רָאשִׁים. רֹאשׁ אֶחָד שֶׁלּוֹ, שִׁבְעִים וְאַרְבָּעָה אֶלֶף וְשֵׁשׁ מֵאוֹת. אֵלֶּה אוֹתָם רֹאשׁ אֶחָד. יוֹצְאִים כֹּחַ בְּיָמִין שֶׁהוּא הֵרִים עֲלֵיהֶם, פְּרָט לְכָל אוֹתָם מְמֻנִּים שֶׁלְּמַטָּה, תַּחַת אֵלֶּה. שִׁלְטוֹנִים אֵלֶּה עַל אֵלֶּה, דְּרָגוֹת תַּחְתּוֹנוֹת עִם עֶלְיוֹנוֹת, שֶׁאֵין לָהֶם חֶשְׁבּוֹן."],[13,"","רֹאשׁ שֵׁנִי, שֶׁהוֹלֵךְ בָּרֹאשׁ הָרִאשׁוֹן, חֶשְׁבּוֹנוֹ חֲמִשִּׁים וְאַרְבָּעָה אֶלֶף וְאַרְבַּע מֵאוֹת, פְּרָט לְכָל הַמְמֻנִּים הַלָּלוּ שֶׁתַּחַת לְאַרְבָּעָה צְדָדִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן. רֹאשׁ שְׁלִישִׁי, שֶׁהוֹלֵךְ אַחֲרֵיהֶם, חֲמִשִּׁים וְשִׁבְעָה אֶלֶף וְאַרְבַּע מֵאוֹת. כְּמוֹ שֶׁנּוֹטֵל הַיָּמִין, כָּךְ גַּם נוֹטֵל הַשְּׂמֹאל. כָּךְ גַּם מִלִּפְנֵיהֶם, כָּךְ גַּם מֵאַחֲרֵיהֶם."]]],[["כֵּיוָן דְּנָטִיל הַאי קַדְמָאָה, וְהוּרַד הַמִּשְׁכָּן. וְכֻלְּהוּ לֵיוָואֵי אַמְרֵי שִׁירָתָא, מָארֵי דְּתוּשְׁבְּחָן כֻּלְּהוּ מִסִּטְרֵיהּ. כְּדֵין (יחזקאל א׳:כ״א) כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים כְּתִיב.","דִּגְלָא תִּנְיָינָא. מַשִׁרְיָיא מִזַּיְינָא, נֶשֶׁ\"ר, אוּרִיאֵ\"ל, דָּרוֹ\"ם. תְּרֵי מְמָנָן עִמֵּיהּ, שַׁמְשִׁיאֵ\"ל חַסְדִּיאֵ\"ל. הַאי נֶשֶׁר סָלִיק, וְכָל מָארֵיהוֹן דְּגַדְפִּין מִקַּמֵּיהּ. כַּמָה מַשִׁרְיָין סַלְּקִין בְּכָל סִטְרִין. כָּל חַד וְחַד בְּתּוּקְפָא דְּשִׁמְשָׁא.","רוּחָא דְּרוּחָא פְּנִימָאָה נָפִיק, וְהַהוּא רוּחָא מָטֵי לְהַאי נֶשֶׁר, וְסָלִיק אֶבְרוֹי וּמְכַסְּיָיא לְגוּפָא. כְּמָה דְאַתְּ אָמֵר, (איוב ל״ט:כ״ו) הֲמִבִּינָתְךָ יַאֲבֶר נֵץ יִפְרוֹשׂ כְּנָפָיו לְתֵימָן. כְּגַוְונָא כְּדוּגְמָא כְּעֵין כְּנֶשֶׁר יָעִיר קִנּוֹ הַאי נֶשֶׁר נֵץ בַּהֲדֵיהּ יוֹנָה, בַּהֲדֵיהּ נֵץ, וְכָל מָארֵי דְּגַדְפִּין כֻּלְּהוּ מְצַפְצְפָן וְחַדָּאן. חַד מִסִּטְרָא (ס\"א חד סמכא) קָמֵּיהּ, סָלִיק מִתַּתָּא לְעֵילָּא. כַּמָה צִיפָּרִין נַחְתִּין וְעָאלִין, מְצַפְצְפָן וְחַדָּאן, אַזְלִין וְשָׁאטִין.","כַּד נָטִיל, אוֹשִׁיט גַּדְפָּא יְמִינָא, כָּנִישׁ לְכָל חֵילוֹי, תְּלַת מְאָה וְחַמְשִׁין אֶלֶף מָארֵי דְּגַדְפִין, בִּתְרֵי גּוּפֵי, נֶשֶׁ\"ר וְאַרְיֵ\"ה כַּחֲדָא. אָרִים קָלָא, כֻּלְּהוּ אַחֲרָנִין סַלְּקִין וְנַחְתִּין, מְצַפְצְפָן מִסִּטְרַיְיהוּ, מִכַּמָּה דַּרְגִּין.","ג' רֵישִׁין אִינּוּן כַּחֲדָא, בְּמַשִּׁרְיָין אִלֵּין. וְכֻלְּהוּ בְּחַד חוּשְׁבָּן. וְחוּשְׁבָּן דְּאִלֵּין רֵישִׁין, רֵישָׁא חֲדָא, אַרְבְּעִין וְשִׁית אֶלֶף וַחֲמֵשׁ מְאָה. רֵישָׁא תִּנְיָנָא חַמְשִׁין וְתֵשַׁע אֶלֶף וּתְלַת מְאָה. רֵישָׁא תְּלִיתָאָה, אַרְבְּעִין וַחֲמֵשׁ אַלְפִין, וְשִׁית מְאָה וְחַמְשִׁין.","מֵאִלֵּין תְּרֵי סִטְרִין, נָפִיק תְּרֵין כָּרוֹזֵי, דְּאָזְלֵי מִקַּמֵּי כֻּלְּהוּ מַשִּׁרְיָין. כַּד אִלֵּין תְּרֵי מַכְרִיזֵי, כָּל חֵילִין, וְכָל מַשִׁרְיָין, חֵיוָון זְעִירִין עִם רַבְרְבָן, כֻּלְּהוּ מִתְכַּנְּשֵׁי. מַאן חָמֵי נְטִילָא דְּכֻלְּהוּ רְקִיעִין, כּוּלְּהוּ נַטְלִין בְּמַטוּלָא בְּמַשִׁרְיָין, לְקַמֵּיהּ דְּהַהוּא מַשְׁכְּנָא.","בְּשַׁעֲתָא דְּחַד מִנַּיְיהוּ, הַהוּא דְּאָתֵי מִסִּטְרָא דְּאַרְיֵה, פָּשִׁיט קָלָא, בְּגִין דְּלָא יִזְדַּעְזְעוּן כָּל אִינּוּן קַלִין. כְּדֵין מִתְכַּנְּשִׁין כָּל אִינּוּן מַשִׁרְיָין. בְּשַׁעֲתָא דְּאַחֲרָא קָרֵי, מַתְּבָּר קָלָא וְלָא פָּשִׁיט, כָּל אִינּוּן מַשִׁרְיָין דְהַאי נֶשֶׁר, כֻּלְּהוּ מִתְכַּנְּשׁוּ לְנַטְלָא בְּמָטַלְנַיְיהוּ. לָקֳבֵיל אִינּוּן, שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף, כְּגַוְונָא דָּא כֹּלָּא לְתַתָּא. תָּא חֲזֵי, כַּד אִלֵּין נַטְלִין מַה כְּתִיב, (יחזקאל א׳:י״ט) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם, אִינּוּן דְּמִתְכָּנְּשוּ לְגַבַּיְיהוּ, כְּגַוְונָא דְּרֵישָׁא אִסְתְּכַּל, הָכִי נָמֵי כֻּלְּהוּ.","דִּגְלָא תְּלִיתָאָה. שׁוֹר. גַּבְרִיאֵל. צָפוֹן. תְּרֵין מְמָנָן עִמֵּיהּ, קַפְצִיאֵ\"ל חִזְקִיאֵ\"ל. הַאי שׁוֹר מִסִּטְרָא דִּשְׂמָאלָא. קַרְנוֹי סַלְּקִין בֵּין תְּרֵין עֵינוֹי. רָגִיז בְּאִסְתַּכְּלוּתָא, עַיְינִין מְלַהֲטָן כְּאֶשָּׁא דְּנוּר דָּלִיק. נָגַח וְרַפְסָא בְּרַגְלוֹי וְלָא חָיִיס.","כַּד גָּעֵי הַאי שׁוֹר, נָפְקִין מִנוּקְבָּא דִּתְהוֹמָא רַבָּא, כַּמָה חֲבִילֵי שְׁרִיקִין (ס\"א טריקין), כֻּלְּהוּ גָּעָאן וְשָׁטָאן קָמֵיהּ, וְחֵימָתָא, וְאַחְמְתָא דְּכָל חוֹבִין תַּלְיָיא קָמֵיהּ, דְּהָא כָּל חוֹבֵי עָלְמָא, כֻּלְּהוּ בְּסִפְרָא סְלִיקִין וּכְתִיבִין.","שִׁבְעָה נַהֲרֵי דְּאֶשָּׁא נַגְדִּין קַמֵּיהּ, כַּד צָחֵי אָזִיל לְגַבֵּי הַהוּא נְהַר דִּינוּר, וְשָׁאִיב לֵיהּ בִּגְמִיעָא חֲדָא. וְהַהוּא נָהָר אִתְמְלֵי כִּדְבְּקַדְמֵיתָא, וְלָא כָּדִיב. כָּל אִינּוּן חַיָּילִין, שָׁאֲבִין אֶשָּׁא אַכְלָא אֶשָּׁא. וְאִלְמָלֵא דְּמִסִּטְרָא דְּאַרְיֵה, נָפִיק חַד נַהֲרָא דְּמַיָיא, דִּמְכַבִּין גַּחֲלָתַיְיהוּ, לָא יָכִיל עָלְמָא לְמִסְבַּל.","חֲשׁוֹכָא דְּשִׁמְשָׁא תַּמָּן אִשְׁתְּכַח, לָא אִשְׁתְּכַח נְהִירוּ. כַּמָה גַּרְדִּינֵי נִמוּסִין אָזְלִין וְשָׁטָאן בְּחָשׁוֹכָא וְהַהוּא נָהָר דְּדָלִיק בְּסִטְרָא דָּא, נוּרָא אוּכָמָא חֲשׁוּךְ. וְאִי תֵּימָא, דְּלָא אִית אֶשָּׁא חִוָּורָא, אֶשָּׁא אוּכָמָא, אֶשָּׁא סוּמָקָא, אֶשָּׁא דִּתְרֵי גְּוָונֵי. לָא תֵּימָא, דְּהָא וַדַּאי הָכִי הוּא, וְעִם כָּל דָּא לְעֵילָּא לְעֵילָּא הָכִי אִשְׁתְּכַח, וּמִתַּמָּן נָגִיד לְאִלֵּין תַּתָּאֵי.","תָּנֵינָן אוֹרַיְיתָא בְּמָה אִשְׁתְּכָחַת. אֶשָּׁא חִוָּורָא, וְאֶשָּׁא אוּכָמָא עַל גַּבֵּי אֶשָּׁא חִוָּורָא. בִּתְרֵי אִשֵּׁי אִשְׁתְּכָחַת אוֹרַיְיתָא. תָּא חֲזֵי, אֶשָּׁא חֲדָא הוּא, וְהַאי אִתְפְּלִג לְאַרְבָּעָה. מַיָּא חֲדָא אִיהוּ, וְהַאי אִתְפְּלִיג לְאַרְבַּע. רוּחָא חֲדָא אִיהוּ, וְהַאי אִתְפְּלִיג לְאַרְבַּע."],[[0,"כיון דנטיל האי","וכו': כיון שנוסע זה הראשון, והורד המשכן, וכל הלוים אומרים שירה, וכל בעלי התשבחות הם כולם מצדו. אז, כי רוח החיה באופנים, כתוב."],[0,"","ביאור \u0003דגלא קדמאה,\u0004 שהוא דגל מחנה יהודה. כבר ידעת סוד הנסיעות בכל מקום שהוא, הוא כדי לגלות הארת החכמה בסוד תלת דוכתי, שה\"ס ג' קוין. כי אין הארת החכמה מתגלה אלא בזמן הנסיעה (כנ\"ל בשלח דף ל\"ט ד\"ה וג') שז\"ס הורדת המשכן ע\"י שליטת קו ימין, והקמת המשכן ע\"י גילוי קו שמאל, והתלבשותו בחסדים. כי המשכן ה\"ס המלכות, שבנינה בסוד חכמה תתאה, וע\"כ בשליטת קו ימין בלבדו, והורד המשכן, כי אז בטלה הארת החכמה שבו, ואח\"כ בגילוי קו שמאל והתלבשותו בחסדים, שהוא ע\"י התכללות הקוין זב\"ז חוזר והוקם המשכן."],[0,"","וסוד י\"ב שבטים, ה\"ס חו\"ג תו\"מ שבמלכות שכל אחת כוללת ג' קוין, שה\"ס י\"ב בקר, שהים, שה\"ס המלכות, עומד עליהם. ויהודה שה\"ס המלך שבי\"ב שבטים הוא כולל אותם. ולכאורה היה צריך להיות סדר הנסיעה, שראובן יסע תחילה, שה\"ס קו ימין, ודרום. ואח\"כ יסע דגל מחנה דן, שה\"ס קו שמאל וצפון. ואח\"כ יהודה, שה\"ס קו אמצעי ומזרח. ולבסוף אפרים, שה\"ס מערב דהיינו המלכות המקבלת מג' קוין. אמנם נסיעה זו שבמדבר היתה על דרך המתוקן ביותר. ותחילה יצאו כל ג' הקוין וגם נכללו זה בזה בסוד י\"ב שבטים, כנ\"ל. וכיון שעיקר הפועל לתקון הקוין, הוא קו אמצעי, שבמזרח, ע\"כ הוא נסע ראשונה במזרח, אבל הוא נחשב לקו ימין. והטעם הוא, כי יש ב' הכרעות בקו האמצעי, א) נקרא \u0003שירותא דשמשא,\u0004 דהיינו הכרעה הראשונה של קו האמצעי הנקרא שמש. שאז הוא משליט הקו ימין, והשמאל נכלל ומתבטל בימין כאלו לא היה כלל. ב) נקרא \u0003תוקפא דשמשא,\u0004 שהוא מיחד ב' הקוין זב\"ז באפן שיהיה גילוי לשניהם הן לחסד והן לחכמה. וז\"ס ב' דגלים הראשונים, שתחילה נסע דגל מחנה יהודה במזרח, ואע\"פ שמזרח הוא קו האמצעי, אמנם הנסיעה היתה בבחינת \u0003שירותא דשמשא,\u0004 שאז שולט קו ימין ואין שם גילוי לקו שמאל, וע\"כ נחשב לקו ימין. ולא שמאל, וע\"כ הורד המשכן עם נסיעתו, מחמת שנתבטלה הארת השמאל, שה\"ס הארת החכמה שה\"ס המשכן."],[0,"","וזה אמרו (באות ק\"ב) \u0003דגלא קדמאה משרייא מזיינא אריה,\u0004 שדגל מחנה יהודה, שהוא הדגל הראשון ה\"ס אריה שהוא חסד וקו ימין, \u0003מיכאל,\u0004 וכן הוא בבחינת מיכאל, שהוא על מחנה שכינה של החסד. והוא \u0003רשים בפרישו דגלא פרישא לימינא\u0004 שהדגל שלו הוא לצד ימין, שהוא חסד. \u0003מזרח,\u0004 אמנם ה\"ס קו האמצעי שנקרא מזרח, וע\"כ נסיעתו לצד מזרח של המשכן. ומפרש הטעם, למה הוא נבחן לחסד שהוא קו ימין, ואומר, \u0003שירותא דשמשא אזיל במטלנוי בנהירו,\u0004 שהוא בחינת ההכרעה של תחילתו של השמש, שהוא קו האמצעי, אשר אז הוא משליט הימין על השמאל כנ\"ל וע\"כ נחשב לאריה, ולבחינת מלאך מיכאל, שהם סוד קו ימין. ואינו נחשב לקו אמצעי ממש, כי קו אמצעי ממש צריך לכלול ימין ושמאל יחדיו, שה\"ס הכרעה ב' שנקרא \u0003תוקפא דשמשא\u0004 כנ\"ל. ולפיכך, נסע יהודה בראשונה, שהוא כולל של המלכות, והוא כולל, בחינת \u0003שירותא דשמשא\u0004 ולא ראובן, כי ראובן אינו אלא פרט של המלכות. דהיינו קו ימין ממש שהוא חסד, שאין לו שלמות אלא ע\"י \u0003תוקפא דשמשא,\u0004 שאז נכלל בקו שמאל ומקבל ממנו ג\"ר. וע\"כ נסע אחר יהודה. באפן, שיהודה הוא קו אמצעי בעצם והארתו חסד לבד, ימין בלי שמאל, וע\"כ נקרא חסד, אע\"פ שהוא במזרח. וראובן הוא קו ימין בעצם, והארתו היא ימין בהתכללות השמאל, ויהודה ה\"ס שירותא דשמשא, וע\"כ נסע ראשונה. וראובן ה\"ס תוקפא דשמשא, וע\"כ נסע אחר יהודה. ונודע שכל דגל מד' דגלים כולל ג' קוין. שע\"כ יש ג' שבטים בכל דגל. וע\"כ כנגד יששכר וזבולן שבדגל יהודה, יש ב' ממונים תחת מיכאל, וז\"ש, \u0003תרין ממנן תחות ידיה, יופיאל, צדקיאל.\u0004 אחד כנגד יששכר ואחד כנגד זבולן. \u0003חד לאורייתא,\u0004 שהוא יופיאל, שהוא כנגד יששכר שעסק בתורה, \u0003וחד למיהך בשוקא,\u0004 שהוא צדקיאל, שכנגד זבולן שהולך בשוק לישא וליתן בסחורה ומפרנס ליששכר. (כנ\"ל אות כ\"ו)."],[0,"","ומה שאומר, שבשירותא דשמשא משליט הימין על השמאל ורק הימין בלבד מאיר, אין הפירוש שהימין אינו נכלל כלל בשמאל, כי אם לא היה נכלל בשמאל לא היה אלא ו\"ק בחסר ג\"ר כנודע. אלא הפירוש הוא, שגם השמאל אינו אלא משמש לבחינת ימין לעטר אותו בג\"ר, ומבטל בחינתו עצמו. וז\"ש, (באות ק\"ג) \u0003לסטרא שמאלא שמשא אזיל ונהיר ומעטר להו,\u0004 שהשמש שה\"ס קו האמצעי, אפילו בשירותא דשמשא, הוא הולך לקו שמאל, ומאיר משם לכל המחנות שמצד ימין את הארת השמאל כדי לעטר אותם בג\"ר, אבל אינו מגלה כלום הארת השמאל עצמו. \u0003אלף ורבוון ממנן תחותוי,\u0004 וע\"כ יש שם הארת אלף שהוא חכמה המכונה אלף, והארת רבוון, שה\"ס חסדים המכונים רבבות. כלומר שיש בהם ג\"ר, אבל, \u0003וכלהו בדחילו באימתא בזיע ברתת,\u0004 כלומר שפחד הדינים שבקו שמאל שורה עליהם, וע\"כ הם נזהרים שלא לקבל מהארתו כלום, אלא רק שיעור המספיק לג\"ר בלבד."],[0,"","וז\"ש (באות ק\"ד) \u0003אריה אושיט ידיה ימינא,\u0004 דהיינו שמשליט בחינת הימין על הכל, \u0003כניש לכל חילוי לגביה,\u0004 אז מאסף כל צבאיו אצלו, כלומר שאז הוא מגלה שלמות כל המוחין שלו. שהם \u0003תלת מאה ושבעין אלף אריוותא סוחרניה דההוא אריה.\u0004 דהיינו כללות כל המוחין, שהם ג' קוין חב\"ד ומלכות המקבלתם, שחב\"ד הם ג' מאות אלף, ומלכות רק שבעים אלף, להורות שהיא חסרה ג\"ר דחכמה. ואין בה אלא ז\"ת. ומאה אלף, ה\"ס חכמה וחסדים, אבל מלכות שה\"ס חכמה בלבד, נאמר בה ושבעים אלף. וכולם נקראים אריות. להורות שרק שליטת הימין בלבד שם בלי שמאל. וז\"ש \u0003ואיהו בינייהו באמצעיתא,\u0004 שבחינת האמצע שה\"ס שירותא דשמשא כנ\"ל, הוא האריה שבאמצעם של ש\"ע אלף אריות. וע\"כ כולם פונים לימין בלבד."],[0,"","אחר שביאר גדר הארתו של דגל מחנה יהודה בדרך הכלל והשלמות, הולך עתה ומפרט סדר הכרעה הנוהג במזרח, שהוא קו האמצעי. ונודע שאין קו האמצעי יכול להכריע את קו השמאל להכנע ולהכלל בימין זולת ע\"י ב' פעולות, בפעולה א' מעורר כח המסך מבחינת המנעולא, שאז מסתלקים כל אורותיו של קו שמאל, ואח\"כ בפעולה ב' גונז בחינת המנעולא ומעורר בחינת המפתחא שבמסך, שעי\"ז חוזר קו השמאל להאיר בו\"ק דג\"ר (כנ\"ל פרשת לך דף י\"ג ד\"ה ונתבאר ע\"ש) וז\"ש (באות ק\"ה) \u0003כד געי האי אריה מזדעזען רקיעין וכל חילין\u0004 וכו', ושאגה זו פירושה פעולה הא' של קו האמצעי, שהיא ההתעוררות של כח המנעולא, שהוא מלכות דמדת הדין הקשה, המסלק לכל האורות, ואז כל הצבאות מזדעזעים הן מימין, דהיינו \u0003הרקיעין וכל חילין ומשריין\u0004 וכו'. והן משמאל, אשר \u0003מההוא קלא נהר די נור מתלהטא,\u0004 שנהר דינור הנמשך מן קו השמאל, מתלהט מחמת הדינין דמנעולא, \u0003ונחית באלף וחמש מאה דרגין דגיהנם לתתא,\u0004 כי כח השמאל משמש בקו השמאל, דהיינו בינה שחזרה לחכמה, שה\"ס אלף, שחכמה נקראת אלף, וגם בחצי השמאלי של הדעת שהוא ת\"ק כלומר חצי אלף, חצי מדרגה. ועתה ירד כח השמאל מכל שליטתו דהיינו מאלף וחצי אלף. וז\"ש, \u0003ונחית באלף ות\"ק דרגין\u0004 וכו' שהוא ירד מכל מדרגותיו, ונפל בעמקות הגיהגם למטה. וז\"ש, \u0003כדין כלהו חייבין דגיהנם מזדעזען ומלהטן אשא,\u0004 כי נדונים בדינים הקשים של מנעולא. \u0003וע\"ד כתיב אריה שאג מי לא יירא.\u0004 כי שאגה ההיא מחרידה הכל ומפילם ממדרגותיהם."],[0,"","וז\"ש (באות ק\"ז) \u0003געי תניינות,\u0004 דהיינו שמעורר פעולה ב' הנ\"ל (בפ' לך דף י\"ג ד\"ה ונתבאר) שה\"ס התעוררות של המסך דמפתחא, הראוי להמשיך ו\"ק דג\"ר דשמאל, אז, \u0003תלת מאה ושבעין אלף אריוותא כלהו געאן,\u0004 דהיינו, שכולם קבלו ממנו כח המסך הזה דמפתחא, ואז \u0003אושיט ידיה שמאלא,\u0004 שחזר והמשיך האורות דו\"ק דג\"ר שביד שמאל, שחזרו ונגלו הו\"ק דחכמה, \u0003ואז כל מאריהון דדינא לתתא דחלין ואתכפיין תחות ההוא ידא,\u0004 כי הארת החכמה מכניע כל בעלי הדין, שזסו\"ה, \u0003ידך בעורף אויביך,\u0004 שהארת החכמה שביד שמאל מכניע כל האויבים של הקדושה."],[0,"","אמנם הג\"ר דג\"ר, נשארו נעלמים מכח התעוררות המסך דקו האמצעי, כי לא נגלו על ידו אלא ו\"ק דג\"ר (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת). וז\"ש (באות ק\"ז) \u0003ארבע גדפין לכל חד וחד מאשא חוורא,\u0004 שכנגד ד' מוחין יצאו ד' כנפים המכסים על ג\"ר דג\"ר של כל מוח שלא יאיר. ומשום שכח המסך הזה המכסה הג\"ר דג\"ר, ממשיך כל החסדים, לפיכך הוא נקרא \u0003אשא חוורא. כלהו מלהטין,\u0004 שלוהטים בדינים דמסך, כדי לכסות הג\"ר דג\"ר. וז\"ש, \u0003כל אפין דחיזור ושושן,\u0004 שהם הפנים השלמים דג\"ר דג\"ר שבשמאל, המכונים כפתור ופרח, \u0003בחוורתא דההיא אשא שקיען,\u0004 שהם נשקעו, ואינם מאירים, מחמת האשא חוורתא שבכח המסך, כנ\"ל."],[0,"","עתה מבאר ההפרש שיש בין אלו ד' סטרין, שהם ג' הקוין ומלכות המקבלתם. ואומר (באות ק\"ח) \u0003ד' אנפין לכל חד וחד לארבע סטרין,\u0004 שהם שיעור ו\"ק דג\"ר הנקראים פנים, שנשארו בכל ד' סטרין, שהם ג' קוין ומלכות, ואומר, \u0003כלהו נהירין בחוורא דשמשא,\u0004 ששיעור הארתם הוא כמו הלבן שבקו האמצעי הנקרא שמש, דהיינו שעיקר הארתם הוא חסדים בלבד שנקראים לבן. וההפרש שבהם הוא, \u0003חד לסטר מזרח נהיר בחידו\u0004 האחד המאיר במזרח, שהוא קו האמצעי, מאיר בכל השלמות בשמחה. \u0003וחד לסטר מערב, דא כניש נהוריה,\u0004 והאחד המאיר בצד מערב, שהוא מלכות, אין לו אור מעצמו אלא מקבץ האור מכל ג' קוין. \u0003וחד לסטר צפון חשוך בלא נהירו\u0004 והאחד המאיר בצד צפון, שהוא קו השמאל, הוא חושך בלי אור. אמנם אין חושך זה, פירושו העדר של האור, אלא שהיא מציאות הנברא מן האור, \u0003כצלא דשמשא לגבי שמשא,\u0004 כמו הצל של השמש הוא תולדה מאור השמש, ולולא אור השמש לא היה נמצא הצל. כך החושך דקו שמאל הוא תולדה מאור הג\"ר דג\"ר שהאיר בו, שהיה נמשך ממנו חושך, מחמת חסרון אור החסדים (כנ\"ל ב\"א דף מ\"ז אות ל\"ד ד\"ה נפק) ואחר כך אע\"פ שנסתלקו ממנו הג\"ר דג\"ר, אינו מאיר אלא בהתכללותו עם קו ימין שהוא חסדים. וז\"ש, \u0003צלא חשוך שמשא נהיר, בגין דשמשא וצלא ימינא ושמאלא\u0004 כי כל עוד שהשמאל אינו נכלל בימין, נמצא השמאל שהוא צל של האור, ובחינת שמאל של האור, כלומר תולדה שלו. \u0003ואזלא כחדא,\u0004 כי במקום שאין אור אין צל. ונודע שאין הארת חכמה שבשמאל מאירה אלא ביחד עם הדינים והעונשים על הרשעים הרוצים להמשיך הג\"ר דג\"ר (כנ\"ל באדרא רבא נשא אות רי\"ט) וז\"ש, \u0003חשוכן דאזלין עמיה,\u0004 אלו החשכים, דהיינו הדינים שאמרנו ההולכים עם קו השמאל, הם \u0003כל אינון דנטלין זיינא,\u0004 שהם הנושאים כלי הזיין להעניש הרשעים הרוצים לינק מג\"ר דג\"ר. ונתבאר ההפרש מב' הקוין, האמצעי והשמאל, והמלכות, וקו הימין לא נתבאר, כי הוא סוד החסדים שמדבר בו בלי הרף, ואינו צריך ביאור."],[0,"","אחר שביאר כל הבחינות שבקו האמצעי הכללים והפרטים מבאר עתה סוד ג' השבטים שבדגלא קדמאה, שהם יהודה ויששכר וזבולן. וקוראם ג' ראשים. וז\"ש (באות ק\"ט) \u0003רישא חדא דיליה ע\"ד אלף ושית מאה,\u0004 דהיינו המספר של שבט יהודה המובא בכתוב. \u0003נפקי חילא בימינא דאיהו ארים עלייהו,\u0004 שהצבאות אלו יוצאים בכח הימין שהשליט עליהם, כנ\"ל בסוד שירותא דשמשא, ע\"ש. \u0003בר כל אינון ממנן דלתתא\u0004 וכו' \u0003דלית לון חושבנא,\u0004 היינו בחינות הנשים והטף של שבט יהודה, שלא התפקדו עמהם. \u0003רישא תנינא וכו' נ\"ד אלף וארבע מאה,\u0004 היינו המספר של שבט יששכר המובא בכתוב. \u0003בר כל אלין\u0004 וכו' היינו הנשים והטף. \u0003רישא תליתאה נ\"ד אלף וד' מאה,\u0004 היינו המספר של שבט זבולן שבכתוב."],[0,"","וז\"ש (באות ק\"י) \u0003כגוונא דנטיל ימינא\u0004 וכו' כלומר שענין הנסיעה של כל ד' דגלים היתה בדרך אחד על דרך שנתבאר כאן. \u0003כיון דנטיל האי קדמאה, והורד המשכן.\u0004 כי כבר נתבאר לעיל, בתחילת הביאור, שכיון שנסיעת דגלא קדמאה שהוא דגל מחנה יהודה, היתה מבחינת \u0003שירותא דשמשא,\u0004 המשליט החסדים ואינו נותן מקום גילוי להארת החכמה שבשמאל, ע\"כ נתבטל הארת המשכן, שה\"ס חכמה תתאה, שז\"ס והורד המשכן תאמר עם נסיעת דגל הזה. אמנם אין זה מטעם פגם אלא מכח היחוד הגדול שבשירותא דשמשא, וז\"ש, \u0003וכלהו ליואי אמרי שירתא,\u0004 שהיה אומרים שירה בעת הורדה זו הבאה מכח היחוד דשירותא דשמשא. וכן, \u0003מארי דתושבחן כלהו, מסטריה,\u0004 היו אומרים שירה. \u0003כדין כי רוח החיה באופנים כתיב.\u0004 כי הארת החסדים השלמה נקראת רוח חיה, כלומר רוח חכמה, כי חכמה נקראת חיה. וכבר ידעת שסוד ד' החיות הם חגת\"ם דז\"א, וחגת\"ם שבנוקבא שד' מלאכים מיכאל גבריאל אוריאל רפאל כלולים בהם נקראים ג\"כ חיות, וכל המחנות שד' מלאכים שולטים עליהם נקראים אופנים."],[1,"דגלא תניינא","וכו': דגל השני, שהוא דגל מחנה ראובן, הוא מחנה מזוינת, כלומר בסוד יוצאי צבא מבן כ' ומעלה, בבחינת \u0003נשר,\u0004 ובשליטת המלאך אוריאל, השולט מבחינת קו אמצעי, ונסיעתו של הדגל הוא לצד דרום, שהוא קו ימין וחסד. ב' ממונים עמו עם אוריאל, שהם שמשיאל חסדיאל. נשר הזה עולה וכל בעלי כנפים לפניו. כמה מחנות עולים מכל הצדדים, כל אחד ואחד בתוקף השמש."],[1,"","כבר נתבאר, שהן יהודה והן ראובן כלולים מב' בחינות שהם קו אמצעי וקו ימין, אלא ההפרש הוא, שיהודה מעצם בחינתו הוא קו אמצעי, שהוא ת\"ת וע\"כ נסיעתו במזרח, אלא מבחינת הארתו הוא נבחן לקו ימין שהוא חסד, ובחינת מלאך מיכאל שהוא חסד. שהוא מטעם שיחודו הוא בסוד \u0003שירותא דשמשא\u0004 המשליט החסד על הכל. וראובן הוא מעצם בחינתו קו ימין, וע\"כ נסיעתו בדרום, שהוא ימין, וחסד, אלא מבחינת הארתו נבחן להארת קו האמצעי מבחינת \u0003תוקפא דשמשא,\u0004 הנותן גילוי גם לקו שמאל (כנ\"ל אות קי\"א ד\"ה וסוד ע\"ש)."],[1,"","וז\"ש \u0003דגלא תניינא משריא מזיינא נשר,\u0004 שפני נשר ה\"ס קו האמצעי, והיינו מבחינת הארתו, וכן המלאך הוא \u0003אוריאל,\u0004 שהוא בחינת קו אמצעי ות\"ת. אמנם עצם בחינת ראובן, הוא קו ימין, חסד, וע\"כ הוא ב \u0003דרום,\u0004 שנוסע בדרום שהוא חסד, וקו ימין. וכמו שיש עם ראובן ב' שבטים שמעון וגד, כן יש בדגל של מעלה עם אוריאל, ב' מלאכים, וז\"ש, \u0003תרין ממנן עמיה שמשיאל וחסדיאל.\u0004 והוא מטעם להיותם בסוד י\"ב שבטים, שכל אחד מד' דגלים כולל ג', שה\"ס י\"ב כנ\"ל. וכל הצבאות שמבחינת נשר, נקראים בעלי כנפים. וז\"ש, \u0003וכל מאריהון דגדפין מקמיה.\u0004 אמנם הם כלולים מכל ד' סטרין שה\"ס ג' קוין ומלכות המקבלתם, וז\"ש, \u0003כמה משריין סלקין בכל סטרין,\u0004 וכבר נתבאר שע\"כ נבחן הארת דגל הזה בבחינת קו אמצעי, משום שהיחוד דקו אמצעי הוא מבחינת \u0003תוקפא דשמשא,\u0004 וז\"ש, \u0003כל חד וחד בתוקפא דשמשא,\u0004 שכל אחד מד' סטרין, יצא בכח היחוד הב' של קו האמצעי, הנקרא תוקפא דשמשא, וע\"כ יש בו גילוי גם מהארת השמאל. כנ\"ל."],[2,"רוחא דרוחא פנימאה","וכו': רוח של רוח הפנימי יוצא, ורוח ההוא מגיע אל הנשר, והוא מעלה כנפיו ומכסה את הגוף. כש\"א, המבינתך יאבר נץ יפרוש כנפיו לתימן. נשר הזה, התקוטט עם היונה, ועם הנץ, וכל בעלי כנפים כולם מצפצפים ושמחים. אחד מצד הפנים עולה ממטה למעלה, כמה צפרים יורדות ונכנסות, מצפצפות ושמחות. הולכות ומשוטטות."],[2,"","פירוש. כבר ידעת שאין השמאל רוצה להתיחד עם הימין מטרם שקו האמצעי ממעט הג\"ר שלו ע\"י מסך דחירק, וכח הזה נקרא רוח. וז\"ש, \u0003רוחא, דרוחא פנימאה נפיק,\u0004 וממעט הג\"ר משמאל, ומתוך כך גם קו אמצעי עצמו מתמעט מג\"ר. וז\"ש, \u0003וההוא רוחא מטי להאי נשר וסליק אברוי ומכסייא לגופא,\u0004 שאותו הרוח הממעט את קו השמאל מגיע ג\"כ לנשר עצמו שהוא קו האמצעי וגם הוא מתמעט מג\"ר, שזה נבחן שמעלה כנפיו ומכסה אורות גופו. ומה שאומר, \u0003רוחא דרוחא פנימאה,\u0004 הוא משום שיש ב' כחות הממעטים את קו השמאל, הנקרא מנעולא ומפתחא, כנ\"ל בדבור הסמוך, ומדייק לומר שכונתו הוא על רוחא פנימאה, שהוא מפתחא. ולא על החיצון שהוא מנעולא, שאינו עוסק בו כאן. כד\"א, \u0003המבינתך יאבר נץ יפרוש כנפיו לתימן,\u0004 כי קו השמאל מכונה נץ, מלשון כי ינצו אנשים, על שם שהוא מתקוטט עם הימין ויש לו עמו מחלוקת. (כנ\"ל ב\"א דף נ\"ז ד\"ה וזה) וע\"י מיעוט המסך דחירק שבקו אמצעי הוא \u0003פורש כנפיו,\u0004 דהיינו שמכסה אורותיו, \u0003לתימן,\u0004 כדי להכלל בדרום שהוא קו ימין. (כגוונא כדוגמא כעין עד קנו ל\"ג, כי איזה גליון הוא שהכניסוהו המעתיקים בפנים)."],[2,"","וז\"ש, \u0003האי נשר נץ בהדיה יונה, בהדיה נץ,\u0004 כי נץ ה\"ס קו שמאל כנ\"ל. ויונה ה\"ס המלכות המקבלת משמאל, וע\"כ הנשר שהוא קו האמצעי נץ עמהם וממעט הג\"ר שלהם בכח המסך דחירק. ואז, \u0003וכל מארי דגדפין כלהו מצפצפין וחדאן,\u0004 כי אינם יכולים לסבול שליטת הנץ, שהוא קו שמאל, המקפיא כל האורות (כנ\"ל ב\"א דף רמ\"ז ד\"ה ימא דקאפו), וע\"כ הם שמחים לראות איך הנשר קם עליו וממעטו מג\"ר, ודוחה שליטתו. ומפרש ענין זה יותר, \u0003חד מסטרא קמיה,\u0004 שהוא קו האמצעי, שהוא בחינת פנים. כי קו ימין הוא בימין וקו שמאל בשמאל וקו אמצעי בפנים והמלכות באחור. \u0003סליק מתתא לעילא,\u0004 שהוא עולה ממטה, ומכריע בין ב' הקוין ימין ושמאל שלמעלה ממנו (כנ\"ל תרומה רע\"ג ד\"ה ונודע). ואז כל האורות שהיו נקפאים מחמת שליטת השמאל נתכו וקונים כה להאיר למעלה ולמטה וכו'. וז\"ש, \u0003כמה צפרין נחתין ועאלין מצפצפן וחדאן אזלין ושאטין,\u0004 כי הצפרים, שהם האורות, יצאו מבחינת הקפיאה ויכולים ללכת ולעוף ככל אשר יחפצו. וע\"כ הם מצפצפים ושמחים."],[3,"כד נטיל אושיט","וכו': כשנוסע, הנשר, הוא מושיט כנף הימין, מקבץ לכל צבאיו, שהם ש\"נ אלף בעלי כנפים, בב' גופים של נשר ושל אריה ביחד. מרים קול, כל האחרים עולים ויורדים מצפצפים מן הצד שלהם מכמה מדרגות."],[3,"","פירוש. כבר ידעת שדגל מחנה ראובן יש בו ב' בחינות, כי מעצם בחינתו הוא ימין, שה\"ס אריה, ודרום. ומבחינת הארתו, הוא קו האמצעי, שהוא נשר ומזרח. וז\"ש \u0003וכד נטיל,\u0004 כשדגל מחנה ראובן, שה\"ס נשר מבחינת הארתו, נוסע, \u0003אושיט גדפא ימינא,\u0004 דהיינו שמושיט בחינת הימין שבו, והוא נוסע בדרום בימין. מחמת שהימין הוא עצם בחינתו. ואז, \u0003כניש לכל חילוי ש\"נ אלף מארי דגדפין, בתרי גופי נשר ואריה כחדא\u0004 שכל צבאותיו הם בב' בחינות, שמעצם בחינתם הם אריה וימין, ומבחינת הארתם הם נשר וקו אמצעי, ונבחנים משום זה שמלובשים כב' גופים ביחד. וסוד המספר ש\"נ אלף. הוא, כי ג' קוין ה\"ס ש', ומלכות נחשבת רק לחצי פרצוף (כנ\"ל ב\"ב דף קנ\"ח ד\"ה בארבעין) וע\"כ היא חמשים, והארת החכמה שבהם מכונה אלף, וע\"כ הם ש\"נ אלף."],[3,"","ואע\"פ שמבחינת הנסיעה אין נוסעים עם הנשר, אלא ב' הבחינות אריה ונשר, עכ\"ז מבחינת ההכרעה שבו, הוא פועל בכל ד' הבחינות. וז\"ש, \u0003ארים קלא,\u0004 דהיינו בעת שמכריע בין הקוין, המכונה הרמת קול. כי קו אמצעי נקרא קול, ומה שעולה למעלה להכריע בין הקוין נבחן להרמה של הקול. ואז, \u0003כלהו אחרנין סלקין ונחתין מצפצפן מסטרייהו מכמה דרגין\u0004 שכל בחינות האחרות, דהיינו גם הנמשכים מן שור ומן אדם, כולם מתפעלים ומקבלים מהארת הנשר מכמה בחינות שבהם, וכל אחד לפי המדרגה שלו כך מקבל ממנו."],[4,"ג' רישין אינון כחדא","וכו': ג' ראשים הם יחד, באלו המחנות, כי ג' שבטים הם במחנה ראובן. וכולם בחשבון מיוחד, והחשבון של אלו ראשים הוא כך, ראש אחד, מ\"ו אלף וחמש מאה, שהוא מספר שבט ראובן. ראש השני, נ\"ט אלף וג' מאות. שהוא מספר שבט שמעון. ראש הג' מ\"ה אלף ושש מאות וחמשים. שהוא מספר שבט גד."],[5,"מאלין תרי סטרין","וכו': מאלו ב' הצדדים, שהם נשר ואריה הנ\"ל (באות קי\"ד) יוצאים ב' כרוזים ההולכים לפני כל המחנות, כשאלו השנים שה\"ס ב' חצוצרות, כמ\"ש לפנינו. מכריזים, כל הצבאות וכל המחנות, חיות קטנות עם גדולות כולם מתקבצים. מי ראה הנסיעה של כל הרקיעים, שכולם נוסעים במסע במחנות לפני משכן ההוא, שהוא המלכות."],[6,"בשעתא דחד מניייהו","וכו': בשעה שאחד מהם, דהיינו אותו הבא מצד האריה, פושט קול, דהיינו שתוקע בחצוצרות תקיעה שהוא קול פשוט, כדי שלא יזדעזעו כל אלו הקולות שתוקע, אלא קולות פשוטים בלי זעזוע, אז מתאספים כל אלו המחנות, דהיינו בסו\"ה, ותקעו בהן ונועדו אליך כל העדה. בשעה שהאחר קורא, דהיינו שתוקע בחצוצרות, בשליטת אותו הבא מצד הנשר, הקול שבור ואינו פשוט, דהיינו שהוא קול תרועה, ואז כל אלו המחנות של נשר הזה, כולם מתאספים לנסוע במסעיהם. דהיינו בסו\"ה ותקעתם תרועה ונסעו המחנות וגו'. כנגד אלו השנים, שהם אריה ונשר, הם שתי חצוצרות כסף. כי כעין זה שנוהג למעלה כן הוא הכל למטה. בוא וראה, כשאלו נוסעים מה כתוב, ובלכת החיות ילכו האופנים אצלם, היינו אלו הצבאות המתאספים אל הממונים הם נקראים אופנים. וכמו שהראש מסתכל, דהיינו הממונה, כן מסתכלים כולם. דהיינו הצבאות שמתחתיהם."],[7,"דגלא תליתאה","וכו': דגל השלישי שהוא דגל מחנה דן, הוא פני שור מן החיות, שהוא שמאל, ומד' מלאכים הוא גבריאל, דהיינו מקו שמאל, ונוסע בצד צפון של המשכן, שהוא שמאל. ועם גבריאל יש ב' ממונים, קפציאל חזקיאל. כי גבריאל הוא כנגד דן, וב' הממונים הם כנגד אשר ונפתלי המחוברים לדגל מחנה דן. שור הזה הוא מצד שמאל. קרניו עולים מבין שתי עיניו. כועס בהסתכלות, העינים לוהטים כאש של אש דולק. נוגח ורומס ברגליו ואינו מרחם."],[7,"","פירוש. אחר שביאר ב' דגלים הראשונים שהם קו אמצעי וקו ימין. מבאר עתה דגל השלישי שהוא קו השמאל שבחיות נקרא פני שור, ובד' מלאכים נקרא גבריאל. ונודע שאחר שקו האמצעי הכריע ויחד קו ימין וקו שמאל זב\"ז, לא נשאר בקו שמאל, כי אם אור המלכות, דהיינו הארת החכמה שממטה למעלה, שהוא בחינת ו\"ק, (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) והג\"ר נעלמו ממנו. וז\"ש, \u0003קרנוי סלקין בין תרין עינוי,\u0004 המלכות נקראת קרן, והחכמה נקראת עינים, ואומר, שמב' עיניו שה\"ס החכמה לא עלו יותר מבחינת קרנים שהוא אור המלכות שממטה למעלה, והג\"ר שבאור עינים שלו נסתלקו. גם ידעת שאין הארת החכמה שבשמאל מאירה רק עם דינים קשים על ראש הרשעים (כנ\"ל באדרא רבה אות רי\"ט) וז\"ש \u0003רגיז באסתכלותא, עיינין מלהטן\u0004 וכו' דהיינו דינים הקשים המופיעים עם הסתכלות שלו, שה\"ס הארת החכמה שבשמאל."],[8,"כד געי האי","וכו': כששור הזה גועה, יוצאים מנקב של תהום הגדול, כמה גדודים מחבלים, וכולם גועים ומשוטטים לפניו, וחימה, והתיק שבו כל העונות, תלוים לפניו, כי כל עונות העולם, כולם באים בספר ונכתבים."],[8,"","פירוש. כמ\"ש לעיל בגעית האריה (באות ק\"ה) שגועה מחמת כח המסך דחירק המגיע אליו וממעטו מג\"ר כן געיית השור, שהוא קו שמאל שבהגיע אליו כח התמעטות ממסך דחירק שבקו האמצעי היא גועה. גם נודע שסוד התהום הוא עלית המלכות והתכללותה בבינה שממעטה מג\"ר, שהוא דומה לכח המסך דחירק, (כנ\"ל באדרא רבא נשא אות רי\"ד) וז\"ש, \u0003כד געי האי שור,\u0004 כשמגיע אליו כח המיעוט שבמסך דחירק, \u0003נפקין מנוקבא דתהומא רבא כמה חבילי שריקין,\u0004 שאז יוצאים גדודי הקליפות והמחבלים האחוזים במקום החסרון של מיעוט הזה הנקרא תהומא רבא, \u0003געאן ושטאן קמיה,\u0004 שהמה מתחברים עם הגעיה של השור ומשוטטים לפניו, ואז נמצאים נפתחים בהשור, ב' מיני דינים, א' דינים דשמאל, וב', דינים דמסך דחירק שנתדבקו בו, שב' דינים אלו כוללים כל מיני העונות והקלקולים שבעולם. וז\"ש \u0003וחימתא ואחמתא\u0004 וכו' \u0003דכל חובי דעלמא, כלהו בספרא סליקין וכתיבין\u0004 שאז נדונים על העונות של כל העולם, שגרמו ליציאת ב' דינים אלו בקו השמאל, ובחינת הפגמים והקלקולים שנעשו בהארת קו השמאל, ה\"ס הכתיבה של העונות בספר, כי המה מחכים על תשובת התחתונים, שע\"י תשובתם יתוקנו דינים הללו. וז\"ש \u0003בספרא סליקין וכתיבין.\u0004"],[9,"שבעה נהרי דאשא","וכו': שבעה נהרות אש נמשכים לפניו. כשצמא, הולך אל נהר דינור, ושואב אותו בגמיאה אחת, והנהר חוזר ומתמלא כבתחילה, ואינו מכזב. כלומר שאינו כנחל כוזב, שנפסקים מימיו. כל אלו הצבאות של השור הזה, שה\"ס גבריאל, שואבים אש אכלה אש. ולולא שמצד האריה יוצא נהר אחד של מים, שה\"ס אור החסדים, המכבים גחלתם, לא היה יכול העולם לסבול, הדינים שלהם."],[9,"","פירוש. כי נתבאר בדבור הסמוך שמסוד כח המסך דחירק נתמעטו הג\"ר דקו שמאל, ולא נשארו בו אלא ז\"ס תחתונות חג\"ת נהי\"מ חסר ג\"ר. וז\"ש, \u0003שבעה נהרי דאשא נגדין קמיה,\u0004 דהיינו ז\"ס תחתונות, ונקראים נהרי אש, על שם הדינים שבהם כנ\"ל. ונודע שבסוד נסיעת הקוין יוצא הארת החכמה בקו שמאל, ואח\"כ מתמעטת, (כנ\"ל בשלח ל\"ט ד\"ה וג') וז\"ש, \u0003כד צחי,\u0004 דהיינו בעת שהדינים בוערים בו, אז, בסוד נסיעת הקוים הוא \u0003אזיל לגבי ההוא נהר דינור,\u0004 שהוא כולו אש דהיינו דינים, \u0003ושאיב ליה בגמיעה חדא,\u0004 דהיינו ע\"י הופעת הארת החכמה שבו, הוא מבטל כל הדינים שבנהר דינור בבת אחת. אמנם תיכף אחר נסיעת הקוים, החכמה חוזרת ונעלמת (כמ\"ש שם) וע\"כ, \u0003וההוא נהר אתמלי כדבקדמיתא,\u0004 שאחר נסיעת הקוין מתחדשים בו הדינים כבתחילה. ונודע שכל התקון של קו שמאל הוא להתיחד עם קו הימין שהוא חסדים. וז\"ש \u0003כל אינון חיילין שאבין אשא אכלא אשא,\u0004 שכל הצבאות שלו מלאים דינים קשים, \u0003ואלמלא דמסטרא דאריה נפיק חד נהרא דמיא דמכבין גחלתייהו,\u0004 דהיינו לולא התחברותו עם הימין שהוא חסדים, \u0003לא יכיל עלמא למסבל,\u0004 לא היה העולם יכול לסבול הדינים שלו, והיה נחרב."],[10,"חשוכא דשמשא תמן","וכו': החשך של השמש, דהיינו הצל, (כנ\"ל באות ק\"ח, ובסולם באות קי\"א) נמצא שם, בקו שמאל, האור נמצא ואינו נמצא. כמה נעלי דין הולכים ומשוטטים בחושך. ונהר ההוא הדולק בצד שמאל, הוא אש שחורה חשכה. ואם תאמר, שאין כאן אש לבנה אש שחורה אש אדומה אש הכלול מב' צבעים, דהיינו ירוקה. אל תאמר כן, כי ודאי שכך הוא, שנהר הדולק שחור הוא, ועכ\"ז למעלה למעלה, בבינה, נמצא כן, שהאש כלולה מד' אשים, ומשם נמשך לאלו התחתונים, לפני שור שבז\"א, ולמלאך גבריאל שבמלכות, שגם בהם האש של הגבורה כלולה מד' אשים."],[10,"","פירוש. החשך של השמש שיש בשמאל, כבר נתבאר (באות קי\"א בהסולם) ע\"ש. ומ\"ש, \u0003אשתכח לא אשתכח נהירו,\u0004 היינו כשקו השמאל מתיחד עם הימין, נמצא בו אור החכמה, וכשאינו מתיחד עם הימין לא נמצא בו אור, אלא חושך. ונתבאר לעיל ששיעור האור המאיר בקו שמאל הוא כשיעורה של המלכות (כנ\"ל אות קי\"ח). שקרנוי סלקין בין תרין עינוי, ע\"ש. וז\"ש, \u0003וההוא נהר דדליק בסטרא דא נורא אוכמא חשוך,\u0004 דהיינו כשיעור המלכות שהיא אש שחורה וחשכה. אמנם ודאי שקו שמאל כלול מכל ג' קוין והמלכות המקבלתם, וע\"כ יש בו ד' אשים, וז\"ש \u0003ואי תימא\u0004 וכו', שכמו שקו שמאל שבבינה כלול מכל ד' סטרין כך קו השמאל שבחיות ושבד' מלאכים כלול מכל ד' סטרין, שהם לבנה ושחורה ואדומה וירוקה."],[11,"תנינן אורייתא במה","וכו': למדנו התורה העליונה במה היא נמצאת. היא אש לבנה, וכתובה באש שחורה על אש לבנה. ובשתי אשים נמצאת התורה. בוא וראה, אש אחת הוא, דהיינו קו שמאל שנקרא אש, וזו מתחלקת לארבע אשים, להיותו כלול מד' סטרין כנ\"ל. וכן מים אחד הוא שהוא קו ימין הנקרא מים. והוא מתחלק לארבעת שכלול בו ד' סטרין. וכן הרוח, אחד הוא, שהוא קו אמצעי, ומתחלק לארבעה, דהיינו שכלול מכל ד' סטרין. שהם ג' קוין ומלכות המקבלתם."]],[[0,"","כֵּיוָן שֶׁנּוֹסֵעַ רִאשׁוֹן - וְהוּרַד הַמִּשְׁכָּן. וְכָל הַלְוִיִּם אוֹמְרִים שִׁירָה. בַּעֲלֵי הַתִּשְׁבָּחוֹת כֻּלָּם מִצִּדּוֹ. וְאָז כָּתוּב, (יחזקאל א) כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים."],[1,"","דֶּגֶל שֵׁנִי, מֶרְכָּבָה מְזֻיֶּנֶת, נֶשֶׁ\"ר, אוּרִיאֵ\"ל, דָּרוֹ\"ם. וּשְׁנֵי מְמֻנִּים עִמּוֹ - שַׁמְשִׁיאֵ\"ל, חַסְדִּיאֵ\"ל. נֶשֶׁר זֶה עוֹלֶה, וְכָל בַּעֲלֵי הַכְּנָפַיִם מִלְּפָנָיו. כַּמָּה מֶרְכָּבוֹת עוֹלוֹת בְּכָל הַצְּדָדִים, כָּל אַחַת וְאַחַת בְּחֹזֶק הַשֶּׁמֶשׁ."],[2,"","רוּחַ שֶׁל רוּחַ פְּנִימִית יוֹצֵאת, וְאוֹתָהּ הָרוּחַ מַגִּיעָה לַנֶּשֶׁר הַזֶּה, וְעוֹלִים אֵיבָרָיו וּמְכַסִּים אֶת הַגּוּף, כְּמוֹ שֶׁנֶּאֱמַר (איוב לט) הֲמִבִּינָתְךְ יַאֲבֶר נֵץ יִפְרֹשׂ כְּנָפָיו לְתֵימָן. כְּמוֹ דֻגְמַת כְּעֵין (דברים לב) כְּנֶשֶׁר יָעִיר קִנּוֹ, נֶשֶׁר נֵץ זֶה עִם יוֹנָה, עִם נֵץ, וְכָל בַּעֲלֵי הַכְּנָפַיִם כֻּלָּם מְצַפְצְפִים וּשְׂמֵחִים. אֶחָד מִצַּד (עמוד אחד) לְפָנָיו עוֹלֶה מִמַּטָּה לְמַעְלָה. כַּמָּה צִפֳּרִים יוֹרְדוֹת וְעוֹלוֹת, מְצַפְצְפוֹת וּשְׂמֵחוֹת, הוֹלְכוֹת וּמְשׁוֹטְטוֹת."],[3,"","כְּשֶׁנּוֹסֵעַ, מוֹשִׁיט כָּנָף יָמִין, כּוֹנֵס לְכָל חֵילָיו, שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים אֶלֶף בַּעֲלֵי כְנָפַיִם בִּשְׁנֵי גוּפִים, נֶשֶׁ\"ר וְאַרְיֵ\"ה כְּאֶחָד. מֵרִים קוֹל, כָּל הָאֲחֵרִים עוֹלִים וְיוֹרְדִים, מְצַפְצְפִים מִצִּדָּם מִכַּמָּה דְרָגוֹת."],[4,"","שְׁלֹשָה רָאשִׁים הֵם כְּאֶחָד בְּמַחֲנוֹת אֵלּוּ, וְכֻלָּם בְּחֶשְׁבּוֹן אֶחָד. וְחֶשְׁבּוֹן הָרָאשִׁים הַלָּלוּ - רֹאשׁ אֶחָד, אַרְבָּעִים וְשִׁשָּׁה אֶלֶף וַחֲמֵשׁ מֵאוֹת. רֹאשׁ שֵׁנִי, חֲמִשִּׁים וְתִשְׁעָה אֶלֶף וּשְׁלֹשׁ מֵאוֹת. רֹאשׁ שְׁלִישִׁי, אַרְבָּעִים וַחֲמִשָּׁה אֶלֶף וְשׁשׁ מֵאוֹת וַחֲמִשִּׁים."],[5,"","מִשְּׁנֵי צְדָדִים אֵלּוּ יוֹצְאִים שְׁנֵי כָרוֹזִים שֶׁהוֹלְכִים לִפְנֵי כָּל הַמַּחֲנוֹת, כְּשֶׁשְּׁנֵי אֵלֶּה מַכְרִיזִים: כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת, חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת, כֻּלָּם מִתְכַּנְּסִים. מִי רָאָה נְסִיעַת כָּל הָרְקִיעִים, כֻּלָּם נוֹסְעִים בְּמַשָּׂא בַּמַּחֲנוֹת לִפְנֵי אוֹתוֹ מִשְׁכָּן."],[6,"","בְּשָׁעָה שֶׁאֶחָד מֵהֶם, אוֹתוֹ שֶׁבָּא מִצַּד אַרְיֵה, פּוֹשֵׁט קוֹל כְּדֵי שֶׁלֹּא יִזְדַּעְזְעוּ כָּל אוֹתָם קוֹלוֹת, אָז מִתְכַּנְּסוֹת כָּל אוֹתָן מַחֲנוֹת. בְּשָׁעָה שֶׁאַחֵר קוֹרֵא, נִשְׁבָּר הַקּוֹל וְלֹא פוֹשֵׁט, כָּל אוֹתָן הַמַּחֲנוֹת שֶׁל הַנֶּשֶׁר הַזֶּה, כֻּלָּן מִתְכַּנְּסוֹת לִנְסֹע בְּמַסָּעָם. כְּנֶגֶד אֵלּוּ שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף, כְּגוֹן זֶה הַכֹּל לְמַטָּה. בֹּא רְאֵה, כְּשֶׁאֵלֶּה נוֹסְעִים, מַה כָּתוּב? (יחזקאל א) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם, אוֹתָם שֶׁמִּתְכַּנְּסִים אֲלֵיהֶם, כְּמוֹ שֶׁהָרֹאשׁ מִסְתַּכֵּל, כָּךְ גַּם כֻּלָּם."],[7,"","דֶּגֶל שְׁלִישִׁי, שׁוֹר, גַּבְרִיאֵל, צָפוֹן. שְׁנֵי מְמֻנִּים עִמּוֹ, קַפְצִיאֵ\"ל חִזְקִיאֵ\"ל. הַשּׁוֹר הַזֶּה מִצַּד שְׂמֹאל. קַרְנָיו עוֹלוֹת בֵּין שְׁתֵּי עֵינָיו. רוֹגֵז בְּהִסְתַכְּלוּת, עֵינַיִם לוֹהֲטוֹת כְּאֵשׁ שֶׁל נוּר דּוֹלֵק. נוֹגֵחַ וְרוֹפֵס בְּרַגְלָיו וְלֹא חָס."],[8,"","כְּשֶׁגּוֹעָה הַשּׁוֹר הַזֶּה, יוֹצְאִים מִנֶּקֶב תְּהוֹם רַבָּה כַּמָּה חֲבוּרוֹת מַכִּים (מחבלים), כֻּלָּם גּוֹעִים וּמְשׁוֹטְטִים לְפָנָיו, וְהַחֵמֶת וְהַתִּיק שֶׁבּוֹ שֶׁל כָּל עֲווֹנוֹת תְּלוּיִים לְפָנָיו, שֶׁהֲרֵי כָּל עֲבֵרוֹת הָעוֹלָם כְּתוּבִים בְּסֵפֶר וְעוֹלִים."],[9,"","שִׁבְעָה נַהֲרוֹת אֵשׁ שׁוֹפְעִים לְפָנָיו. כְּשֶׁצָּמֵא הוֹלֵךְ לְאוֹתוֹ נְהַר דִּינוּר, וְשׁוֹאֵב אוֹתוֹ בִּגְמִיעָה אַחַת. וְאוֹתוֹ נָהָר מִתְמַלֵּא כְּבַתְּחִלָּה וְלֹא נִהְיֶה אַכְזָב. כָּל אוֹתָם חֲיָלוֹת שׁוֹאֲבִים אֵשׁ אוֹכֶלֶת אֵשׁ. וְאִלְמָלֵא שֶׁמִּצַּד אַרְיֵה יוֹצֵא נָהָר אֶחָד שֶׁל מַיִם שֶׁמְּכַבִּים אֶת הַגֶּחָלִים שֶׁלָּהֶם, לֹא יוּכַל הָעוֹלָם לִסְבֹּל."],[10,"","חֹשֶׁךָ הַשֶּׁמֶשׁ שָׁם נִמְצָא, לֹא נִמְצָא אוֹר. כַּמָּה חֲיָלוֹת שֶׁל שׁוֹמְרֵי חֹק הוֹלְכִים וּמְשׁוֹטְטִים בַּחֹשֶׁךְ, וְאוֹתוֹ נָהָר שֶׁדּוֹלֵק בַּצַּד הַזֶּה, אֵשׁ שְׁחֹרָה חֲשׁוּכָה. וְאִם תֹּאמַר שֶׁאֵין אֵשׁ לְבָנָה, אֵשׁ שְׁחֹרָה, אֵשׁ אֲדֻמָּה, אֵשׁ שֶׁל שְׁנֵי גְוָנִים - אַל תֹּאמַר, שֶׁהֲרֵי וַדַּאי כָּךְ זֶה! וְעִם כָּל זֶה לְמַעְלָה לְמַעְלָה כָּךְ נִמְצָא, וּמִשָּׁם שׁוֹפֵעַ לַתַּחְתּוֹנִים הַלָּלוּ."],[11,"","שָׁנִינוּ, הַתּוֹרָה בַּמֶּה נִמְצֵאת? אֵשׁ לְבָנָה, וְאֵשׁ שְׁחֹרָה עַל גַּבֵּי לְבָנָה. בִּשְׁנֵי סוּגֵי אֵשׁ נִמְצֵאת הַתּוֹרָה. בּא רְאֵה, הָאֵשׁ אַחַת הִיא, וּמִתְחַלֶּקֶת לְאַרְבָּעָה. הַמַּיִם אֶחָד הֵם, וּמִתְחַלְּקִים לְאַרְבָּעָה. הָרוּחַ אַחַת הִיא, וּמִתְחַלֶּקֶת לְאַרְבָּעָה."]]],[["תְּלַת רֵישִׁין אִשְׁתְּכָחוּ (ס\"א אתחברו) בְּמַשְׁרְיָין אִלֵּין. חוּשְׁבָּן דִּלְהוֹן, רֵישָׁא חֲדָא שִׁתִּין וּתְרֵי אֶלֶף וּשְׁבַע מְאָה. רֵישָׁא ב', אַרְבְּעִין וְחַד אֶלֶף וַחֲמֵשׁ מְאָה. רֵישָׁא תְּלִיתָאָה, תְּלַת וְחַמְשִׁין אֶלֶף וְאַרְבַּע מְאָה. בַּר כָּל אִינּוּן דַּרְגִּין אַחֲרָנִין דְּאִתְפָּרְשָׁן בְּסִטְרַיְיהוּ, וְלֵית לוֹן חוּשְׁבָּנָא. כֻּלְּהוּ דַּרְגִּין עַל דַּרְגִּין. בַּר כַּמָה גַּרְדִּינֵי נִמוּסִין דְּאִינּוּן לְתַתָּא, חֲצִיפִין כְּכַלְבָּא, נַשְׁכִין כְּחַמָּרָא, וַוי מַאן דְּאִשְׁתְּכַח גַּבַּיְיהוּ, וְדִינָא דִּלְהוֹן בְּסִטְרָא רְבִיעָאָה.","דִּגְלָא רְבִיעָאָה, אָדָ\"ם רְפָאֵ\"ל. מַעֲרָב. בַּהֲדֵיהּ אַסְוָותָא. בְּסִטְרָא דְּאָדָם אִתְכְּלִיל דִּינָא עִלָּאָה עָלֵיהּ אַתְּסֵי. הַאי (ס\"א חד) אָחִיד בְּקַרְנוֹי דְּשׁוֹר, כַּד מִבָּעֵי לְאַעֲלָא לוֹן לִתְהוֹמָא רַבָּא. וְכָפִית לוֹן, דְּלָא יוֹקִיד עָלְמָא. בָּתַר דָּא שַׁרְיָא קוֹל דְּמָמָה דַּקָּה דִּינָא. (ס\"א הכא) מִלָּה בַּחֲשַׁאי, לָא מִשְׁתְּמַע מִלָּה דְּהַבָרָה כְּלָל.","בְּסִטְרָא דָּא, שַׁרְיָא מַאן דְּשַׁרְיָא, סָלִיק מַאן דְּסָלִיק, שִׁמְשָׁא אִתְכְּנִישׁ לְאַנְהָרָא לְהַאי אֲתָר. בְּגִין כַּךְ וּתְקַעְתֶּם תְּרוּעָה, בִּסְטַר דָּרוֹם. אֲבָל הָכָא, לָאו הַאי וְלָאו הַאי. אֲמַאי תְּרוּעָה. לְאַכְפְּיָיא סְטָר צָפוֹן, וּבְגִין כָּךְ סְטָר צָפוֹן לַאֲחוֹרָא.","תָּא חֲזֵי, שְׁתֵּי חֲצוֹצְרוֹת, בְּגִין דְּאִינּוּן מִסִּטְרֵי תְּרֵי דְּקָאַמְרֵי, מִמִּזְרָח וּמִדָּרוֹם. אִינְהוּ זְמִינִין לְתַּבְרָא דִּינִין, וּלְאַכְפְּיָיא לוֹן. וְעַל דָּא אִינּוּן מִכֶּסֶף. וּבְגִין כָּךְ וּבְיוֹם שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וְגוֹ', וּתְקַעְתֶּם בַּחֲצוֹצְרוֹת, סְתָם, בֵּין לְעֵילָּא בֵּין לְתַתָּא. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן, וְיָהִיב לוֹן חוּלָקָא עִלָּאָה עַל כָּל שְׁאַר עַמִּין. וְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּבַּח בְּהוּ בְּתוּשְׁבַּחְתַּיְיהוּ, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'.","(במדבר י׳:ל״ה) וַיְהִי בִּנְסוֹעַ הָאָרוֹן וַיֹּאמֶר מֹשֶׁה וְגוֹ'. רִבִּי אֶלְעָזָר אָמַר, הָכָא אִית לְאִסְתַּכְּלָא, נ' דְּאִיהִי (ס\"א מנוזרא) מְחַזְרָא לַאֲחוֹרָא הָכָא בִּתְרֵי דּוּכְתֵּי, אֲמַאי. וְאִי תֵּימָא נ' כְּפוּפָה, הָא יְדִיעָה נ' כְּפוּפָה נוּקְבָּא. נ' פְּשׁוּטָה, כְּלָלָא דִּדְכַר וְנוּקְבָּא. וְהָא אוֹקִימְנָא בַּאֲתָר דָּא, וַיְהִי בִּנְסוֹעַ הָאָרוֹן. אֲמַאי אִתְהַדָּר לְבָתַר כְּגַוְונָא דָּא.","תָּא חֲזֵי, נ בְּאַשְׁרֵי יוֹשְבֵי בֵיתֶךָ לָא אִתְּמַר, בְּגִין דְּהִיא בְּגָלוּתָא. וְהָא אוּקְמוּהָ חַבְרַיָּיא דִּכְתִּיב, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל וְגוֹ'. אֶלָּא מַה כְּתִיב לְעֵילָּא, וַאֲרוֹן בְּרִית יְיָ נוֹסֵעַ לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשֶׁת יָמִים לָתוּר לָהֶם מְנוּחָה. כֵּיוָן דְּהֲוָה נָטִיל אֲרוֹנָא, נוּ\"ן נָטִיל עָלֵיהּ (נ\"א עמיה), וְהָא שְׁכִינְתָּא עַל גַּבֵּי אֲרוֹנָא יְתִיב. תָּא חֲזֵי, חֲבִיבוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, דְּהָא אַף עַל גַּב דְּאִינּוּן סָטָאן מֵאֹרַח מֵישָׁר, קוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי לְשַׁבְקָא לוֹן, וּבְכָל זִמְנָא אַהְדָּר אַנְפּוֹי לָקֳבְלַיְיהוּ, דְּאִי לָאו הָכִי לָא יְקוּמוּן בְּעָלְמָא.","תָּא חֲזֵי, אֲרוֹנָא הֲוָה נָטַל קַמַּיְיהוּ אֹרֵחַ תְּלָתָא יוֹמִין, נ לָא הֲוָה מִתְפְּרַשׁ מִנֵּיהּ, וְנָטִיל עִמֵּיהּ. וּמִגּוֹ רְחִימוּ דִּלְהוֹן דְּיִשְׂרָאֵל, אַהְדָּר אַנְפּוֹי וְאִסְתְּחַר מִלְּגַבֵּי אֲרוֹנָא, כְּהַאי אַיָּילָא דְּעָזַלְתָּא, כַּד אִיהוּ אָזִיל, אַהְדָּר אַפּוֹי לַאֲתָר דְּנָפִיק. וְעַל דָּא בִּנְסוֹעַ הָאָרוֹן, נוּ\"ן אַסְחַר אַנְפִּין לָקֳבְלַיְיהוּ דְּיִשְׂרָאֵל, וְכַתְפֵי גּוּפָא לְגַבֵּי אֲרוֹנָא.","וְעַל דָּא כַּד אֲרוֹנָא הֲוָה נָטִיל, מֹשֶׁה אָמַר קוּמָה יְיָ, לָא תִּשְׁבּוֹק לוֹן, אַהְדָּר אַנְפָּךְ לְגַבָּן, כְּדֵין נוּ\"ן אִתְהַדָּר לְגַבַּיְיהוּ כְּגַוְונָא דָּא כְּמַאן דִּמְהַדָּר אַנְפֵּיה לְמַאן דְּרָחִים, וְכַד הֲוָה שָׁארֵי אֲרוֹנָא (וישראל) לְמִשְׁרֵי, כְּדֵין אַהְדָּר נוּן אַנְפּוֹי מִיִשְׂרָאֵל, וְאִתְהַדָּר לְגַבֵּי אֲרוֹנָא, וּבְכֹלָּא אִתְהַדָּר.","אָמַר רִבִּי שִׁמְעוֹן, אֶלְעָזָר, בְּודַּאי הָכִי הוּא, אֲבָל הָכָא לָא אַהְדָּר אַנְפּוֹי מִיִשְׂרָאֵל, דְּאִי הָכִי בָּעֵי נוּן לְאִתְהַפְּכָא מִגַּוְונָא דְּאַחֲרָא עִלָּאָה (ס\"א דלעילא), הַאי מְנוּזָר לַאֲחוֹרָא וְהַאי בְּאוֹרַח מֵישָׁר לְגַבֵּי אֲרוֹנָא.","אֶלָּא ודַּאי לָא אַהְדָּר אַנְפּוֹי מִנַּיְיהוּ, וּמָה עֲבִיד בְּשַׁעֲתָא דְּשָׁארִי אֲרוֹנָא לְמִשְׁרֵי. אָמַר מֹשֶׁה שׁוּבָה יְיָ, כְּדֵין שָׁארֵי אֲרוֹנָא, וּשְׁכִינְתָּא קָאִים בְּסִטְרָא אַחֲרָא, וְאַנְפִּין לָקֳבְלַיְיהוּ דְּיִשְׂרָאֵל, וְלָקֳבְלֵיהּ דַּאֲרוֹנָא. (ובגין כך) וּכְדֵין כֹּלָּא כָּלִיל (לגווה) לְכַוְּונָא, לַאֲרוֹנָא, וּלְיִשְׂרָאֵל. אֶלָּא דְּיִשְׂרָאֵל גָּרְמוּ לְבָתַר, דִּכְתִּיב וַיְהִי הָעָם כְּמִתְאוֹנְנִים."],[[0,"תלת רישין אשתכחו","וכו': ג' ראשים נמצאים במחנות אלו כנגד ג' שבטים, שבמחנה דן. החשבון שלהם, הוא, ראש אחד ס\"ב אלף וז' מאה, והוא המספר של שבט דן שבכתוב, ראש הב', מ\"א אלף וה' מאה. והוא מספר של שבט אשר. ראש הג', נ\"ג אלף וד' מאה. והוא מספר של שבט נפתלי, חוץ מאלו מדרגות האחרות המתפרשים בהצד שלהם שאין להם חשבון. דהיינו הנשים והטף של ג' שבטים אלו שאינם בחשבון האמור. וכולם מדרגות על מדרגות, חוץ מכמה בעלי דין הנמשכים מקו שמאל, שהם למטה, בקליפות, שהם חצופים ככלב ונושכים כחמור, שהם אינם בכלל המחנות האלו דצד שמאל, אוי מי שנמצא אצלם והדין שלהם הוא בצד הרביעי, שהיא המלכות. כלומר, שהם מקבלים חיותם מן המלכות."],[1,"דגלא רביעאה","וכו': דגל הרביעי שהוא דגל מחנה אפרים, מבחינות החיות הוא פני אדם, ומד' המלאכים הוא רפאל, והוא נוסע במערב. שכל אלו הם בחינות המלכות. ועמו רפואה. כי בצד אדם, נכלל דין העליון בו, ומתרפא. זה אוחז בקרניו של השור, כשרוצה להביא אותן לתהום הגדול, וקושר אותן שלא תשרפנה העולם. אחר זה שורה קול דממה דקה. כאן הדבר בחשאי, שלא נשמע דבר הברה כלל."],[1,"","פירוש. דגל הרביעי הזה ה\"ס המלכות, שנקראת אדם ומד' מלאכים שהם מרכבת המלכות הוא המלאך רפאל, וה\"ס רוח מערב. ונודע שבעת שליטת קו שמאל מטרם שנתיחד עם הימין, הוא שורף העולם בדינים שלו ורוצה לבטל את הימין, ואינו יכול להתיחד עם הימין, אלא אחר שמקבל מדתה של המלכות, דהיינו שלא יאיר אלא ממטה למעלה כמדת המלכות (כנ\"ל ב\"א דף ס' ד\"ה מחלוקת) ואז מתיחד עם הימין ומתרפא מדיניו. וז\"ש \u0003בהדיה אסותא, בסטרא דאדם אתכליל דינא עלאה עליה, אתסי,\u0004 בסטרא דאדם, פירושו קו שמאל, אשר המלכות הנקראת אדם נמשכת מן הסטר שלו. \u0003אתכליל דינא עלאה עליה,\u0004 היינו הדינים הקשים דשמאל בלי ימין. \u0003אתסי,\u0004 היינו ע\"י קבלתו את מדת המלכות, שלא יאיר אלא ממטה למעלה. ומפרש דבריו, ואומר, \u0003האי אחיד בקרנוי דשור,\u0004 שהמלכות אוחזת בקרנוי דשור, שמדה זו כשהיא בקו שמאל, שהג\"ר לא יאירו אלא ממטה למעלה נקראים, \u0003קרני השור\u0004 (כנ\"ל באות קי\"ח ע\"ש) ע\"כ נבחן שהמלכות אוחז את השור, שהוא קו שמאל, בקרניו, והיינו רק אחר הפעולה של קו האמצעי שמיעט הקו שמאל במסך דחירק ונחלש ואז נתרצה לקבל מדתה של המלכות שלא יאיר אלא ממטה למעלה (כנ\"ל לך י\"ג ד\"ה ונתבאר) וז\"ש, \u0003כד מבעי לאעלא לון לתהומא רבא,\u0004 דהיינו אחר ששלט עליו המסך דחירק, שמיעטו לו\"ק בלי ראש, (כמ\"ש שם) שזה נבחן שרצה לירד \u0003לתהומא רבא,\u0004 ששם מדת המיעוט דו\"ק בלי ראש, ואחר שהגיע לזה קבל רפואתה של המלכות שלא יאירו הג\"ר שלו אלא ממטה למעלה. \u0003וכפית לון דלא יוקיד עלמא,\u0004 שקשרה אותן הקרנים, שלא תאורנה אלא ממטה למעלה, ואז נתרפא מדיניו, שהיו עומדים לשרוף העולם."],[1,"","וז\"ש, \u0003בתר דא שריא קול דממה דקה,\u0004 כי הארת ממטה למעלה, נבחנת לקול דממה דקה, \u0003הכא מלה בחשאי, לא משתמע מלה דהברה כלל,\u0004 כי אם ההארה היא ממטה למעלה ואינה נמשכת כלום למטה, נבחן שהוא בחשאי, וקול הברה לא נשמע למטה כלל."],[2,"בסטרא דא שריא","וכו': בצד זה, במלכות, שורה מי ששורה, דהיינו החסדים דקו ימין, ועולה מי שעולה, דהיינו הארת החכמה שבקו שמאל, המאירה בדרך עליה ממטה למעלה. השמש, שהוא ז\"א, נאסף להאיר למקום הזה, שהוא מלכות. ומשום זה, כתוב, ותקעתם תרועה, בצד דרום. שהוא קו ימין בהארת קו האמצעי כנ\"ל. אבל כאן, במלכות, לא זה ולא זה. שאין כאן לא תקיעה ולא תרועה. שואל, למה תוקעים תרועה. ומשיב, שהוא סוד כח המסך שבקו האמצעי, המכניע לצד צפון, שהוא קו שמאל, כדי שיתיחד עם הימין, ולא יאיר יותר רק ממטה למעלה, כנ\"ל בדבור הסמוך. ומשום זה צד צפון לאחר כל המחנות כמ\"ש מאסף לכל המחנות. שהוא משום שמתתקן ע\"י המלכות, כנ\"ל בדבור הסמוך, וע\"כ דגל מחנה אפרים שהוא המלכות נוסע מקודם לקו שמאל, שהוא מחנה דן. ומחנה דן לאחרונה יסעו."],[3,"ת\"ח שתי חצוצרות","וכו': בוא וראה, ב' חצוצרות הן, משום שהן מצד השנים שאמרנו, ממזרח שהוא קו אמצעי, ומדרום שהוא קו ימין. והם מוכנים לשבור הדינים ולהכניע אותם, בסוד התרועה, כנ\"ל בדבור הסמוך, וע\"כ הן מכסף. שהוא חסד, ומשום זה, וביום שמחתכם ובמועדיכם וגו' ותקעתם בחצוצרות, סתם, שהוא בין למעלה, ובין למטה בעולם הזה. אשרי הם ישראל שהקב\"ה רצה ביקרם, ונתן להם חלק עליון על כל שאר העמים, והקב\"ה משתבח בהם, בתשבחותיהם שמשבחים לו, ז\"ש ויאמר לי עבדי אתה ישראל וגו'."],[4,"ויהי בנסוע הארון","וגו': רבי אלעזר אמר, כאן יש להסתכל, ה \u0003נ'\u0004 שהיא מחזירה פניה לאחור כאן בב' מקומות, דהיינו ה \u0003נ'\u0004 העומדת לפני פרשת ויהי בנסוע, ולאחריה, למה. ואם תאמר שרומזת על \u0003נ'\u0004 כפופה, אשר נודע, ש \u0003נ'\u0004 כפופה, היא הנוקבא, דהיינו המלכות, \u0003ן'\u0004 פשוטה, היא כלל דכר ונוקבא, שהם ז\"א ומלכות, והעמדנו במקום זה, ב \u0003נ'\u0004 כפופה, שעליה נאמר, ויהי בנסוע הארון ויאמר משה קומה ה', שעל ה \u0003נ'\u0004 כפופה אמר קומה. ותאמר שע\"כ נכתבו ב' הנונין ההפוכות, אבל א\"כ למה נחזרו שוב פניהם לאחור, כעין \"נון הפוכה\"."],[5,"ת\"ח נ' באשרי","וכו': בוא וראה. לא נאמר \u0003נ'\u0004 בהא\"ב של אשרי יושבי ביתך, משום שה \u0003נ'\u0004 שהיא מלכות היא בגלות. וכך העמידו החברים, שכתוב עליה, נפלה לא תוסיף קום בתולת ישראל וגו'. אלא מה כתוב למעלה, וארון ברית ה' נוסע לפניהם דרך שלשת ימים לתור להם מנוחה, כיון שהארון היה נוסע, היתה. ה \u0003נ'\u0004 נוסעת עליו, שהיא המלכות, שהרי השכינה ישבה על הארון. בוא וראה אהבת הקב\"ה לישראל, שאע\"פ שהם סרו מדרך הישר, אין הקב\"ה רוצה לעזוב אותם, ובכל זמן הוא מחזיר פנים אליהם, שאם לא כן, לא היתה להם תקומה בעולם."],[6,"ת\"ח ארונא הוה נגזל","וכו': בוא וראה, הארון היה נוסע לפניהם דרך שלשת ימים הנ' שהיא השכינה, לא היתה נפרשת ממנו, ונוסעת עמו. ומתוך אהבתם של ישראל החזיר פניו לישראל, ומסבכת עצמה מן הארון. כאותה אילה הצעירה כשהיא הולכת היא מחזרת פניה אל המקום שיצאה משם. ועל כן, בנסוע הארון, היתה ה \u0003נ'\u0004 מחזרת פניה כלפי ישראל וכתפי גופה אל הארון."],[7,"וע\"ד כד ארונא","וכו': וע\"כ כשהארון היה נוסע, אמר משה \u0003קומה ה',\u0004 היינו, שלא תעזוב אותנו החזיר פניך אצלנו. ואז החזירה ה \u0003נ'\u0004 פניה אליהם כעין \"נון הפוכה\" כמי שמחזיר פניו למי שאוהב אותו. וכשהתחיל הארון לנוח, אז סיבב פניו מישראל והחזיר פניו אל הארון. ולגמרי החזירם."],[7,"","ביאור המאמר. תחילה מבאר (באות קכ\"ח) שנ' כפופה, שה\"ס המלכות, הוא \u0003בנפילה\u0004 מטרם הזווג עם ז\"א, שאז היא כמו בגלות, שעליה נאמר \u0003נפלה\u0004 לא תוסיף קום וגו'. וע\"כ תחילה היא צריכה \u0003להקימה\u0004 מנפילתה. ואח\"כ היא יכולה להזדווג עמו. \u0003ונפילה,\u0004 פירושה שהיא בחסרון ג\"ר. \u0003וקימה,\u0004 פירושה החזרת הג\"ר, שבמלכות ה\"ס הארת החכמה. והארון עם הלוחות שבתוכו ה\"ס ז\"א ומלכות, שלוחות העדות ה\"ס ז\"א, והארון ה\"ס מלכות (כמ\"ש להלאה פרשת שלח אות י\"ד.) ונמצא שמטרם ויהי בנסוע הארון, לא היתה המלכות בזווג עם ז\"א. מחמת חסרון החכמה, ונודע שאין גילוי החכמה אלא בשעת הנסיעה, שה\"ס נסיעת ג' קוין בתלת דוכתי (כנ\"ל בשלח דף ל\"ט ד\"ה וג') ולפיכך הקדים הנסיעה אל הזווג כנ\"ל. וז\"ס, \u0003ויהי בנסוע הארון ויאמר משה קומה ה'\u0004 כי אז נגלה הארת החכמה \u0003שהקימה\u0004 ה \u0003נ'\u0004 מנפילתה. ואח\"כ אחר שנשלמה הנסיעה וקבלה הארת החכמה, אז אמר משה \u0003שובה ה'\u0004 וגו' שאז נפסק הארת החכמה, וחזרה להזדווג עם ז\"א שה\"ס חסדים."],[7,"","וזה אמרו (באות קכ\"ח) \u0003אלא מה כתיב לעילא, וארון ברית ה' נוסע לפניהם דרך שלשת ימים לתור להם מנוחה.\u0004 מנוחה, פירושו זווג ז\"א ומלכות. ובכדי להכין המלכות שתהיה ראויה לזווג עם ז\"א היה צריך ארון הברית לנסוע דרך ג' ימים, שה\"ס ג' קוין בג' דוכתי, שבדרך ג' ימים אלו, קבלה הארת החכמה שה\"ס קימה מנפילתה, ואז ראויה למנוחה, שה\"ס הזווג. ועד\"ז ישראל אינם ראוים לקבל מזווג זו\"ן, מטרם שמקבלים הארת החכמה שבמלכות. וז\"ש, \u0003לתור להם מנוחה,\u0004 דהיינו כדי שישראל יוכלו לקבל סוד המנוחה מזווג זו\"ן. וז\"ש, \u0003אע\"ג דאינון סטאן מארח מישר,\u0004 דהיינו שאינם ראוים לקבל המנוחה מזווג זו\"ן, \u0003קב\"ה לא בעי לשבקא לון,\u0004 אין הקב\"ה עוזב אותם כך, אלא, \u0003ובכל זמנא אהדר אנפוי לקבלייהו,\u0004 דהיינו שהמלכות מחזירה פניה אליהם ומאירה להם הארת החכמה להכשירם שיוכלו אח\"כ לקבל מסוד המנוחה. וז\"ש (באות קכ\"ט) \u0003ארונא הוה נטל קמייהו ארח תלתא יומין, הנ' לא הוה מתפרש מניה ונטיל עמיה.\u0004 כי סוד נסיעת ג' קוין הם בז\"א, אלא שהמלכות אינה נפרשת מז\"א בשעת הנסיעה וגם היא מקבלת ג' קוין אלו, \u0003ומגו רחימו דלהון דישראל, אהדר אנפוי,\u0004 דהיינו שבחינת הארת החכמה שמקבלת, הנקרא פנים, בסוד חכמת אדם תאיר פניו, היא מחזירה פניה אלו לישראל, ומשפעת להם הארת החכמה. \u0003ואסתחר מלגבי ארונא,\u0004 כלומר שמחזירה את עצמה מז\"א, שה\"ס הלוחות שבארון. כי ז\"א הוא בחינת חסדים מכוסים, ובעת שהמלכות מקבלת חכמה, שאינה בחינת ז\"א, נבחן שהמלכות מחזירה עצמה ממנו, וז\"ש, \u0003וכתפי גופא לגבי ארונא.\u0004 כלומר שפורשת עצמה מבחינת ז\"א, ודומה כמו שמחזירה אליו אחוריה. ומה שאומר במשל האילה, \u0003אהדר אנפוי לאתר דנפיק,\u0004 רומז בזה כי המלכות הנקראת אילה יוצא מקו שמאל, ושם היא שורשה, וע\"כ מחזירה פניה לבחינת הארת החכמה שבקו שמאל."],[7,"","והרמז שבתורה היא, כי פרשת ויהי בנסוע נחשבת לבחינת ארון הברית הנוסע, ואח\"כ בא בסוד הזווג שהוא מנוחה. וכותבים לפניה \"נון הפוכה\", שאחוריה לפרשת ויהי בנסוע, ופניה לפרשיות הקודמות, הנבחנות לבחינת ישראל. וכן אחר פרשת ויהי בנסוע כותבים \"נון הפוכה\", שפניה לפרשת ויהי בנסוע, שה\"ס ארון הברית, ואחוריה לפרשיות האחרות שלאחריה, הנבחנות לבחינות ישראל. בסוד אורייתא וישראל חד הוא."],[7,"","וז\"ש, \u0003וע\"ד, בנסוע הארון, נון אסחר אנפין לקבלייהו דישראל, וכתפי גופא לגבי ארונא,\u0004 דהיינו שכותבים \"נון הפוכה\" המחזרת פניה לפרשיות הקודמות שה\"ס ישראל, וכתפי גופה לפרשת ויהי בנסוע שהיא הארון, דהיינו ז\"א. והיינו מטעם הנ\"ל כי בזמן הנסיעה הבא מקבלת חכמה, שהיא פניה, ופנים האלו היא משפעת לישראל. וכיון שז\"א היא בבחינת חסדים מכוסים נבחן שאחוריה לז\"א, \u0003שאחור,\u0004 יורה שאינה מקבלת ממנו בחינתו. וז\"ש, (באות ק\"ל) \u0003וע\"ד, כד ארונא הוה נטיל, משה אמר קומה ה'.\u0004 שפירושו, \u0003לא תשבוק לון אהדר אנפך לגבן,\u0004 דהיינו שתקבל סוד הקימה, שהיא חכמה, ופנים זה של חכמה תשפיע לישראל, שיזכו אח\"כ לקבל מזווג השלם שה\"ס מנוחה. \u0003וכד הוה שארי ארונא למשרי\u0004 דהיינו אחר שגמר קבלת ג' הקוין שה\"ס הנסיעה ובא בסוד המנוחה, שהיא הזווג עם ז\"א, \u0003כדין אהדר אנפוי דנון מישראל,\u0004 דהיינו שהפסיקה השפעת החכמה, \u0003ואתהדר לגבי ארונא,\u0004 דהיינו שקבלה ג\"ר דחסדים מז\"א, שזה נבחן שנתנה פניה, שה\"ס הג\"ר לז\"א, לבחינת ז\"א, שה\"ס חסדים. \u0003ובכלא אתהדר,\u0004 ולגמרי חזרה לחסדים דז\"א. כי אין גילוי חכמה אלא בשעת נסיעת הקוין, ולאחר הנסיעה, חוזרים לבחינת חסדים לגמרי (כמ\"ש לעיל בשלח ל\"ט ד\"ה וגו' ע\"ש). וע\"כ נכתבה כאן \"נון הפוכה\" שניה, שפניה לפרשת ויהי בנסוע, שהיא ארון הברית, ואחוריה לפרשיות התורה שלאחר ויהי בנסוע, שה\"ס ישראל."],[8,"אמר רבי שמעון","וכו': אר\"ש, אלעזר, בודאי כך הוא, שצריכים להיות כאן ב' נונין הפוכים לפניה ולאחריה. כמו שאמרת. אבל כאן לאחר ויהי בנסוע, לא החזירה המלכות פניה מישראל, כלומר שלא הפסיקה השפעתה מישראל כמו שאמר ר\"א, דאם כן,היתה הנון הזו הכתובה, צריכה להיות בהיפוך, מכעין נון האחרת העליונה, שה\"ס המלכות, כי נון זו מנוזר לאחור אל ישראל, וזו העליונה, שהיא המלכות, היא בדרך יושר עם הארון, כלומר שהיא בזווג עם ז\"א. וכיון שהיא בזווג עם ז\"א, אז ודאי פניה לישראל. ולא כרבי אלעזר."],[9,"אלא ודאי לא","וכו': אלא ודאי הוא שהמלכות לא החזירה פניה מישראל, ומה עשתה בשעה שהתחיל הארון לנוח. אז אמר משה, \u0003שובה ה',\u0004 דהיינו שתפסיק מהארת החכמה ותשוב להארת החסדים דז\"א, אז שכן הארון, דהיינו שנח, והשכינה עמדה בצד אחר, דהיינו בצד ימין שהוא חסדים, ומקבלת ג\"ר דחסדים, שה\"ס פנים מז\"א, ופניה אלו מחזירה לישראל, וכנגד הארון. כלומר שפניה לארון לקבל ממנו חסדים, ופניה לישראל, להשפיע להם החסדים האלו, שמקבלת מארון הברית. ואז כלולה בתוכה מכל, מן הארון ומן ישראל. אלא אח\"כ גרמו ישראל שהמלכות תחזיר אחוריה אליהם, שכתוב, ויהי העם כמתאוננים. ולפיכך כתוב \"נון הפוכה\" בין ויהי בנסוע לבין פרשת ויהי העם כמתאוננים."],[9,"","פירוש. ר\"ש אינו חולק על עצם כתיבת הנ' ומודה לו שצריכה להיות הפוכה, שפניה לפרשת ויהי בנסוע, ואחוריה לישראל דהיינו לשאר פרשיות שבתורה, אלא שחולק על טעמו, שאמר שבעת המנוחה, מפסקת השפעתה מישראל, וע\"כ אחוריה לישראל, ופניה לארון הברית, לקבל ממנו חסדים. על זה חולק ר\"ש, ואמר שבעת המנוחה לא כל שכן שמחזרת פניה לישראל, אלא פנים של חסדים. ועם כל זה כתיבת הנון צריכה להיות הפוכה, שפניה לויהי בנסוע, ואחוריה לשאר פרשיות. אלא מטעם אחר, מטעם שכאן חטאו ישראל בפרשת ויהי העם כמתאוננים. וע\"כ החזירה כאן אחוריה לישראל."]],[[0,"","שְׁלֹשָה רָאשִׁים נִמְצָאִים (מתחברים) בְּמֶרְכָּבוֹת אֵלּוּ. חֶשְׁבּוֹנָם - רֹאשׁ אֶחָד, שִׁשִּׁים וּשְׁנַיִם אֶלֶף וּשְׁבַע מֵאוֹת. רֹאשׁ שֵׁנִי, אַרְבָּעִים וְאֶחָד אֶלֶף וַחֲמֵשׁ מֵאוֹת. רֹאשׁ שְׁלִישִׁי, חֲמִשִּׁים וּשְׁלֹשָׁה אֶלֶף וְאַרְבַּע מֵאוֹת. פְּרָט לְכָל אֵלּוּ הַדְּרָגוֹת הָאֲחֵרוֹת שֶׁנִּפְרָדוֹת בְּצִדֵּיהֶן, וְאֵין לָהֶן חֶשְׁבּוֹן. כֻּלָּן דְּרָגוֹת עַל דְּרָגוֹת, פְּרָט לְכַמָּה חֲיָלוֹת שֶׁל שׁוֹמְרֵי חֹק שֶׁהֵם לְמַטָּה, חֲצוּפִים כַּכֶּלֶב, נוֹשְׁכִים כַּחֲמוֹר. אוֹי לְמִי שֶׁנִּמְצָא לִפְנֵיהֶם, וְדִין שֶׁלָּהֶם בְּצַד רְבִיעִי."],[1,"","דֶּגֶל רְבִיעִי, אָדָ\"ם, רְפָאֵ\"ל, מַעֲרָב. יַחַד אִתּוֹ רְפוּאָה. בַּצַּד שֶׁאָדָם נִכְלָל, דִּין עֶלְיוֹן עָלָיו מִתְרַפֵּא. זֶה (אחד) אוֹחֵז בְּקַרְנֵי הַשּׁוֹר, כְּשֶׁרוֹצֶה לְהַכְנִיסָם לִתְהוֹם רַבָּה, וְכוֹפֵת אוֹתָם שֶׁלֹּא יִשָּׂרֵף הָעוֹלָם. לְאַחַר זֶה שׁוֹרֶה קוֹל דְּמָמָה דַּקָּה, דִּין. (כאן) דָּבָר בַּחֲשַׁאי, לֹא נִשְׁמָע דְּבַר הֲבָרָה כְּלָל."],[2,"","בְּצַד זֶה שׁוֹרֶה מִי שֶׁשּׁוֹרֶה, עוֹלֶה מִי שֶׁעוֹלֶה, הַשֶּׁמֶשׁ מִתְכַּנֵּס לְהָאִיר לְמָקוֹם זֶה. בִּגְלַל זֶה וּתְקַעְתֶּם תְּרוּעָה בְּצַד דָּרוֹם. אֲבָל כָּאן לֹא זֶה וְלֹא זֶה. מַדּוּעַ תְּרוּעָה? לִכְפּוֹת צַד צָפוֹן, וְלָכֵן צַד צָפוֹן לְאָחוֹר."],[3,"","בֹּא רְאֵה, שְׁתֵּי חֲצוֹצְרֹת, מִשּׁוּם שֶׁהֵם מִצַּד שְׁנַיִם שֶׁאָמַרְנוּ, מִמִּזְרָח וּמִדָּרוֹם. הֵן עֲתִידוֹת לִשְׁבֹּר דִּינִים וְלִכְפּוֹתָם. וְעַל זֶה הֵן מִכֶּסֶף. וּמִשּׁוּם זֶה, וּבְיוֹם שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וְגוֹ', וּתְקַעְתֶּם בַּחֲצֹצְרֹת. סְתָם, בֵּין לְמַעְלָה בֵּין לְמַטָּה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדָם וְנָתַן לָהֶם חֵלֶק עֶלְיוֹן עַל כָּל שְׁאָר הָעַמִּים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בְּתִשְׁבְּחוֹתֵיהֶם. זֶהוּ שֶׁכָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'."],[4,"","וַיְהִי בִּנְסֹעַ הָאָרֹן וַיֹּאמֶר מֹשֶׁה וְגוֹ'. רַבִּי אֶלְעָזָר אָמַר, כָּאן יֵשׁ לְהִסְתַּכֵּל, נ' שֶׁהִיא (מנזרת) מְחַזֶּרֶת לְאָחוֹר, כָּאן בִּשְׁנֵי מְקוֹמוֹת, לָמָּה? וְאִם תֹּאמַר נ' כְּפוּפָה, הֲרֵי יָדוּעַ נ' כְּפוּפָה נְקֵבָה. נ' פְּשׁוּטָה, כְּלָל שֶׁל זָכָר וּנְקֵבָה. וַהֲרֵי בֵּאַרְנוּ בְּמָקוֹם זֶה, וַיְהִי בִּנְסֹעַ הָאָרֹן. לָמָּה חָזַר לְאַחַר כָּךְ כְּמוֹ זֶה?"],[5,"","בֹּא רְאֵה, נ' בְּאַשְׁרֵי יוֹשְׁבֵי בֵיתֶךְ לֹא נֶאֶמְרָה, מִשּׁוּם שֶׁהִיא בַּגָּלוּת, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל וְגוֹ'. אֶלָּא מַה כָּתוּב לְמַעְלָה? וַאֲרוֹן בְּרִית ה' נֹסֵעַ לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשֶׁת יָמִים לָתוּר לָהֶם מְנוּחָה. כֵּיוָן שֶׁהָיָה נוֹסֵעַ הָאָרוֹן, נוּ\"ן נוֹסַעַת עָלָיו (עמו), וַהֲרֵי הַשְּׁכִינָה יוֹשֶׁבֶת עַל גַּבֵּי הָאָרוֹן. בֹּא רְאֵה חֲבִיבוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַבֵּי יִשְׂרָאֵל, שֶׁהֲרֵי אַף עַל גַּב שֶׁהֵם סוֹטִים מִדֶּרֶךְ הַיָּשָׁר, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לְעָזְבָם, וּבְכָל זְמַן מַחֲזִיר פָּנָיו לְמוּלָם, שֶׁאִם לֹא כָּךְ, לֹא יַעַמְדוּ בָעוֹלָם."],[6,"","בֹּא רְאֵה, הָאָרוֹן הָיָה נוֹסֵעַ לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשָׁה יָמִים, נ' לֹא הָיְתָה נִפְרֶדֶת מִמֶּנּוּ, וְנוֹסַעַת עִמּוֹ. וּמִתּוֹךְ אַהֲבַת יִשְׂרָאֵל מַחֲזִיר פָּנָיו וּמִסְתּוֹבֵב מִלְּגַבֵּי הָאָרוֹן, כְּמוֹ עֹפֶר הָאַיָּלִים, כְּשֶׁהוּא הוֹלֵךְ, מַחֲזִיר פָּנָיו לַמָּקוֹם שֶׁמִּשָּׁם יָצָא. וְעַל כֵּן בִּנְסֹעַ הָאָרֹן, נוּ\"ן מְסוֹבֶבֶת פָּנִים לְמוּל יִשְׂרָאֵל, וְכִתְפֵי הַגּוּף לְגַבֵּי הָאָרוֹן."],[7,"","וְעַל כָּךְ, כְּשֶׁהָאָרוֹן הָיָה נוֹסֵעַ, מֹשֶׁה אָמַר קוּמָה ה', לֹא תַעֲזֹב אוֹתָם, הַחֲזֵר פָּנִים אֵלֵינוּ, וְאָז נוּ\"ן חוֹזֶרֶת לְגַבֵּיהֶם כְּצוּרָה זוֹ, כְּמִי שֶׁמַּחֲזִיר פָּנָיו לְמִי שֶׁאוֹהֵב. וּכְשֶׁהָיָה מַתְחִיל הָאָרוֹן (וישראל) לִשְׁרוֹת, אָז הֶחֱזִירָה נוּ\"ן פָּנֶיהָ מִיִּשְׂרָאֵל, וְהָחְזְרָה לְגַבֵּי הָאָרוֹן, וּבַכֹּל הָחֳזַר."],[8,"","אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, בְּוַדַּאי כָּךְ הוּא, אֲבָל כָּאן לֹא הֶחֱזִיר פָּנָיו מִיִּשְׂרָאֵל, שֶׁאִם כָּךְ, צְרִיכָה נוּ\"ן לְהִתְהַפֵּךְ מִגָּוֶן שֶׁל אַחֵר עֶלְיוֹן (שלמעלה), זֶה מְנֻזָּר לְאָחוֹר, וְזֶה בְּדֶרֶךְ יָשָׁר לְגַבֵּי הָאָרוֹן."],[9,"","אֶלָּא וַדַּאי לֹא הֶחֱזִיר פָּנָיו מֵהֶם. וּמֶה עָשָׂה בְּשָׁעָה שֶׁהָאָרוֹן הִתְחִיל לְהַשְׁרוֹת? אָמַר מֹשֶׁה שׁוּבָה ה', וְאָז שׁוֹרֶה הָאָרוֹן, וְהַשְּׁכִינָה עוֹמֶדֶת בְּצַד אַחֵר, וְהַפָּנִים מוּל יִשְׂרָאֵל וּמוּל הָאָרוֹן. (ומשום כך) וְאָז הַכֹּל נִכְלָל (לתוכה) לַכִּוּוּן, לָאָרוֹן וּלְיִשְׂרָאֵל. אֶלָּא שֶׁיִּשְׂרָאֵל גָּרְמוּ אַחַר כָּךְ, שֶׁכָּתוּב וַיְהִי הָעָם כְּמִתְאֹנֲנִים."]]],[["אָמַר רִבִּי אֶלְעָזָר, אֲנָא דְּאַמָרָן מִסִּפְרָא דְּרַב יֵיבָא סָבָא, דְּאָמַר דְּבֵין בְּהַאי גִּיסָא, וּבֵין בְּהַאי גִּיסָא, אִתְהַדָּר. אָמַר לֵיהּ, שַׁפִּיר קָאָמַר, אֲבָל דָּא דַּאֲמֵינָא, הָכִי תִּשְׁכַּח בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, וְהָכִי הוּא וַדַּאי.","וְהָמָן (במדבר י״א:ז׳) כִּזְרַע גָּד הוּא. אָמַר רִבִּי יוֹסֵי, לְקַיְּימָא זַרְעָא וְחֵילִין בְּאַרְעָא, כְּמָה דְאַתְּ אָמֵר (בראשית מ״ט:י״ט) גָּד גְּדוּד יְגוּדֶנּוּ. מַה זַרְעָא דְּגָד נַטְלֵי חוּלָקֵיהוֹן בְּאַרְעָא אַחֲרָא, כַּךְ מָן שַׁרְיָא עָלַיְיהוּ דְּיִשְׂרָאֵל, לְבַר מֵאַרְעָא קַדִּישָׁא.","דָּבָר אַחֵר כִּזְרַע גָּד הוּא. כְּזַרְעָא דְּגָד חִוָּורָא, וְאִקְפֵּי כַּד נָחִית לַאֲוִירָא, וְאִתְנֵגְרִיס (ס\"א ואתגשים) (ס\"א ואתבלע) בְּגוּפָא, וְהָא אוּקְמוּהָ חַבְרַיָּיא. וְעֵינוֹ כְּעֵין הַבְּדוֹלַח, כְּהַהוּא בְּדוֹלְחָא דְּאִיהוּ חִוָּור, כְּגַוְונָא דִּימִינָא (ס\"א חיוורא דעינא) דִּלְעֵילָּא. (כזרע גד הכי לא אקרון בארעא דמצראי אבל לכך מחרשי זריעא כזרע גד הוא כזרע גדא חוורא ואתקפיה כד נחית מלעילא לתתא)","אָמַר רִבִּי יִצְחָק, מַאי שְׁנָא (דאמר) דְּמֹשֶׁה בְּמִלָּה דָּא (חליש) לְעֵילָּא כְּנוּקְבָּא, דִּכְתִּיב אִם כָּכָה אַתְּ עוֹשֶׂה לִּי, אַתְּ, אַתָּה מִבָּעֵי לֵיהּ. אֶלָּא לַאֲתָר דְּמוֹתָא שָׁארֵי בֵּיהּ קָאָמַר, וְהַהוּא אֲתָר דְּנוּקְבָּא אִיהוּ. בְּגִין כַּךְ אָמַר הָרְגֵנִי נָא הָרוֹג, וְדָא אִילָנָא דְּמוֹתָא. וְהָא אוֹקִימְנָא דִּבְאִילָנָא דְּחַיֵּי לָא שַׁרְיָיא בֵּיהּ מוֹתָא. וְעַל דָּא אִתְהַדָּר לְגַבֵּי אִילָנָא דְּמוֹתָא וְאָמַר אַתְּ, וְלָא אָמַר אַתָּה, וְהָכִי מִבָּעֵי לֵיהּ.","מִיַּד (במדבר י״א:ט״ז) וַיֹּאמֶר יְיָ אֶל מֹשֶׁה אֶסְפָה לִּי שִׁבְעִים אִישׁ וְגוֹ'. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַתְּ בָּעֵי מוֹתָא בְּכָל זִמְנָא, הֲרֵי לָךְ, וְאָצַלְתִּי מִן הָרוּחַ וְגוֹ'. תָּא חֲזֵי, דְּהָכָא יָדַע מֹשֶׁה דְּאִיהוּ יָמוּת, וְלָא יֵיעוּל לְאַרְעָא, דְּהָא אֶלְדָּד וּמֵידָד מִלָּה דָּא הֲווֹ אַמְרֵי.","עַל דָּא, לָא לִבְעֵי לֵיהּ לֶאֱינָשׁ, בְּשַׁעֲתָא דְּרוּגְזָא שָׁארֵי בֵּיהּ, לְלַטְיָיא גַּרְמֵיהּ. דְּהָא כַּמָה קַיְימֵי עָלֵיהּ דִּמְקַבְּלֵי הַהִיא מִלָּה. בְּזִמְנָא אוֹחֲרָנָא דְּבָעָא מִיתָה, לָא קַבִּילוּ מִנֵּיהּ. בְּגִין דְּכֹלָּא לְתוֹעַלְתָּא דְּיִשְׂרָאֵל הֲוָה. הַשְּׁתָּא לָאו אִיהוּ, אֶלָּא מִגּוֹ רוּגְזָא וְדוֹחֲקָא, וּבְגִין כָּךְ קַבִּילוּ מִנֵיהּ. וְעַל דָּא אִשְׁתָּאֲרוּ לְבָתַר אֶלְדָּד וּמֵידָד, וְאָמְרוּ דָּא, דְּמֹשֶׁה יִתְכְּנִישׁ, וִיהוֹשֻׁעַ יֵיעוּל לוֹן לְיִשְׂרָאֵל לְאַרְעָא.","וּבְגִין כָּךְ אָתָא יְהוֹשֻׁעַ לְגַבֵּי מֹשֶׁה, וְקַּנֵי עָלֵיהּ דְּמֹשֶׁה. וּמֹשֶׁה לָא אַשְׁגַּח בִּיקָרָא דִּילֵיהּ. וְעַל דָּא אָמַר, אֲדֹנִי מֹשֶׁה כְּלָאֵם. מַאי כְּלָאֵם. מָנַע מִנְּהוֹן אִינּוּן מִלִּין, כְּמָה דְאַתְּ אָמֵר (שמות ל״ו:ו׳) וַיִּכָּלֵא הָעָם מֵהָבִיא. (בראשית ח׳:ב׳) וַיִּכָּלֵא הַגֶּשֶׁם מִן הַשָּׁמָיִם. מְנִיעוּתָא מַמָּשׁ. וּמֹשֶׁה לָא בָּעָא. פּוּק חָמֵי עַנְוָותָנוּתֵיהּ דְּמֹשֶׁה, מַה כְּתִיב הַמְקַנֵּא אַתָּה לִי וְגוֹ'. זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּאִיהוּ סָלִיק עַל כֻּלְּהוּ נְבִיאֵי עִלָּאֵי (נ\"א דעלמא). אָמַר רִבִּי יְהוּדָה, כָּל שְׁאַר נְבִיאִין לְגַבֵּי מֹשֶׁה, כְּסִיהֲרָא לְגַבֵּי שִׁמְשָׁא.","רִבִּי אַבָּא הֲוָה יָתִיב לֵילְיָא חַד, וְלָעֵי בְּאוֹרַיְיתָא. וַהֲווּ עִמֵּיהּ רִבִּי יוֹסֵי וְרִבִּי חִזְקִיָּה. אָמַר רִבִּי יוֹסֵי, כַּמָה אִינּוּן בְּנֵי נָשָׁא תַּקִיפוּ לִבָּא, דְּלָא מַשְׁגְחֵי בְּמִלֵּי דְּהַהוּא עָלְמָא כְּלוּם. אָמַר רִבִּי אַבָּא, בִּשְׂרָא דְּלִבָּא, דַּאֲחִידָא בְּכָל שַׁיְיפֵי גּוּפָא, קָא עָבִיד לוֹן. פָּתַח וְאָמַר, (קהלת ו׳:א׳) יֵשׁ רָעָה אֲשֶׁר רָאִיתִי תַּחַת הַשָּׁמֶשׁ וְרַבָּה הִיא עַל הָאָדָם. יֵשׁ רָעָה: דָּא אִיהִי תּוּקְפָּא בִּישָׁא דְּלִבָּא, דְּבָעֵי לְשַׁלְּטָאָה בְּמִלֵּי דְּהַאי עָלְמָא, וְלָא אַשְׁגַּח בְּמִלֵּי דְּהַהוּא עָלְמָא מִדִי.","אֲמַאי אִיהִי רָעָה. קְרָא דְּבַתְרֵיהּ אוֹכַח, דִּכְתִּיב אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עוֹשֶׁר וּנְכָסִים וְגוֹ'. הַאי קְרָא קַשְׁיָא, כֵּיוָן דִּכְתִּיב וְאֵינֶנּוּ חָסֵר לְנַפְשׁוֹ מִכָּל אֲשֶׁר יִתְאַוְּה, אֲמַאי וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכוֹל מִמֶּנּוּ, דְּהָא אֵינוֹ חָסֵר לְנַפְשׁוֹ כְּלוּם אֶלָּא. רָזָא אִיהוּ, וְכָל מִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, מִתְלַבְּשָׁן אִינּוּן בְּמִלִּין אַחֲרָנִין, כְּמִלֵּי דְּאוֹרַיְיתָא, דְּאִינּוּן מִתְלַבְּשָׁן בְּסִפּוּרֵי עָלְמָא.","תָּא חֲזֵי, אַף עַל גַּב דְּבָעֵינָן לְאִסְתַּכְּלָא בִּלְבוּשָׁא, הַשְׁתָּא הַאי קְרָא הָכִי קָאָמַר, דְּבַּר נָשׁ אָזִיל בְּהַאי עָלְמָא, וְיָהִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא עוּתְרָא, בְּגִין דְּיִזְכֵּי בֵּיהּ לְעָלְמָא דְּאָתֵי, וְיִשְׁתְּאַר לְגַבֵּיהּ קֶרֶן. מַאי קֶרֶן. הַהוּא דְּאִיהוּ קַיָּים, דְּאִיהוּ אֲתָר לְאִתְצַרְרָא בֵּיהּ נִשְׁמְתָא. בְּגִין כָּךְ בָּעֵי לְאַשְׁאָרָא אֲבַּתְרֵיהּ (נ\"א עותריה) לְהַאי קֶרֶן, וְהַאי קֶרֶן יְקַבֵּל לֵיהּ, בָּתַר דְּיִפּוֹק מֵהַאי עָלְמָא."],[[0,"אמר ר' אלעזר","וכו': אר\"א, אני מה שאמרתי הוא מספרו של רב ייבא סבא שאמר כך, שבין בצד זה ובין בצד זה מחזירה הנון פניה, שלפני ויהי בנסוע מחזירה פניה לישראל, ואחר ויהי בנסוע מחזירה פניה לארון ואחוריה לישראל. אמר לו יפה אמר, שהכתיבה של הנונין צריכה להיות כך, אבל זה שאמרתי שמה שהחזירה אחוריה לישראל אינו מטעם המנוחה אלא מטעם שכתוב אחריה, ויהי העם כמתאוננים, כך תמצא בספרו של רב המנונא סבא. וכך הוא ודאי."],[1,"והמן כזרע גד הוא:","אמר ר' יוסי כזרע גד, פירושו כמו גדוד, דהיינו לקיים זרע וצבאות בארץ. כמש\"א גד גדוד יגודנו. ומה זרע גד לקחו חלקם בארץ אחר, דהיינו בעבר הירדן, כך המן היה שורה על ישראל לחוץ מארץ הקדושה. דהיינו במדבר."],[2,"ד\"א כזרע גד","וכו': פירוש אחר, כזרע גד הוא, היינו כמין זרע גד, הנקרא בלע\"ז קאלענדער, שהוא לבן ונקפא כשירד לאויר, ונבלע בגוף. וכבר העמידוהו החברים. ועינו כעין הבדולח, היינו כבדולח ההוא שהוא לבן, כעין הימין שלמעלה שהוא חסד המכונה לבן."],[3,"אמר ר' יצחק","וכו': אר\"י מהו השינוי שאמר משה בדבר זה למעלה כמו אל נוקבא, שכתוב, אם ככה \u0003את\u0004 עושה לי, שאומר לשון נקבה את, הלא אתה היה צריך לומר. ומשיב, אלא למקום שהמות שורה בו אמר, שאותו מקום הוא של הנקבה, דהיינו המלכות, ומשום זה אמר הרגני נא הרוג, שזה אילן המות, וכבר העמדנו שבאילן החיים, שהוא ז\"א, אין מות שורה בו, ולא יוכל לומר אליו הרגני נא הרוג, וע\"כ החזיר עצמו מאילן החיים, ואמר אל אילן המות, שהוא המלכות, \u0003את,\u0004 ולא אמר אתה, וכך היה צריך לומר. כי המלכות היא נוקבא."],[4,"מיד ויאמר ה'","וגו': מיד, ויאמר ה' אל משה אספה לי שבעים איש וגו'. אמר לו הקב\"ה, אתה מבקש בכל עת מות, הרי לך, ואצלתי מן הרוח וגו', בוא וראה, שכאן ידע משה שהוא ימות ולא יכנס לארץ, כי אלדד ומידד היו מתנבאים דבר זה. (סנהדרין י\"ז.)"],[5,"על דא לא","וכו': ע\"כ לא צריך האדם, בעת ששרוי בכעס, לקלל את עצמו. כי כמה מקטרגים עומדים עליו שמקבלים דבר זה. כלומר שקללתו מתקיימת. בזמן אחר שמשה ביקש מיתה, דהיינו במעשה העגל, שאמר, מחני נא מספרך אשר כתבת, לא קבלו ממנו, משום שהיה הכל לתועלת ישראל. עתה לא אמר זה אלא מתוך כעס ודוחק, וע\"כ קבלו ממנו. וע\"כ נשארו אח\"כ אלדד ומידד במחנה, ואמרו זה, שמשה יאסף אל עמו, ויהושע יכניס ישראל לארץ."],[6,"ובג\"כ אתא יהושע","וכו': ומשום זה בא יהושע אל משה וקנא על משה. ומשה לא השגיח על כבודו. וע\"כ אמר יהושע, אדני משה כלאם. מהו כלאם. היינו מנע מהם דברים אלו, שלא יתקיימו. כש\"א, \u0003ויכלא\u0004 העם מהביא. וכן \u0003ויכלא\u0004 הגשם מן השמים, שפירושו של ויכלא הוא מניעה ממש. ומשה לא רצה. צא וראה עניוות של משה. מה כתוב, המקנא אתה לי וגו'. אשרי חלקו של משה, שהוא עלה על כל נביאים העליונים. אמר רבי יהודה, כל שאר נביאים כלפי משה הם כלבנה כלפי השמש."],[7,"רבי אבא הוה","וכו': ר\"א היה יושב לילה אחד ועסק בתורה. והיו עמו ר' יוסי ור' חזקיה. אר\"י כמה הם בני אדם קשי לב, שאינם משגיחים בדברי עולם ההוא כלום. א\"ר אבא, הרע שבלב, האחוז בכל אברי הגוף עושה להם את זה. פתח ואמר, יש רעה אשר ראיתי תחת השמש ורבה היא על האדם. \u0003יש רעה,\u0004 זו היא תוקף הרע שבלב, שרוצה לשלוט בדברי עולם הזה, ואינו משגיח בדברי עולם ההוא כלום."],[8,"אמאי איהי רעה","וכו': שואל, למה הלב רע. ומשיב המקרא שלאחריו מוכיח זה, שכתוב, איש אשר יתן לו האלקים עושר ונכסים וגו'. מקרא זה קשה. כיון שכתוב, ואיננו חסר לנפשו מכל אשר יתאוה, למה ולא ישליטנו האלקים לאכול ממנו. הרי אינו חסר לנפשו כלום. ומשיב אלא סוד הוא, וכל דבריו של שלמה המלך הם מתלבשים בדברים אחרים, והם כדברי תורה המתלבשים בספורי עולם הזה."],[9,"ת\"ח אע\"ג דבעינן","וכו': בוא וראה אע\"פ שצריכים להסתכל בלבוש שהוא בספורי העולם, כלומר, אע\"פ שאין המקרא יוצא מידי פשוטו, מקרא זה עתה כך הוא אומר. שאדם הולך בעולם הזה, והקב\"ה נותן לו עושר, כדי שיזכה בו לעולם הבא, וישאר אצלו קרן מכספו. מהו קרן. כסף ההוא שהוא קיים לנצח, שהוא מקום לצרור בו הנשמה. משום זה הוא צריך להשאיר אחריו קרן הזה, וקרן הזה יקבלו אחר שיצא מעולם הזה."]],[[0,"","אָמַר רַבִּי אֶלְעָזָר, אֲנִי שֶׁאָמַרְתִּי מִסִּפְרוֹ שֶׁל רַב יֵיבָא סָבָא, שֶׁאָמַר שֶׁבֵּין מִצַּד זֶה וּבֵין מִצַּד זֶה חָזַר. אָמַר לוֹ, נָאֶה אָמַר, אֲבָל זֶה שֶׁאָמַרְנוּ, כָּךְ תִּמְצָא בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְכָךְ זֶה בְּוַדַּאי."],[1,"","וְהַמָּן כִּזְרַע גַּד הוּא. אָמַר רַבִּי יוֹסֵי, לְהַעֲמִיד זֶרַע וַחֲיָלוֹת בָּאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר (בראשיתמט) גָּד גְּדוּד יְגוּדֶנּוּ. מַה זֶּרַע גָּד נָטְלוּ חֶלְקָם בְּאֶרֶץ אַחֶרֶת, כָּךְ הַמָּן שָׁרָה עַל יִשְׂרָאֵל מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה."],[2,"","דָּבָר אַחֵר כִּזְרַע גַּד הוּא - כִּזְרַע גָּד לָבָן, וְנִקְפֶּה כְּשֶׁיּוֹרֵד לָאֲוִיר, וְנִטְחַן (והתגשם) (ונבלע) בַּגּוּף, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. וְעֵינוֹ כְּעֵין הַבְּדלַח, כְּמוֹ אוֹתוֹ בְּדוֹלַח שֶׁהוּא לָבָן, כְּגוֹן הַיָּמִין (לבן העין) שֶׁלְּמַעְלָה. (כזרע גד, כך לא נקראו בארץ מצרים, אבל לכך מכשפים זרע כזרע גד הוא, כזרעגדלבן, וכחוכאשריורדמלמעלהלמטה)."],[3,"","אָמַר רַבִּי יִצְחָק, מַה שּׁוֹנֶה (שאמר) מֹשֶׁה בְּדָבָר זֶה (חלש) לְמַעְלָה כִּנְקֵבָה, שֶׁכָּתוּב אִם כָּךְ אַתְּ עֹשֶׂה לִּי? אַתְּ?! אַתָּה צָרִיךְ לוֹ לִהְיוֹת! אֶלָּא לְמָקוֹם שֶׁהַמָּוֶת שׁוֹרֶה בּוֹ הוּא אָמַר, וְאוֹתוֹ מָקוֹם שֶׁל הַנְּקֵבָה הוּא. בִּגְלַל זֶה אָמַר הָרְגֵנִי נָא הָרוֹג, וְזֶה עֵץ הַמָּוֶת. וַהֲרֵי בֵּאַרְנוּ שֶׁבְּעֵץ הַחַיִּים לֹא שׁוֹרֶה הַמָּוֶת. וְעַל כָּךְ חָזַר לְגַבֵּי אִילַן הַמָּוֶת וְאָמַר אַתְּ, וְלֹא אָמַר אַתָּה, וְכָךְ צָרִיךְ לוֹ."],[4,"","מִיָּד - וַיֹּאמֶר ה' אֶל מֹשֶׁה אֶסְפָה לִּי שִׁבְעִים אִישׁ וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה רוֹצֶה מָוֶת בְּכָל זְמַן - הֲרֵי לְךְ, וְאָצַלְתִּי מִן הָרוּחַ וְגוֹ'. בּא רְאֵה שֶׁכָּאן יָדַע מֹשֶׁה שֶׁהוּא יָמוּת וְלֹא יִכָּנֵס לָאָרֶץ, שֶׁהֲרֵי אֶלְדָּד וּמֵידָד הָיוּ אוֹמְרִים דָּבָר זֶה."],[5,"","עַל כָּךְ לֹא צָרִיךְ לוֹ לָאָדָם בְּשָׁעָה שֶׁהָרֹגֶז שׁוֹרֶה בּוֹ לְקַלֵּל עַצְמוֹ, שֶׁהֲרֵי כַּמָּה עוֹמְדִים עָלָיו שֶׁמְּקַבְּלִים אוֹתוֹ דָּבָר. בִּזְמַן אַחֵר שֶׁרָצָה מִיתָה, לֹא קִבְּלוּ מִמֶּנּוּ, מִשּׁוּם שֶׁהַכֹּל הָיָה לְתוֹעֶלֶת יִשְׂרָאֵל. כָּעֵת אֵינוֹ, אֶלָּא מִתּוֹךְ רֹגֶז וְדחַק, וּמִשּׁוּם זֶה קִבְּלוּ מִמֶּנּוּ. וְעַל כָּךְ נִשְׁאֲרוּ לְאַחַר כָּךְ אֶלְדָּד וּמֵידָד וְאָמְרוּ אֶת זֶה, שֶׁמֹּשֶׁה יִתְאַסֵּף, וִיהוֹשֻׁעַ יַכְנִיסָם לְיִשְׂרָאֵל לָאָרֶץ."],[6,"","וּמִשּׁוּם זֶה בָּא יְהוֹשֻׁעַ לְמֹשֶׁה וְקִנֵּא עַל מֹשֶׁה, וּמֹשֶׁה לֹא הִשְׁגִּיחַ בִּכְבוֹדוֹ, וְעַל כָּךְ אָמַר, אֲנִי מֹשֶׁה כְּלָאֵם. מַה זֶּה כְּלָאֵם? מָנַע מֵהֶם אוֹתָם דְּבָרִים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לו) וַיִּכָּלֵא הָעָם מֵהָבִיא. (בראשית ח) וַיִּכָּלֵא הַגֶּשֶׁם מִן הַשָּׁמָיִם. מְנִיעוּת מַמָּשׁ. וּמֹשֶׁה לֹא רָצָה. צֵא וּרְאֵה עַוְנְתָנוּתוֹ שֶׁל מֹשֶׁה, מַה כָּתוּב? הַמְקַנֵּא אַתָּה לִי וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהוּא עָלָה עַל כָּל הַנְּבִיאִים הָעֶלְיוֹנִים (של העולם). אָמַר רַבִּי יְהוּדָה, כָּל שְׁאָר הַנְּבִיאִים לְגַבֵּי מֹשֶׁה כִּלְבָנָה לְגַבֵּי הַשֶּׁמֶשׁ."],[7,"","רַבִּי אַבָּא הָיָה יוֹשֵׁב לַיְלָה אֶחָד וְעוֹסֵק בַּתּוֹרָה, וְהָיוּ עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי יוֹסֵי, כַּמָּה אוֹתָם בְּנֵי הָאָדָם חַזְקֵי לֵב, שֶׁלֹּא מַשְׁגִּיחִים בְּדִבְרֵי אוֹתוֹ עוֹלָם כְּלוּם. אָמַר רַבִּי אַבָּא, בְּשַׂר הַלֵּב שֶׁאָחוּז בְּכָל אֵיבְרֵי הַגּוּף עוֹשֶׂה לָהֶם. פָּתַח וְאָמַר, (קהלת ו) יֵשׁ רָעָה אֲשֶׁר רָאִיתִי תַּחַת הַשָּׁמֶשׁ וְרַבָּה הִיא עַל הָאָדָם. יֵשׁ רָעָה - זֶה הוּא חֹזֶק רַע שֶׁל הַלֵּב, שֶׁרוֹצֶה לִשְׁלֹט בְּדִבְרֵי הָעוֹלָם הַזֶּה וְלֹא מַשְׁגִּיחַ בְּדִבְרֵי הָעוֹלָם הַהוּא דָּבָר."],[8,"","מַדּוּעַ הִיא רָעָה? הַפָּסוּק אַחַר כָּךְ מוֹכִיחַ, שֶׁכָּתוּבּ אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְגוֹ'. פָּסוּק זֶה קָשֶׁה, כֵּיוָן שֶׁכָּתוּב וְאֵינֶנּוּ חָסֵר לְנַפְשׁוֹ מִכֹּל אֲשֶׁר יִתְאַוֶּה, לָמָּה וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ, שֶׁהֲרֵי אֵינוֹ חָסֵר לְנַפְשׁוֹ כְּלוּם? אֶלָּא סוֹד הוּא, וְכָל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ מִתְלַבְּשִׁים הֵם בִּדְבָרִים אֲחֵרִים, כְּדִבְרֵי הַתּוֹרָה שֶׁמִּתְלַבְּשִׁים בְּסִפּוּרֵי הָעוֹלָם."],[9,"","בֹּא רְאֵה, אַף עַל גַּב שֶׁרוֹצִים לְהִסְתַּכֵּל בַּלְּבוּשׁ, כָּעֵת פָּסוּק זֶה כָּךְ אוֹמֵר, שֶׁאָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה וְנוֹתֵן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עֹשֶׁר כְּדֵי שֶׁיִּזְכֶּה בּוֹ לָעוֹלָם הַבָּא וְתִשָּׁאֵר אֶצְלוֹ הַקֶּרֶן. מַהִי הַקֶּרֶן? אוֹתָהּ שֶׁעוֹמֶדֶת, שֶׁהוּא מָקוֹם לִצְרֹר בּוֹ הַנְּשָׁמָה. בִּגְלַל זֶה צָרִיךְ לְהַשְׁאִיר אַחֲרָיו לְאוֹתָהּ קֶרֶן, וְקֶרֶן זוֹ יְקַבְּלָהּ לְאַחַר שֶׁיֵּצֵא מֵהָעוֹלָם הַזֶּה."]]],[["בְּגִין דְּהַאי קֶּרֶן, הוּא אִילָנָא דְּחַיֵּי דְּהַהוּא עָלְמָא, וְלָא קַיְּימָא בְּהַאי עָלְמָא, אֶלָּא הַהוּא אִיבָּא דְּנָפִיק מִנֵּיהּ, וְעַל דָּא אִיבָּא דִּילֵיהּ אָכִיל בַּר נָשׁ, דְּזָכֵי בְּהַאי עָלְמָא, וְהַקֶּרֶן קַיְּימָא לֵיהּ לְהַהוּא עָלְמָא, לְמִזְכֵּי בֵּיהּ בַּחַיִּין עִלָּאִין דִּלְעֵילָּא.","וּמַאן דְּסָאִיב גַּרְמֵיהּ, וְאִתְמְשַׁךְ בָּתַר גַּרְמֵיהּ, וְלֵיתֵיהּ חָסֵר לְנַפְשֵׁיהּ וּלְגַרְמֵיהּ כְּלוּם. וְהַהוּא אִילָנָא אִשְׁתְּאַר, וְלָא שַׁוְיֵהּ לָקֳבְלֵיהּ בִּדְחִילוּ, וּלְקַבְּלָא לֵיהּ לְעֵילָּא. כְּדֵין וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ, וּלְמִזְכֵּי בְּהַהוּא עוּתְרָא, וַדַּאי אִישׁ אַחֵר יֹאכְלֶנּוּ, כְּמָה דְאַתְּ אָמֵר (איוב כ״ז:י״ז) יָכִין וְצַדִּיק יִלְבַּשׁ. בְּגִין כָּךְ, בָּעֵי בַּר נָשׁ לְמִזְכֵּי, בְּמַה דְּיָהִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְהַהוּא עָלְמָא, וּכְדֵין אָכִיל מִינֵּיהּ בְּהַאי עָלְמָא, וְיִשְׁתְּאַר לְגַבֵּיהּ הַהוּא קֶרֶן לְעָלְמָא אַחֲרָא, לְמֶהֱוִי צְרוֹרָא בִּצְרוֹרָא דְּחַיֵּי. אָמַר רִבִּי יוֹסֵי וַדַּאי.","תּוּ אָמַר רִבִּי יוֹסֵי, כְּתִיב אִם כָּכָה אַתְּ עוֹשֶׂה לִי הָרְגֵנִי נָא וְגוֹ' וְכִי מֹשֶׁה דְּאִיהוּ עָנָו מִכָּל בְּנֵי עָלְמָא, בְּגִין דְּשָׁאִילוּ מִנֵּיהּ יִשְׂרָאֵל לְמֵיכַל, מָסַר גַּרְמֵיהּ לַמִּיתָה, אֲמַאי. אָמַר רִבִּי אַבָּא, הַאי מִלָּה אוֹלִיפְנָא, וְרָזָא עִלָּאָה אִיהוּ, מֹשֶׁה לָא אַבְאִישׁ קַמֵּיהּ, וְלָא שָׁאַל לַמִּיתָה עַל דְּשָׁאִילוּ יִשְׂרָאֵל.","תָּא חֲזֵי, מֹשֶׁה אִתְאֲחָד, וַהֲוָה סָלִיק בְּמַה דְּלָא אִתְאֲחָד נְבִיאָה אַחֲרָא. (דהא אחיד צדקה הוי) וּבְשַׁעֲתָא דְאֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. חַדֵּי מֹשֶׁה וְאָמַר, וַדַּאי הַשְׁתָּא הַהוּא שְׁלִימוּ בִּי אִשְׁתְּכַח. דְּהָא בְּגִינַי אִשְׁתְּכַח מָן לְיִשְׂרָאֵל. כֵּיוָן דְּחָמָא מֹשֶׁה דְּאָהַדְרוּ לְנַחְתָּא לְדַרְגָּא אַחֲרָא, וְשָׁאִילּוּ בָּשָׂר, וְאָמְרֵי וְנַפְשֵׁנוּ קָצָה בַּלֶּחֶם הַקְּלוֹקֵל. אָמַר אִי הָכִי הוּא, הָא דַּרְגָּא דִּילִי פָּגִים. דְּהָא בְּגִינִי יֵיכְלוּן יִשְׂרָאֵל מָן בְּמַדְבְּרָא (קפ\"א), הָא אֲנָא פְּגִימָא, וְאַהֲרֹן פָּגִים, וְנַחְשׁוֹן בֶּן עֲמִינָדָב פָּגִים.","אָמַר וְאִם כָּכָה אַתְּ עוֹשֶׂה לִי הָרְגֵנִי נָא הָרוֹג, דַּחֲשִׁיבְנָא נוּקְבָּא בְּמֵיכְלָא דִּילָהּ, (ואנא נחית מן שמייא דאיהו דרגא עלאה, לנחתא לדרגא דנוקבא, ואנא עדיף מן שאר נביאי עלמא, ועל דא אמר ואל אראה (אחותי) ברעתי כמת ודאי לנחתא לדרגא תתאה.","כדין ויאמר יי אל משה אספה לי שבעים איש. את שאיל אתר דמיתה לא תבעי אתר דלא תהא פגים בדרגא דילך. ועל דא כתיב ואצלתי מן הרוח אשר עליך דכלהו אינון דתמן אתאחדו). (ס\"א ואנא נחית מן שמייא לארעא. את עושה לי לנחתא לאתר דנוקבא, ולמפגם לאתרי ודרגי אי הכי הרגני נא הרוג אם נא מצאתי חן בעיניך ואל אראה ברעתי. רעתי היא ודאי לאחדא בדרגא תתאה. כדין ויאמר ה' אל משה אספה לי שבעים איש מזקני ישראל. הא אינון למיתן להו מיכלא אחרא, ולא תהא פגים בדרגא דילך. ועל דא ואצלתי מן הרוח אשר עליך ושמתי עליהם. מאי טעמא. בגין דאינון אתאחדו בסיהרא וכו') בְּסִיהֲרָא וּבָעֵי שִׁמְשָׁא לְאַנְהָרָא לָהּ. וְעַל דָּא וְשַׂמְתִּי עֲלֵיהֶם, בְּגִין לְאַנְהָרָא מִן שִׁמְשָׁא, כִּנְהוֹרָא דְּסִיהֲרָא. (ס\"א ובגיני האי מיכלא דא, לא) אַתְיָיא עַל יְדָא דְּמֹשֶׁה, בְּגִין דְּלָא יִתְפְּגִים.","זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהּ, עָלֵיהּ כְּתִיב (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְגוֹ'. יִשְׂמַח אָבִיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאִמֶּךָ: דָּא כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךָ: דָּא אִימָּא דְּמֹשֶׁה דִּלְתַּתָּא. קוּדְשָׁא בְּרִיךְ הוּא רָחִים לֵיהּ יַתִּיר מִכָּל נְבִיאֵי עָלְמָא, בְּלָא, אֶמְצָעִי כְּלָל. (ס\"א דהא משה אסתלק על כל נביאי עלמא בלא אמצעי כלל כמה) דִּכְתִּיב פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ, וְהָא אוֹקִימְנָא בְּכַמָּה אֲתָר."],[[0,"בגין דהאי קרן","וכו': משום שקרן הזה הוא עץ החיים של עולם ההוא, שהוא ז\"א, ולא נמצא ממנו בעולם הזה רק אותם חפירות שיוצאים ממנו. וע\"כ הפירות שלו אוכל האדם, שזכה להם, בעולם הזה, והקרן קיימת לו לעולם ההוא, לזכות בו בחיים עליונים שלמעלה."],[1,"ומאן דסאיב גרמיה","וכו': ומי שמטמא עצמו, ונמשך אחד טובת עצמו, ואינו חסר לנפשו וגופו כלום, ואותו האילן, שהוא ז\"א, נשאר, ואינו משים אותו לפניו ביראה, ולקבלו למעלה, אז, ולא ישליטנו האלקים לאכל ממנו, ולזכות באותו העושר, ודאי איש אחר יאכלנו. כש\"א, יכין וצדיק ילבש. משום זה צריך האדם לזכות לעולם ההוא במה שנותן לו הקב\"ה, ואז אוכל ממנו בעולם הזה, וקרן ההוא ישאר אצלו לעולם האחר, שיהיה צרור בצרור החיים. א\"ר יוסי, ודאי הוא כן."],[2,"תו אמר ר' יוסי","וכו': עוד אר\"י, כתוב, אם ככה את עושה לי הרגני נא הרוג וגו'. שואל, וכי משה שהיה ענו מכל בני העולם, משום ששאלו ממנו ישראל לאכול, מסר עצמו למיתה. למה. א\"ר אבא, דבר זה למדתי, וסוד עליון הוא, משה לא חרה לו, ולא שאל למסור עצמו למיתה משום זה ששאלו ממנו ישראל, לאכול בשר."],[3,"ת\"ח משה אתאחד","וכו': בוא וראה, משה נתאחד למעלה, והיה עולה במה שלא נתאחד נביא אחר, ובשעה שאמר לו הקב\"ה למשה, הנני ממטיר לכם לחם מן השמים, שמח משה ואמר ודאי עתה, שלימות הזה תהיה נמצאת בי, כי בזכותי נמצא המן לישראל. כיון שראה משה, שחזרו לרדת למדרגה אחרת ושאלו בשר, ואמרו, ונפשנו קצה בלחם הקלוקל. אמר, אם כן הוא, הרי מדרגתי היא פגומה, שהרי בזכותי יאכלו ישראל מן במדבר, הרי אני פגום ואהרן פגום ונחשון בן עמינדב פגום כי אהרן ונחשון. היו אחוזים בימין ושמאל של משה, (כמ\"ש בזוהר ואתחנן אות י\"ג)."],[4,"אמר ואם ככה","וגו': לפיכך אמר, ואם ככה את עושה לי הרגני נא הרוג, כי נהייתי כנוקבא, שהיא מלכות, בהמאכל שלה, דהיינו בבשר שהם שואלים. ואני יורד מן השמים שהוא מדרגה עליונה דהיינו ז\"א, עי\"ז שמאסו בלחם מן השמים, לרדת למדרגת הנוקבא, לאכילת בשר, והלא אני מעולה מכל שאר נביאי העולם, כי כל הנביאים נתנבאו ב \u0003כה,\u0004 שהיא הנוקבא, ומשה התנבא ב \u0003זה,\u0004 שהוא ז\"א, הנקרא שמים. וע\"כ אמר ואל אראה ברעתי. שנחשב למת ודאי לרדת למדרגה תחתונה. כי היורד ממדרגה למדרגה נחשב לו למיתה."],[5,"כדין ויאמר ה' אל","וגו': אז, ויאמר ה' אל משה אספה לי שבעים איש מזקני ישראל, הרי הם לתת להם מאכל אחר, שאינו מן השמים, שהוא מדגת משה. ולא תהיה נפגם במדרגה שלך. וע\"כ ואצלתי מן הרוח אשר עליך ושמתי עליהם. מהו הטעם, הוא משום שהם נתאחדו בלבנה, שהיא הנוקבא, וצריך השמש, שהוא מדרגת ז\"א, ומדרגת משה, להאיר לה, וע\"כ \u0003ושמתי עליהם,\u0004 כדי שיאירו מן השמש, שהוא מדרגת משה כאור הלבנה שהוא מן השמש, ומשום זה מאכל זה, בשר, לא בא על יד משה, אלא ע\"י שבעים איש, כדי שלא יופגם. שלא יוצרך לרדת ממדרגתו כנ\"ל."],[6,"זכאה חולקא דמשה","וכו': אשרי חלקו של משה, שהקב\"ה רצה ביקרו, עליו כתוב, ישמח אביך ואמך וגו'. \u0003ישמח אביך\u0004 זה הקב\"ה, \u0003ואמך,\u0004 זו היא כנסת ישראל, שהיא המלכות. \u0003ותגל יולדתך,\u0004 זו אמו של משה שלמטה. הקב\"ה אהב אותו יותר מכל נביאי העולם, שנבואתו היתה בלי אמצעי כלל, שכתוב, פה אל פה אדבר בו. והעמדנו בכמה מקומות."]],[[0,"","מִשּׁוּם שֶׁקֶּרֶן זוֹ הִיא עֵץ הַחַיִּים שֶׁל אוֹתוֹ עוֹלָם, וְלֹא עוֹמֵד בָּעוֹלָם הַזּה אֶלָּא אוֹתוֹ פְּרִי שֶׁיּוֹצֵא מִמֶּנּוּ, וְלָכֵן אוֹכֵל הָאָדָם פִּרְיוֹ, שֶׁזּוֹכֶה בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לְאוֹתוֹ עוֹלָם לִזְכּוֹת בָּהּ בְּחַיִּים עֶלְיוֹנִים שֶׁלְּמַעְלָה."],[1,"","וּמִי שֶׁמְּטַמֵּא עַצְמוֹ וְנִמְשָׁךְ אַחַר עַצְמוֹ וְלֹא מְחַסֵּר לְנַפְשׁוֹ וּלְעַצְמוֹ כְּלוּם, וְאוֹתוֹ עֵץ נִשְׁאָר וְלֹא שָׂם אוֹתוֹ מוּלוֹ בְּיִרְאָה וּלְקַבְּלוֹ לְמַעְלָה, אָז - וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ, וְלִזְכּוֹת בְּאוֹתוֹ עֹשֶׁר. וַדַּאי אָדָם אַחֵר יֹאכְלֶנּוּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב כז) יָכִין וְצַדִּיק יִלְבָּשׁ. בִּגְלַל זֶה צָרִיךְ הָאָדָם לִזְכּוֹת בְּמַה שֶּׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ עוֹלָם, וְאָז אוֹכֵל מִמֶּנּוּ בָּעוֹלָם הַזֶּה, וְתִשָּׁאֵר לוֹ אוֹתָהּ קֶרֶן לְעוֹלָם אַחֵר, לִהְיוֹת צָרוּר בִּצְרוֹר הַחַיִּים. אָמַר רַבִּי יוֹסֵי, וַדַּאי."],[2,"","עוֹד אָמַר רַבִּי יוֹסֵי, כָּתוּב אִם כָּכָה אַתְּ עֹשֶׂה לִּי הָרְגֵנִי נָא וְגוֹ'. וְכִי מֹשֶׁה, שֶׁהוּא עָנָו מִכָּל בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁשָּׁאֲלוּ מִמֶּנּוּ יִשְׂרָאֵל לֶאֱכֹל מָסַר עַצְמוֹ לְמִיתָה? לָמָּה? אָמַר רַבִּי אַבָּא, דָּבָר זֶה לָמַדְנוּ וְסוֹד עֶלְיוֹן הוּא. מֹשֶׁה לֹא הֵרַע לְפָנָיו וְלֹא שָׁאַל מִיתָה עַל שֶׁשָּׁאֲלוּ יִשְׂרָאֵל."],[3,"","בֹּא וּרְאֵה, מֹשֶׁה נֶאֱחַז, וְהָיָה עוֹלֶה בְּמַה שֶּׁלֹּא נֶאֱחַז נָבִיא אַחֵר. (שהרי היה אחוז בצדקה) וּבְשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, שָׂמַח מֹשֶׁה וְאָמַר, וַדַּאי כָּעֵת אוֹתָהּ שְׁלֵמוּת נִמְצֵאת בִּי, שֶׁהֲרֵי בִּגְלָלִי נִמְצָא מָן לְיִשְׂרָאֵל. כֵּיוָן שֶׁרָאָה מֹשֶׁה שֶׁחָזְרוּ לָרֶדֶת לְדַרְגָּה אַחֶרֶת וְשָׁאֲלוּ בָשָׂר, וְאָמְרוּ (במדבר כא) וְנַפְשֵׁנוּ קָצָה בַּלֶּחֶם הַקְּלוֹקֵל, אָמַר, אִם כָּךְ זֶה, הֲרֵי דַּרְגָּתִי פְגוּמָה, שֶׁהֲרֵי בִּגְלָלִי יֹאכְלוּ יִשְׂרָאֵל מָן בַּמִּדְבָּר. הֲרֵי אֲנִי פָגוּם, וְאַהֲרֹן פָּגוּם, וְנַחְשׁוֹן בֶּן עַמִּינָדָב פָּגוּם."],[4,"","אָמַר, וְאִם כָּכָה אַתְּ עֹשֶׂה לִּי הָרְגֵנִי נָא הָרֹג, שֶׁנֶּחְשַׁבְתִּי נְקֵבָה בְּמַאֲכָלָהּ, (ואני יורד מהשמים, שהוא דרגה עליונה, לרדת לדרגת נקבה, ואני עדיף משאר נביאי העולם. ועל זה אמר, ואל אראה (אחותי) ברעתי, כמת, ודאי לרדת לדרגה תחתונה."],[5,"","אז, ויאמר ה' אל משה אספה לי שבעים איש. אתה שאלת מקום שמיתה לא תצטרך, מקום שלא תהא פגום בדרגה שלך, ועל זה כתוב ואצלתי מן הרוח אשר עליך, שכלם הם שנאחזו שם). (ואני ירדתי מן השמים לארץ. את עשה לי, לרדת למקום הנקבה ולפגם מקומי ודרגתי. אם כך, הרגני נא הרג אם נא מצאתי חן בעיניך ואל אראה ברעתי. רעתי היא ודאי לאחז בדרגה תחתונה. אז, ויאמרה'אלמשהאספהלישבעים איש מזקני ישראל. הרי הם לתתלהם אכל אחר, ולא תהיה פגום בדרגתך. ועל זה, ואצלתי מן הרוח אשר עליך ושמתי עליהם. מה הטעם, ' משום שהם נאחזו בלבנה וכו') בַּלְּבָנָה, וְרָצָה הַשֶּׁמֶשׁ לְהָאִיר לָהּ. וְעַל כָּךְ וְשַׂמְתִּי עֲלֵיהֶם, כְּדֵי לְהָאִיר מֵהַשֶּׁמֶשׁ, כְּאוֹר הַלְּבָנָה. (ומשום זה אכל זה לא) בָּא עַל יְדֵי מֹשֶׁה, כְּדֵי שֶׁלֹּא יִפָּגֵם."],[6,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִכְבוֹדוֹ, עָלָיו כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְגוֹ'. יִשְׂמַח אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךְ - זוֹ אֵם מֹשֶׁה שֶׁלְּמַטָּה. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבוֹ יוֹתֵר מִכָּל נְבִיאֵי הָעוֹלָם לְלֹא אֶמְצָעִי כְּלָל, (שהרי משה נתעלה על כל נביאי העולם ללא אמצעי כלל, כמו) שֶׁכָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ, וַהֲרֵי בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת."]]],[["(במדבר י״ב:י״ג) וְיִצְעַק מֹשֶׁה אֶל יְיָ לֵאמֹר אֵל נָא רְפָא נָא לָהּ. הָא אוּקְמוּהָ, וְהוּא רָזָא דִּשְׁמָא קַדִּישָׁא, מֵחַד סְרֵי אַתְוָון, וְלָא בָּעָא מֹשֶׁה לְצַלָּאָה יַתִּיר, בְּגִין דְּעַל דִּידֵיהּ לְמַלְכָּא לָא בָּעֵי לְאַטְרְחָא יַתִּיר. בְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא בָּעָא עַל יְקָרָא דְּמֹשֶׁה. וּבְכָל אֲתָר קוּדְשָׁא בְּרִיךְ הוּא בָּעָא עַל יְקָרֵיהוֹן דְּצַדִּיקַיָּיא, יַתִּיר עַל דִּילֵיהּ. וּלְזִמְנָא דְּאָתֵי, עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְמִתְבַּע עֶלְבּוֹנָא דְּיִשְׂרָאֵל מֵעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וּלְמֵחדֵי לוֹן בְּחֶדְוָותָא דְּצִיּוֹן. דִּכְתִּיב, (ירמיהו ל״א:י״ב) וּבָאוּ וְרִנְּנוּ בִמְרוֹם צִיּוֹן וְגוֹ'. וּכְדֵין (ישעיהו נ״ט:כ׳) וּבָא לְצִיּוֹן גּוֹאֵל וְגוֹ'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"ויצעק משה אל","וגו': ויצעק משה אל ה' לאמר אל נא רפא נא לה. כבר העמידוהו. והוא סוד שם הקדוש של י\"א אותיות, דהיינו אותם י\"א אותיות שיש בהמלות אל נא רפא נא לה. ולא רצה משה להתפלל יותר, משום שעל שלו לא רצה להטריח את המלך יותר, על כן רצה הקב\"ה ביקרו של משה. ובכל מקום רוצה הקב\"ה בכבודם של הצדיקים יותר משלו. ולעתיד לבא עתיד הקב\"ה לתבוע עלבונם של ישראל מעמים עכו\"ם ולשמח את ישראל בשמחת ציון. שכתוב, ובאו ורננו במרום ציון וגו'. ואז, ובא לציון גואל וגו'. ברוך ה' לעולם אמן ואמן. ימלוך ה' לעולם אמן ואמן."]],[[0,"","וַיִּצְעַק מֹשֶׁה אֶל ה' לֵאמֹר אֵל נָא רְפָא נָא לָהּ. הֲרֵי פֵּרְשׁוּהָ, וְהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ מֵאַחַת עֶשְׂרֵה אוֹתִיּוֹת, וְלֹא רָצָה מֹשֶׁה לְהִתְפַּלֵּל יוֹתֵר, מִשּׁוּם שֶׁעַל שֶׁלּוֹ לֹא רָצָה לְהַטְרִיחַ יוֹתֵר לַמֶּלֶךְ. בִּגְלַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִּכְבוֹד מֹשֶׁה. וּבְכָל מָקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹד הַצַּדִּיקִים יוֹתֵר עַל שֶׁלּוֹ. וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְבֹּעַ עֶלְבּוֹן יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וּלְשַׂמְּחָם בְּחֶדְוַת צִיּוֹן, שֶׁכָּתוּב (ירמיה לא) וּבָאוּ וְרִנְּנוּ בִמְרוֹם צִיּוֹן וְגוֹ'. וְאָז (ישעיה נט) וּבָא לְצִיּוֹן גּוֹאֵל וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
